def normalize_photo_emotion_key(value):
    """Normalize legacy/new emotion values into the current normal-mode choices or ''."""
    if isinstance(value, dict):
        value = value.get("key") or value.get("emotion") or value.get("label") or value.get("emoji")
    value = str(value or "").strip()
    aliases = {
        "cozy": "cozy", "ほっこり": "cozy", "ほっこりした": "cozy", "🥰": "cozy",
        "joy": "joy", "喜": "joy", "うれしい": "joy", "嬉しい": "joy", "😊": "joy",
        "surprise": "surprise", "びっくり": "surprise", "驚き": "surprise", "😲": "surprise",
        "anger": "anger", "怒": "anger", "おこった": "anger", "怒った": "anger", "😠": "anger",
        "sadness": "sadness", "sad": "sadness", "哀": "sadness", "かなしい": "sadness", "悲しい": "sadness", "😢": "sadness",
        "frustration": "frustration", "くやしい": "frustration", "悔しい": "frustration", "😣": "frustration",
        "relaxed": "relaxed", "のほほん": "relaxed", "😌": "relaxed",
        "delicious": "delicious", "美味しい": "delicious", "おいしい": "delicious", "😋": "delicious",
        "beautiful": "beautiful", "きれい": "beautiful", "綺麗": "beautiful", "✨": "beautiful",
        "mixed": "mixed", "複雑": "mixed", "複雑な気持ち": "mixed", "😵‍💫": "mixed",
        # v149-v158 compatibility: the former 楽/🎉 choice is folded into the
        # closest remaining positive choice instead of discarding old records.
        "fun": "joy", "楽": "joy", "🎉": "joy",
    }
    return aliases.get(value, "")


def normalize_parenting_tag_key(value):
    """Normalize parenting-mode values into one of the current こどもーど tags or ''."""
    if isinstance(value, dict):
        value = value.get("key") or value.get("tag") or value.get("label") or value.get("emoji")
    value = str(value or "").strip()
    aliases = {
        "effort": "effort", "がんばった": "effort", "頑張った": "effort", "⭐": "effort",
        "challenge": "challenge", "ちょうせん": "challenge", "挑戦": "challenge", "💪": "challenge",
        "discovery": "discovery", "はっけん": "discovery", "発見": "discovery", "💡": "discovery",
        "kindness": "kindness", "やさしさ": "kindness", "優しさ": "kindness", "❤️": "kindness", "❤": "kindness",
        "together": "together", "いっしょに": "together", "一緒に": "together", "🤝": "together",
        "tears": "tears", "なみだ": "tears", "涙": "tears", "😭": "tears",
        "hmm": "hmm", "むーん": "hmm", "ムーン": "hmm", "🤔": "hmm",
        "peace": "peace", "ピース": "peace", "✌️": "peace", "✌": "peace",
        "teach_me": "teach_me", "教えて": "teach_me", "🙋": "teach_me",
        "sharp": "sharp", "キリッ": "sharp", "きりっ": "sharp", "🫡": "sharp",
    }
    return aliases.get(value, "")


def photo_parenting_tag_key(photo):
    reflection = (photo or {}).get("reflection_json") or {}
    if not isinstance(reflection, dict):
        return ""
    return normalize_parenting_tag_key(reflection.get("parenting_tag"))


def photo_parenting_tag_meta(photo_or_key):
    key = photo_or_key if isinstance(photo_or_key, str) else photo_parenting_tag_key(photo_or_key)
    key = normalize_parenting_tag_key(key)
    meta = dict(PARENTING_TAGS.get(key) or {})
    meta["key"] = key
    return meta


def parenting_tag_record(tag_key, source="parent_tap_cycle_v168"):
    tag_key = normalize_parenting_tag_key(tag_key)
    if not tag_key:
        return None
    meta = PARENTING_TAGS[tag_key]
    return {
        "key": tag_key,
        "label": meta["label"],
        "emoji": meta["emoji"],
        "color": meta["color"],
        "meaning": meta["meaning"],
        "updated_at": now_jst().isoformat(),
        "source": str(source or "parent_tap_cycle_v168"),
    }


def next_parenting_tag_key(current):
    current = normalize_parenting_tag_key(current)
    cycle = ("",) + PARENTING_TAG_ORDER
    try:
        index = cycle.index(current)
    except ValueError:
        index = 0
    return cycle[(index + 1) % len(cycle)]


def photo_emotion_key(photo):
    reflection = (photo or {}).get("reflection_json") or {}
    if not isinstance(reflection, dict):
        return ""
    return normalize_photo_emotion_key(reflection.get("emotion"))


def photo_emotion_meta(photo_or_key):
    key = photo_or_key if isinstance(photo_or_key, str) else photo_emotion_key(photo_or_key)
    key = normalize_photo_emotion_key(key)
    meta = dict(PHOTO_EMOTIONS.get(key) or {})
    meta["key"] = key
    return meta


ALL_PHOTO_TAG_ORDER = PHOTO_EMOTION_ORDER + PARENTING_TAG_ORDER


def photo_selected_tag_meta(photo):
    """Return the single visible tag across 通常 and こどもーど.

    v168 makes the two modes mutually exclusive. For legacy rows that still contain
    both fields, prefer the record with the newer updated_at timestamp; ties keep the
    normal feeling for backward compatibility.
    """
    reflection = (photo or {}).get("reflection_json") or {}
    if not isinstance(reflection, dict):
        reflection = {}
    emotion_record = reflection.get("emotion")
    parenting_record = reflection.get("parenting_tag")
    emotion_key = normalize_photo_emotion_key(emotion_record)
    parenting_key = normalize_parenting_tag_key(parenting_record)

    if emotion_key and parenting_key:
        emotion_at = str(emotion_record.get("updated_at") or "") if isinstance(emotion_record, dict) else ""
        parenting_at = str(parenting_record.get("updated_at") or "") if isinstance(parenting_record, dict) else ""
        if parenting_at and (not emotion_at or parenting_at > emotion_at):
            emotion_key = ""
        else:
            parenting_key = ""

    if emotion_key:
        meta = dict(PHOTO_EMOTIONS.get(emotion_key) or {})
        meta.update({"key": emotion_key, "mode": "normal"})
        return meta
    if parenting_key:
        meta = dict(PARENTING_TAGS.get(parenting_key) or {})
        meta.update({"key": parenting_key, "mode": "parenting"})
        return meta
    return {"key": "", "mode": "", "label": "", "emoji": "", "color": "", "meaning": ""}


def photo_selected_tag_key(photo):
    return str(photo_selected_tag_meta(photo).get("key") or "")


def photo_selected_tag_mode(photo):
    return str(photo_selected_tag_meta(photo).get("mode") or "")


def photo_selected_tag_values(photo):
    meta = photo_selected_tag_meta(photo)
    key = str(meta.get("key") or "")
    if meta.get("mode") == "parenting":
        return "", key
    return key, ""


# ============================================================
# Per-photo favorite marker (v352)
# ============================================================
PHOTO_FAVORITE_KEY = "_favorite"
PHOTO_FAVORITE_TAG = "お気に入り"
PHOTO_VOICE_TAG = "声付き"


def photo_favorite_info(photo):
    reflection = (photo or {}).get("reflection_json") or {}
    if not isinstance(reflection, dict):
        return {}
    value = reflection.get(PHOTO_FAVORITE_KEY)
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, bool):
        return {"favorite": bool(value)}
    return {}


def photo_favorite_is_enabled(photo):
    return bool(photo_favorite_info(photo).get("favorite"))


def set_photo_favorite(photo_id, enabled=True):
    """Persist favorite state and keep the searchable 「お気に入り」 tag in sync."""
    photo_id = str(photo_id or "").strip()
    if not photo_id:
        raise ValueError("お気に入りにする写真を確認できませんでした。")

    client = supabase_client()
    rows = (
        client.table(PHOTO_TABLE)
        .select("id,reflection_json")
        .eq("id", photo_id)
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .limit(1)
        .execute()
    ).data or []
    row = rows[0] if rows else None
    if not isinstance(row, dict) or not row.get("id"):
        raise ValueError("現在の個人アカウントの写真が見つかりませんでした。")

    reflection = row.get("reflection_json") or {}
    reflection = dict(reflection) if isinstance(reflection, dict) else {}
    updated_at = now_jst().isoformat()
    if enabled:
        reflection[PHOTO_FAVORITE_KEY] = {
            "version": 1,
            "favorite": True,
            "updated_at": updated_at,
        }
    else:
        reflection.pop(PHOTO_FAVORITE_KEY, None)

    # v353: 「お気に入り」 is a real searchable tag as well as a star marker.
    # Preserve existing AI tags and their version/source. A favorite may have one
    # additional manual tag beyond the normal AI-tag limit so no content tag is lost.
    raw_ai = reflection.get("ai_tags")
    ai_meta = dict(raw_ai) if isinstance(raw_ai, dict) else {}
    raw_tags = ai_meta.get("tags") if isinstance(raw_ai, dict) else raw_ai
    if isinstance(raw_tags, str):
        raw_tags = [part.strip() for part in re.split(r"[,，、]", raw_tags) if part.strip()]
    if not isinstance(raw_tags, (list, tuple)):
        raw_tags = []
    content_tags = [
        tag for tag in normalize_ai_photo_tags(raw_tags, max_tags=AI_PHOTO_TAG_MAX_PER_PHOTO + 2)
        if tag not in {PHOTO_FAVORITE_TAG, PHOTO_VOICE_TAG}
    ][:AI_PHOTO_TAG_MAX_PER_PHOTO]
    synced_tags = ([PHOTO_FAVORITE_TAG] + content_tags) if enabled else content_tags

    if synced_tags:
        if not ai_meta:
            # Version 0 keeps an otherwise-untagged favorite eligible for normal AI tagging.
            ai_meta = {"version": 0, "source": "manual_favorite_v353"}
        ai_meta["tags"] = synced_tags
        ai_meta["updated_at"] = updated_at
        ai_meta["favorite_tag_synced"] = bool(enabled)
        reflection["ai_tags"] = ai_meta
    elif isinstance(raw_ai, dict) and any(key in ai_meta for key in ("version", "source")):
        ai_meta["tags"] = []
        ai_meta["updated_at"] = updated_at
        ai_meta["favorite_tag_synced"] = False
        reflection["ai_tags"] = ai_meta
    else:
        reflection.pop("ai_tags", None)

    (
        client.table(PHOTO_TABLE)
        .update({"reflection_json": reflection})
        .eq("id", photo_id)
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .execute()
    )
    signed_photo_url_map.clear()
    _invalidate_fast_db_cache()
    return bool(enabled)


def handle_photo_favorite_event(result, valid_photo_ids, serial_key=None):
    payload = getattr(result, "favorite_photo", None) if result is not None else None
    if not isinstance(payload, dict):
        return False
    photo_id = str(payload.get("photo_id") or "").strip()
    valid = {str(value) for value in (valid_photo_ids or []) if str(value)}
    if not photo_id or photo_id not in valid:
        return False
    token = str(payload.get("token") or "").strip()
    token_key = "_photo_favorite_action_token_v352"
    if token and token == str(st.session_state.get(token_key) or ""):
        return False
    if token:
        st.session_state[token_key] = token
    enabled = bool(payload.get("enabled"))
    try:
        set_photo_favorite(photo_id, enabled=enabled)
        st.session_state["_photo_favorite_notice"] = "★ お気に入りタグに登録しました。" if enabled else "お気に入りタグを解除しました。"
    except Exception as exc:
        st.session_state["_photo_favorite_notice"] = f"お気に入り設定を変更できませんでした：{exc}"
    if serial_key:
        try:
            st.session_state[serial_key] = int(st.session_state.get(serial_key) or 0) + 1
        except Exception:
            st.session_state[serial_key] = 1
    st.rerun()
    return True


def render_photo_favorite_notice():
    notice = st.session_state.pop("_photo_favorite_notice", None)
    if notice:
        st.success(str(notice))


def render_enlarged_photo_favorite_control(photo, key_prefix):
    """Show the shared favorite-tag toggle for one enlarged photo owned by this member."""
    photo = photo if isinstance(photo, dict) else {}
    photo_id = str(photo.get("id") or "").strip()
    if not photo_id:
        return
    favorite = photo_favorite_is_enabled(photo)
    label = "★ お気に入りタグを解除" if favorite else "☆ お気に入りタグに登録"
    if st.button(
        label,
        use_container_width=True,
        key=f"{key_prefix}_{photo_id}_{'on' if favorite else 'off'}",
    ):
        try:
            set_photo_favorite(photo_id, enabled=not favorite)
            st.session_state["_photo_favorite_notice"] = (
                "★ お気に入りタグに登録しました。" if not favorite else "お気に入りタグを解除しました。"
            )
        except Exception as exc:
            st.session_state["_photo_favorite_notice"] = f"お気に入り設定を変更できませんでした：{exc}"
        st.rerun()


# ============================================================
# Individual photo sharing inside one family account (v225)
# ============================================================
PHOTO_FAMILY_SHARE_KEY = "_family_photo_share"


def photo_family_share_info(photo):
    """Return per-photo family-share metadata stored inside reflection_json."""
    reflection = (photo or {}).get("reflection_json") or {}
    if not isinstance(reflection, dict):
        return {}
    share = reflection.get(PHOTO_FAMILY_SHARE_KEY) or {}
    return dict(share) if isinstance(share, dict) else {}


def photo_family_share_is_enabled(photo):
    return bool(photo_family_share_info(photo).get("shared"))


def _photo_family_share_tag_snapshot(reflection):
    """Snapshot the currently visible 通常/こどもーど tag for family sharing."""
    reflection = dict(reflection) if isinstance(reflection, dict) else {}
    meta = photo_selected_tag_meta({"reflection_json": reflection})
    return {
        "key": str(meta.get("key") or ""),
        "mode": str(meta.get("mode") or ""),
        "label": str(meta.get("label") or ""),
        "emoji": str(meta.get("emoji") or ""),
        "color": str(meta.get("color") or ""),
    }


def _sync_photo_family_share_tag_snapshot(reflection):
    """Keep an already-shared photo's tag metadata synchronized with its live tag."""
    reflection = dict(reflection) if isinstance(reflection, dict) else {}
    share = reflection.get(PHOTO_FAMILY_SHARE_KEY) or {}
    if not isinstance(share, dict) or not share.get("shared"):
        return reflection
    share = dict(share)
    share["version"] = max(2, int(share.get("version") or 0))
    share["tag_snapshot"] = _photo_family_share_tag_snapshot(reflection)
    share["tag_updated_at"] = now_jst().isoformat()
    reflection[PHOTO_FAMILY_SHARE_KEY] = share
    return reflection


def set_photo_family_share(photo_id, enabled=True, emotion_key=None, parenting_key=None):
    """Share/unshare one owned still photo, including its current feeling/tag.

    The image is not copied.  Sharing stores a lightweight permission marker plus a
    tag snapshot in the existing photo row.  The recipient still reads the owner's
    live reflection_json, so later tag changes remain synchronized automatically.

    ``emotion_key`` / ``parenting_key`` are optional browser-visible values.  When
    supplied, they are persisted atomically with the share toggle so a user can tap a
    feeling and immediately tap Share without losing the newest on-screen choice.
    """
    photo_id = str(photo_id or "").strip()
    if not photo_id:
        raise ValueError("共有する写真を確認できませんでした。")

    client = supabase_client()
    row = (
        client.table(PHOTO_TABLE)
        .select("id,trip_id,storage_path,reflection_json")
        .eq("id", photo_id)
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .limit(1)
        .execute()
    ).data or []
    photo = row[0] if row else None
    if not isinstance(photo, dict) or not photo.get("id"):
        raise ValueError("現在の個人アカウントの写真が見つかりませんでした。")

    reflection = photo.get("reflection_json") or {}
    reflection = dict(reflection) if isinstance(reflection, dict) else {}

    # v225: a share click carries the tag currently visible in the browser.  Apply it
    # before the permission marker so the photo and its feeling are one atomic share.
    browser_tag_supplied = emotion_key is not None or parenting_key is not None
    if browser_tag_supplied:
        resolved_emotion = normalize_photo_emotion_key(emotion_key)
        resolved_parenting = normalize_parenting_tag_key(parenting_key)
        if resolved_emotion:
            reflection["emotion"] = photo_emotion_record(
                resolved_emotion,
                source="family_share_visible_tag_v225",
            )
            reflection.pop("parenting_tag", None)
        elif resolved_parenting:
            reflection["parenting_tag"] = parenting_tag_record(
                resolved_parenting,
                source="family_share_visible_tag_v225",
            )
            reflection.pop("emotion", None)
        else:
            # Both values were explicitly sent as blank: the on-screen photo is untagged.
            reflection.pop("emotion", None)
            reflection.pop("parenting_tag", None)

    if enabled:
        previous = reflection.get(PHOTO_FAMILY_SHARE_KEY) or {}
        previous = previous if isinstance(previous, dict) else {}
        now_value = now_jst().isoformat()
        reflection[PHOTO_FAMILY_SHARE_KEY] = {
            "version": 2,
            "shared": True,
            "shared_by_member_key": current_member_key(),
            "shared_by_member_name": current_member_name(),
            "shared_at": str(previous.get("shared_at") or now_value),
            "updated_at": now_value,
            "tag_updated_at": now_value,
            "tag_snapshot": _photo_family_share_tag_snapshot(reflection),
        }
    else:
        reflection.pop(PHOTO_FAMILY_SHARE_KEY, None)

    (
        client.table(PHOTO_TABLE)
        .update({"reflection_json": reflection})
        .eq("id", photo_id)
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .execute()
    )
    _invalidate_fast_db_cache()
    return bool(enabled)


def list_family_shared_photos(limit=90):
    """Return still photos explicitly shared by other members of the current family."""
    try:
        requested = max(1, min(180, int(limit)))
    except Exception:
        requested = 90
    cache_key = _account_cache_key("family_shared_photos_v456", requested)
    cached = _session_cache_get(cache_key, max_age_seconds=90)
    if cached is not None:
        return cached
    query_limit = max(180, min(800, requested * 6))
    try:
        rows = (
            supabase_client()
            .table(PHOTO_TABLE)
            .select("id,member_key,trip_id,storage_path,captured_at,reflection_json,signals_json")
            .eq("family_key", current_family_key())
            .order("captured_at", desc=True)
            .limit(query_limit)
            .execute()
        ).data or []
    except Exception:
        return []

    try:
        member_map = {
            str(row.get("member_key") or ""): str(row.get("display_name") or row.get("member_key") or "")
            for row in list_family_members(current_family_key())
            if isinstance(row, dict)
        }
    except Exception:
        member_map = {}

    current_member = current_member_key()
    shared = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        owner_key = str(row.get("member_key") or "").strip()
        if not owner_key or owner_key == current_member:
            continue
        if not str(row.get("storage_path") or "").strip():
            continue
        reflection = row.get("reflection_json") or {}
        if not isinstance(reflection, dict):
            continue
        # Original videos are not exposed as individual shared images. A still saved
        # from Good Moments is a normal photo row and can be shared normally.
        if str(reflection.get("media_type") or "").strip().lower() == "video":
            continue
        share = reflection.get(PHOTO_FAMILY_SHARE_KEY) or {}
        if not isinstance(share, dict) or not share.get("shared"):
            continue
        item = dict(row)
        item["_shared_owner_key"] = owner_key
        item["_shared_owner_name"] = str(
            member_map.get(owner_key)
            or share.get("shared_by_member_name")
            or owner_key
        ).strip()
        item["_shared_at"] = str(share.get("updated_at") or share.get("shared_at") or "")
        item["_shared_tag_snapshot"] = dict(share.get("tag_snapshot") or {}) if isinstance(share.get("tag_snapshot"), dict) else {}
        shared.append(item)
        if len(shared) >= requested:
            break
    return _session_cache_set(cache_key, shared)


def render_photo_family_share_notice():
    notice = st.session_state.pop("_photo_family_share_notice", None)
    if notice:
        st.success(str(notice))


def handle_photo_family_share_event(result, valid_photo_ids, serial_key=None):
    """Persist a browser share toggle together with the exact visible feeling/tag."""
    payload = getattr(result, "share_photo", None) if result is not None else None
    if not isinstance(payload, dict):
        return False
    photo_id = str(payload.get("photo_id") or "").strip()
    valid = {str(value) for value in (valid_photo_ids or []) if str(value)}
    if not photo_id or photo_id not in valid:
        return False
    token = str(payload.get("token") or "").strip()
    token_key = "_photo_family_share_action_token_v225"
    if token and token == str(st.session_state.get(token_key) or ""):
        return False
    if token:
        st.session_state[token_key] = token
    enabled = bool(payload.get("enabled"))
    emotion_value = payload.get("emotion") if "emotion" in payload else None
    parenting_value = payload.get("parenting") if "parenting" in payload else None
    try:
        set_photo_family_share(
            photo_id,
            enabled=enabled,
            emotion_key=emotion_value,
            parenting_key=parenting_value,
        )
        st.session_state["_photo_family_share_notice"] = (
            "この写真と選んだ感情を、同じ家族IDの別アカウントに共有しました。"
            if enabled else
            "この写真の家族共有を解除しました。"
        )
    except Exception as exc:
        st.session_state["_photo_family_share_notice"] = f"写真の共有設定を変更できませんでした：{exc}"
    if serial_key:
        try:
            st.session_state[serial_key] = int(st.session_state.get(serial_key) or 0) + 1
        except Exception:
            st.session_state[serial_key] = 1
    st.rerun()
    return True


def selection_item_tag_values(item):
    """Resolve one tag from an AI-selected still, including legacy dual-tag rows."""
    item = item if isinstance(item, dict) else {}
    emotion_record = item.get("emotion")
    parenting_record = item.get("parenting_tag")
    emotion_key = normalize_photo_emotion_key(emotion_record)
    parenting_key = normalize_parenting_tag_key(parenting_record)
    if emotion_key and parenting_key:
        emotion_at = str(emotion_record.get("updated_at") or "") if isinstance(emotion_record, dict) else ""
        parenting_at = str(parenting_record.get("updated_at") or "") if isinstance(parenting_record, dict) else ""
        if parenting_at and (not emotion_at or parenting_at > emotion_at):
            emotion_key = ""
        else:
            parenting_key = ""
    return emotion_key, parenting_key


def photo_tag_meta_from_key(key):
    key = str(key or "")
    if key in PHOTO_EMOTIONS:
        meta = dict(PHOTO_EMOTIONS[key])
        meta.update({"key": key, "mode": "normal"})
        return meta
    if key in PARENTING_TAGS:
        meta = dict(PARENTING_TAGS[key])
        meta.update({"key": key, "mode": "parenting"})
        return meta
    return {"key": "", "mode": "", "label": "", "emoji": "", "color": "", "meaning": ""}


def photo_emotion_record(emotion_key, source="child_tap_cycle_v168"):
    """Return the persisted reflection_json payload for one current normal-mode feeling."""
    emotion_key = normalize_photo_emotion_key(emotion_key)
    if not emotion_key:
        return None
    meta = PHOTO_EMOTIONS[emotion_key]
    return {
        "key": emotion_key,
        "label": meta["label"],
        "emoji": meta["emoji"],
        "color": meta["color"],
        "updated_at": now_jst().isoformat(),
        "source": str(source or "child_tap_cycle_v168"),
    }


def next_photo_emotion_key(current):
    current = normalize_photo_emotion_key(current)
    cycle = ("",) + PHOTO_EMOTION_ORDER
    try:
        index = cycle.index(current)
    except ValueError:
        index = 0
    return cycle[(index + 1) % len(cycle)]


def photo_emotion_counts(photos):
    """Count the one selected tag per photo across both mode palettes."""
    counts = {key: 0 for key in ALL_PHOTO_TAG_ORDER}
    selected = 0
    for photo in diary_photos_only(photos or []):
        key = photo_selected_tag_key(photo)
        if key in counts:
            counts[key] += 1
            selected += 1
    return counts, selected


def photo_emotion_summary_text(photos, include_unset=True):
    photos = diary_photos_only(photos or [])
    counts, selected = photo_emotion_counts(photos)
    parts = []
    for key in ALL_PHOTO_TAG_ORDER:
        count = int(counts.get(key) or 0)
        if not count:
            continue
        meta = photo_tag_meta_from_key(key)
        parts.append(f"{meta['emoji']}{meta['label']} {count}枚")
    unset = max(0, len(photos) - selected)
    if include_unset and unset:
        parts.append(f"未設定 {unset}枚")
    return " ／ ".join(parts)


def _invalidate_monthly_review_for_trip(trip_id):
    """Emotion changes invalidate any saved monthly interpretation for that day."""
    try:
        trip = get_trip(trip_id) or {}
        trip_date = str(trip.get("trip_date") or "")
        month_key = trip_date[:7] if len(trip_date) >= 7 else ""
        if not month_key:
            return
        first_day, _ = month_bounds(month_key)
        supabase_client().table(MONTHLY_TABLE).delete().eq(
            "review_month", first_day
        ).eq("family_key", current_family_key()).eq("member_key", current_member_key()).execute()
        _invalidate_fast_db_cache()
        for key in (
            f"monthly_review_{month_key}",
            f"monthly_audio_{month_key}",
            f"monthly_audio_pending_{month_key}",
        ):
            st.session_state.pop(key, None)
    except Exception:
        # Emotion tagging itself must still succeed even if a stale monthly cache
        # cannot be invalidated at this moment.
        pass


def _refresh_after_photo_emotion_changes(trip_ids):
    return _refresh_diaries_batched_v468(trip_ids)


def update_photo_emotion(photo_id, emotion_key, trip_id=None, refresh_related=True):
    """Persist one six-choice feeling tag.

    The optional refresh_related=False path is used by v158 batched UI commits so
    multiple rapid taps do not repeat diary/monthly refresh work for every tap.
    """
    emotion_key = normalize_photo_emotion_key(emotion_key)
    if emotion_key and emotion_key not in PHOTO_EMOTIONS:
        raise ValueError("感情の種類を確認できませんでした。")

    client = supabase_client()
    query = (
        client
        .table(PHOTO_TABLE)
        .select("id,trip_id,reflection_json")
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .limit(1)
        .execute()
    )
    row = (query.data or [None])[0] or {}
    if not row.get("id"):
        raise ValueError("感情を設定する写真が見つかりませんでした。")
    resolved_trip_id = str(trip_id or row.get("trip_id") or "")
    reflection = row.get("reflection_json") or {}
    if not isinstance(reflection, dict):
        reflection = {}

    if emotion_key:
        reflection["emotion"] = photo_emotion_record(emotion_key, source="child_tap_cycle_v168")
        reflection.pop("parenting_tag", None)
    else:
        reflection.pop("emotion", None)
    reflection = _sync_photo_family_share_tag_snapshot(reflection)

    (
        client
        .table(PHOTO_TABLE)
        .update({"reflection_json": reflection})
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .execute()
    )
    if refresh_related:
        _refresh_after_photo_emotion_changes([resolved_trip_id] if resolved_trip_id else [])
    return emotion_key


def update_photo_emotions_batch(changes, valid_photo_ids=None, trip_id=None):
    """Persist only the final emotion for each photo after a burst of taps."""
    valid = {str(value) for value in (valid_photo_ids or []) if str(value)} if valid_photo_ids is not None else None
    latest = {}
    for change in changes or []:
        if not isinstance(change, dict):
            continue
        photo_id = str(change.get("photo_id") or "").strip()
        if not photo_id or (valid is not None and photo_id not in valid):
            continue
        latest[photo_id] = normalize_photo_emotion_key(change.get("emotion"))
    if not latest:
        return {}

    touched_trips = set()
    for photo_id, emotion_key in latest.items():
        # The supplied trip_id is authoritative for the normal diary/recent-photo
        # views. update_photo_emotion still resolves the row trip when it is absent.
        update_photo_emotion(photo_id, emotion_key, trip_id=trip_id, refresh_related=False)
        if trip_id:
            touched_trips.add(str(trip_id))
    if not touched_trips:
        try:
            rows = (
                supabase_client().table(PHOTO_TABLE)
                .select("id,trip_id")
                .in_("id", list(latest.keys()))
                .eq("family_key", current_family_key())
                .eq("member_key", current_member_key())
                .execute()
            ).data or []
            touched_trips.update(str(row.get("trip_id") or "") for row in rows if row.get("trip_id"))
        except Exception:
            pass
    _refresh_after_photo_emotion_changes(touched_trips)
    return latest


def update_photo_parenting_tag(photo_id, tag_key, trip_id=None, refresh_related=True):
    """Persist one parent-facing child-rearing tag independently of normal emotion."""
    tag_key = normalize_parenting_tag_key(tag_key)
    if tag_key and tag_key not in PARENTING_TAGS:
        raise ValueError("こどもーどアイコンの種類を確認できませんでした。")

    client = supabase_client()
    query = (
        client.table(PHOTO_TABLE)
        .select("id,trip_id,reflection_json")
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .limit(1)
        .execute()
    )
    row = (query.data or [None])[0] or {}
    if not row.get("id"):
        raise ValueError("こどもーどアイコンを設定する写真が見つかりませんでした。")
    resolved_trip_id = str(trip_id or row.get("trip_id") or "")
    reflection = row.get("reflection_json") or {}
    if not isinstance(reflection, dict):
        reflection = {}

    if tag_key:
        reflection["parenting_tag"] = parenting_tag_record(tag_key, source="parent_tap_cycle_v168")
        reflection.pop("emotion", None)
    else:
        reflection.pop("parenting_tag", None)
    reflection = _sync_photo_family_share_tag_snapshot(reflection)

    (
        client.table(PHOTO_TABLE)
        .update({"reflection_json": reflection})
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .execute()
    )
    if refresh_related:
        _refresh_after_photo_emotion_changes([resolved_trip_id] if resolved_trip_id else [])
    return tag_key


def update_photo_parenting_tags_batch(changes, valid_photo_ids=None, trip_id=None):
    """Persist final parenting-mode tags when the next real app interaction occurs."""
    valid = {str(value) for value in (valid_photo_ids or []) if str(value)} if valid_photo_ids is not None else None
    latest = {}
    for change in changes or []:
        if not isinstance(change, dict):
            continue
        photo_id = str(change.get("photo_id") or "").strip()
        if not photo_id or (valid is not None and photo_id not in valid):
            continue
        latest[photo_id] = normalize_parenting_tag_key(change.get("parenting"))
    if not latest:
        return {}

    touched_trips = set()
    for photo_id, tag_key in latest.items():
        update_photo_parenting_tag(photo_id, tag_key, trip_id=trip_id, refresh_related=False)
        if trip_id:
            touched_trips.add(str(trip_id))
    if not touched_trips:
        try:
            rows = (
                supabase_client().table(PHOTO_TABLE)
                .select("id,trip_id")
                .in_("id", list(latest.keys()))
                .eq("family_key", current_family_key())
                .eq("member_key", current_member_key())
                .execute()
            ).data or []
            touched_trips.update(str(row.get("trip_id") or "") for row in rows if row.get("trip_id"))
        except Exception:
            pass
    _refresh_after_photo_emotion_changes(touched_trips)
    return latest


def update_photo_tags_combined_v166(emotion_changes=None, parenting_changes=None):
    """Persist both tag axes with one row read/write per photo and one diary refresh."""
    emotion_latest = {}
    for change in emotion_changes or []:
        if isinstance(change, dict):
            pid = str(change.get("photo_id") or "").strip()
            if pid:
                emotion_latest[pid] = normalize_photo_emotion_key(change.get("emotion"))
    parenting_latest = {}
    for change in parenting_changes or []:
        if isinstance(change, dict):
            pid = str(change.get("photo_id") or "").strip()
            if pid:
                parenting_latest[pid] = normalize_parenting_tag_key(change.get("parenting"))

    photo_ids = sorted(set(emotion_latest) | set(parenting_latest))
    if not photo_ids:
        return {"emotion": emotion_latest, "parenting": parenting_latest}

    client = supabase_client()
    owner = _owner_v468()
    rows = _rows_v468(client, PHOTO_TABLE, owner, "id", photo_ids, "id,trip_id,reflection_json")
    row_map = {str(row.get("id") or ""): row for row in rows if row.get("id")}
    touched_trips = set()

    def save_one(photo_id):
        row = row_map.get(photo_id)
        if not row:
            return ""
        emotion_present = photo_id in emotion_latest
        parenting_present = photo_id in parenting_latest
        emotion_key = emotion_latest.get(photo_id, "")
        tag_key = parenting_latest.get(photo_id, "")
        def merge(reflection):
            original = dict(reflection)
            current = {"reflection_json": reflection}
            if emotion_present and emotion_key:
                if photo_emotion_key(current) != emotion_key or reflection.get("parenting_tag"):
                    reflection["emotion"] = photo_emotion_record(emotion_key, source="child_tap_batch_v168")
                    reflection.pop("parenting_tag", None)
            elif parenting_present and tag_key:
                if normalize_parenting_tag_key((reflection.get("parenting_tag") or {}).get("key")) != tag_key or reflection.get("emotion"):
                    reflection["parenting_tag"] = parenting_tag_record(tag_key, source="parent_tap_batch_v168")
                    reflection.pop("emotion", None)
            else:
                if emotion_present:
                    reflection.pop("emotion", None)
                if parenting_present:
                    reflection.pop("parenting_tag", None)
            return reflection if reflection == original else _sync_photo_family_share_tag_snapshot(reflection)
        _json_cas_v468(client, PHOTO_TABLE, owner, photo_id, "reflection_json", merge, initial_row=row)
        return str(row.get("trip_id") or "")
    # Independent photos only; no worker touches Streamlit session state.
    touched_trips.update(x for x in _read_executor_v467().map(save_one, photo_ids) if x)

    _refresh_after_photo_emotion_changes(touched_trips)
    return {"emotion": emotion_latest, "parenting": parenting_latest}


# ============================================================
# Deferred browser emotion persistence (v159)
# ============================================================
# Choosing a feeling must not cause a Streamlit rerun. Browser components write a
# compact pending payload into the current URL with history.replaceState(), which
# does not navigate. The next real app interaction/rerun consumes it here *before*
# the requested page action is rendered, so diary generation / keeping a moment can
# use the newest choices without making emotion taps themselves reload the page.
PENDING_EMOTION_QUERY_PARAM = "feel_v159"


def _decode_pending_emotion_query(raw_value):
    raw = str(raw_value or "").strip()
    if not raw or len(raw) > 24000:
        return None
    try:
        padded = raw + ("=" * ((4 - len(raw) % 4) % 4))
        payload = json.loads(base64.urlsafe_b64decode(padded.encode("ascii")).decode("utf-8"))
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


def _query_param_scalar(name):
    try:
        value = st.query_params.get(name, "")
    except Exception:
        return ""
    if isinstance(value, (list, tuple)):
        value = value[-1] if value else ""
    return str(value or "").strip()


def consume_pending_emotion_query():
    """Persist browser-only feeling choices on the next non-emotion app rerun.

    Returns True when a pending payload was successfully consumed. Failures leave
    the URL payload intact so a later interaction can retry instead of losing the
    child's selections.
    """
    raw = _query_param_scalar(PENDING_EMOTION_QUERY_PARAM)
    payload = _decode_pending_emotion_query(raw)
    if not payload:
        return False

    token = str(payload.get("t") or "").strip()
    if not token:
        return False

    # Never apply one person's browser-pending choices to another login.
    if str(payload.get("f") or "") != str(current_family_key()) or str(payload.get("m") or "") != str(current_member_key()):
        st.session_state["_emotion_query_ack_token"] = token
        return False

    if token == str(st.session_state.get("_emotion_query_processed_token") or ""):
        st.session_state["_emotion_query_ack_token"] = token
        return True

    try:
        photo_map = payload.get("p") or {}
        photo_changes = []
        if isinstance(photo_map, dict):
            for photo_id, emotion in photo_map.items():
                pid = str(photo_id or "").strip()
                if pid:
                    photo_changes.append({"photo_id": pid, "emotion": normalize_photo_emotion_key(emotion)})
        parenting_map = payload.get("g") or {}
        parenting_changes = []
        if isinstance(parenting_map, dict):
            for photo_id, parenting in parenting_map.items():
                pid = str(photo_id or "").strip()
                if pid:
                    parenting_changes.append({"photo_id": pid, "parenting": normalize_parenting_tag_key(parenting)})
        if photo_changes or parenting_changes:
            update_photo_tags_combined_v166(photo_changes, parenting_changes)

        moments = payload.get("x") or {}
        if isinstance(moments, dict):
            for video_id, state in moments.items():
                vid = str(video_id or "").strip()
                if not vid or not isinstance(state, dict):
                    continue
                try:
                    round_number = max(0, int(state.get("r") or 0))
                except Exception:
                    round_number = 0

                selected_raw = state.get("s") or []
                selected = sorted({
                    int(value)
                    for value in selected_raw
                    if str(value).strip().lstrip("-").isdigit() and int(value) > 0
                }) if isinstance(selected_raw, (list, tuple)) else []
                st.session_state[f"_moments_tap_selected_{vid}_{round_number}"] = selected

                emotion_map = state.get("e") or {}
                changes = []
                if isinstance(emotion_map, dict):
                    for rank_value, emotion in emotion_map.items():
                        try:
                            rank = int(rank_value)
                        except Exception:
                            rank = 0
                        if rank > 0:
                            changes.append({"rank": rank, "emotion": normalize_photo_emotion_key(emotion)})

                parenting_state_map = state.get("g") or {}
                parenting_changes = []
                if isinstance(parenting_state_map, dict):
                    for rank_value, parenting in parenting_state_map.items():
                        try:
                            rank = int(rank_value)
                        except Exception:
                            rank = 0
                        if rank > 0:
                            parenting_changes.append({"rank": rank, "parenting": normalize_parenting_tag_key(parenting)})
                if not changes and not parenting_changes:
                    continue

                row = (
                    supabase_client().table(PHOTO_TABLE)
                    .select("*")
                    .eq("id", vid)
                    .eq("family_key", current_family_key())
                    .eq("member_key", current_member_key())
                    .limit(1)
                    .execute()
                ).data or []
                video_photo = row[0] if row else None
                if video_photo and photo_is_video(video_photo):
                    update_video_ai_selection_tags(
                        video_photo,
                        emotion_changes=changes,
                        parenting_changes=parenting_changes,
                    )

        st.session_state["_emotion_query_processed_token"] = token
        st.session_state["_emotion_query_ack_token"] = token
        return True
    except Exception as exc:
        st.session_state["_emotion_sync_warning"] = (
            "選んだ気持ちの保存を次の操作でもう一度試します。"
        )
        st.session_state["_emotion_sync_warning_detail"] = _safe_error_text(exc, 700)
        return False


