def _nearby_localized_text_v459(value):
    """Normalize Google LocalizedText without ever exposing its object representation."""
    if isinstance(value, dict):
        return str(value.get("text") or "").strip()
    raw = str(value or "").strip()
    if not raw:
        return ""
    # Older session state can retain a stringified LocalizedText object across a hot reload.
    # Recover only the human-readable text field.
    if raw.startswith("{") and "text" in raw:
        match = re.search(r"['\"]text['\"]\s*:\s*['\"]([^'\"]+)['\"]", raw)
        if match:
            return str(match.group(1) or "").strip()
    return raw


def _nearby_detailed_genre_text(place):
    """Return a compact, pre-detail genre description from data already in search results."""
    place = place if isinstance(place, dict) else {}
    kind = str(place.get("kind") or "").strip()
    category = str(place.get("category") or "").strip()
    labels = []

    def add(label):
        label = str(label or "").strip()
        if not label or label in {"おまかせ", "ランチ", "レストラン"}:
            return
        # Avoid near-duplicate labels such as イタリアン / イタリア料理店.
        normalized = re.sub(r"[・\s　()（）/／_-]+", "", label).replace("料理店", "").replace("店", "")
        for existing in labels:
            existing_norm = re.sub(r"[・\s　()（）/／_-]+", "", existing).replace("料理店", "").replace("店", "")
            if normalized == existing_norm or (normalized and existing_norm and (normalized in existing_norm or existing_norm in normalized)):
                return
        labels.append(label)

    # Lunch searches already remember which fine-grained atomic query matched the place.
    if kind == "lunch":
        for label in list(place.get("lunch_atomic_genres") or []):
            add(label)

    # Google types are more specific than the broad UI group and cost no extra request.
    for google_type in list(place.get("google_types") or []):
        add(NEARBY_GOOGLE_TYPE_DETAIL_LABELS.get(str(google_type or "").strip()))

    # Google returns localized labels as LocalizedText objects. Extract only .text so
    # internal {'text': ..., 'languageCode': ...} data never leaks into the UI.
    google_label = _nearby_localized_text_v459(place.get("google_maps_type_label"))
    if google_label:
        add(google_label)
    primary_label = _nearby_localized_text_v459(place.get("google_primary_type_label"))
    if primary_label:
        add(primary_label)

    # For OpenStreetMap fallback or sparse Google results, retain the existing category.
    if not labels:
        add(category)

    if not labels:
        return ""

    # Do not add a second line when it would merely repeat the broad category verbatim.
    joined = "・".join(labels[:3])
    if re.sub(r"\s+", "", joined) == re.sub(r"\s+", "", category):
        return ""
    return joined


def _nearby_place_priority(tags, kind):
    if kind != "snack":
        return 0
    tags = tags if isinstance(tags, dict) else {}
    name = str(tags.get("name:ja") or tags.get("name") or "")
    direct_terms = ("\u5927\u798f", "\u56e3\u5b50", "\u3060\u3093\u3054", "\u305f\u3044\u713c", "\u9bdb\u713c", "\u548c\u83d3\u5b50", "\u30b1\u30fc\u30ad", "\u6d0b\u83d3\u5b50", "\u30a2\u30a4\u30b9", "\u30b8\u30a7\u30e9\u30fc\u30c8", "\u30bd\u30d5\u30c8\u30af\u30ea\u30fc\u30e0", "\u304b\u304d\u6c37", "\u30af\u30ec\u30fc\u30d7", "\u30c9\u30fc\u30ca\u30c4", "\u30d7\u30ea\u30f3")
    if tags.get("amenity") == "ice_cream" or tags.get("shop") in {"bakery", "confectionery", "pastry", "chocolate"}:
        return 0
    if any(term in name for term in direct_terms):
        return 0
    return 1


