def _nearby_lunch_atomic_query_specs(subkind):
    group = str(subkind or "おまかせ")
    members = NEARBY_LUNCH_GROUP_MEMBERS.get(group) or ("おまかせ",)
    specs = []
    for member in members:
        query = NEARBY_LUNCH_ATOMIC_QUERIES.get(member)
        if query:
            specs.append((member, query))
    return specs or [("おまかせ", NEARBY_LUNCH_ATOMIC_QUERIES["おまかせ"])]

def _nearby_lunch_text_query(subkind):
    # Compatibility helper used outside the multi-query lunch path.
    specs = _nearby_lunch_atomic_query_specs(subkind)
    return specs[0][1]


def _nearby_google_text_query(kind, subkind):
    if kind == "snack":
        mapping = {
            "食べ歩き向き": "食べ歩き テイクアウト おやつ たい焼き 団子 クレープ ドーナツ ソフトクリーム アイス パン ベーカリー 焼き菓子 おにぎり 肉まん",
            "店内中心": "カフェ 喫茶店 スイーツ デザート ケーキ 甘味処 プリン かき氷",
        }
        return mapping.get(str(subkind), mapping["食べ歩き向き"])
    if kind == "lunch":
        return _nearby_lunch_text_query(subkind)
    if kind == "rain_sightseeing":
        return "屋内 観光 博物館 美術館 科学館 資料館 記念館 展示館 水族館 プラネタリウム ミュージアム 屋内施設"
    mapping = {
        "なんでも": "観光スポット 公園 神社 寺 博物館 鉄道",
        "公園": "公園 庭園 遊歩道",
        "神社・寺": "神社 寺 寺院",
        "博物館・施設": "博物館 美術館 見学施設",
        "電車・乗り物": "鉄道 電車 車両 博物館 交通",
    }
    return mapping.get(str(subkind), mapping["なんでも"])


def _nearby_google_photo_refs(photo_rows, limit=10):
    refs = []
    for row in list(photo_rows or [])[:max(1, int(limit))]:
        if not isinstance(row, dict):
            continue
        name = str(row.get("name") or "").strip()
        if not name:
            continue
        attribution = ""
        attrs = row.get("authorAttributions") or []
        if isinstance(attrs, list):
            names = []
            for attr in attrs[:2]:
                if isinstance(attr, dict):
                    label = str(attr.get("displayName") or "").strip()
                    if label and label not in names:
                        names.append(label)
            attribution = " / ".join(names)
        refs.append({"name": name, "attribution": attribution})
    return refs


def search_nearby_quick_stops_google(latitude, longitude, kind, subkind, radius_m, open_now_only=False, budget_under_1000=False, budget_limit=None):
    """Search Google Places around the phone's fresh GPS fix.

    v223: snack discovery uses Nearby Search (New) with snack-specific place types instead of
    a long free-text keyword string.  Generic takeaway restaurants are deliberately excluded:
    "takeaway" is a serving method, not evidence that a place is an snack shop.
    """
    if not GOOGLE_PLACES_API_KEY:
        return None
    try:
        latitude = float(latitude)
        longitude = float(longitude)
        radius_m = max(50, min(4000, int(radius_m)))
    except (TypeError, ValueError):
        return {"places": [], "error": "現在地を確認できませんでした。", "provider": "Google Places"}

    is_snack = str(kind) == "snack"
    is_lunch = str(kind) == "lunch"
    is_rain_sightseeing = str(kind) == "rain_sightseeing"
    snack_style = str(subkind or "食べ歩き向き")
    lunch_genre = str(subkind or "おまかせ") if is_lunch else ""

    # For snacks, Nearby Search is a better fit than Text Search. Lunch keeps the
    # compact UI groups, but each original genre is searched independently and the
    # results are merged/deduplicated before distance, budget and rating evaluation.
    field_mask = (
        "places.id,places.displayName,places.formattedAddress,places.location,places.types,places.primaryType,"
        "places.primaryTypeDisplayName,places.googleMapsTypeLabel,places.photos,places.businessStatus,places.currentOpeningHours,places.rating,places.userRatingCount,"
        "places.priceLevel,places.priceRange,places.takeout,places.dineIn,places.servesDessert"
    )

    if is_snack:
        if snack_style == "店内中心":
            included_types = [
                "cafe", "coffee_shop", "tea_house", "dessert_restaurant",
                "dessert_shop", "cake_shop", "ice_cream_shop", "pastry_shop",
                "confectionery", "bakery", "bagel_shop", "donut_shop",
                "candy_store", "chocolate_shop",
            ]
        else:
            included_types = [
                "bakery", "bagel_shop", "cake_shop", "candy_store",
                "chocolate_shop", "confectionery", "dessert_shop", "donut_shop",
                "ice_cream_shop", "pastry_shop",
            ]
        discovery_radius = min(50000.0, max(float(radius_m) + 35.0, float(radius_m) * 1.25))
        body = {
            "includedTypes": included_types,
            "maxResultCount": 20,
            "rankPreference": "DISTANCE",
            "languageCode": "ja",
            "regionCode": "JP",
            "locationRestriction": {
                "circle": {
                    "center": {"latitude": latitude, "longitude": longitude},
                    "radius": discovery_radius,
                }
            },
        }
        endpoint = "https://places.googleapis.com/v1/places:searchNearby"
        req = Request(
            endpoint,
            data=json.dumps(body, ensure_ascii=False).encode("utf-8"),
            headers={
                "Content-Type": "application/json; charset=UTF-8",
                "X-Goog-Api-Key": GOOGLE_PLACES_API_KEY,
                "X-Goog-FieldMask": field_mask,
            },
            method="POST",
        )
        try:
            with urlopen(req, timeout=7.0) as response:
                data = json.loads(response.read().decode("utf-8"))
        except Exception as exc:
            return {
                "places": [],
                "error": "画像つき周辺検索につながりませんでした。",
                "detail": str(exc)[:260],
                "provider": "Google Places",
            }
        lunch_query_count = 0
        lunch_atomic_genres = []
    else:
        if is_lunch:
            query_specs = _nearby_lunch_atomic_query_specs(lunch_genre)
        else:
            query_specs = [(str(subkind or ""), _nearby_google_text_query(kind, subkind))]

        def _run_text_search(spec):
            genre_label, query_text = spec
            genre_label = str(genre_label)
            errors = []

            # v319: preserve the same two Google lookups, but run them concurrently.
            # This keeps the fine-grained text search + exact place-type coverage while
            # avoiding the old serial wait (text request, then type request) for every genre.
            request_body = {
                "textQuery": str(query_text),
                "languageCode": "ja",
                "regionCode": "JP",
                "maxResultCount": 20,
                "locationBias": {
                    "circle": {
                        "center": {"latitude": latitude, "longitude": longitude},
                        "radius": float(radius_m),
                    }
                },
            }
            if bool(open_now_only):
                request_body["openNow"] = True
            text_request = Request(
                "https://places.googleapis.com/v1/places:searchText",
                data=json.dumps(request_body, ensure_ascii=False).encode("utf-8"),
                headers={
                    "Content-Type": "application/json; charset=UTF-8",
                    "X-Goog-Api-Key": GOOGLE_PLACES_API_KEY,
                    "X-Goog-FieldMask": field_mask,
                },
                method="POST",
            )

            place_types = tuple(NEARBY_LUNCH_ATOMIC_PLACE_TYPES.get(genre_label) or ()) if is_lunch else ()
            nearby_request = None
            if place_types:
                nearby_body = {
                    "includedTypes": list(place_types),
                    "maxResultCount": 20,
                    "rankPreference": "DISTANCE",
                    "languageCode": "ja",
                    "regionCode": "JP",
                    "locationRestriction": {
                        "circle": {
                            "center": {"latitude": latitude, "longitude": longitude},
                            "radius": float(radius_m),
                        }
                    },
                }
                nearby_request = Request(
                    "https://places.googleapis.com/v1/places:searchNearby",
                    data=json.dumps(nearby_body, ensure_ascii=False).encode("utf-8"),
                    headers={
                        "Content-Type": "application/json; charset=UTF-8",
                        "X-Goog-Api-Key": GOOGLE_PLACES_API_KEY,
                        "X-Goog-FieldMask": field_mask,
                    },
                    method="POST",
                )

            def _fetch(req, label):
                try:
                    with urlopen(req, timeout=6.0) as response:
                        payload = json.loads(response.read().decode("utf-8"))
                    return label, list((payload or {}).get("places") or []), ""
                except Exception as exc:
                    return label, [], str(exc)[:180]

            jobs = [("text", text_request)]
            if nearby_request is not None:
                jobs.append(("type", nearby_request))
            collected = []
            if len(jobs) == 1:
                label, rows, error = _fetch(jobs[0][1], jobs[0][0])
                collected.extend(rows)
                if error:
                    errors.append(label + ":" + error)
            else:
                with ThreadPoolExecutor(max_workers=2) as pair_pool:
                    futures = [pair_pool.submit(_fetch, req, label) for label, req in jobs]
                    for future in futures:
                        label, rows, error = future.result()
                        collected.extend(rows)
                        if error:
                            errors.append(label + ":" + error)

            deduped = {}
            for raw in collected:
                if not isinstance(raw, dict):
                    continue
                pid = str(raw.get("id") or "").strip()
                if pid:
                    key = "id:" + pid
                else:
                    display = raw.get("displayName") if isinstance(raw.get("displayName"), dict) else {}
                    loc = raw.get("location") if isinstance(raw.get("location"), dict) else {}
                    key = f"fallback:{str(display.get('text') or '').strip().lower()}:{loc.get('latitude')}:{loc.get('longitude')}"
                if key not in deduped:
                    deduped[key] = raw
            if deduped:
                return {"genre": genre_label, "data": {"places": list(deduped.values())}, "error": ""}
            return {"genre": genre_label, "data": {}, "error": " / ".join(errors)[:260] or "no results"}

        if len(query_specs) <= 1:
            query_results = [_run_text_search(query_specs[0])]
        else:
            worker_count = max(1, min(4, len(query_specs)))
            with ThreadPoolExecutor(max_workers=worker_count) as executor:
                query_results = list(executor.map(_run_text_search, query_specs))

        successful = [row for row in query_results if isinstance(row, dict) and not row.get("error")]
        if not successful:
            details = " / ".join(str(row.get("error") or "") for row in query_results if isinstance(row, dict) and row.get("error"))
            return {
                "places": [],
                "error": "画像つき周辺検索につながりませんでした。",
                "detail": details[:260],
                "provider": "Google Places",
            }

        merged_places = {}
        for search_result in successful:
            genre_label = str(search_result.get("genre") or "")
            payload = search_result.get("data") if isinstance(search_result.get("data"), dict) else {}
            for raw in list(payload.get("places") or []):
                if not isinstance(raw, dict):
                    continue
                place_id = str(raw.get("id") or "").strip()
                if place_id:
                    merge_key = "id:" + place_id
                else:
                    display = raw.get("displayName") if isinstance(raw.get("displayName"), dict) else {}
                    name_key = str(display.get("text") or "").strip().lower()
                    loc = raw.get("location") if isinstance(raw.get("location"), dict) else {}
                    merge_key = f"fallback:{name_key}:{loc.get('latitude')}:{loc.get('longitude')}"
                if merge_key not in merged_places:
                    merged_places[merge_key] = dict(raw)
                    if is_lunch:
                        merged_places[merge_key]["_matched_lunch_atomic_genres"] = []
                if is_lunch and genre_label:
                    labels = merged_places[merge_key].setdefault("_matched_lunch_atomic_genres", [])
                    if genre_label not in labels:
                        labels.append(genre_label)

        data = {"places": list(merged_places.values())}
        lunch_query_count = len(query_specs) if is_lunch else 0
        lunch_atomic_genres = [str(spec[0]) for spec in query_specs] if is_lunch else []

    places = []
    raw_count = 0
    in_range_count = 0
    snack_candidate_count = 0
    open_candidate_count = 0

    snack_terms = (
        "大福", "団子", "だんご", "たい焼", "鯛焼", "どら焼", "饅頭", "まんじゅう",
        "おはぎ", "最中", "羊羹", "せんべい", "煎餅", "和菓子", "洋菓子", "ケーキ",
        "パティスリー", "焼き菓子", "クッキー", "スコーン", "マフィン", "カヌレ", "タルト",
        "アイス", "ジェラート", "ソフトクリーム", "かき氷", "クレープ", "ドーナツ", "シュー",
        "プリン", "スイーツ", "パン", "ベーカリー", "チョコ", "ワッフル", "チュロス",
    )
    portable_name_terms = snack_terms
    strong_snack_types = {
        "bakery", "bagel_shop", "cake_shop", "candy_store", "chocolate_shop",
        "confectionery", "dessert_shop", "donut_shop", "ice_cream_shop", "pastry_shop",
        "dessert_restaurant",
    }
    cafe_types = {"cafe", "coffee_shop", "tea_house"}
    sitdown_types = cafe_types | {"dessert_restaurant", "dessert_shop"}

    def _looks_like_meal_place(place_types):
        place_types = {str(x) for x in (place_types or set()) if str(x)}
        if any(t == "restaurant" or t.endswith("_restaurant") for t in place_types):
            return True
        return bool(place_types.intersection({
            "bar", "pub", "night_club", "meal_takeaway", "meal_delivery",
            "food_court", "diner", "cafeteria", "deli", "bar_and_grill",
            "wine_bar", "sandwich_shop",
        }))

    def _walking_suitability_rank(place_name, place_types, primary_type_value, takeout_value, serves_dessert_value):
        """Rank portable-snack suitability first; distance breaks ties later.

        0 = clearly hand-held / snack-specialist, 1 = portable bakery/sweets,
        2 = dessert shop with takeout potential, 3 = cafe/tea shop or weak evidence.
        A cafe must not outrank a true street-snack shop merely because Google also
        assigns it a secondary bakery/confectionery type.
        """
        name_text = str(place_name or "")
        type_set = {str(x) for x in (place_types or set()) if str(x)}
        primary = str(primary_type_value or "")
        explicit_handheld_terms = (
            "大福", "団子", "だんご", "たい焼", "鯛焼", "どら焼", "今川焼", "大判焼",
            "回転焼", "人形焼", "おはぎ", "最中", "せんべい", "煎餅", "クレープ",
            "ドーナツ", "アイス", "ジェラート", "ソフトクリーム", "ワッフル",
            "チュロス", "焼き菓子", "クッキー", "スコーン", "マフィン", "カヌレ",
        )
        cafe_primary_types = {"cafe", "coffee_shop", "tea_house"}
        top_portable_primary_types = {
            "donut_shop", "ice_cream_shop", "candy_store", "chocolate_shop",
            "confectionery", "pastry_shop",
        }
        bakery_primary_types = {"bakery", "bagel_shop"}
        dessert_types = {"cake_shop", "dessert_shop", "dessert_restaurant"}

        # Actual product words in the shop name are the strongest signal.
        if any(term in name_text for term in explicit_handheld_terms):
            return 0

        # A cafe/coffee/tea shop stays below genuine take-away snack specialists even
        # when Google attaches bakery or confectionery as a secondary type.
        if primary in cafe_primary_types:
            return 3

        if primary in top_portable_primary_types:
            return 0
        if primary in bakery_primary_types:
            return 1
        if primary in dessert_types:
            return 1 if takeout_value is True else 2

        # Secondary types are useful, but weaker than the primary business identity.
        if type_set.intersection(top_portable_primary_types):
            return 1
        if type_set.intersection(bakery_primary_types):
            return 1
        if type_set.intersection(dessert_types):
            return 2 if takeout_value is True else 3
        if serves_dessert_value is True and takeout_value is True:
            return 2
        return 3

    for raw in list((data or {}).get("places") or []):
        if not isinstance(raw, dict):
            continue
        raw_count += 1
        name = str(((raw.get("displayName") or {}).get("text") if isinstance(raw.get("displayName"), dict) else "") or "").strip()
        loc = raw.get("location") or {}
        try:
            plat = float(loc.get("latitude"))
            plon = float(loc.get("longitude"))
        except (TypeError, ValueError):
            continue
        if not name:
            continue
        business_status = str(raw.get("businessStatus") or "").strip()
        if business_status == "CLOSED_PERMANENTLY":
            continue

        distance_m = _nearby_haversine_m(latitude, longitude, plat, plon)
        distance_limit = float(radius_m) if (is_snack or is_lunch) else float(radius_m) * 1.25
        if not math.isfinite(distance_m) or distance_m > distance_limit:
            continue
        in_range_count += 1

        types = {str(x) for x in (raw.get("types") or []) if str(x)}
        primary_type = str(raw.get("primaryType") or "")
        if primary_type:
            types.add(primary_type)

        rain_reason = ""
        if is_rain_sightseeing:
            strong_indoor_types = {
                "museum", "art_gallery", "aquarium", "shopping_mall",
                "visitor_center", "cultural_center", "amusement_center"
            }
            outdoor_types = {"park", "garden", "hiking_area", "campground", "beach"}
            indoor_name_terms = (
                "博物館", "美術館", "科学館", "資料館", "記念館", "展示館", "水族館",
                "プラネタリウム", "ミュージアム", "屋内", "室内", "地下街", "展望室"
            )
            strong_type = bool(types.intersection(strong_indoor_types))
            strong_name = any(term in name for term in indoor_name_terms)
            if types.intersection(outdoor_types) and not (strong_type or strong_name):
                continue
            if not (strong_type or strong_name):
                # A generic tourist_attraction can be outdoors; do not claim rain protection
                # unless the place type or name itself provides strong indoor evidence.
                continue
            rain_reason = "屋内施設" if strong_type else "屋内を示す施設名"

        takeout = raw.get("takeout") if isinstance(raw.get("takeout"), bool) else None
        dine_in = raw.get("dineIn") if isinstance(raw.get("dineIn"), bool) else None
        serves_dessert = raw.get("servesDessert") if isinstance(raw.get("servesDessert"), bool) else None
        hours = raw.get("currentOpeningHours") if isinstance(raw.get("currentOpeningHours"), dict) else {}

        if is_snack:
            direct_name_signal = any(term in name for term in snack_terms)
            strong_type_signal = bool(types.intersection(strong_snack_types))
            cafe_signal = bool(types.intersection(cafe_types))

            # A takeaway flag alone must never turn a restaurant/izakaya into a snack.
            # Meal-like places are accepted only when Google/name data independently says
            # they are dessert/snack specialists (e.g. dessert_restaurant).
            meal_like = _looks_like_meal_place(types)
            snack_identity = strong_type_signal or direct_name_signal or serves_dessert is True
            if meal_like and not (strong_type_signal or direct_name_signal):
                continue

            if snack_style == "食べ歩き向き":
                # For portable snacks, the place itself must be snack-oriented.  Specialty
                # bakeries/sweets shops are assumed portable; cafes need explicit dessert
                # identity plus takeaway availability.
                portable_signal = (
                    strong_type_signal
                    or any(term in name for term in portable_name_terms)
                    or (cafe_signal and snack_identity and takeout is True)
                )
                if not snack_identity or not portable_signal:
                    continue
            else:
                # A normal cafe is reasonable for the sit-down option, while ordinary
                # restaurants/bars remain excluded by the meal_like guard above.
                sitdown_identity = snack_identity or cafe_signal
                sitdown_signal = (
                    dine_in is True
                    or bool(types.intersection(sitdown_types))
                    or any(term in name for term in ("カフェ", "喫茶", "甘味", "ケーキ", "パティスリー", "デザート"))
                )
                if not sitdown_identity or not sitdown_signal:
                    continue
            snack_candidate_count += 1

            # Nearby Search (New) does not have an openNow request parameter.  Apply
            # the user's "営業中だけ" choice using Google's currentOpeningHours result.
            if bool(open_now_only):
                if hours.get("openNow") is not True:
                    continue
            open_candidate_count += 1
        else:
            if bool(open_now_only) and hours.get("openNow") is False:
                continue

        walk_minutes = max(1, int(math.ceil((distance_m * 1.25) / 80.0)))
        pseudo_tags = {"name": name}
        if is_snack:
            if "ice_cream_shop" in types:
                pseudo_tags["amenity"] = "ice_cream"
            elif "bakery" in types or "bagel_shop" in types:
                pseudo_tags["shop"] = "bakery"
            elif types.intersection({"candy_store", "dessert_shop", "confectionery", "chocolate_shop", "cake_shop", "pastry_shop", "donut_shop"}):
                pseudo_tags["shop"] = "confectionery"
        matched_lunch_atomic_genres = [
            str(x) for x in (raw.get("_matched_lunch_atomic_genres") or []) if str(x).strip()
        ] if is_lunch else []
        if is_snack and primary_type in cafe_types:
            category = "カフェ・喫茶"
        elif is_rain_sightseeing:
            category = "雨でも安心・屋内観光"
        elif is_lunch:
            if matched_lunch_atomic_genres and matched_lunch_atomic_genres != ["おまかせ"]:
                category = "・".join(matched_lunch_atomic_genres[:2])
            else:
                category = lunch_genre if lunch_genre != "おまかせ" else "ランチ"
        else:
            category = _nearby_place_label(pseudo_tags, kind)
        refs = _nearby_google_photo_refs(raw.get("photos") or [], limit=10)
        try:
            rating = float(raw.get("rating")) if raw.get("rating") is not None else None
        except (TypeError, ValueError):
            rating = None
        try:
            rating_count = max(0, int(raw.get("userRatingCount") or 0))
        except (TypeError, ValueError):
            rating_count = 0
        price_level = str(raw.get("priceLevel") or "").strip()
        price_range = raw.get("priceRange") if isinstance(raw.get("priceRange"), dict) else {}
        walkability_rank = 0
        if is_snack and snack_style == "\u98df\u3079\u6b69\u304d\u5411\u304d":
            walkability_rank = _walking_suitability_rank(name, types, primary_type, takeout, serves_dessert)
        places.append({
            "id": f"google:{raw.get('id') or hashlib.sha1((name+str(plat)+str(plon)).encode()).hexdigest()[:16]}",
            "google_place_id": str(raw.get("id") or ""),
            "name": name,
            "kind": str(kind),
            "category": category,
            "latitude": plat,
            "longitude": plon,
            "distance_m": int(round(distance_m)),
            "walk_minutes": walk_minutes,
            "opening_hours": "",
            "current_opening_hours": dict(hours),
            "business_status": business_status,
            "rating": rating,
            "user_rating_count": rating_count,
            "price_level": price_level,
            "price_range": dict(price_range),
            "address": str(raw.get("formattedAddress") or "").strip(),
            "priority": 0,
            "provider": "Google Places",
            "photo_refs": refs,
            "snack_style": snack_style if is_snack else "",
            "lunch_genre": lunch_genre if is_lunch else "",
            "lunch_atomic_genres": matched_lunch_atomic_genres if is_lunch else [],
            "takeout": takeout,
            "dine_in": dine_in,
            "serves_dessert": serves_dessert,
            "google_types": sorted(types),
            "google_maps_type_label": _nearby_localized_text_v459(raw.get("googleMapsTypeLabel")),
            "google_primary_type_label": _nearby_localized_text_v459(raw.get("primaryTypeDisplayName")),
            "walkability_rank": walkability_rank,
            "rain_suitable": bool(is_rain_sightseeing),
            "rain_suitable_reason": rain_reason if is_rain_sightseeing else "",
        })

    if is_lunch and budget_limit is not None:
        places = [item for item in places if _nearby_budget_match_limit(item, budget_limit)]
    elif bool(budget_under_1000):
        places = [item for item in places if _nearby_budget_match_1000(item)]
    if is_lunch:
        # Review-count-adjusted lunch score (Bayesian weighted rating).
        # A raw 5.0 from only a handful of reviews should not automatically outrank
        # a well-established 4.5 with hundreds of reviews.  The local candidate mean
        # acts as the prior, and 100 reviews is the confidence reference point.
        valid_ratings = []
        for item in places:
            try:
                raw_rating = float(item.get("rating"))
            except (TypeError, ValueError):
                continue
            if math.isfinite(raw_rating) and raw_rating > 0:
                valid_ratings.append(raw_rating)
        local_mean_rating = (sum(valid_ratings) / len(valid_ratings)) if valid_ratings else 4.0
        prior_review_count = 100.0

        for item in places:
            try:
                raw_rating = float(item.get("rating"))
                rating_valid = math.isfinite(raw_rating) and raw_rating > 0
            except (TypeError, ValueError):
                raw_rating = 0.0
                rating_valid = False
            try:
                reviews = max(0, int(item.get("user_rating_count") or 0))
            except (TypeError, ValueError):
                reviews = 0

            if rating_valid:
                weighted_rating = (
                    (reviews / (reviews + prior_review_count)) * raw_rating
                    + (prior_review_count / (reviews + prior_review_count)) * local_mean_rating
                )
                item["burari_rating"] = round(float(weighted_rating), 4)
                item["burari_rating_prior_mean"] = round(float(local_mean_rating), 4)
                item["burari_rating_prior_reviews"] = int(prior_review_count)
            else:
                item["burari_rating"] = None
                item["burari_rating_prior_mean"] = round(float(local_mean_rating), 4)
                item["burari_rating_prior_reviews"] = int(prior_review_count)

        # Display order: review-count-adjusted score, review volume, raw Google rating,
        # then walking distance. Places without ratings remain after rated places.
        def _lunch_rating_sort_key(item):
            try:
                score = float(item.get("burari_rating"))
                score_valid = math.isfinite(score) and score > 0
            except (TypeError, ValueError):
                score = 0.0
                score_valid = False
            try:
                reviews = max(0, int(item.get("user_rating_count") or 0))
            except (TypeError, ValueError):
                reviews = 0
            try:
                raw_rating = float(item.get("rating"))
                raw_valid = math.isfinite(raw_rating) and raw_rating > 0
            except (TypeError, ValueError):
                raw_rating = 0.0
                raw_valid = False
            return (
                0 if score_valid else 1,
                -score if score_valid else 0.0,
                -reviews,
                -raw_rating if raw_valid else 0.0,
                int(item.get("distance_m") or 0),
            )
        places.sort(key=_lunch_rating_sort_key)
    elif is_snack and snack_style == "\u98df\u3079\u6b69\u304d\u5411\u304d":
        places.sort(key=lambda item: (
            int(item.get("walkability_rank") or 0),
            int(item.get("distance_m") or 0),
        ))
    else:
        places.sort(key=lambda item: int(item.get("distance_m") or 0))
    return {
        "places": places[:24],
        "error": "",
        "provider": "Google Places",
        "open_now_only": bool(open_now_only),
        "budget_under_1000": bool(budget_under_1000),
        "budget_limit": int(budget_limit) if is_lunch and budget_limit is not None else None,
        "sort_mode": "review_weighted_rating" if is_lunch else ("walkability" if is_snack and snack_style == "食べ歩き向き" else "distance"),
        "search_mode": "nearby_types" if is_snack else ("atomic_text_plus_types" if is_lunch else "text"),
        "lunch_query_count": int(lunch_query_count) if is_lunch else 0,
        "lunch_atomic_genres": list(lunch_atomic_genres) if is_lunch else [],
        "raw_count": raw_count,
        "in_range_count": in_range_count,
        "snack_candidate_count": snack_candidate_count,
        "open_candidate_count": open_candidate_count,
    }

@st.cache_data(ttl=600, show_spinner=False)
def _nearby_google_photo_data_url(photo_ref, max_px=760):
    if not GOOGLE_PLACES_API_KEY or not isinstance(photo_ref, dict):
        return ""
    name = str(photo_ref.get("name") or "").strip()
    if not name:
        return ""
    safe_name = quote(name, safe="/")
    params = urlencode({
        "maxWidthPx": max(320, min(1200, int(max_px))),
        "maxHeightPx": max(240, min(900, int(max_px))),
        "key": GOOGLE_PLACES_API_KEY,
    })
    req = Request(
        f"https://places.googleapis.com/v1/{safe_name}/media?{params}",
        headers={"User-Agent": "TokyoBurariApp/1.0", "Accept": "image/*"},
    )
    try:
        with urlopen(req, timeout=3.8) as response:
            raw = response.read()
            content_type = str(response.headers.get("Content-Type") or "image/jpeg").split(";", 1)[0].strip()
        if not raw or not content_type.startswith("image/"):
            return ""
        return f"data:{content_type};base64," + base64.b64encode(raw).decode("ascii")
    except Exception:
        return ""


def _nearby_load_preview_images(places):
    places = list(places or [])[:6]
    jobs = []
    for place in places:
        refs = list((place or {}).get("photo_refs") or [])
        jobs.append(refs[0] if refs else None)
    results = [""] * len(jobs)
    work = [(idx, ref) for idx, ref in enumerate(jobs) if isinstance(ref, dict)]
    if not work:
        return results
    workers = max(1, min(6, len(work)))
    def fetch(spec):
        idx, ref = spec
        return idx, _nearby_google_photo_data_url(ref, max_px=520)
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="burari-nearby-photo") as pool:
        for idx, data_url in pool.map(fetch, work):
            results[idx] = data_url
    return results


def _nearby_load_detail_images(place, limit=3):
    refs = list((place or {}).get("photo_refs") or [])[:max(1, int(limit))]
    if not refs:
        return []
    workers = max(1, min(3, len(refs)))
    def fetch(ref):
        return {
            "src": _nearby_google_photo_data_url(ref, max_px=900),
            "attribution": str(ref.get("attribution") or ""),
        }
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="burari-nearby-detail") as pool:
        return [item for item in pool.map(fetch, refs) if item.get("src")]


def _nearby_parse_place_time(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=JST)
        return dt.astimezone(JST)
    except Exception:
        return None


def _nearby_relative_time_label(value):
    dt = _nearby_parse_place_time(value)
    if dt is None:
        return ""
    today = now_jst().date()
    if dt.date() == today:
        prefix = ""
    elif dt.date() == today + timedelta(days=1):
        prefix = "明日 "
    else:
        prefix = f"{dt.month}/{dt.day} "
    return prefix + dt.strftime("%H:%M")


def _nearby_open_status(place):
    place = place if isinstance(place, dict) else {}
    business_status = str(place.get("business_status") or "").strip()
    if business_status == "CLOSED_PERMANENTLY":
        return {"label": "閉業", "css": "closed"}
    if business_status == "CLOSED_TEMPORARILY":
        return {"label": "臨時休業", "css": "closed"}
    hours = place.get("current_opening_hours") or {}
    if not isinstance(hours, dict):
        hours = {}
    open_now = hours.get("openNow")
    if open_now is True:
        label = "営業中"
        close_text = _nearby_relative_time_label(hours.get("nextCloseTime"))
        if close_text:
            label += f"・{close_text}まで"
        return {"label": label, "css": "open"}
    if open_now is False:
        label = "営業時間外"
        open_text = _nearby_relative_time_label(hours.get("nextOpenTime"))
        if open_text:
            label += f"・{open_text}から"
        return {"label": label, "css": "closed"}
    return {"label": "営業時間情報なし", "css": "unknown"}


def _nearby_rating_text(place):
    place = place if isinstance(place, dict) else {}
    try:
        rating = float(place.get("rating"))
    except (TypeError, ValueError):
        return ""
    if not math.isfinite(rating) or rating <= 0:
        return ""
    try:
        count = max(0, int(place.get("user_rating_count") or 0))
    except (TypeError, ValueError):
        count = 0
    return f"★ {rating:.1f}" + (f"（{count:,}件）" if count else "")


def _nearby_burari_rating_text(place):
    place = place if isinstance(place, dict) else {}
    try:
        score = float(place.get("burari_rating"))
    except (TypeError, ValueError):
        return ""
    if not math.isfinite(score) or score <= 0:
        return ""
    return f"ぶらり旅評価 {score:.2f}"


def _nearby_price_level_text(value):
    mapping = {
        "PRICE_LEVEL_FREE": "無料",
        "PRICE_LEVEL_INEXPENSIVE": "価格帯：お手頃",
        "PRICE_LEVEL_MODERATE": "価格帯：標準",
        "PRICE_LEVEL_EXPENSIVE": "価格帯：やや高め",
        "PRICE_LEVEL_VERY_EXPENSIVE": "価格帯：高め",
    }
    return mapping.get(str(value or "").strip(), "")


def _nearby_money_jpy(value):
    if not isinstance(value, dict):
        return None
    currency = str(value.get("currencyCode") or "").strip().upper()
    if currency and currency != "JPY":
        return None
    try:
        units = float(value.get("units") or 0)
        nanos = float(value.get("nanos") or 0) / 1_000_000_000.0
        amount = units + nanos
    except (TypeError, ValueError):
        return None
    if amount < 0 or not math.isfinite(amount):
        return None
    return amount


def _nearby_price_range_text(value):
    if not isinstance(value, dict):
        return ""
    start = _nearby_money_jpy(value.get("startPrice"))
    end = _nearby_money_jpy(value.get("endPrice"))
    if start is None and end is None:
        return ""
    if start is not None and end is not None:
        return f"価格目安：¥{int(round(start)):,}〜¥{int(round(end)):,}未満"
    if start is not None:
        return f"価格目安：¥{int(round(start)):,}〜"
    return f"価格目安：¥{int(round(end)):,}未満"


def _nearby_budget_match_limit(place, budget_limit):
    """Keep places that appear usable within the selected budget.

    Google price metadata is incomplete for many Japanese restaurants. Known prices are
    filtered; unknown prices remain visible so a good nearby option is not silently lost.
    """
    place = place if isinstance(place, dict) else {}
    try:
        limit = int(budget_limit)
    except (TypeError, ValueError):
        return True
    if limit not in {1000, 2000, 5000}:
        return True

    price_range = place.get("price_range") or {}
    if isinstance(price_range, dict):
        start = _nearby_money_jpy(price_range.get("startPrice"))
        if start is not None:
            return start <= float(limit)

    level = str(place.get("price_level") or "").strip()
    allowed_by_limit = {
        1000: {"PRICE_LEVEL_FREE", "PRICE_LEVEL_INEXPENSIVE"},
        2000: {"PRICE_LEVEL_FREE", "PRICE_LEVEL_INEXPENSIVE", "PRICE_LEVEL_MODERATE"},
        5000: {"PRICE_LEVEL_FREE", "PRICE_LEVEL_INEXPENSIVE", "PRICE_LEVEL_MODERATE", "PRICE_LEVEL_EXPENSIVE"},
    }
    known_levels = {
        "PRICE_LEVEL_FREE", "PRICE_LEVEL_INEXPENSIVE", "PRICE_LEVEL_MODERATE",
        "PRICE_LEVEL_EXPENSIVE", "PRICE_LEVEL_VERY_EXPENSIVE",
    }
    if level in known_levels:
        return level in allowed_by_limit[limit]
    return True


def _nearby_budget_match_1000(place):
    """Backward-compatible ¥1,000 filter for snack/sightseeing mode."""
    return _nearby_budget_match_limit(place, 1000)


def _nearby_budget_text(place):
    place = place if isinstance(place, dict) else {}
    range_text = _nearby_price_range_text(place.get("price_range"))
    if range_text:
        return "💴 " + range_text.replace("価格目安：", "")
    level = str(place.get("price_level") or "").strip()
    labels = {
        "PRICE_LEVEL_FREE": "💴 無料",
        "PRICE_LEVEL_INEXPENSIVE": "💴 お手頃",
        "PRICE_LEVEL_MODERATE": "💴 標準",
        "PRICE_LEVEL_EXPENSIVE": "💴 やや高め",
        "PRICE_LEVEL_VERY_EXPENSIVE": "💴 高め",
    }
    return labels.get(level, "")


def _nearby_today_hours_text(hours):
    if not isinstance(hours, dict):
        return ""
    descriptions = hours.get("weekdayDescriptions") or []
    if isinstance(descriptions, list) and len(descriptions) >= 7:
        try:
            return str(descriptions[now_jst().weekday()] or "").strip()
        except Exception:
            pass
    return ""


@st.cache_data(ttl=600, show_spinner=False)
def _nearby_google_place_details(place_id):
    place_id = str(place_id or "").strip()
    if not GOOGLE_PLACES_API_KEY or not place_id:
        return {}
    safe_id = quote(place_id, safe="")
    req = Request(
        f"https://places.googleapis.com/v1/places/{safe_id}",
        headers={
            "Content-Type": "application/json; charset=UTF-8",
            "X-Goog-Api-Key": GOOGLE_PLACES_API_KEY,
            "X-Goog-FieldMask": (
                "id,currentOpeningHours,businessStatus,priceLevel,priceRange,nationalPhoneNumber,websiteUri"
            ),
        },
        method="GET",
    )
    try:
        with urlopen(req, timeout=6.5) as response:
            data = json.loads(response.read().decode("utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _auto_discovery_name_quality_v586(requested, found):
    """Only accept a same-name shop, or a clearly labeled branch of that shop.

    Proximity alone NEVER establishes identity. Japanese punctuation, whitespace,
    corporate forms and a few unambiguous shop-type prefixes are normalized.
    An arbitrary shared substring or common shop type is not sufficient.
    """
    def key(value):
        value = unicodedata.normalize("NFKC", str(value or "")).casefold()
        value = re.sub(r"^(?:株式会社|有限会社|合同会社)", "", value)
        return re.sub(r"[^0-9a-z\u3040-\u30ff\u3400-\u9fff]+", "", value)

    target = key(requested)
    actual = key(found)
    if not target or not actual:
        return 0
    if target == actual:
        return 3
    # The venue type may precede the proper shop name in Google Places.
    prefixes = ("和菓子", "御菓子司", "洋菓子", "ベーカリー", "甘味処", "カフェ", "喫茶店")
    variants = [actual]
    for prefix in prefixes:
        if actual.startswith(prefix) and len(actual) > len(prefix):
            variants.append(actual[len(prefix):])
    # Generic trailing corporate descriptors do not justify accepting a different shop.
    for name in variants:
        if name == target:
            return 2
        if len(target) >= 4 and name.startswith(target):
            suffix = name[len(target):]
            if suffix in {"本店", "支店", "直売所", "工場直売所", "販売所", "ショップ"}:
                return 2
            # Branches like 「東京羊羹 芝店」 are acceptable only if very nearby.
            if 2 <= len(suffix) <= 6 and suffix.endswith("店"):
                return 1
    return 0


@st.cache_data(ttl=3600, show_spinner=False)
def _auto_discovery_google_match(place_name, latitude, longitude):
    """Resolve a stored OSM notification candidate WITHOUT accepting nearby strangers.

    Status is returned separately from the matched place so the UI can distinguish
    absent image metadata, media failures and venue-identity uncertainty.
    One Text Search request per opened detail; no automatic follow-up API calls.
    """
    if not GOOGLE_PLACES_API_KEY:
        return {"_lookup_status_v586": "not_configured"}
    try:
        latitude = float(latitude)
        longitude = float(longitude)
        if not (math.isfinite(latitude) and math.isfinite(longitude)):
            raise ValueError("invalid coordinates")
    except (TypeError, ValueError):
        return {"_lookup_status_v586": "invalid_coordinates"}
    place_name = str(place_name or "").strip()
    if not place_name:
        return {"_lookup_status_v586": "missing_name"}
    body = json.dumps({
        "textQuery": place_name,
        "languageCode": "ja",
        "maxResultCount": 5,
        "locationBias": {
            "circle": {
                "center": {"latitude": latitude, "longitude": longitude},
                "radius": 350.0,
            }
        },
    }, ensure_ascii=False).encode("utf-8")
    req = Request(
        "https://places.googleapis.com/v1/places:searchText",
        data=body,
        headers={
            "Content-Type": "application/json; charset=UTF-8",
            "X-Goog-Api-Key": GOOGLE_PLACES_API_KEY,
            "X-Goog-FieldMask": (
                "places.id,places.displayName,places.formattedAddress,places.location,places.photos,"
                "places.currentOpeningHours,places.businessStatus,places.rating,places.userRatingCount"
            ),
        },
        method="POST",
    )
    try:
        with urlopen(req, timeout=6.0) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        return {"_lookup_status_v586": "api_error", "_http_code_v586": int(exc.code)}
    except Exception:
        return {"_lookup_status_v586": "api_error"}
    if not isinstance(payload, dict):
        return {"_lookup_status_v586": "api_error"}
    rows = payload.get("places")
    if not isinstance(rows, list) or not rows:
        return {"_lookup_status_v586": "no_results"}

    ranked = []
    for raw in rows:
        if not isinstance(raw, dict) or str(raw.get("businessStatus") or "") == "CLOSED_PERMANENTLY":
            continue
        google_id = str(raw.get("id") or "").strip()
        if not google_id:
            continue
        location = raw.get("location") if isinstance(raw.get("location"), dict) else {}
        try:
            candidate_lat = float(location.get("latitude"))
            candidate_lon = float(location.get("longitude"))
            if not (math.isfinite(candidate_lat) and math.isfinite(candidate_lon)):
                continue
            distance_m = _nearby_haversine_m(latitude, longitude, candidate_lat, candidate_lon)
        except (TypeError, ValueError):
            continue
        display = raw.get("displayName") if isinstance(raw.get("displayName"), dict) else {}
        candidate_name = str(display.get("text") or "").strip()
        quality = _auto_discovery_name_quality_v586(place_name, candidate_name)
        # Exact names tolerate differences in map/building centroids. Variants
        # require much stronger location agreement. Never use distance alone.
        max_distance = 150.0 if quality == 3 else (95.0 if quality == 2 else 65.0)
        if quality == 0 or not math.isfinite(distance_m) or distance_m > max_distance:
            continue
        ranked.append((quality, -distance_m, raw, candidate_name, candidate_lat, candidate_lon))
    if not ranked:
        return {"_lookup_status_v586": "name_or_location_mismatch"}
    _, negative_distance, raw, candidate_name, candidate_lat, candidate_lon = max(
        ranked, key=lambda item: (item[0], item[1])
    )
    return {
        "_lookup_status_v586": "matched",
        "id": f"google:{raw.get('id') or ''}",
        "google_place_id": str(raw.get("id") or ""),
        "name": candidate_name,
        "latitude": candidate_lat,
        "longitude": candidate_lon,
        "_match_distance_m_v586": round(-negative_distance, 1),
        "address": str(raw.get("formattedAddress") or "").strip(),
        "provider": "Google Places",
        "business_status": str(raw.get("businessStatus") or ""),
        "current_opening_hours": dict(raw.get("currentOpeningHours") or {}),
        "rating": raw.get("rating"),
        "user_rating_count": raw.get("userRatingCount"),
        "photo_refs": _nearby_google_photo_refs(raw.get("photos") or [], limit=3),
    }

def _nearby_shortlist_safe_place(place):
    """Do not persist transient Google photo resource names in shortlist state."""
    if not isinstance(place, dict):
        return {}
    allowed = ("id","name","kind","category","latitude","longitude","distance_m","walk_minutes","opening_hours","address","provider")
    return {key: place.get(key) for key in allowed if key in place}

@st.cache_data(ttl=60, show_spinner=False)
def search_nearby_quick_stops(latitude, longitude, kind, subkind, radius_m):
    try:
        latitude = round(float(latitude), 5)
        longitude = round(float(longitude), 5)
        radius_m = max(50, min(4000, int(radius_m)))
    except (TypeError, ValueError):
        return {"places": [], "error": "現在地を確認できませんでした。", "provider": "OpenStreetMap"}

    selectors = _nearby_overpass_selectors(kind, subkind, radius_m, latitude, longitude)
    query = "[out:json][timeout:9];(" + "".join(selectors) + ");out center tags;"
    payload = urlencode({"data": query}).encode("utf-8")
    endpoints = (
        "https://overpass-api.de/api/interpreter",
        "https://overpass.kumi.systems/api/interpreter",
    )
    data = None
    last_error = ""
    for endpoint in endpoints:
        req = Request(
            endpoint,
            data=payload,
            headers={
                "User-Agent": "TokyoBurariApp/1.0 (family-use nearby search)",
                "Accept": "application/json",
                "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
            },
        )
        try:
            with urlopen(req, timeout=7.5) as response:
                data = json.loads(response.read().decode("utf-8"))
            if isinstance(data, dict):
                break
        except Exception as exc:
            last_error = str(exc)
            data = None

    if not isinstance(data, dict):
        return {
            "places": [],
            "error": "周辺検索サービスにつながりませんでした。少し時間をおいてもう一度お試しください。",
            "detail": last_error[:240],
            "provider": "OpenStreetMap",
        }

    places = []
    seen = set()
    for element in data.get("elements") or []:
        if not isinstance(element, dict):
            continue
        tags = element.get("tags") or {}
        if not isinstance(tags, dict):
            tags = {}
        name = str(tags.get("name:ja") or tags.get("name") or "").strip()
        if not name:
            continue
        if kind == "snack":
            amenity = str(tags.get("amenity") or "")
            takeaway = str(tags.get("takeaway") or "").strip().lower()
            snack_name_terms = (
                "大福", "団子", "だんご", "たい焼", "鯛焼", "どら焼", "饅頭", "まんじゅう",
                "おはぎ", "最中", "羊羹", "せんべい", "煎餅", "和菓子", "洋菓子", "ケーキ",
                "パティスリー", "焼き菓子", "クッキー", "スコーン", "マフィン", "カヌレ", "タルト",
                "アイス", "ジェラート", "ソフトクリーム", "かき氷", "クレープ", "ドーナツ",
                "プリン", "スイーツ", "パン", "ベーカリー", "チョコ", "ワッフル", "チュロス",
            )
            shop_type = str(tags.get("shop") or "")
            portable_shop = shop_type in {"bakery", "pastry", "confectionery", "chocolate"}
            direct_snack = any(term in name for term in snack_name_terms)
            snack_identity = amenity == "ice_cream" or portable_shop or direct_snack
            meal_amenity = amenity in {"restaurant", "fast_food", "bar", "pub", "biergarten", "food_court"}
            if meal_amenity and not direct_snack:
                continue
            if str(subkind) == "食べ歩き向き":
                # Takeaway=yes is only a portability clue; it is not snack identity.
                portable_signal = snack_identity and (portable_shop or amenity == "ice_cream" or direct_snack or takeaway == "yes")
                if not portable_signal:
                    continue
            if str(subkind) == "店内中心":
                sitdown_signal = amenity == "cafe" or str(tags.get("cuisine") or "").lower() in {"dessert", "cake", "coffee_shop", "japanese_sweets"} or direct_snack
                if not sitdown_signal:
                    continue
        elif kind == "lunch":
            amenity = str(tags.get("amenity") or "")
            if amenity not in {"restaurant", "fast_food", "food_court", "cafe"} and not str(tags.get("cuisine") or "").strip():
                continue
        elif kind == "rain_sightseeing":
            tourism = str(tags.get("tourism") or "").strip().lower()
            indoor = str(tags.get("indoor") or "").strip().lower()
            covered = str(tags.get("covered") or "").strip().lower()
            building = str(tags.get("building") or "").strip().lower()
            leisure = str(tags.get("leisure") or "").strip().lower()
            indoor_name_terms = ("博物館", "美術館", "科学館", "資料館", "記念館", "展示館", "水族館", "プラネタリウム", "ミュージアム", "屋内", "室内", "地下街")
            strong_rain = (
                tourism in {"museum", "gallery", "aquarium"}
                or indoor == "yes" or covered == "yes"
                or (bool(building) and tourism in {"attraction", "museum", "gallery", "aquarium"})
                or leisure == "indoor_playground"
                or any(term in name for term in indoor_name_terms)
            )
            if not strong_rain:
                continue
        center = element.get("center") if isinstance(element.get("center"), dict) else {}
        plat = element.get("lat", center.get("lat"))
        plon = element.get("lon", center.get("lon"))
        try:
            plat = float(plat)
            plon = float(plon)
        except (TypeError, ValueError):
            continue
        distance_m = _nearby_haversine_m(latitude, longitude, plat, plon)
        distance_limit = float(radius_m) if kind in {"snack", "lunch"} else float(radius_m) * 1.15
        if not math.isfinite(distance_m) or distance_m > distance_limit:
            continue
        dedupe = (name, round(plat, 4), round(plon, 4))
        if dedupe in seen:
            continue
        seen.add(dedupe)
        walk_minutes = max(1, int(math.ceil((distance_m * 1.25) / 80.0)))
        addr_parts = []
        for key in ("addr:suburb", "addr:quarter", "addr:city", "addr:street"):
            value = str(tags.get(key) or "").strip()
            if value and value not in addr_parts:
                addr_parts.append(value)
        place_id = f"osm:{element.get('type','x')}:{element.get('id','')}"
        places.append(
            {
                "id": place_id,
                "name": name,
                "kind": str(kind),
                "category": _nearby_place_label(tags, kind),
                "latitude": plat,
                "longitude": plon,
                "distance_m": int(round(distance_m)),
                "walk_minutes": walk_minutes,
                "opening_hours": str(tags.get("opening_hours") or "").strip(),
                "address": " ".join(addr_parts[:3]),
                "priority": _nearby_place_priority(tags, kind),
                "provider": "OpenStreetMap",
                "rain_suitable": bool(kind == "rain_sightseeing"),
                "rain_suitable_reason": "屋内・屋根あり情報" if kind == "rain_sightseeing" else "",
            }
        )

    if kind == "snack":
        places.sort(key=lambda item: (int(item.get("priority") or 0), int(item.get("distance_m") or 0)))
    else:
        # OSM does not provide Google-style ratings; lunch fallback is distance ordered.
        places.sort(key=lambda item: int(item.get("distance_m") or 0))
    return {"places": places[:24], "error": "", "provider": "OpenStreetMap"}


def _nearby_shortlist_key():
    return f"_nearby_shortlist_{current_family_key()}_{current_member_key()}"


def _nearby_shortlist():
    value = st.session_state.get(_nearby_shortlist_key())
    return [dict(item) for item in value] if isinstance(value, list) else []


def _nearby_add_shortlist(place):
    if not isinstance(place, dict) or not place.get("id"):
        return
    items = _nearby_shortlist()
    pid = str(place.get("id"))
    items = [item for item in items if str(item.get("id")) != pid]
    items.append(_nearby_shortlist_safe_place(place))
    st.session_state[_nearby_shortlist_key()] = items[-6:]


def _nearby_remove_shortlist(place_id):
    pid = str(place_id or "")
    st.session_state[_nearby_shortlist_key()] = [
        item for item in _nearby_shortlist() if str(item.get("id")) != pid
    ]


def _nearby_directions_url(place):
    """Open Google Maps on the walking-route preview screen.

    Deliberately omit ``dir_action=navigate``. On phones this keeps the user on the
    route-confirmation screen (current location -> destination) so navigation starts
    only after the user explicitly taps the Maps navigation button.
    """
    try:
        row = place or {}
        lat = float(row.get("latitude") if row.get("latitude") is not None else row.get("lat"))
        lon = float(row.get("longitude") if row.get("longitude") is not None else row.get("lon"))
    except (TypeError, ValueError):
        return ""
    params = urlencode(
        {
            "api": "1",
            "destination": f"{lat:.7f},{lon:.7f}",
            "travelmode": "walking",
        }
    )
    return f"https://www.google.com/maps/dir/?{params}"


# v412: Android WebView does not reliably honor route anchors rendered inside
# Streamlit HTML/iframe content. Use a v2 component so the actual tap navigates the
# top-level app window. The same component also receives route requests relayed from
# the Leaflet toilet-map iframe.
_ROUTE_LAUNCHER_HTML_V412 = r"""
<div class="burari-route-launcher-v412">
  <button id="burari-route-launch-v412" type="button"></button>
</div>
"""

_ROUTE_LAUNCHER_CSS_V412 = r"""
.burari-route-launcher-v412 { width:100%; box-sizing:border-box; }
#burari-route-launch-v412 {
  appearance:none; -webkit-appearance:none; width:100%; min-height:2.78rem; margin:0;
  box-sizing:border-box; padding:.48rem .56rem; border-radius:12px;
  border:1px solid rgba(47,128,237,.48); background:rgba(47,128,237,.10);
  color:#235fa8; font:inherit; font-size:.80rem; font-weight:820; line-height:1.22;
  text-align:center; cursor:pointer; touch-action:manipulation; -webkit-tap-highlight-color:transparent;
}
#burari-route-launch-v412:active { background:rgba(47,128,237,.24); transform:translateY(1px) scale(.99); }
#burari-route-launch-v412[hidden] { display:none !important; }
#burari-route-launch-v412:disabled { opacity:.45; cursor:default; }
"""

_ROUTE_LAUNCHER_JS_V412 = r"""
export default function(component) {
  const { data, parentElement } = component;
  const button = parentElement.querySelector('#burari-route-launch-v412');
  const listenerOnly = Boolean(data?.listener_only);
  const ownUrl = String(data?.url || '');
  const nativeBridgeToken = String(data?.native_bridge_token || '');
  const legacyMessageType = 'tokyo-burari-open-route-v412';
  const nativeMessageType = 'burari-native-external-request-v1';

  const safeRouteUrl = (value) => {
    try {
      const parsed = new URL(String(value || ''), window.location.href);
      if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') return '';
      const host = String(parsed.hostname || '').toLowerCase();
      if (!(host === 'google.com' || host.endsWith('.google.com'))) return '';
      if (!String(parsed.pathname || '').startsWith('/maps/dir')) return '';
      return parsed.href;
    } catch (_) { return ''; }
  };

  const askAndroidToOpenRoute = (url) => {
    if (!nativeBridgeToken) return false;
    // addJavascriptInterface is normally visible in every WebView frame. Use it first.
    try {
      const bridge = globalThis.BurariExternal || window.BurariExternal || null;
      if (bridge && typeof bridge.openRoute === 'function') {
        bridge.openRoute(nativeBridgeToken, url);
        return true;
      }
    } catch (_) {}
    // Streamlit can isolate component frames. The Android host installs this relay on
    // the trusted top page, so the request still reaches ACTION_VIEW without navigating
    // this iframe/WebView to google.com.
    try {
      const target = (window.parent && window.parent !== window) ? window.parent : window;
      target.postMessage({
        type: nativeMessageType,
        request_id: `route-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        action: 'open_route',
        token: nativeBridgeToken,
        url,
      }, '*');
      return true;
    } catch (_) { return false; }
  };

  const openRoute = (value) => {
    const url = safeRouteUrl(value);
    if (!url) return;
    if (askAndroidToOpenRoute(url)) return;
    // Browser/PWA fallback only. Never use same-frame navigation for the Android app,
    // because Google Maps can reject an embedded WebView with ERR_BLOCKED_BY_RESPONSE.
    try {
      const opened = window.open(url, '_blank', 'noopener,noreferrer');
      if (opened) return;
    } catch (_) {}
    try { window.top.location.href = url; } catch (_) {}
  };

  const onMessage = (event) => {
    const payload = event?.data;
    if (!payload || payload.type !== legacyMessageType) return;
    openRoute(payload.url);
  };
  window.addEventListener('message', onMessage);

  if (button) {
    button.hidden = listenerOnly;
    button.disabled = !safeRouteUrl(ownUrl);
    button.textContent = String(data?.label || '🗺️ この場所に案内してもらう');
    const onClick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      openRoute(ownUrl);
    };
    button.addEventListener('click', onClick);
    return () => {
      button.removeEventListener('click', onClick);
      window.removeEventListener('message', onMessage);
    };
  }
  return () => window.removeEventListener('message', onMessage);
}
"""

_route_launcher_component_v412 = None
_route_launcher_component_initialized_v412 = False


def _get_route_launcher_component_v412():
    global _route_launcher_component_v412, _route_launcher_component_initialized_v412
    if _route_launcher_component_initialized_v412:
        return _route_launcher_component_v412
    _route_launcher_component_initialized_v412 = True
    try:
        _route_launcher_component_v412 = st.components.v2.component(
            "tokyo_burari_route_launcher_v412",
            html=_ROUTE_LAUNCHER_HTML_V412,
            css=_ROUTE_LAUNCHER_CSS_V412,
            js=_perf_instrument_js_v466(_ROUTE_LAUNCHER_JS_V412),
        )
    except Exception:
        _route_launcher_component_v412 = None
    return _route_launcher_component_v412


def render_route_launcher_v412(place, *, label="🗺️ この場所に案内してもらう", key="route_v412"):
    """Render a route action that navigates the main WebView, not an HTML subframe."""
    url = _nearby_directions_url(place)
    if not url:
        st.button(label, use_container_width=True, disabled=True, key=f"{key}_disabled")
        return False
    component = _get_route_launcher_component_v412()
    if component is not None:
        component(
            data={
                "url": url,
                "label": label,
                "listener_only": False,
                "native_bridge_token": str(_query_param_scalar("native_bridge_token") or ""),
            },
            key=key,
        )
    else:
        # Old-runtime fallback: same-frame navigation is more reliable in Android
        # WebView than target=_top/_blank links.
        st.markdown(
            f'<a href="{html.escape(url, quote=True)}" target="_self" rel="noopener noreferrer" '
            'style="display:flex;align-items:center;justify-content:center;width:100%;min-height:2.78rem;'
            'box-sizing:border-box;padding:.48rem .56rem;border-radius:12px;border:1px solid rgba(47,128,237,.48);'
            'background:rgba(47,128,237,.10);color:#235fa8;text-decoration:none;text-align:center;font-weight:820;">'
            f'{html.escape(label)}</a>',
            unsafe_allow_html=True,
        )
    return True


def render_route_message_listener_v412(*, key="route_listener_v412"):
    """Listen for route requests from sandboxed map iframes and navigate the main app."""
    component = _get_route_launcher_component_v412()
    if component is not None:
        component(data={"listener_only": True, "native_bridge_token": str(_query_param_scalar("native_bridge_token") or "")}, key=key)


def _nearby_distance_text(place):
    distance = max(0, int((place or {}).get("distance_m") or 0))
    minutes = max(1, int((place or {}).get("walk_minutes") or 1))
    if distance >= 1000:
        distance_text = f"{distance / 1000:.1f}km"
    else:
        distance_text = f"{distance}m"
    return f"徒歩約{minutes}分（{distance_text}・目安）"


# ============================================================
# Nearby toilet search (OpenStreetMap / Overpass)
# ============================================================
_TOILET_DAY_CODES = ("Mo", "Tu", "We", "Th", "Fr", "Sa", "Su")


def _toilet_expand_days(day_expr):
    """Expand a small, common subset of OSM opening_hours weekday syntax."""
    expr = str(day_expr or "").strip()
    result = set()
    if not expr:
        return result
    for token in [part.strip() for part in expr.split(",") if part.strip()]:
        if "-" in token:
            start, end = [part.strip() for part in token.split("-", 1)]
            if start in _TOILET_DAY_CODES and end in _TOILET_DAY_CODES:
                i = _TOILET_DAY_CODES.index(start)
                j = _TOILET_DAY_CODES.index(end)
                if i <= j:
                    result.update(_TOILET_DAY_CODES[i:j + 1])
                else:
                    result.update(_TOILET_DAY_CODES[i:])
                    result.update(_TOILET_DAY_CODES[:j + 1])
        elif token in _TOILET_DAY_CODES:
            result.add(token)
    return result


def _toilet_minutes(value):
    match = re.fullmatch(r"(\d{1,2}):(\d{2})", str(value or "").strip())
    if not match:
        return None
    hour = int(match.group(1))
    minute = int(match.group(2))
    if hour > 24 or minute > 59 or (hour == 24 and minute != 0):
        return None
    return hour * 60 + minute


def _toilet_time_ranges_open(time_expr, minute_of_day):
    parsed_any = False
    for piece in [part.strip() for part in str(time_expr or "").split(",") if part.strip()]:
        match = re.fullmatch(r"(\d{1,2}:\d{2})-(\d{1,2}:\d{2})", piece)
        if not match:
            continue
        start = _toilet_minutes(match.group(1))
        end = _toilet_minutes(match.group(2))
        if start is None or end is None:
            continue
        parsed_any = True
        if start == end:
            return True, True
        if end > start and start <= minute_of_day < end:
            return True, True
        if end < start and (minute_of_day >= start or minute_of_day < end):
            return True, True
    return parsed_any, False


def _toilet_opening_status(opening_hours):
    """Return a conservative current-use status for common Japanese OSM hours."""
    raw = str(opening_hours or "").strip()
    if not raw:
        return {"known": False, "open_now": None, "label": "利用時間情報なし", "raw": ""}
    normalized = raw.replace("；", ";").strip()
    if normalized.lower() in {"24/7", "24x7"} or "24/7" in normalized:
        return {"known": True, "open_now": True, "label": "🟢 24時間", "raw": raw}

    now = now_jst()
    today = _TOILET_DAY_CODES[now.weekday()]
    minute_of_day = now.hour * 60 + now.minute
    saw_explicit_day = False
    today_rule_seen = False
    today_parse_seen = False

    for segment in [part.strip() for part in normalized.split(";") if part.strip()]:
        if re.fullmatch(r"off|closed", segment, flags=re.I):
            return {"known": True, "open_now": False, "label": "🔴 利用時間外", "raw": raw}

        day_match = re.match(
            r"^((?:Mo|Tu|We|Th|Fr|Sa|Su)(?:(?:-|,)(?:Mo|Tu|We|Th|Fr|Sa|Su))*)\s+(.+)$",
            segment,
        )
        if day_match:
            saw_explicit_day = True
            days = _toilet_expand_days(day_match.group(1))
            if today not in days:
                continue
            today_rule_seen = True
            time_expr = day_match.group(2).strip()
            if re.fullmatch(r"off|closed", time_expr, flags=re.I):
                return {"known": True, "open_now": False, "label": "🔴 利用時間外", "raw": raw}
            parsed, is_open = _toilet_time_ranges_open(time_expr, minute_of_day)
            if parsed:
                today_parse_seen = True
                if is_open:
                    return {"known": True, "open_now": True, "label": "🟢 利用可能", "raw": raw}
            continue

        parsed, is_open = _toilet_time_ranges_open(segment, minute_of_day)
        if parsed:
            if is_open:
                return {"known": True, "open_now": True, "label": "🟢 利用可能", "raw": raw}
            return {"known": True, "open_now": False, "label": "🔴 利用時間外", "raw": raw}

    if saw_explicit_day and not today_rule_seen:
        return {"known": True, "open_now": False, "label": "🔴 本日は時間外", "raw": raw}
    if today_rule_seen and today_parse_seen:
        return {"known": True, "open_now": False, "label": "🔴 利用時間外", "raw": raw}
    return {"known": False, "open_now": None, "label": "利用時間情報なし", "raw": raw}


def _toilet_access_info(tags, standalone=True):
    tags = tags if isinstance(tags, dict) else {}
    raw = str(
        (tags.get("access") if standalone else tags.get("toilets:access"))
        or tags.get("toilets:access")
        or tags.get("access")
        or ""
    ).strip().lower()
    if raw in {"private", "no"}:
        return {"allowed": False, "label": "利用不可"}
    if raw in {"customers", "customer"}:
        return {"allowed": True, "label": "施設利用者向け"}
    if raw in {"permissive", "public", "yes"}:
        return {"allowed": True, "label": "一般利用可"}
    return {"allowed": True, "label": ""}


def _toilet_fee_info(tags, standalone=True):
    tags = tags if isinstance(tags, dict) else {}
    raw = str(
        (tags.get("fee") if standalone else tags.get("toilets:fee"))
        or tags.get("toilets:fee")
        or tags.get("fee")
        or ""
    ).strip().lower()
    if raw in {"no", "free", "0"}:
        return {"status": "free", "label": "🆓 無料"}
    if raw in {"yes", "pay", "paid"}:
        return {"status": "paid", "label": "💴 有料"}
    return {"status": "unknown", "label": "料金情報なし"}


def _toilet_wheelchair_info(tags, standalone=True):
    tags = tags if isinstance(tags, dict) else {}
    raw = str(
        (tags.get("wheelchair") if standalone else tags.get("toilets:wheelchair"))
        or tags.get("toilets:wheelchair")
        or ""
    ).strip().lower()
    if raw in {"yes", "designated"}:
        return {"ok": True, "label": "♿ 車いす対応"}
    if raw == "limited":
        return {"ok": True, "label": "♿ 一部対応"}
    if raw == "no":
        return {"ok": False, "label": "♿ 非対応"}
    return {"ok": None, "label": ""}


def _toilet_baby_info(tags):
    tags = tags if isinstance(tags, dict) else {}
    raw = str(tags.get("changing_table") or tags.get("toilets:changing_table") or "").strip().lower()
    if raw in {"yes", "limited"}:
        return {"ok": True, "label": "👶 おむつ交換台あり"}
    if raw == "no":
        return {"ok": False, "label": "👶 交換台なし"}
    return {"ok": None, "label": ""}


