def update_photo_reflection(photo_id, conversation, signals, done=None):
    client = supabase_client()
    current = (
        client
        .table(PHOTO_TABLE)
        .select("reflection_json,signals_json")
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .limit(1)
        .execute()
    )
    row = (current.data or [None])[0] or {}
    reflection = row.get("reflection_json") or {}
    if not isinstance(reflection, dict):
        reflection = {}
    reflection["conversation"] = conversation
    child_comments = [
        str(turn.get("text") or "").strip()
        for turn in (conversation or [])
        if isinstance(turn, dict) and turn.get("role") == "child" and str(turn.get("text") or "").strip()
    ]
    reflection["child_comment"] = " / ".join(child_comments)
    if done is not None:
        reflection["conversation_done"] = bool(done)

    existing_signals = row.get("signals_json") or {}
    if not isinstance(existing_signals, dict):
        existing_signals = {}
    next_signals = dict(signals or {}) if isinstance(signals, dict) else {}
    # Preserve existing legacy metadata and photo framing without generating map indexes.
    for metadata_key in ("memory_map_v1", FRAMING_KEY_V468):
        if metadata_key in existing_signals and metadata_key not in next_signals:
            next_signals[metadata_key] = existing_signals[metadata_key]

    (
        client
        .table(PHOTO_TABLE)
        .update({"reflection_json": reflection, "signals_json": next_signals})
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .execute()
    )
    _invalidate_fast_db_cache()


