def diaries_for_trip_ids(trip_ids):
    """Fetch many diaries in one request instead of one request per trip."""
    ids = list(dict.fromkeys(str(x) for x in (trip_ids or []) if x))
    if not ids:
        return {}
    rows = (
        supabase_client()
        .table(DIARY_TABLE)
        .select("*")
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .in_("trip_id", ids)
        .execute()
    ).data or []
    return {str(row.get("trip_id")): row for row in rows if row.get("trip_id")}


def photos_for_trip_ids(trip_ids):
    """Fetch many trips' photo metadata in one request and group it locally."""
    ids = list(dict.fromkeys(str(x) for x in (trip_ids or []) if x))
    grouped = {trip_id: [] for trip_id in ids}
    if not ids:
        return grouped
    rows = (
        supabase_client()
        .table(PHOTO_TABLE)
        .select("*")
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .in_("trip_id", ids)
        .order("captured_at")
        .execute()
    ).data or []
    for row in rows:
        trip_id = str(row.get("trip_id") or "")
        if trip_id in grouped:
            grouped[trip_id].append(row)
    return grouped


def save_diary(trip_id, title, diary_text, raw_conversation, ai_meta):
    existing = get_diary_for_trip(trip_id)
    trip = get_trip(trip_id)
    if not trip:
        raise ValueError("現在の個人アカウントのぶらり旅が見つかりません。")
    existing_title = str((existing or {}).get("title") or "").strip()
    requested_title = str(title or "").strip()
    if existing_title:
        fixed_title = existing_title
    else:
        auto_title = requested_title or diary_title_for_trip(trip)
        fixed_title = unique_auto_diary_title(auto_title, exclude_trip_id=trip_id)

    incoming_meta = dict(ai_meta or {}) if isinstance(ai_meta or {}, dict) else {}
    existing_meta = (existing or {}).get("ai_meta") or {}
    if not isinstance(existing_meta, dict):
        existing_meta = {}
    if existing_meta.get("summary_feedback_history") and not incoming_meta.get("summary_feedback_history"):
        incoming_meta["summary_feedback_history"] = list(existing_meta.get("summary_feedback_history") or [])

    payload = {
        "trip_id": trip_id,
        "family_key": current_family_key(),
        "member_key": current_member_key(),
        "title": fixed_title,
        "diary_text": str(diary_text or "").strip(),
        "raw_conversation": raw_conversation,
        "ai_meta": incoming_meta,
        "updated_at": now_jst().isoformat(),
    }
    if existing:
        (
            supabase_client()
            .table(DIARY_TABLE)
            .update(payload)
            .eq("id", existing["id"])
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .execute()
        )
    else:
        payload["created_at"] = now_jst().isoformat()
        supabase_client().table(DIARY_TABLE).insert(payload).execute()
    (
        supabase_client()
        .table(TRIP_TABLE)
        .update({"status": "diary_done", "ended_at": trip.get("ended_at") or now_jst().isoformat()})
        .eq("id", trip_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .execute()
    )
    _invalidate_fast_db_cache()
    return get_diary_for_trip(trip_id)


def delete_diary_and_related_data(trip_id):
    """Delete one saved diary plus all photos and their attached metadata for that trip."""
    client = supabase_client()
    trip = get_trip(trip_id) or {}
    photos = list_trip_photos(trip_id)
    storage_paths = []
    for photo in photos:
        storage_paths.extend(photo_all_storage_paths(photo))
    storage_paths = list(dict.fromkeys(path for path in storage_paths if path))

    # Remove the binary photo files first. If Storage cannot be reached, abort the
    # deletion so the visible database records are not left pointing to missing files.
    if storage_paths:
        client.storage.from_(PHOTO_BUCKET).remove(storage_paths)

    # A photo's reflection_json contains per-photo metadata, so
    # deleting the photo rows deletes those comments together with the photo record.
    client.table(PHOTO_TABLE).delete().eq("trip_id", trip_id).eq("family_key", current_family_key()).eq("member_key", current_member_key()).execute()
    client.table(DIARY_TABLE).delete().eq("trip_id", trip_id).eq("family_key", current_family_key()).eq("member_key", current_member_key()).execute()
    # Once its diary/photos are gone, remove the trip container as well so the
    # deleted day cannot reappear as an empty trip in diary/monthly screens.
    client.table(TRIP_TABLE).delete().eq("id", trip_id).eq("family_key", current_family_key()).eq("member_key", current_member_key()).execute()

    # A saved monthly review can contain wording derived from the deleted diary.
    # Remove that month's snapshot so it cannot continue showing deleted material.
    trip_date = str(trip.get("trip_date") or "")
    month_key = trip_date[:7] if len(trip_date) >= 7 else ""
    if month_key:
        first_day, _ = month_bounds(month_key)
        client.table(MONTHLY_TABLE).delete().eq("review_month", first_day).eq("family_key", current_family_key()).eq("member_key", current_member_key()).execute()
        for key in (
            f"monthly_review_{month_key}",
            f"monthly_audio_{month_key}",
            f"monthly_audio_pending_{month_key}",
        ):
            st.session_state.pop(key, None)

    # Clear any in-progress diary state for the deleted trip.
    st.session_state.pop(f"reflection_state_{trip_id}", None)
    st.session_state.pop(f"diary_selected_photo_{trip_id}", None)
    st.session_state.pop(f"diary_talk_photo_{trip_id}", None)
    st.session_state.pop(f"diary_existing_photo_view_{trip_id}", None)
    st.session_state.pop("diary_trip_selector", None)
    if st.session_state.get("history_detail_trip_id") == trip_id:
        st.session_state.pop("history_detail_trip_id", None)
    if st.session_state.get("preferred_diary_trip_id") == trip_id:
        st.session_state.preferred_diary_trip_id = None
    if st.session_state.get("active_trip_id") == trip_id:
        st.session_state.active_trip_id = None
        _invalidate_active_trip_snapshot()
    download_photo.clear()
    thumbnail_photo_bytes.clear()
    thumbnail_photo_data_url.clear()
    signed_photo_url_map.clear()
    _invalidate_fast_db_cache()

    return {"photo_count": len(photos), "month_key": month_key}


@st.dialog("この日記を削除しますか？")
def confirm_diary_delete_dialog(trip_id, photo_count):
    trip = get_trip(trip_id) or {}
    photos = list_trip_photos(trip_id)
    diary = get_diary_for_trip(trip_id)
    title = diary_display_title(diary, trip, photos=photos)
    st.markdown(f"**{title}**")
    delete_col, cancel_col = st.columns([1.35, 0.85], gap="small")
    with delete_col:
        if st.button(
            "日記を削除",
            type="primary",
            use_container_width=True,
            key=f"dialog_delete_yes_{trip_id}",
        ):
            try:
                result = delete_diary_and_related_data(trip_id)
                st.session_state["_diary_notice"] = (
                    f"日記と写真 {result['photo_count']}枚、関連するコメントを削除しました。"
                )
                st.rerun(scope="app")
            except Exception as exc:
                st.error("日記を削除できませんでした。")
                with st.expander("保護者向け詳細"):
                    st.code(str(exc))
    with cancel_col:
        if st.button(
            "やめる",
            use_container_width=True,
            key=f"dialog_delete_no_{trip_id}",
        ):
            st.rerun(scope="app")



def _photo_batch_sync_trip_state_v589(trip_id, deleted_ids, remaining_photos, diary_deleted):
    """Apply the normal single-photo deletion's in-progress UI cleanup only once per trip."""
    deleted_ids = set(str(x) for x in deleted_ids)
    remaining_ids = [str(p.get("id")) for p in remaining_photos if p.get("id")]
    state_key = f"reflection_state_{trip_id}"
    state = st.session_state.get(state_key)
    if diary_deleted:
        st.session_state.pop(state_key, None)
    elif isinstance(state, dict):
        old_ids = list(state.get("photo_ids") or [])
        old_index = int(state.get("photo_index") or 0)
        new_ids = [pid for pid in old_ids if str(pid) not in deleted_ids]
        if len(new_ids) != len(old_ids):
            selected_old = old_ids[old_index] if 0 <= old_index < len(old_ids) else ""
            state["photo_ids"] = new_ids
            items = state.get("items")
            if isinstance(items, dict):
                for photo_id in deleted_ids:
                    items.pop(photo_id, None)
            removed_before = sum(1 for pid in old_ids[:old_index] if str(pid) in deleted_ids)
            state["photo_index"] = min(max(0, old_index - removed_before), max(0, len(new_ids) - 1))
            for key, value in (
                ("draft", None), ("draft_title", None), ("draft_meta", {}),
                ("raw_conversation", {}), ("draft_audio", None),
                ("draft_audio_pending", False), ("audio_bytes", None),
                ("audio_pending", False),
            ):
                state[key] = value
            state["answer_serial"] = int(state.get("answer_serial") or 0) + 1
            if str(state.get("selected_photo_id") or "") in deleted_ids:
                state["selected_photo_id"] = new_ids[0] if new_ids else None

    selected_key = f"diary_selected_photo_{trip_id}"
    if not remaining_ids:
        st.session_state.pop(selected_key, None)
    elif str(st.session_state.get(selected_key) or "") in deleted_ids:
        st.session_state[selected_key] = remaining_ids[0]

    st.session_state.pop(f"delete_photo_selector_{trip_id}", None)
    if diary_deleted or str(st.session_state.get(f"diary_talk_photo_{trip_id}") or "") in deleted_ids:
        st.session_state.pop(f"diary_talk_photo_{trip_id}", None)
    if st.session_state.pop(f"diary_existing_photo_view_{trip_id}", False):
        st.session_state.pop(state_key, None)

    if diary_deleted:
        st.session_state.pop(f"_diary_title_override_{trip_id}", None)
        if st.session_state.get("history_detail_trip_id") == trip_id:
            st.session_state.pop("history_detail_trip_id", None)
        if str(st.session_state.get("preferred_diary_trip_id") or "") == str(trip_id):
            st.session_state.preferred_diary_trip_id = None
        if str(st.session_state.get("active_trip_id") or "") == str(trip_id):
            st.session_state.active_trip_id = None
            _invalidate_active_trip_snapshot()
        st.session_state["_diary_selector_serial"] = int(st.session_state.get("_diary_selector_serial") or 0) + 1


def delete_photos_in_batches_v589(photo_ids, photos=None, *, skip_existing_diary_lookup=False):
    """Batch Storage/DB deletion, then recalculate affected diaries ONCE per trip.

    Uses fresh owner-scoped rows, not browser-supplied photo metadata, to authorize
    every deletion. If one storage batch fails, split it to isolate failures.
    Unrelated photos, videos and diaries remain untouched.
    """
    wanted = list(dict.fromkeys(str(x or "").strip() for x in (photo_ids or []) if str(x or "").strip()))
    if not wanted:
        return {"deleted_count": 0, "failures": []}
    supplied = {str(p.get("id") or ""): p for p in (photos or []) if isinstance(p, dict)}
    trip_ids = list(dict.fromkeys(str(supplied.get(pid, {}).get("trip_id") or "") for pid in wanted))
    trip_ids = [x for x in trip_ids if x]
    if not trip_ids:
        return {"deleted_count": 0, "failures": [(pid, "写真の旅情報がありません。") for pid in wanted]}

    client = supabase_client()
    family_key = current_family_key()
    member_key = current_member_key()
    fresh_grouped = photos_for_trip_ids(trip_ids)  # ONE Supabase read, even across many trips.
    by_id = {
        str(row.get("id") or ""): row
        for rows in fresh_grouped.values() for row in rows
        if isinstance(row, dict) and row.get("id") and not photo_is_video(row)
    }
    selected = []
    failures = []
    for pid in wanted:
        photo = by_id.get(pid)
        if photo and str(photo.get("trip_id") or "") == str(supplied.get(pid, {}).get("trip_id") or ""):
            selected.append(photo)
        else:
            failures.append((pid, "削除対象が見つからない、または写真を削除する権限がありません。"))
    if not selected:
        return {"deleted_count": 0, "failures": failures}

    trip_rows = (
        client.table(TRIP_TABLE).select("id,trip_date")
        .eq("family_key", family_key).eq("member_key", member_key)
        .in_("id", list(dict.fromkeys(p["trip_id"] for p in selected))).execute()
    ).data or []
    trips_by_id = {str(p.get("id")): p for p in trip_rows}
    selected = [p for p in selected if str(p.get("trip_id")) in trips_by_id]
    authorized_ids = {str(p.get("id")) for p in selected}
    for pid in wanted:
        if pid in by_id and pid not in authorized_ids and not any(x[0] == pid for x in failures):
            failures.append((pid, "ぶらり旅の登録を確認できませんでした。"))
    if not selected:
        return {"deleted_count": 0, "failures": failures}

    diaries = {} if skip_existing_diary_lookup else diaries_for_trip_ids(trips_by_id.keys())
    # Keep all the paths of each photo in the same chunk. Supabase Storage accepts
    # multiple keys per request; cap it to avoid oversized HTTP requests.
    chunks = []
    current = []
    num_paths = 0
    for photo in selected:
        paths = list(dict.fromkeys(p for p in photo_all_storage_paths(photo) if p))
        if current and (len(current) >= 45 or num_paths + len(paths) > 70):
            chunks.append(current)
            current, num_paths = [], 0
        current.append(photo)
        num_paths += len(paths)
    if current:
        chunks.append(current)

    deleted = {}

    def remove_chunk(rows):
        if not rows:
            return
        ids = [str(p["id"]) for p in rows]
        try:
            paths = list(dict.fromkeys(path for p in rows for path in photo_all_storage_paths(p) if path))
            if paths:
                client.storage.from_(PHOTO_BUCKET).remove(paths)
            client.table(PHOTO_TABLE).delete().in_("id", ids).eq(
                "family_key", family_key
            ).eq("member_key", member_key).execute()
            for photo in rows:
                deleted[str(photo["id"])] = photo
        except Exception as exc:
            if len(rows) == 1:
                failures.append((ids[0], str(exc)[:300]))
            else:
                middle = len(rows) // 2
                remove_chunk(rows[:middle])
                remove_chunk(rows[middle:])

    for chunk in chunks:
        remove_chunk(chunk)

    if not deleted:
        return {"deleted_count": 0, "failures": failures}

    for row in deleted.values():
        reflection = row.get("reflection_json") or {}
        if not isinstance(reflection, dict):
            continue
        try:
            source_id = str(reflection.get("source_video_photo_id") or "").strip()
            rank = int(reflection.get("source_selection_rank") or 0)
            if source_id and rank > 0:
                _clear_video_ai_saved_photo_link(source_id, rank, str(row.get("id") or ""))
        except Exception:
            pass

    affected_trip_ids = list(dict.fromkeys(str(p["trip_id"]) for p in deleted.values()))
    month_keys = set()
    for trip_id in affected_trip_ids:
        removed_ids = {pid for pid, row in deleted.items() if str(row.get("trip_id")) == trip_id}
        remaining = [row for row in fresh_grouped.get(trip_id, []) if str(row.get("id") or "") not in removed_ids]
        if not remaining:
            # A second device might have added a photo during deletion.
            remaining = list_trip_photos(trip_id)
        existing = diaries.get(trip_id)
        diary_deleted = not remaining
        try:
            if diary_deleted:
                if not skip_existing_diary_lookup:
                    client.table(DIARY_TABLE).delete().eq("trip_id", trip_id).eq(
                        "family_key", family_key
                    ).eq("member_key", member_key).execute()
                client.table(TRIP_TABLE).delete().eq("id", trip_id).eq(
                    "family_key", family_key
                ).eq("member_key", member_key).execute()
            elif existing:
                raw = dict(existing.get("raw_conversation") or {}) if isinstance(existing.get("raw_conversation") or {}, dict) else {}
                for pid in removed_ids:
                    raw.pop(pid, None)
                ai_meta = dict(existing.get("ai_meta") or {}) if isinstance(existing.get("ai_meta") or {}, dict) else {}
                remaining_child_points = []
                for conversation in raw.values():
                    if not isinstance(conversation, list):
                        continue
                    for turn in conversation:
                        if isinstance(turn, dict) and turn.get("role") == "child":
                            value = str(turn.get("text") or "").strip()
                            if value and value not in remaining_child_points:
                                remaining_child_points.append(value)
                ai_meta["child_points"] = remaining_child_points[:3]
                merged_signals = {}
                for photo in remaining:
                    merged_signals = merge_signals(merged_signals, photo.get("signals_json") or {})
                ai_meta["signals"] = merged_signals
                ai_meta["reflection_summary"] = ""
                ai_meta["trip_summary"] = ""
                _clear_summary_feedback_fields(ai_meta, clear_history=True)
                client.table(DIARY_TABLE).update({
                    "raw_conversation": raw,
                    "ai_meta": ai_meta,
                    "updated_at": now_jst().isoformat(),
                }).eq("id", existing["id"]).eq(
                    "family_key", family_key
                ).eq("member_key", member_key).execute()
            _photo_batch_sync_trip_state_v589(trip_id, removed_ids, remaining, diary_deleted)
            if not skip_existing_diary_lookup:
                month = str(trips_by_id.get(trip_id, {}).get("trip_date") or "")[:7]
                if len(month) == 7:
                    month_keys.add(month)
        except Exception as exc:
            failures.append((trip_id, "写真の削除後、日記情報の更新に失敗: " + str(exc)[:220]))

    for month in month_keys:
        try:
            first_day, _ = month_bounds(month)
            client.table(MONTHLY_TABLE).delete().eq("review_month", first_day).eq(
                "family_key", family_key
            ).eq("member_key", member_key).execute()
            for prefix in ("monthly_review_", "monthly_audio_", "monthly_audio_pending_"):
                st.session_state.pop(prefix + month, None)
        except Exception as exc:
            failures.append((month, "月次振り返りの更新に失敗: " + str(exc)[:220]))

    download_photo.clear()
    thumbnail_photo_bytes.clear()
    thumbnail_photo_data_url.clear()
    signed_photo_url_map.clear()
    _invalidate_fast_db_cache()
    return {"deleted_count": len(deleted), "failures": failures}


def delete_photo_and_related_data(
    trip_id,
    photo_id,
    known_photos=None,
    known_trip=None,
    skip_existing_diary_lookup=False,
):
    """Delete one photo; if it was the last image, remove the empty diary/trip too.

    Pending-diary grids already know the trip/photo metadata and know that no saved
    diary exists. Reusing that information avoids several Supabase round-trips.
    """
    client = supabase_client()
    trip = dict(known_trip) if isinstance(known_trip, dict) else (get_trip(trip_id) or {})
    photos = list(known_photos) if isinstance(known_photos, (list, tuple)) else list_trip_photos(trip_id)
    photo = next((p for p in photos if p.get("id") == photo_id), None)
    if not photo:
        raise ValueError("削除する画像が見つかりませんでした。")

    try:
        reflection = photo.get("reflection_json") or {}
        reflection = reflection if isinstance(reflection, dict) else {}
        source_video_id = str(reflection.get("source_video_photo_id") or "").strip()
        source_selection_rank = int(reflection.get("source_selection_rank") or 0)
        if source_video_id and source_selection_rank > 0:
            _clear_video_ai_saved_photo_link(source_video_id, source_selection_rank, str(photo_id or ""))
    except Exception:
        pass

    storage_paths = photo_all_storage_paths(photo)
    if storage_paths:
        client.storage.from_(PHOTO_BUCKET).remove(storage_paths)

    client.table(PHOTO_TABLE).delete().eq("id", photo_id).eq("trip_id", trip_id).eq(
        "family_key", current_family_key()
    ).eq("member_key", current_member_key()).execute()

    # We already have the gallery's photo metadata, so normal deletions need no
    # second photo-list query. Only when it looks like the last image was removed do
    # one tiny verification query, protecting against another device adding a photo
    # at the same moment.
    remaining_photos = [p for p in photos if p.get("id") != photo_id]
    if not remaining_photos:
        remaining_photos = (
            client
            .table(PHOTO_TABLE)
            .select("id,trip_id,storage_path,captured_at,reflection_json,signals_json")
            .eq("trip_id", trip_id)
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .order("captured_at")
            .execute()
        ).data or []
    existing = None if skip_existing_diary_lookup else get_diary_for_trip(trip_id)
    diary_deleted = not remaining_photos

    if diary_deleted:
        # An image-less record has no source material in this app. Pending trips have
        # no diary row, so skip that unnecessary delete request in the fast path.
        if not skip_existing_diary_lookup:
            client.table(DIARY_TABLE).delete().eq("trip_id", trip_id).eq(
                "family_key", current_family_key()
            ).eq("member_key", current_member_key()).execute()
        client.table(TRIP_TABLE).delete().eq("id", trip_id).eq(
            "family_key", current_family_key()
        ).eq("member_key", current_member_key()).execute()
    elif existing:
        raw = existing.get("raw_conversation") or {}
        if not isinstance(raw, dict):
            raw = {}
        raw.pop(str(photo_id), None)
        raw.pop(photo_id, None)

        ai_meta = existing.get("ai_meta") or {}
        if not isinstance(ai_meta, dict):
            ai_meta = {}
        remaining_child_points = []
        for conversation in raw.values():
            if not isinstance(conversation, list):
                continue
            for turn in conversation:
                if isinstance(turn, dict) and turn.get("role") == "child":
                    value = str(turn.get("text") or "").strip()
                    if value and value not in remaining_child_points:
                        remaining_child_points.append(value)
        ai_meta["child_points"] = remaining_child_points[:3]

        merged_signals = {}
        for remaining in remaining_photos:
            merged_signals = merge_signals(merged_signals, remaining.get("signals_json") or {})
        ai_meta["signals"] = merged_signals
        ai_meta["reflection_summary"] = ""
        ai_meta["trip_summary"] = ""
        _clear_summary_feedback_fields(ai_meta, clear_history=True)

        (
            client
            .table(DIARY_TABLE)
            .update(
                {
                    "raw_conversation": raw,
                    "ai_meta": ai_meta,
                    "updated_at": now_jst().isoformat(),
                }
            )
            .eq("id", existing["id"])
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .execute()
        )

    # A monthly summary may contain content from the removed image/emotion.
    trip_date = str(trip.get("trip_date") or "")
    month_key = trip_date[:7] if len(trip_date) >= 7 else ""
    if month_key and not skip_existing_diary_lookup:
        first_day, _ = month_bounds(month_key)
        client.table(MONTHLY_TABLE).delete().eq("review_month", first_day).eq(
            "family_key", current_family_key()
        ).eq("member_key", current_member_key()).execute()
        for key in (
            f"monthly_review_{month_key}",
            f"monthly_audio_{month_key}",
            f"monthly_audio_pending_{month_key}",
        ):
            st.session_state.pop(key, None)

    state_key = f"reflection_state_{trip_id}"
    state = st.session_state.get(state_key)
    if diary_deleted:
        st.session_state.pop(state_key, None)
    elif isinstance(state, dict):
        old_ids = list(state.get("photo_ids") or [])
        old_index = int(state.get("photo_index") or 0)
        if photo_id in old_ids:
            deleted_index = old_ids.index(photo_id)
            new_ids = [pid for pid in old_ids if pid != photo_id]
            state["photo_ids"] = new_ids
            items = state.get("items") or {}
            if isinstance(items, dict):
                items.pop(photo_id, None)
            if deleted_index < old_index:
                state["photo_index"] = max(0, old_index - 1)
            elif deleted_index == old_index:
                state["photo_index"] = min(old_index, len(new_ids) - 1)
            else:
                state["photo_index"] = min(old_index, len(new_ids) - 1)
            state["draft"] = None
            state["draft_title"] = None
            state["draft_meta"] = {}
            state["raw_conversation"] = {}
            state["draft_audio"] = None
            state["draft_audio_pending"] = False
            state["audio_bytes"] = None
            state["audio_pending"] = False
            state["answer_serial"] = int(state.get("answer_serial") or 0) + 1
            if state.get("selected_photo_id") == photo_id:
                state["selected_photo_id"] = new_ids[0] if new_ids else None

    remaining_ids = [p.get("id") for p in remaining_photos if p.get("id")]
    selected_key = f"diary_selected_photo_{trip_id}"
    if remaining_ids:
        if st.session_state.get(selected_key) == photo_id:
            st.session_state[selected_key] = remaining_ids[0]
    else:
        st.session_state.pop(selected_key, None)

    st.session_state.pop(f"delete_photo_selector_{trip_id}", None)
    if st.session_state.get(f"diary_talk_photo_{trip_id}") == photo_id or diary_deleted:
        st.session_state.pop(f"diary_talk_photo_{trip_id}", None)
    if st.session_state.pop(f"diary_existing_photo_view_{trip_id}", False):
        st.session_state.pop(state_key, None)

    if diary_deleted:
        st.session_state.pop(f"_diary_title_override_{trip_id}", None)
        if st.session_state.get("history_detail_trip_id") == trip_id:
            st.session_state.pop("history_detail_trip_id", None)
        if str(st.session_state.get("preferred_diary_trip_id") or "") == str(trip_id):
            st.session_state.preferred_diary_trip_id = None
        if str(st.session_state.get("active_trip_id") or "") == str(trip_id):
            st.session_state.active_trip_id = None
            _invalidate_active_trip_snapshot()
        st.session_state["_diary_selector_serial"] = int(
            st.session_state.get("_diary_selector_serial") or 0
        ) + 1

    # Clear only image/data caches affected by this deletion. This also prevents a
    # just-deleted image from lingering visually in a cached thumbnail.
    download_photo.clear()
    thumbnail_photo_bytes.clear()
    thumbnail_photo_data_url.clear()
    signed_photo_url_map.clear()
    _invalidate_fast_db_cache()
    return {
        "month_key": month_key,
        "diary_deleted": diary_deleted,
        "remaining_photo_count": len(remaining_photos),
    }


def delete_video_and_related_data(video_photo):
    """Delete one saved video plus its poster/AI working files and DB record."""
    if not isinstance(video_photo, dict) or not photo_is_video(video_photo):
        raise ValueError("削除する動画が見つかりませんでした。")
    photo_id = str(video_photo.get("id") or "").strip()
    trip_id = str(video_photo.get("trip_id") or "").strip()
    if not photo_id or not trip_id:
        raise ValueError("削除する動画の情報を確認できませんでした。")

    # Best effort: stop a queued/running selector from doing more work for a video
    # that the user has explicitly removed. Running provider calls may not cancel,
    # but later DB writes are owner/id guarded and will simply find no row.
    try:
        registry = _video_ai_job_registry()
        with registry["lock"]:
            future = registry["futures"].pop(photo_id, None)
            if future is not None:
                future.cancel()
    except Exception:
        pass

    result = delete_photo_and_related_data(trip_id, photo_id)

    # Clear video-specific counters/audits immediately so the UI and quota checks
    # reflect the newly freed Storage rather than waiting for cache expiry.
    try:
        _home_video_counts_cached.clear()
    except Exception:
        pass
    try:
        _invalidate_video_storage_audit_cache()
    except Exception:
        pass
    if st.session_state.get(f"_camera_recent_photo_{trip_id}") == photo_id:
        st.session_state.pop(f"_camera_recent_photo_{trip_id}", None)
    return result


def render_video_delete_controls(
    video_photo,
    key_prefix,
    begin_label="🗑 この動画を削除",
    confirm_label="動画を削除",
    success_message="動画を削除しました。",
):
    """Show a two-step delete control directly below any displayed saved video."""
    if not isinstance(video_photo, dict) or not photo_is_video(video_photo):
        return
    photo_id = str(video_photo.get("id") or "").strip()
    if not photo_id:
        return
    safe_prefix = str(key_prefix or "video").replace(" ", "_")
    state_key = f"_video_delete_confirm_{safe_prefix}_{photo_id}"

    if not st.session_state.get(state_key):
        if st.button(
            str(begin_label or "🗑 この動画を削除"),
            use_container_width=True,
            key=f"video_delete_begin_{safe_prefix}_{photo_id}",
        ):
            st.session_state[state_key] = True
            st.rerun()

    if st.session_state.get(state_key):
        delete_col, cancel_col = st.columns([1.35, 0.85], gap="small")
        with delete_col:
            if st.button(
                str(confirm_label or "動画を削除"),
                type="primary",
                use_container_width=True,
                key=f"video_delete_yes_{safe_prefix}_{photo_id}",
            ):
                try:
                    delete_video_and_related_data(video_photo)
                    st.session_state.pop(state_key, None)
                    reload_current_page_after_action(
                        "_video_delete_notice",
                        str(success_message or "動画を削除しました。"),
                    )
                except Exception as exc:
                    st.error("動画を削除できませんでした。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))
        with cancel_col:
            if st.button(
                "やめる",
                use_container_width=True,
                key=f"video_delete_no_{safe_prefix}_{photo_id}",
            ):
                st.session_state.pop(state_key, None)
                st.rerun()


@st.dialog("この動画を削除しますか？")
def show_video_delete_dialog(video_photo):
    """Confirm deletion started from the × button on a video card."""
    if not isinstance(video_photo, dict) or not photo_is_video(video_photo):
        st.warning("この動画はすでに削除されているか、読み込めませんでした。")
        return

    photo_id = str(video_photo.get("id") or "").strip()
    if not photo_id:
        st.warning("削除する動画を確認できませんでした。")
        return

    st.markdown(f"**{html.escape(_moments_video_title(video_photo))}**")
    yes_col, no_col = st.columns([1.35, 0.85], gap="small")
    with yes_col:
        if st.button(
            "動画を削除",
            type="primary",
            use_container_width=True,
            key=f"video_grid_delete_yes_{photo_id}",
        ):
            try:
                delete_video_and_related_data(video_photo)
                reload_current_page_after_action("_video_delete_notice", "動画を削除しました。")
            except Exception as exc:
                st.error("動画を削除できませんでした。")
                with st.expander("保護者向け詳細"):
                    st.code(str(exc))
    with no_col:
        if st.button(
            "やめる",
            use_container_width=True,
            key=f"video_grid_delete_no_{photo_id}",
        ):
            st.rerun()


def render_video_batch_delete_controls(videos):
    """Allow multiple saved videos to be selected and deleted in one confirmed action."""
    rows = [row for row in list(videos or []) if isinstance(row, dict) and photo_is_video(row)]
    if not rows:
        return

    open_key = "_video_batch_delete_open"
    selected_key = "_video_batch_delete_selected_ids"
    confirm_key = "_video_batch_delete_confirm"
    running_key = "_video_batch_delete_running_ids"

    valid_ids = [str(row.get("id") or "").strip() for row in rows]
    valid_ids = [value for value in valid_ids if value]
    row_by_id = {str(row.get("id") or "").strip(): row for row in rows if str(row.get("id") or "").strip()}

    # Drop stale selections when the underlying vault changed after a deletion.
    stored = st.session_state.get(selected_key)
    if isinstance(stored, list):
        cleaned = [str(value) for value in stored if str(value) in row_by_id]
        if cleaned != stored:
            st.session_state[selected_key] = cleaned
    elif stored is not None:
        st.session_state[selected_key] = []

    if not st.session_state.get(open_key):
        st.session_state.pop(running_key, None)
        if st.button(
            "🗑 動画をまとめて削除",
            use_container_width=True,
            key="video_batch_delete_open_button",
        ):
            st.session_state[open_key] = True
            st.session_state.pop(confirm_key, None)
            st.session_state.pop(running_key, None)
            st.rerun()
        return

    with st.container(border=True):
        st.markdown("#### 🗑 動画をまとめて削除")

        running_ids = st.session_state.get(running_key)
        if isinstance(running_ids, list) and running_ids:
            running_rows = [row_by_id[value] for value in running_ids if value in row_by_id]
            st.caption("選択した動画を削除しています。完了するまでそのままお待ちください。")
            running_yes_col, running_no_col = st.columns([1.35, 0.85], gap="small")
            with running_yes_col:
                st.button(
                    f"削除中…（{len(running_rows)}本）",
                    type="primary",
                    use_container_width=True,
                    disabled=True,
                    key="video_batch_delete_running",
                )
            with running_no_col:
                st.button(
                    "処理中",
                    use_container_width=True,
                    disabled=True,
                    key="video_batch_delete_running_wait",
                )

            deleted_count = 0
            failures = []
            for row in list(running_rows):
                try:
                    delete_video_and_related_data(row)
                    deleted_count += 1
                except Exception as exc:
                    failures.append((_moments_video_title(row), str(exc)))

            st.session_state.pop(open_key, None)
            st.session_state.pop(selected_key, None)
            st.session_state.pop(confirm_key, None)
            st.session_state.pop(running_key, None)
            st.session_state.pop("_video_library_grid_page", None)
            st.session_state["_video_library_grid_serial"] = int(
                st.session_state.get("_video_library_grid_serial") or 0
            ) + 1

            if failures:
                notice = f"{deleted_count}本を削除しました。{len(failures)}本は削除できませんでした。"
                st.session_state["_video_batch_delete_failures"] = failures
            else:
                notice = f"選択した動画を{deleted_count}本削除しました。"
                st.session_state.pop("_video_batch_delete_failures", None)
            reload_current_page_after_action("_video_delete_notice", notice)
            return


        all_col, clear_col, close_col = st.columns(3, gap="small")
        with all_col:
            if st.button("すべて選択", use_container_width=True, key="video_batch_select_all"):
                st.session_state[selected_key] = list(valid_ids)
                st.session_state.pop(confirm_key, None)
                st.rerun()
        with clear_col:
            if st.button("選択解除", use_container_width=True, key="video_batch_clear_all"):
                st.session_state[selected_key] = []
                st.session_state.pop(confirm_key, None)
                st.rerun()
        with close_col:
            if st.button("閉じる", use_container_width=True, key="video_batch_close"):
                st.session_state.pop(open_key, None)
                st.session_state.pop(selected_key, None)
                st.session_state.pop(confirm_key, None)
                st.session_state.pop(running_key, None)
                st.rerun()

        def _batch_video_label(video_id):
            row = row_by_id.get(str(video_id)) or {}
            metadata = photo_media_metadata(row)
            parts = [_moments_video_title(row)]
            duration_ms = max(0, int(metadata.get("video_duration_ms") or 0))
            size_value = max(0, int(metadata.get("video_size_bytes") or 0))
            if duration_ms:
                parts.append(f"{max(1, round(duration_ms / 1000))}秒")
            if size_value:
                parts.append(format_storage_size(size_value))
            return " ／ ".join(part for part in parts if part)

        selected_ids = st.multiselect(
            "削除する動画",
            options=valid_ids,
            format_func=_batch_video_label,
            key=selected_key,
            placeholder="動画を選択",
        )
        selected_rows = [row_by_id[value] for value in selected_ids if value in row_by_id]
        selected_size = sum(
            max(0, int(photo_media_metadata(row).get("video_size_bytes") or 0))
            for row in selected_rows
        )
        if selected_rows:
            st.caption(f"選択中：{len(selected_rows)}本 ／ 約 {format_storage_size(selected_size)}")
        else:
            st.caption("まだ動画を選択していません。")

        if not st.session_state.get(confirm_key):
            if st.button(
                f"選んだ動画を削除する（{len(selected_rows)}本）",
                type="primary",
                use_container_width=True,
                disabled=not selected_rows,
                key="video_batch_delete_prepare",
            ):
                st.session_state[confirm_key] = True
                st.rerun()
            return

        st.warning(
            f"選択した{len(selected_rows)}本の元動画を削除します。"
            "削除した動画は動画保管庫から元に戻せません。"
        )
        yes_col, no_col = st.columns([1.35, 0.85], gap="small")
        with yes_col:
            if st.button(
                f"{len(selected_rows)}本を削除",
                type="primary",
                use_container_width=True,
                disabled=not selected_rows,
                key="video_batch_delete_execute",
            ):
                # v423: switch to a dedicated progress-state rerun before performing
                # network/storage deletion so Android immediately shows the new label
                # and colour and the destructive button cannot be pressed twice.
                st.session_state[running_key] = [
                    str(row.get("id") or "").strip()
                    for row in selected_rows
                    if str(row.get("id") or "").strip()
                ]
                st.rerun()
        with no_col:
            if st.button(
                "やめる",
                use_container_width=True,
                key="video_batch_delete_cancel",
            ):
                st.session_state.pop(confirm_key, None)
                st.session_state.pop(running_key, None)
                st.rerun()


def render_photo_batch_delete_controls_v442(
    photos,
    scope_key,
    *,
    button_label="🗑 写真をまとめて削除",
    panel_title="🗑 写真をまとめて削除",
    force_pending=False,
):
    """Select and delete several still photos with an explicit final confirmation.

    Deletions are intentionally performed one-by-one through the established single-photo
    deletion routine. That keeps diary/trip cleanup correct when several selected photos
    belong to the same trip and the last remaining image disappears during the batch.
    """
    rows = [
        row for row in list(photos or [])
        if isinstance(row, dict)
        and not photo_is_video(row)
        and str(row.get("id") or "").strip()
        and str(row.get("trip_id") or "").strip()
    ]
    if not rows:
        return False

    scope_text = str(scope_key or "photo_batch")
    scope_token = hashlib.sha1(scope_text.encode("utf-8")).hexdigest()[:12]
    open_key = f"_photo_batch_delete_open_v442_{scope_token}"
    selected_key = f"_photo_batch_delete_selected_v442_{scope_token}"
    confirm_key = f"_photo_batch_delete_confirm_v442_{scope_token}"
    running_key = f"_photo_batch_delete_running_v442_{scope_token}"
    failure_key = f"_photo_batch_delete_failures_v442_{scope_token}"

    valid_ids = [str(row.get("id") or "").strip() for row in rows]
    row_by_id = {str(row.get("id") or "").strip(): row for row in rows}
    order_by_id = {photo_id: index + 1 for index, photo_id in enumerate(valid_ids)}

    stored = st.session_state.get(selected_key)
    if isinstance(stored, list):
        cleaned = [str(value) for value in stored if str(value) in row_by_id]
        if cleaned != stored:
            st.session_state[selected_key] = cleaned
    elif stored is not None:
        st.session_state[selected_key] = []

    failures = st.session_state.pop(failure_key, None)
    if isinstance(failures, list) and failures:
        with st.expander("削除できなかった写真の詳細"):
            for label, detail in failures:
                st.write(f"・{label}")
                st.code(str(detail))

    if not st.session_state.get(open_key):
        st.session_state.pop(running_key, None)
        if st.button(
            str(button_label or "🗑 写真をまとめて削除"),
            use_container_width=True,
            key=f"photo_batch_delete_open_{scope_token}",
        ):
            st.session_state[open_key] = True
            st.session_state.pop(confirm_key, None)
            st.session_state.pop(running_key, None)
            st.rerun()
        return False

    with st.container(border=True):
        st.markdown(f"#### {panel_title}")

        running_ids = st.session_state.get(running_key)
        if isinstance(running_ids, list) and running_ids:
            running_rows = [row_by_id[value] for value in running_ids if value in row_by_id]
            st.caption("選択した写真を削除しています。完了するまでそのままお待ちください。")
            running_col, wait_col = st.columns([1.35, 0.85], gap="small")
            with running_col:
                st.button(
                    f"削除中…（{len(running_rows)}枚）",
                    type="primary",
                    use_container_width=True,
                    disabled=True,
                    key=f"photo_batch_delete_running_{scope_token}",
                )
            with wait_col:
                st.button(
                    "処理中",
                    use_container_width=True,
                    disabled=True,
                    key=f"photo_batch_delete_running_wait_{scope_token}",
                )

            with st.spinner("写真をまとめて削除しています…"):
                result = delete_photos_in_batches_v589(
                    [str(row.get("id") or "") for row in running_rows],
                    photos=running_rows,
                    skip_existing_diary_lookup=bool(force_pending),
                )
            deleted_count = int(result.get("deleted_count") or 0)
            delete_failures = result.get("failures") or []

            st.session_state.pop(open_key, None)
            st.session_state.pop(selected_key, None)
            st.session_state.pop(confirm_key, None)
            st.session_state.pop(running_key, None)

            if delete_failures:
                notice = f"{deleted_count}枚を削除しました。{len(delete_failures)}件の処理エラーがあります。"
                st.session_state[failure_key] = delete_failures
            else:
                notice = f"選択した写真を{deleted_count}枚削除しました。"
                st.session_state.pop(failure_key, None)
            reload_current_page_after_action("_diary_notice", notice)
            return True

        all_col, clear_col, close_col = st.columns(3, gap="small")
        with all_col:
            if st.button("すべて選択", use_container_width=True, key=f"photo_batch_select_all_{scope_token}"):
                st.session_state[selected_key] = list(valid_ids)
                st.session_state.pop(confirm_key, None)
                st.rerun()
        with clear_col:
            if st.button("選択解除", use_container_width=True, key=f"photo_batch_clear_all_{scope_token}"):
                st.session_state[selected_key] = []
                st.session_state.pop(confirm_key, None)
                st.rerun()
        with close_col:
            if st.button("閉じる", use_container_width=True, key=f"photo_batch_close_{scope_token}"):
                st.session_state.pop(open_key, None)
                st.session_state.pop(selected_key, None)
                st.session_state.pop(confirm_key, None)
                st.session_state.pop(running_key, None)
                st.rerun()

        def _batch_photo_label(photo_id):
            row = row_by_id.get(str(photo_id)) or {}
            number = order_by_id.get(str(photo_id), 0)
            parts = [f"写真{number}" if number else "写真"]
            captured = _photo_library_captured_label_v418(row.get("captured_at"))
            if captured:
                parts.append(captured)
            location = str(photo_location_label(row) or "").strip()
            if location:
                parts.append(location)
            if photo_favorite_is_enabled(row):
                parts.append("★ お気に入り")
            return " ／ ".join(parts)

        selected_ids = st.multiselect(
            "削除する写真",
            options=valid_ids,
            format_func=_batch_photo_label,
            key=selected_key,
            placeholder="写真を選択",
        )
        selected_rows = [row_by_id[value] for value in selected_ids if value in row_by_id]
        if selected_rows:
            st.caption(f"選択中：{len(selected_rows)}枚")
        else:
            st.caption("まだ写真を選択していません。")

        if not st.session_state.get(confirm_key):
            if st.button(
                f"選んだ写真を削除する（{len(selected_rows)}枚）",
                type="primary",
                use_container_width=True,
                disabled=not selected_rows,
                key=f"photo_batch_delete_prepare_{scope_token}",
            ):
                st.session_state[confirm_key] = True
                st.rerun()
            return False

        st.warning(
            f"選択した{len(selected_rows)}枚の写真を削除します。"
            "写真に付けた感情・声・共有情報も削除され、元に戻せません。"
        )
        yes_col, no_col = st.columns([1.35, 0.85], gap="small")
        with yes_col:
            if st.button(
                f"{len(selected_rows)}枚を削除",
                type="primary",
                use_container_width=True,
                disabled=not selected_rows,
                key=f"photo_batch_delete_execute_{scope_token}",
            ):
                st.session_state[running_key] = [
                    str(row.get("id") or "").strip()
                    for row in selected_rows
                    if str(row.get("id") or "").strip()
                ]
                st.rerun()
        with no_col:
            if st.button(
                "やめる",
                use_container_width=True,
                key=f"photo_batch_delete_cancel_{scope_token}",
            ):
                st.session_state.pop(confirm_key, None)
                st.session_state.pop(running_key, None)
                st.rerun()
    return False


def reset_photo_conversation(trip_id, photo_id):
    """Clear only the conversation/signals for one photo while keeping the image."""
    client = supabase_client()
    trip = get_trip(trip_id) or {}

    # update_photo_reflection preserves capture/location metadata in reflection_json.
    update_photo_reflection(photo_id, [], {}, done=False)

    # If a completed diary already exists, the copied raw conversation and AI
    # analysis must not keep showing a comment that was just reset. Keep the diary
    # prose itself, matching the existing reset behavior.
    existing = get_diary_for_trip(trip_id)
    if existing:
        raw = existing.get("raw_conversation") or {}
        if not isinstance(raw, dict):
            raw = {}
        raw.pop(str(photo_id), None)
        raw.pop(photo_id, None)

        ai_meta = existing.get("ai_meta") or {}
        if not isinstance(ai_meta, dict):
            ai_meta = {}
        remaining_child_points = []
        for conversation in raw.values():
            if not isinstance(conversation, list):
                continue
            for turn in conversation:
                if isinstance(turn, dict) and turn.get("role") == "child":
                    value = str(turn.get("text") or "").strip()
                    if value and value not in remaining_child_points:
                        remaining_child_points.append(value)
        ai_meta["child_points"] = remaining_child_points[:3]
        ai_meta["reflection_summary"] = ""
        ai_meta["trip_summary"] = ""
        _clear_summary_feedback_fields(ai_meta, clear_history=True)

        remaining_photos = list_trip_photos(trip_id)
        merged_signals = {}
        for remaining in remaining_photos:
            if remaining.get("id") == photo_id:
                continue
            merged_signals = merge_signals(merged_signals, remaining.get("signals_json") or {})
        ai_meta["signals"] = merged_signals

        (
            client
            .table(DIARY_TABLE)
            .update(
                {
                    "raw_conversation": raw,
                    "ai_meta": ai_meta,
                    "updated_at": now_jst().isoformat(),
                }
            )
            .eq("id", existing["id"])
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .execute()
        )

    # A saved monthly review may contain wording from this photo conversation.
    trip_date = str(trip.get("trip_date") or "")
    month_key = trip_date[:7] if len(trip_date) >= 7 else ""
    if month_key:
        first_day, _ = month_bounds(month_key)
        client.table(MONTHLY_TABLE).delete().eq("review_month", first_day).eq("family_key", current_family_key()).eq("member_key", current_member_key()).execute()
        for key in (
            f"monthly_review_{month_key}",
            f"monthly_audio_{month_key}",
            f"monthly_audio_pending_{month_key}",
        ):
            st.session_state.pop(key, None)

    state = st.session_state.get(f"reflection_state_{trip_id}")
    if isinstance(state, dict):
        items = state.setdefault("items", {})
        items[photo_id] = {
            "conversation": [],
            "signals": {},
            "done": False,
            "started": False,
        }
        state["selected_photo_id"] = photo_id
        photo_ids = list(state.get("photo_ids") or [])
        if photo_id in photo_ids:
            state["photo_index"] = photo_ids.index(photo_id)
        state["audio_bytes"] = None
        state["audio_pending"] = False
        state["answer_serial"] = int(state.get("answer_serial") or 0) + 1
        # Any unsaved draft was based on the old conversation, so require rebuilding it.
        state["draft"] = None
        state["draft_title"] = None
        state["draft_meta"] = {}
        state["raw_conversation"] = {}
        state["draft_audio"] = None
        state["draft_audio_pending"] = False

    st.session_state[f"diary_selected_photo_{trip_id}"] = photo_id
    return {"month_key": month_key}


@st.dialog("この画像の会話をリセットしますか？")
def confirm_photo_conversation_reset_dialog(trip_id, photo_id):
    photos = list_trip_photos(trip_id)
    photo_ids = [p.get("id") for p in photos]
    if photo_id not in photo_ids:
        st.warning("この画像は見つかりません。")
        if st.button("閉じる", use_container_width=True, key=f"dialog_reset_missing_{trip_id}"):
            st.rerun(scope="app")
        return

    photo_number = photo_ids.index(photo_id) + 1
    st.write(f"**写真 {photo_number} / {len(photo_ids)}** の会話をリセットします。")
    st.warning(
        "この画像について保存した本人の発言、AIとの会話、感情・Wantの記録を消します。"
        "画像そのものと保存済みの日記本文は残ります。"
    )
    reset_col, cancel_col = st.columns(2)
    with reset_col:
        if st.button(
            "リセットする",
            type="primary",
            use_container_width=True,
            key=f"dialog_photo_reset_yes_{trip_id}_{photo_id}",
        ):
            try:
                reset_photo_conversation(trip_id, photo_id)
                st.session_state["_diary_notice"] = "この画像の会話をリセットしました。もう一度、最初から話せます。"
                st.rerun(scope="app")
            except Exception as exc:
                st.error("会話をリセットできませんでした。")
                with st.expander("保護者向け詳細"):
                    st.code(str(exc))
    with cancel_col:
        if st.button(
            "キャンセル",
            use_container_width=True,
            key=f"dialog_photo_reset_no_{trip_id}_{photo_id}",
        ):
            st.rerun(scope="app")


