def render_diary_delete_controls(
    trip_id,
    photos,
    current_photo_id=None,
    show_photo_navigation=False,
):
    """Render photo navigation/reset/delete controls and whole-day delete at the bottom."""
    st.divider()

    photo_ids = [p.get("id") for p in photos if p.get("id")]
    selected_key = f"diary_selected_photo_{trip_id}"
    selected_photo_id = current_photo_id if current_photo_id in photo_ids else st.session_state.get(selected_key)
    if selected_photo_id not in photo_ids:
        selected_photo_id = photo_ids[0] if photo_ids else None
        if selected_photo_id:
            st.session_state[selected_key] = selected_photo_id

    if selected_photo_id:
        photo_index = photo_ids.index(selected_photo_id)
        photo_number = photo_index + 1
        st.caption(f"写真 {photo_number} / {len(photo_ids)}")

        if show_photo_navigation:
            has_next_photo = photo_index < len(photo_ids) - 1
            nav_label = "次の写真へ" if has_next_photo else "前の画面に戻る"
            with st.container(key="diary_photo_nav"):
                if st.button(
                    nav_label,
                    use_container_width=True,
                    key=f"diary_photo_nav_button_{trip_id}_{selected_photo_id}",
                ):
                    if has_next_photo:
                        next_photo_id = photo_ids[photo_index + 1]
                        state = st.session_state.get(f"reflection_state_{trip_id}")
                        if isinstance(state, dict):
                            open_diary_photo_talk(trip_id, next_photo_id, state)
                        else:
                            st.session_state[selected_key] = next_photo_id
                            st.session_state[f"diary_talk_photo_{trip_id}"] = next_photo_id
                        st.rerun()
                    else:
                        st.session_state.pop(f"diary_talk_photo_{trip_id}", None)
                        if st.session_state.pop(f"diary_existing_photo_view_{trip_id}", False):
                            st.session_state.pop(f"reflection_state_{trip_id}", None)
                        st.rerun()

        if st.button(
            "↻ この画像の会話をリセット",
            use_container_width=True,
            key=f"diary_photo_reset_{trip_id}_{selected_photo_id}",
        ):
            confirm_photo_conversation_reset_dialog(trip_id, selected_photo_id)
        if st.button(
            "🗑 この画像を削除",
            use_container_width=True,
            key=f"diary_photo_delete_{trip_id}_{selected_photo_id}",
        ):
            confirm_photo_delete_dialog(trip_id, selected_photo_id, photos=photos)

    if st.button(
        "🗑 この日記を削除",
        use_container_width=True,
        key=f"diary_page_delete_{trip_id}",
    ):
        confirm_diary_delete_dialog(trip_id, len(photos))


def _list_recent_diaries_uncached(limit=60, _owner=None, _client=None):
    """Load diaries and their trip metadata in one PostgREST request when available."""
    owner = _owner or _owner_v468()
    client = _client or supabase_client()
    try:
        relation = TRIP_TABLE
        rows = (
            client
            .table(DIARY_TABLE)
            .select(f"*,{relation}(*)")
            .eq("family_key", owner[2]).eq("member_key", owner[3])
            .order("created_at", desc=True)
            .limit(limit)
            .execute()
        ).data or []
        bundled = []
        for diary in rows:
            trip = diary.pop(relation, None) if isinstance(diary, dict) else None
            if isinstance(trip, list):
                trip = trip[0] if trip else None
            if isinstance(trip, dict) and trip.get("id"):
                bundled.append({"diary": diary, "trip": trip})
        if bundled or not rows:
            return bundled
    except Exception:
        pass

    # Compatibility fallback for PostgREST schemas where relationship embedding is
    # not exposed yet. Still batched: two requests total, never N+1.
    result = (
        client
        .table(DIARY_TABLE)
        .select("*")
        .eq("family_key", owner[2]).eq("member_key", owner[3])
        .order("created_at", desc=True)
        .limit(limit)
        .execute()
    )
    diaries = result.data or []
    if not diaries:
        return []
    trip_ids = list({d["trip_id"] for d in diaries if d.get("trip_id")})
    trip_result = (
        client
        .table(TRIP_TABLE)
        .select("*")
        .eq("family_key", owner[2]).eq("member_key", owner[3])
        .in_("id", trip_ids)
        .execute()
    )
    trip_map = {t["id"]: t for t in (trip_result.data or [])}
    return [
        {"diary": d, "trip": trip_map.get(d["trip_id"], {})}
        for d in diaries
        if d.get("trip_id") in trip_map
    ]


def list_recent_diaries(limit=60):
    cache_key = _account_cache_key("recent_diaries", int(limit))
    cached = _session_cache_get(cache_key, max_age_seconds=90)
    if cached is not None:
        return cached
    started = time.perf_counter()
    rows = _list_recent_diaries_uncached(limit=limit)
    _perf_log_v457("db:recent_diaries", started_at=started, meta={"count": len(rows or [])}, force=True)
    return _session_cache_set(cache_key, rows)


def month_bounds(month_key):
    year, month = [int(x) for x in month_key.split("-")]
    start = date(year, month, 1)
    if month == 12:
        end = date(year + 1, 1, 1)
    else:
        end = date(year, month + 1, 1)
    return start.isoformat(), end.isoformat()


def previous_month_key(month_key=None):
    if month_key:
        year, month = [int(x) for x in str(month_key).split("-")]
        first = date(year, month, 1)
    else:
        today = now_jst().date()
        first = date(today.year, today.month, 1)
    return (first - timedelta(days=1)).strftime("%Y-%m")


def _month_has_photo_input(month_key):
    """True when the month has a diary or at least one explicit photo emotion."""
    start, end = month_bounds(month_key)
    client = supabase_client()

    def photo_has_emotion(photo):
        return bool(photo_selected_tag_key(photo))

    try:
        rows = (
            client
            .table(TRIP_TABLE)
            .select(f"id,{DIARY_TABLE}(id),{PHOTO_TABLE}(id,reflection_json)")
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .gte("trip_date", start)
            .lt("trip_date", end)
            .execute()
        ).data or []
        for row in rows:
            diaries = (row or {}).get(DIARY_TABLE) or []
            if isinstance(diaries, dict):
                diaries = [diaries]
            if diaries:
                return True
            photos = (row or {}).get(PHOTO_TABLE) or []
            if isinstance(photos, dict):
                photos = [photos]
            if any(photo_has_emotion(photo) for photo in photos):
                return True
        return False
    except Exception:
        trips = (
            client
            .table(TRIP_TABLE)
            .select("id")
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .gte("trip_date", start)
            .lt("trip_date", end)
            .execute()
        ).data or []
        trip_ids = [str(row.get("id")) for row in trips if row.get("id")]
        if not trip_ids:
            return False
        diaries = (
            client
            .table(DIARY_TABLE)
            .select("id")
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .in_("trip_id", trip_ids)
            .limit(1)
            .execute()
        ).data or []
        if diaries:
            return True
        photos = (
            client
            .table(PHOTO_TABLE)
            .select("id,reflection_json")
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .in_("trip_id", trip_ids)
            .execute()
        ).data or []
        return any(photo_has_emotion(photo) for photo in photos)


_BROWSER_STATE_UNSET = object()


def home_review_attention_needed(browser_state=_BROWSER_STATE_UNSET):
    """Nudge once each month when the immediately preceding month has photo input."""
    current_month = now_jst().strftime("%Y-%m")
    prior_month = previous_month_key(current_month)

    if st.session_state.get("_review_seen_month") == current_month:
        return False

    session_check = st.session_state.get("_home_review_attention_check")
    if isinstance(session_check, dict) and (
        str(session_check.get("month") or "") == current_month
        and str(session_check.get("previous_month") or "") == prior_month
    ):
        return bool(session_check.get("has_previous_content"))

    if browser_state is _BROWSER_STATE_UNSET:
        browser_state = read_browser_review_state()
    if isinstance(browser_state, dict):
        if str(browser_state.get("review_seen_month") or "") == current_month:
            st.session_state["_review_seen_month"] = current_month
            return False
        stored_check = browser_state.get("review_check")
        if isinstance(stored_check, dict) and (
            str(stored_check.get("month") or "") == current_month
            and str(stored_check.get("previous_month") or "") == prior_month
        ):
            st.session_state["_home_review_attention_check"] = dict(stored_check)
            return bool(stored_check.get("has_previous_content"))
    elif browser_persistence_component is not None:
        # Keep the first Home paint DB-free. localStorage returns immediately and
        # triggers a cheap rerun; the monthly DB check happens only after that.
        return False

    # v563: The monthly review badge is advisory, not a reason to hold Home
    # while large relational photo/diary queries complete. Prepare it off-thread
    # with the same family/member isolation and only harvest a finished result.
    check = _read_ahead_value_v520("home_review_check", block=False)
    if isinstance(check, dict) and (
        str(check.get("month") or "") == current_month
        and str(check.get("previous_month") or "") == prior_month
    ):
        st.session_state["_home_review_attention_check"] = dict(check)
        write_browser_review_check(check)
        return bool(check.get("has_previous_content"))
    _prime_read_ahead_v520("home_review_check")
    return False


def mark_current_month_review_seen():
    current_month = now_jst().strftime("%Y-%m")
    if st.session_state.get("_review_seen_month") == current_month:
        return
    st.session_state["_review_seen_month"] = current_month
    write_browser_review_seen(current_month)


def format_month_label(month_key):
    try:
        year, month = [int(x) for x in str(month_key).split("-")]
        return f"{year}年{month}月"
    except Exception:
        return str(month_key)


def get_month_bundle(month_key):
    start, end = month_bounds(month_key)
    client = supabase_client()
    try:
        rows = (
            client
            .table(TRIP_TABLE)
            .select(
                f"*,{DIARY_TABLE}(*),"
                f"{PHOTO_TABLE}(id,trip_id,storage_path,captured_at,reflection_json,signals_json)"
            )
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .gte("trip_date", start)
            .lt("trip_date", end)
            .order("trip_date")
            .execute()
        ).data or []
        trips, diaries, photos = [], [], []
        for row in rows:
            if not isinstance(row, dict):
                continue
            trip = dict(row)
            embedded_diaries = trip.pop(DIARY_TABLE, []) or []
            embedded_photos = trip.pop(PHOTO_TABLE, []) or []
            if isinstance(embedded_diaries, dict):
                embedded_diaries = [embedded_diaries]
            if isinstance(embedded_photos, dict):
                embedded_photos = [embedded_photos]
            trips.append(trip)
            diaries.extend(x for x in embedded_diaries if isinstance(x, dict))
            photos.extend(x for x in embedded_photos if isinstance(x, dict))
        return {"trips": trips, "diaries": diaries, "photos": photos}
    except Exception:
        pass

    trips_result = (
        client
        .table(TRIP_TABLE)
        .select("*")
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .gte("trip_date", start)
        .lt("trip_date", end)
        .order("trip_date")
        .execute()
    )
    trips = trips_result.data or []
    if not trips:
        return {"trips": [], "diaries": [], "photos": []}
    trip_ids = [t["id"] for t in trips]
    diaries_result = (
        client
        .table(DIARY_TABLE)
        .select("*")
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .in_("trip_id", trip_ids)
        .execute()
    )
    photos_result = (
        client
        .table(PHOTO_TABLE)
        .select("id,trip_id,storage_path,captured_at,reflection_json,signals_json")
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .in_("trip_id", trip_ids)
        .order("captured_at")
        .execute()
    )
    return {
        "trips": trips,
        "diaries": diaries_result.data or [],
        "photos": photos_result.data or [],
    }

def get_saved_monthly_review(month_key):
    first_day, _ = month_bounds(month_key)
    result = (
        supabase_client()
        .table(MONTHLY_TABLE)
        .select("*")
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .eq("review_month", first_day)
        .limit(1)
        .execute()
    )
    return (result.data or [None])[0]


def save_monthly_review(month_key, review_json):
    first_day, _ = month_bounds(month_key)
    existing = get_saved_monthly_review(month_key)
    payload = {
        "family_key": current_family_key(),
        "member_key": current_member_key(),
        "review_month": first_day,
        "review_json": review_json,
        "updated_at": now_jst().isoformat(),
    }
    if existing:
        (
            supabase_client()
            .table(MONTHLY_TABLE)
            .update(payload)
            .eq("id", existing["id"])
            .eq("family_key", current_family_key()).eq("member_key", current_member_key())
            .execute()
        )
    else:
        payload["created_at"] = now_jst().isoformat()
        supabase_client().table(MONTHLY_TABLE).insert(payload).execute()
    _invalidate_fast_db_cache()


# ============================================================
# AI photo-tag review helpers (v207)
# ============================================================
# AI content tags (for example 子ども / 大人 / 複数人 / 電車 / 食事) are
# different from the user-selected feeling / parenting tags. Tag reviews use only
# reflection_json.ai_tags, which are created by the existing vision tagger.
#
# Persist tag-specific review/music state in the existing monthly-review table so
# no Supabase migration is required. Calendar reviews stay untouched. A private
# historical month range (1800-1899) is reserved for dynamic AI tags; each tag gets
# one stable month slot, with collision resolution if two hashes land together.
AI_TAG_REVIEW_SENTINEL_START = "1800-01-01"
AI_TAG_REVIEW_SENTINEL_END_EXCLUSIVE = "1900-01-01"
AI_TAG_REVIEW_SENTINEL_START_YEAR = 1800
AI_TAG_REVIEW_SENTINEL_MONTH_COUNT = 100 * 12
AI_TAG_REVIEW_SOURCE_LIMIT = 5000
AI_TAG_REVIEW_PRIORITY_TAGS = ("子ども", "大人", "複数人")


def _ai_tag_review_rows():
    try:
        rows = (
            supabase_client()
            .table(MONTHLY_TABLE)
            .select("id,review_month,review_json,created_at,updated_at")
            .eq("family_key", current_family_key())
            .eq("member_key", current_member_key())
            .gte("review_month", AI_TAG_REVIEW_SENTINEL_START)
            .lt("review_month", AI_TAG_REVIEW_SENTINEL_END_EXCLUSIVE)
            .order("review_month")
            .execute()
        ).data or []
        return [row for row in rows if isinstance(row, dict)]
    except Exception:
        return []


def _ai_tag_review_key_from_row(row):
    review = _coerce_review_json((row or {}).get("review_json"))
    if str(review.get("_review_scope_type") or "") != "ai_tag":
        return ""
    # v330: multi-tag reviews use a stable synthetic scope key while old single-tag
    # reviews keep their original tag key, so existing saved reviews remain readable.
    return normalize_ai_photo_tag(review.get("_ai_tag_scope_key") or review.get("_ai_tag_key"))


def _ai_tag_review_storage_candidates(tag_key):
    tag_key = normalize_ai_photo_tag(tag_key)
    if not tag_key:
        return []
    digest = hashlib.sha1(tag_key.encode("utf-8")).hexdigest()
    base = int(digest[:12], 16) % AI_TAG_REVIEW_SENTINEL_MONTH_COUNT
    candidates = []
    for offset in range(AI_TAG_REVIEW_SENTINEL_MONTH_COUNT):
        index = (base + offset) % AI_TAG_REVIEW_SENTINEL_MONTH_COUNT
        year = AI_TAG_REVIEW_SENTINEL_START_YEAR + (index // 12)
        month = (index % 12) + 1
        candidates.append(f"{year:04d}-{month:02d}")
    return candidates


def tag_review_storage_month(tag_key, create=False):
    """Return the reserved storage month assigned to one AI image tag."""
    tag_key = normalize_ai_photo_tag(tag_key)
    if not tag_key:
        raise ValueError("振り返るAIタグを確認できませんでした。")
    rows = _ai_tag_review_rows()
    for row in rows:
        if _ai_tag_review_key_from_row(row) == tag_key:
            value = str(row.get("review_month") or "")[:7]
            if len(value) == 7:
                return value
    if not create:
        return ""

    occupied = {
        str(row.get("review_month") or "")[:7]
        for row in rows
        if len(str(row.get("review_month") or "")) >= 7
    }
    for candidate in _ai_tag_review_storage_candidates(tag_key):
        if candidate not in occupied:
            return candidate
    raise ValueError("AIタグ別振り返りの保存枠を確保できませんでした。")


def get_tag_review_source(limit=AI_TAG_REVIEW_SOURCE_LIMIT):
    """Load still photos across all dates, including AI-tagged and yet-untagged rows."""
    limit = max(1, int(limit))
    cache_key_v561 = _account_cache_key("tag_review_source_v561", limit)
    cached_v561 = _session_cache_get(cache_key_v561, max_age_seconds=90)
    if isinstance(cached_v561, dict):
        return cached_v561
    photos = list_member_still_photos_for_tags(max_items=limit)
    photos = [photo for photo in photos if isinstance(photo, dict) and not photo_is_video(photo)]
    photos.sort(key=lambda photo: (str(photo.get("captured_at") or ""), str(photo.get("id") or "")))

    trip_ids = []
    seen_trip_ids = set()
    for photo in photos:
        trip_id = str(photo.get("trip_id") or "").strip()
        if trip_id and trip_id not in seen_trip_ids:
            seen_trip_ids.add(trip_id)
            trip_ids.append(trip_id)

    trips = []
    client = supabase_client()
    family, member = current_family_key(), current_member_key()
    chunks = [trip_ids[offset:offset + 100] for offset in range(0, len(trip_ids), 100)]
    def fetch(chunk):
        try:
            batch = (client.table(TRIP_TABLE).select("*")
                     .eq("family_key", family).eq("member_key", member)
                     .in_("id", chunk).execute()).data or []
            return [row for row in batch if isinstance(row, dict)]
        except Exception:
            return []
    batches = _read_executor_v467().map(fetch, chunks) if len(chunks) > 1 else map(fetch, chunks)
    for batch in batches:
        trips.extend(batch)

    _queue_framing_rows_v468(photos)
    return _session_cache_set(cache_key_v561, {"trips": trips, "diaries": [], "photos": photos})


def tag_review_counts(source):
    counts = {}
    for photo in (source or {}).get("photos", []) or []:
        for tag in photo_ai_tags(photo):
            counts[tag] = int(counts.get(tag) or 0) + 1
    return counts


def ordered_ai_review_tags(counts):
    counts = counts if isinstance(counts, dict) else {}
    priority = {tag: index for index, tag in enumerate(AI_TAG_REVIEW_PRIORITY_TAGS)}
    return sorted(
        [tag for tag, count in counts.items() if int(count or 0) > 0],
        key=lambda tag: (
            0 if tag in priority else 1,
            priority.get(tag, 999),
            -int(counts.get(tag) or 0),
            tag,
        ),
    )


def _normalize_tag_review_selection(values):
    if isinstance(values, str):
        values = [values]
    result = []
    for value in values or []:
        tag = normalize_ai_photo_tag(value)
        if tag and tag not in result:
            result.append(tag)
    return result[:20]


def tag_review_scope_key(tag_keys, match_mode="any"):
    tags = _normalize_tag_review_selection(tag_keys)
    if not tags:
        return ""
    mode = "all" if str(match_mode or "").lower() == "all" and len(tags) > 1 else "any"
    # Preserve the old storage key for a single tag so all existing reviews continue to open.
    if len(tags) == 1:
        return tags[0]
    canonical = mode + "|" + "|".join(sorted(tags))
    return "multi_" + hashlib.sha1(canonical.encode("utf-8")).hexdigest()[:16]


def tag_review_scope_label(tag_keys, match_mode="any"):
    tags = _normalize_tag_review_selection(tag_keys)
    if not tags:
        return "🏷️ AIタグ"
    if len(tags) == 1:
        return f"🏷️ {tags[0]}"
    if str(match_mode or "").lower() == "all":
        return "🏷️ " + " ＋ ".join(tags)
    return "🏷️ " + " ／ ".join(tags)


def tag_review_bundle(source, tag_key, match_mode="any"):
    tags = _normalize_tag_review_selection(tag_key)
    selected = set(tags)
    mode = "all" if str(match_mode or "").lower() == "all" and len(tags) > 1 else "any"
    photos = []
    for photo in (source or {}).get("photos", []) or []:
        if not isinstance(photo, dict):
            continue
        photo_tags = set(photo_ai_tags(photo))
        matched = selected.issubset(photo_tags) if mode == "all" else bool(selected.intersection(photo_tags))
        if matched:
            photos.append(photo)
    # Each source photo is traversed once, so a photo carrying several selected tags is never duplicated.
    photos.sort(key=lambda photo: (str(photo.get("captured_at") or ""), str(photo.get("id") or "")))
    trip_ids = {str(photo.get("trip_id") or "") for photo in photos if photo.get("trip_id")}
    trips = [
        trip for trip in (source or {}).get("trips", []) or []
        if isinstance(trip, dict) and str(trip.get("id") or "") in trip_ids
    ]
    return {"trips": trips, "diaries": [], "photos": photos}


def tag_review_stats(bundle):
    trip_map = {
        str(trip.get("id") or ""): trip
        for trip in (bundle or {}).get("trips", []) or []
        if isinstance(trip, dict)
    }
    dates = []
    for photo in (bundle or {}).get("photos", []) or []:
        trip = trip_map.get(str(photo.get("trip_id") or ""), {})
        date_value = str((trip or {}).get("trip_date") or "").strip()
        if not date_value:
            captured = str(photo.get("captured_at") or "")
            date_value = captured[:10] if len(captured) >= 10 else ""
        if date_value:
            dates.append(date_value)
    unique_dates = sorted(set(dates))
    return {
        "photo_count": len((bundle or {}).get("photos", []) or []),
        "day_count": len(unique_dates),
        "first_date": unique_dates[0] if unique_dates else "",
        "last_date": unique_dates[-1] if unique_dates else "",
    }


def build_tag_review_evidence(tag_key, bundle, max_lines=70, match_mode="any"):
    tags = _normalize_tag_review_selection(tag_key)
    selected = set(tags)
    trip_map = {
        str(trip.get("id") or ""): trip
        for trip in (bundle or {}).get("trips", []) or []
        if isinstance(trip, dict)
    }
    related_counts = {}
    rows = []
    photos = list((bundle or {}).get("photos", []) or [])
    photos.sort(key=lambda photo: (str(photo.get("captured_at") or ""), str(photo.get("id") or "")))

    for photo in photos:
        for other_tag in photo_ai_tags(photo):
            if other_tag and other_tag not in selected:
                related_counts[other_tag] = int(related_counts.get(other_tag) or 0) + 1

    sampled = photos
    if len(sampled) > max_lines:
        step = len(sampled) / float(max_lines)
        sampled = [sampled[min(int(index * step), len(sampled) - 1)] for index in range(max_lines)]

    for photo in sampled:
        trip = trip_map.get(str(photo.get("trip_id") or ""), {})
        date_value = str((trip or {}).get("trip_date") or "").strip()
        if not date_value:
            captured = str(photo.get("captured_at") or "")
            date_value = captured[:10] if len(captured) >= 10 else "日付不明"
        place = str(photo_location_label(photo) or (trip or {}).get("destination") or "").strip()
        photo_tags = photo_ai_tags(photo)
        selected_here = [tag for tag in photo_tags if tag in selected]
        related = [tag for tag in photo_tags if tag not in selected][:5]
        row = f"[{date_value}] {place or '場所メモなし'}"
        if selected_here:
            row += " / 選択タグ: " + "、".join(selected_here)
        if related:
            row += " / 関連AIタグ: " + "、".join(related)
        rows.append(row)

    related_top = sorted(related_counts, key=lambda tag: (-related_counts[tag], tag))[:10]
    stats = tag_review_stats(bundle)
    return {
        "text": "\n".join(rows),
        "photo_count": int(stats.get("photo_count") or 0),
        "day_count": int(stats.get("day_count") or 0),
        "first_date": str(stats.get("first_date") or ""),
        "last_date": str(stats.get("last_date") or ""),
        "tag_label": "、".join(tags),
        "related_tags": [f"{tag}({related_counts[tag]}枚)" for tag in related_top],
    }


def make_tag_review(tag_key, bundle, match_mode="any"):
    tags = _normalize_tag_review_selection(tag_key)
    if not tags:
        raise ValueError("振り返るAIタグを確認できませんでした。")
    mode = "all" if str(match_mode or "").lower() == "all" and len(tags) > 1 else "any"
    scope_key = tag_review_scope_key(tags, mode)
    evidence = build_tag_review_evidence(tags, bundle, match_mode=mode)
    schema = {
        "type": "object",
        "properties": {
            "opening": {"type": "string"},
            "findings": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "theme": {"type": "string"},
                        "evidence": {"type": "string"},
                        "ask_child": {"type": "string"},
                    },
                    "required": ["theme", "evidence", "ask_child"],
                    "additionalProperties": False,
                },
            },
            "repeated_notices": {"type": "array", "items": {"type": "string"}},
            "wishes": {"type": "array", "items": {"type": "string"}},
            "one_question": {"type": "string"},
            "parent_note": {"type": "string"},
        },
        "required": ["opening", "findings", "repeated_notices", "wishes", "one_question", "parent_note"],
        "additionalProperties": False,
    }
    related_text = "、".join(evidence.get("related_tags") or []) or "なし"
    scope_label = tag_review_scope_label(tags, mode)
    tag_text = "、".join(tags)
    rule_text = "選んだタグをすべて含む写真" if mode == "all" and len(tags) > 1 else "選んだタグのどれか1つ以上を含む写真"
    prompt = f"""
「ぶらり旅」の保存写真から、AI画像タグ別の短い振り返りを作ります。

選んだAI画像タグ: {tag_text}
写真のまとめ方: {rule_text}
対象写真: {evidence['photo_count']}枚
記録日数: {evidence['day_count']}日
最初の記録日: {evidence['first_date'] or '不明'}
最後の記録日: {evidence['last_date'] or '不明'}
同じ写真に多く付いている別のAIタグ: {related_text}

写真ごとの日付・場所・選択タグ・関連AIタグ:
{evidence['text'] or '記録なし'}

厳守:
- 選択した「{tag_text}」はAIが写真から見える内容を整理するために自動付与した画像タグであり、利用者本人が選んだ気持ちタグではない。
- 複数タグを選んだ場合も、タグ同士の関係や因果を推測しない。
- タグ判定を絶対的な事実として扱わず、「AIタグ上では」「写真整理上では」という範囲で扱う。
- 子ども／大人／複数人など人物タグから、本人、親、家族、友達などの関係を推測しない。
- 人物の性格、能力、感情、健康状態、民族などを推測しない。
- 日付、場所、枚数、AIタグの共起など、入力から確認できる範囲だけを使う。
- opening は本人にも読める短い一言。25〜55文字程度、1文。
- findings は最大2件。theme は12文字程度まで。evidence は35〜80文字程度。
- ask_child は必要なときだけ短い問いを1件まで。不要なら空文字。
- one_question も問いは1つまで。ask_child がある場合は原則空文字。
- repeated_notices と wishes は互換用のため通常は空配列。
- parent_note は保護者向けに、写真枚数・記録日数・期間・選択したAIタグを簡潔に説明し、関係性や性格を推測していないことを明記する。
- 全体として簡潔にする。
""".strip()
    result = ask_json(prompt, "burari_ai_photo_tag_review_v330", schema, 850)
    result["_insight_version"] = 6
    result["_review_scope_type"] = "ai_tag"
    result["_ai_tag_key"] = scope_key
    result["_ai_tag_scope_key"] = scope_key
    result["_ai_tag_keys"] = tags
    result["_ai_tag_match_mode"] = mode
    result["_tag_label"] = "・".join(tags)
    result["_scope_label"] = scope_label
    result["_subjective_input_mode"] = "ai_observable_photo_tags_v330"
    return result


def get_saved_tag_review(tag_key):
    if isinstance(tag_key, (list, tuple, set)):
        tag_key = tag_review_scope_key(tag_key)
    tag_key = normalize_ai_photo_tag(tag_key)
    if not tag_key:
        return None
    for row in _ai_tag_review_rows():
        if _ai_tag_review_key_from_row(row) == tag_key:
            return row
    return None


def save_tag_review(tag_key, review_json):
    if isinstance(tag_key, (list, tuple, set)):
        mode = str((review_json or {}).get("_ai_tag_match_mode") or "any")
        tag_key = tag_review_scope_key(tag_key, mode)
    tag_key = normalize_ai_photo_tag(tag_key)
    if not tag_key:
        raise ValueError("保存するAIタグを確認できませんでした。")
    updated = dict(review_json or {})
    selected_tags = _normalize_tag_review_selection(updated.get("_ai_tag_keys") or [])
    mode = "all" if str(updated.get("_ai_tag_match_mode") or "").lower() == "all" and len(selected_tags) > 1 else "any"
    label = str(updated.get("_tag_label") or ("・".join(selected_tags) if selected_tags else tag_key)).strip()
    scope_label = str(updated.get("_scope_label") or tag_review_scope_label(selected_tags or [label], mode)).strip()
    updated["_review_scope_type"] = "ai_tag"
    updated["_ai_tag_key"] = tag_key
    updated["_ai_tag_scope_key"] = tag_key
    if selected_tags:
        updated["_ai_tag_keys"] = selected_tags
        updated["_ai_tag_match_mode"] = mode
    updated["_tag_label"] = label
    updated["_scope_label"] = scope_label
    storage_month = tag_review_storage_month(tag_key, create=True)
    updated["_tag_storage_month"] = storage_month
    save_monthly_review(storage_month, updated)
    st.session_state[f"monthly_review_{storage_month}"] = updated
    return updated


def make_tag_movie_draft_review(tag_keys, bundle, match_mode="any"):
    """Create a lightweight saved scope so a tag selection can go straight to movie setup.

    No AI call is made here. The user can add AI comments later as an optional action.
    """
    tags = _normalize_tag_review_selection(tag_keys)
    if not tags:
        raise ValueError("振り返るAIタグを確認できませんでした。")
    mode = "all" if str(match_mode or "").lower() == "all" and len(tags) > 1 else "any"
    scope_key = tag_review_scope_key(tags, mode)
    stats = tag_review_stats(bundle)
    return {
        "opening": "",
        "findings": [],
        "repeated_notices": [],
        "wishes": [],
        "one_question": "",
        "parent_note": "",
        "_insight_version": 6,
        "_review_scope_type": "ai_tag",
        "_ai_tag_key": scope_key,
        "_ai_tag_scope_key": scope_key,
        "_ai_tag_keys": tags,
        "_ai_tag_match_mode": mode,
        "_tag_label": "・".join(tags),
        "_scope_label": tag_review_scope_label(tags, mode),
        "_subjective_input_mode": "ai_observable_photo_tags_v330",
        "_tag_movie_draft": True,
        "_tag_movie_photo_count": int(stats.get("photo_count") or 0),
    }


def tag_review_has_ai_content(review):
    if not isinstance(review, dict):
        return False
    if str(review.get("opening") or "").strip():
        return True
    if any(isinstance(item, dict) and (str(item.get("theme") or "").strip() or str(item.get("evidence") or "").strip()) for item in (review.get("findings") or [])):
        return True
    if str(review.get("one_question") or "").strip() or str(review.get("parent_note") or "").strip():
        return True
    return False


def carry_tag_movie_state(refreshed, previous):
    refreshed = dict(refreshed or {})
    previous = previous if isinstance(previous, dict) else {}
    for key in (
        "_playback",
        "_tag_movie_photo_ids",
        "_tag_movie_photo_count",
        "_tag_movie_saved",
        "_tag_movie_saved_at",
        "_tag_movie_draft",
        "_tag_movie_membership_mode",
        "_tag_movie_membership_updated_at",
    ):
        if key in previous:
            refreshed[key] = previous[key]
    return refreshed


def tag_movie_snapshot_photo_ids(bundle):
    ids = []
    seen = set()
    for photo in (bundle or {}).get("photos", []) or []:
        if not isinstance(photo, dict):
            continue
        photo_id = str(photo.get("id") or "").strip()
        if photo_id and photo_id not in seen:
            seen.add(photo_id)
            ids.append(photo_id)
    return ids


def tag_movie_bundle_from_snapshot(bundle, review):
    """Return the latest photos matching the saved tag condition.

    Older builds stored ``_tag_movie_photo_ids`` as a fixed snapshot. From v406
    those IDs are only a membership cache: the tag condition is authoritative, so
    photos tagged later are included automatically and photos that no longer match
    are removed the next time the movie is opened.
    """
    return bundle


def save_tag_replay_movie(scope_key, review, bundle):
    """Persist a dynamic tag movie: tag condition + current music/playback window."""
    latest = dict(review or {})
    storage_key = str(latest.get("_tag_storage_month") or tag_review_storage_month(scope_key, create=True))[:7]
    session_review = st.session_state.get(f"monthly_review_{storage_key}")
    if isinstance(session_review, dict):
        latest = dict(session_review)
    playback = get_active_monthly_playback(storage_key, latest)
    if not monthly_playback_is_ready(playback):
        raise ValueError("先に音楽と再生時間を設定してください。")
    latest["_playback"] = dict(playback)
    photo_ids = tag_movie_snapshot_photo_ids(bundle)
    if not photo_ids:
        raise ValueError("保存する写真を確認できませんでした。")
    latest["_tag_movie_photo_ids"] = photo_ids
    latest["_tag_movie_photo_count"] = len(photo_ids)
    latest["_tag_movie_membership_mode"] = "dynamic"
    latest["_tag_movie_membership_updated_at"] = now_jst().isoformat()
    latest["_tag_movie_saved"] = True
    latest["_tag_movie_saved_at"] = now_jst().isoformat()
    latest["_tag_movie_draft"] = False
    saved = save_tag_review(scope_key, latest)
    discard_monthly_preview_playback(storage_key)
    return saved


def sync_dynamic_tag_movie_membership(scope_key, review, bundle):
    """Refresh a saved tag movie from its live tag condition, without user action."""
    current = dict(review or {})
    if not current.get("_tag_movie_saved"):
        return current
    photo_ids = tag_movie_snapshot_photo_ids(bundle)
    old_ids = [str(value or "").strip() for value in (current.get("_tag_movie_photo_ids") or [])]
    old_ids = [value for value in old_ids if value]
    if old_ids == photo_ids and current.get("_tag_movie_membership_mode") == "dynamic":
        return current
    current["_tag_movie_photo_ids"] = photo_ids
    current["_tag_movie_photo_count"] = len(photo_ids)
    current["_tag_movie_membership_mode"] = "dynamic"
    current["_tag_movie_membership_updated_at"] = now_jst().isoformat()
    if monthly_family_share_is_enabled(current):
        previous = monthly_family_share_info(current)
        current["_family_share"] = _monthly_family_share_payload(
            str(current.get("_tag_storage_month") or "")[:7],
            str(current.get("_scope_label") or current.get("_tag_label") or "AIタグ別振り返り"),
            bundle,
            previous_share=previous,
        )
    saved = save_tag_review(scope_key, current)
    storage_key = str(saved.get("_tag_storage_month") or "")[:7]
    if storage_key:
        st.session_state[f"monthly_review_{storage_key}"] = saved
    return saved


def sync_dynamic_month_movie_membership(month_key, period_label, review, bundle):
    """Keep an existing month movie attached to every current photo in that month."""
    current = dict(review or {})
    if not monthly_playback_is_ready(get_monthly_playback(current)):
        return current
    photo_ids = tag_movie_snapshot_photo_ids(bundle)
    old_ids = [str(value or "").strip() for value in (current.get("_monthly_movie_photo_ids") or [])]
    old_ids = [value for value in old_ids if value]
    if old_ids == photo_ids and current.get("_monthly_movie_membership_mode") == "dynamic":
        return current
    current["_monthly_movie_photo_ids"] = photo_ids
    current["_monthly_movie_photo_count"] = len(photo_ids)
    current["_monthly_movie_membership_mode"] = "dynamic"
    current["_monthly_movie_membership_updated_at"] = now_jst().isoformat()
    if monthly_family_share_is_enabled(current):
        previous = monthly_family_share_info(current)
        current["_family_share"] = _monthly_family_share_payload(
            month_key,
            period_label,
            bundle,
            previous_share=previous,
        )
    save_monthly_review(month_key, current)
    st.session_state[f"monthly_review_{month_key}"] = current
    return current


# ============================================================
# Monthly replay helpers
# ============================================================
def get_monthly_playback(review):
    if not isinstance(review, dict):
        return {}
    playback = review.get("_playback") or {}
    return dict(playback) if isinstance(playback, dict) else {}


def save_monthly_playback(month_key, review, playback):
    """Persist a replay association only when the caller explicitly wants persistence."""
    updated = dict(review or {})
    if isinstance(playback, dict) and playback:
        updated["_playback"] = dict(playback)
    else:
        updated.pop("_playback", None)
        if str(updated.get("_review_scope_type") or "") != "ai_tag":
            updated.pop("_monthly_movie_photo_ids", None)
            updated.pop("_monthly_movie_photo_count", None)
            updated.pop("_monthly_movie_membership_mode", None)
            updated.pop("_monthly_movie_membership_updated_at", None)
    if str(updated.get("_review_scope_type") or "") == "ai_tag":
        updated["_tag_movie_saved"] = False
        updated.pop("_tag_movie_saved_at", None)
    save_monthly_review(month_key, updated)
    st.session_state[f"monthly_review_{month_key}"] = updated
    return updated


def _monthly_preview_playback_key(month_key):
    return f"_monthly_preview_playback_v333_{month_key}"


def get_active_monthly_playback(month_key, review):
    """Return the session-only audition setting when present, else the saved setting."""
    key = _monthly_preview_playback_key(month_key)
    if key in st.session_state:
        value = st.session_state.get(key)
        return dict(value) if isinstance(value, dict) else {}
    return get_monthly_playback(review)


def set_monthly_preview_playback(month_key, playback):
    """Keep the current movie/music experiment in session only; never write the review DB."""
    value = dict(playback) if isinstance(playback, dict) and playback else {}
    st.session_state[_monthly_preview_playback_key(month_key)] = value
    st.session_state[f"_monthly_preview_playback_dirty_v333_{month_key}"] = True
    return value


def discard_monthly_preview_playback(month_key):
    st.session_state.pop(_monthly_preview_playback_key(month_key), None)
    st.session_state.pop(f"_monthly_preview_playback_dirty_v333_{month_key}", None)


def monthly_preview_playback_is_active(month_key):
    return _monthly_preview_playback_key(month_key) in st.session_state


def _music_library_session_key():
    return f"_music_library_{current_family_key()}_{current_member_key()}"


def _normalize_music_library_item(item):
    item = item if isinstance(item, dict) else {}
    url = str(item.get("youtube_url") or "").strip()
    video_id = str(item.get("video_id") or "").strip() or parse_youtube_video_id(url)
    if not video_id:
        return None
    try:
        start_seconds = max(0, int(item.get("start_seconds") or 0))
    except Exception:
        start_seconds = 0
    try:
        end_seconds = int(item.get("end_seconds") or (start_seconds + 20))
    except Exception:
        end_seconds = start_seconds + 20
    if end_seconds <= start_seconds:
        end_seconds = start_seconds + 20
    return {
        "youtube_url": url or youtube_watch_url(video_id),
        "video_id": video_id,
        "title": str(item.get("title") or "").strip(),
        "author_name": str(item.get("author_name") or "").strip(),
        "start_seconds": start_seconds,
        "end_seconds": end_seconds,
        "reason": str(item.get("reason") or "").strip(),
        "confidence": str(item.get("confidence") or "").strip(),
        "saved_at": str(item.get("saved_at") or item.get("updated_at") or "").strip(),
    }


# v469: music presets use stable identities, independent of their display order.
def _music_preset_key_v469(item):
    normalized = _normalize_music_library_item(item)
    if not normalized:
        return ""
    return json.dumps([normalized["video_id"], normalized["start_seconds"], normalized["end_seconds"]], separators=(",", ":"))


def _sorted_music_library_v469(items):
    valid = [_normalize_music_library_item(item) for item in (items or [])]
    return sorted((item for item in valid if item), key=lambda item: (
        item["end_seconds"] - item["start_seconds"],
        item["title"].casefold(), item["video_id"], item["start_seconds"], item["end_seconds"],
    ))


def delete_saved_music_v469(item):
    """Remove only this member's exact saved interval; never edit a movie's playback."""
    target = _music_preset_key_v469(item)
    if not target:
        raise ValueError("\u524a\u9664\u3059\u308b\u97f3\u697d\u3092\u78ba\u8a8d\u3067\u304d\u307e\u305b\u3093\u3002")
    # Re-read at confirmation, rather than writing the earlier selectbox snapshot.
    current = get_saved_music_library(force=True)
    remaining = [row for row in current if _music_preset_key_v469(row) != target]
    if len(remaining) == len(current):
        return False
    _write_saved_music_library(remaining)
    return True


def _voice_duration_value_ms_v469(meta):
    """Read finite durations without a network request. Zero means unknown, NOT silent."""
    meta = meta if isinstance(meta, dict) else {}
    for key, multiplier in (("duration_ms", 1), ("voice_duration_ms", 1), ("duration_seconds", 1000), ("duration_sec", 1000)):
        try:
            value = float(meta.get(key) or 0) * multiplier
            if math.isfinite(value) and value > 0:
                return int(math.ceil(value))
        except (TypeError, ValueError, OverflowError):
            pass
    return 0


