_MUSIC_EDITOR_JS_V469 = r"""
export default function(component) {
  const {parentElement, data, setTriggerValue} = component;
  const root = parentElement.querySelector('.music-editor-469');
  if (!root) return;
  const mode = ['time','library'].includes(data?.mode) ? data.mode : 'music';
  const url = root.querySelector('.music-url');
  const pad = root.querySelector('.music-keypad');
  const display = root.querySelector('.music-pad-display');
  const error = root.querySelector('.music-error');
  const signature = JSON.stringify([data?.youtube_url, data?.start_seconds, data?.end_seconds, data?.revision, mode]);
  // Keep the seconds-based draft compatible with v469-v471.
  const draftKey = 'burari-music-editor-v469:' + String(data?.scope || '');
  let draft = null;
  try { draft = JSON.parse(sessionStorage.getItem(draftKey) || 'null'); } catch (_) {}
  if (!draft || draft.signature !== signature) draft = {signature, url:String(data?.youtube_url || ''), start:Number(data?.start_seconds ?? 0), end:Number(data?.end_seconds ?? 20)};
  const MAX_SECONDS = 999999999;
  const integer = (value, minimum=0) => Math.max(minimum, Math.min(MAX_SECONDS, Math.floor(Number(value) || 0)));
  const timeLabel = (value) => {const n=integer(value);return `${Math.floor(n/60)}\u5206${n%60}\u79d2`;};
  draft.start = integer(draft.start); draft.end = integer(draft.end, 1);
  let editing = '', part = 'minutes', digits = '', replace = true;
  let parts = {minutes:'0', seconds:'0'};
  const saveDraft = () => {try { sessionStorage.setItem(draftKey, JSON.stringify(draft)); } catch (_) {}};
  const showError = (message='') => {error.textContent=message;error.hidden=!message;};
  const render = () => {
    root.querySelector('[data-edit="start"]').textContent=timeLabel(draft.start);
    root.querySelector('[data-edit="end"]').textContent=timeLabel(draft.end);
    const end=draft.end>draft.start?draft.end:draft.start+20;
    root.querySelector('.music-summary').textContent=`${timeLabel(draft.start)} \u301c ${timeLabel(end)}\uff08\u518d\u751f ${timeLabel(end-draft.start)}\uff09`+(draft.end<=draft.start?'\uff0f\u7d42\u4e86\u306f\u958b\u59cb\u304b\u30890\u520620\u79d2\u5f8c\u306b\u8abf\u6574\u3057\u307e\u3059\u3002':'');
    display.textContent=`${integer(parts.minutes)}\u5206${integer(parts.seconds)}\u79d2`;
    for (const button of root.querySelectorAll('[data-part]')) {
      const name=button.dataset.part;
      button.textContent=String(integer(parts[name]))+(name==='minutes'?'\u5206':'\u79d2');
      button.setAttribute('aria-pressed',String(name===part));
      button.setAttribute('aria-label',button.textContent+'\u3092\u5165\u529b');
    }
  };
  const commitPad = () => {
    if(!editing)return true;
    const minutes=integer(parts.minutes), seconds=integer(parts.seconds);
    if(seconds>59){showError('\u79d2\u306f0\u301c59\u3067\u5165\u529b\u3057\u3066\u304f\u3060\u3055\u3044\u3002');return false;}
    const total=minutes*60+seconds;
    if(total>MAX_SECONDS){showError('\u8a2d\u5b9a\u3067\u304d\u308b\u4e0a\u9650\u306f'+timeLabel(MAX_SECONDS)+'\u3067\u3059\u3002');return false;}
    draft[editing]=integer(total,editing==='end'?1:0);
    editing='';pad.hidden=true;saveDraft();render();return true;
  };
  const selectPart = (name) => {
    if(!editing || !['minutes','seconds'].includes(name))return;
    part=name;digits=parts[part];replace=true;render();pad.focus({preventScroll:true});
  };
  const openPad = (field) => {
    if(!['start','end'].includes(field))return;
    editing=field;const value=integer(draft[field]);
    parts={minutes:String(Math.floor(value/60)),seconds:String(value%60)};
    root.querySelector('.music-pad-label').textContent=(field==='start'?'\u958b\u59cb':'\u7d42\u4e86')+'\u6642\u9593';
    pad.hidden=false;selectPart('minutes');
  };
  const pressPad = (action) => {
    if(!editing)return;
    if(/^\d$/.test(action)){
      const limit=part==='seconds'?2:8;
      digits=replace?action:(digits+action).slice(0,limit);
      digits=digits.replace(/^0+(?=\d)/,'');replace=false;
    }
    else if(action==='clear'){digits='';replace=false;}
    else if(action==='back'){digits=digits.slice(0,-1);replace=false;}
    else if(action==='ok'){commitPad();return;}
    else if(action==='cancel'){editing='';pad.hidden=true;render();return;}
    parts[part]=digits||'0';render();
  };
  url.value=draft.url;
  root.querySelector('.music-url-block').hidden=mode==='time';
  root.querySelector('.music-helper-actions').hidden=mode==='time'||mode==='library';
  if(mode==='library'){const b=root.querySelector('.music-apply');b.textContent='\u3053\u306e\u97f3\u697d\u3092\u4fdd\u5b58';b.dataset.action='save';}
  if(mode==='time')root.querySelector('.music-apply').textContent='\u3053\u306e\u6642\u9593\u3092\u518d\u751f\u306b\u53cd\u6620';
  const onInput=()=>{draft.url=url.value;saveDraft();showError();};
  const onClick=(event)=>{
    const button=event.target.closest('button');if(!button||!root.contains(button))return;
    event.preventDefault();showError();
    if(button.dataset.edit){if(commitPad())openPad(button.dataset.edit);return;}
    if(button.dataset.part){selectPart(button.dataset.part);return;}
    if(button.dataset.digit!==undefined){pressPad(button.dataset.digit);return;}
    if(button.dataset.pad){pressPad(button.dataset.pad);return;}
    if(button.dataset.step){if(!commitPad())return;const [field,delta]=button.dataset.step.split(':');draft[field]=integer(draft[field]+Number(delta),field==='end'?1:0);saveDraft();render();return;}
    if(button.dataset.action){
      if(!commitPad())return;draft.url=url.value.trim();saveDraft();
      const action=button.dataset.action;
      if(action!=='clear' && !draft.url){showError('YouTube URL\u3092\u5165\u529b\u3057\u3066\u304f\u3060\u3055\u3044\u3002');return;}
      // UI is minutes/seconds, but the server and the replay retain integer seconds.
      setTriggerValue('editor_action',{action,youtube_url:draft.url,start_seconds:draft.start,end_seconds:draft.end,token:`${Date.now()}:${Math.random()}`});
    }
  };
  const onKey=(event)=>{
    if(!editing)return;const key=event.key;let action='';
    if(key==='ArrowLeft'||key==='ArrowRight'){event.preventDefault();showError();selectPart(key==='ArrowLeft'?'minutes':'seconds');return;}
    if(/^\d$/.test(key))action=key;else if(key==='Backspace')action='back';else if(key==='Delete')action='clear';else if(key==='Enter')action='ok';else if(key==='Escape')action='cancel';
    if(action){event.preventDefault();showError();pressPad(action);}
  };
  root.addEventListener('click',onClick);url.addEventListener('input',onInput);pad.addEventListener('keydown',onKey);
  render();
  return ()=>{saveDraft();root.removeEventListener('click',onClick);url.removeEventListener('input',onInput);pad.removeEventListener('keydown',onKey);};
}
"""


@st.cache_resource(show_spinner=False)
def _music_editor_component_v469():
    return st.components.v2.component("burari_music_editor_v473", html=_MUSIC_EDITOR_HTML_V469,
        css=_MUSIC_EDITOR_CSS_V469, js=_perf_instrument_js_v466(_MUSIC_EDITOR_JS_V469))


def _render_music_editor_v469(month_key, youtube_url, start_seconds, end_seconds, mode="music"):
    scope = f"{current_family_key()}|{current_member_key()}|{month_key}|{mode}"
    key = "music_editor_v472_" + hashlib.sha256(scope.encode()).hexdigest()[:20]
    result = _music_editor_component_v469()(
        data={"scope": scope, "mode": mode, "youtube_url": str(youtube_url or ""),
              "start_seconds": max(0, int(start_seconds)), "end_seconds": max(1, int(end_seconds)),
              "revision": int(st.session_state.get(f"_music_editor_revision_v469_{month_key}") or 0)},
        key=key, on_editor_action_change=lambda: None,
    )
    payload = getattr(result, "editor_action", None)
    if not isinstance(payload, dict) or str(payload.get("action") or "") not in {"apply", "guess", "save", "clear"}:
        return {}
    token = str(payload.get("token") or "")
    if not token or token == st.session_state.get(key + "_consumed"):
        return {}
    try:
        start = max(0, min(999999999, int(payload.get("start_seconds") or 0)))
        end = max(1, min(999999999, int(payload.get("end_seconds") or 1)))
    except (TypeError, ValueError, OverflowError):
        return {}
    st.session_state[key + "_consumed"] = token
    return {"action": payload["action"], "youtube_url": str(payload.get("youtube_url") or "").strip(),
            "start_seconds": start, "end_seconds": end}


def get_saved_music_library(force=False):
    """Return the current member's saved YouTube music choices.

    The library lives in one sentinel row of the existing monthly-review table, so
    no new Supabase table or migration is required. It is still isolated by family/member.
    """
    cache_key = _music_library_session_key()
    if not force and isinstance(st.session_state.get(cache_key), list):
        return _sorted_music_library_v469(st.session_state.get(cache_key) or [])

    result = (
        supabase_client()
        .table(MONTHLY_TABLE)
        .select("id,review_json,updated_at")
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .eq("review_month", MUSIC_LIBRARY_REVIEW_DATE)
        .limit(1)
        .execute()
    )
    row = (result.data or [None])[0]
    review_json = (row or {}).get("review_json") or {}
    raw_items = review_json.get("items") if isinstance(review_json, dict) else []
    raw_items = raw_items if isinstance(raw_items, list) else []
    items = []
    seen = set()
    for raw in raw_items:
        item = _normalize_music_library_item(raw)
        if not item:
            continue
        key = (item["video_id"], int(item["start_seconds"]), int(item["end_seconds"]))
        if key in seen:
            continue
        seen.add(key)
        items.append(item)
    items = _sorted_music_library_v469(items)
    st.session_state[cache_key] = items
    return list(items)


def _write_saved_music_library(items):
    normalized = []
    seen = set()
    for raw in list(items or [])[:50]:
        item = _normalize_music_library_item(raw)
        if not item:
            continue
        key = (item["video_id"], int(item["start_seconds"]), int(item["end_seconds"]))
        if key in seen:
            continue
        seen.add(key)
        normalized.append(item)

    client = supabase_client()
    existing = (
        client.table(MONTHLY_TABLE)
        .select("id")
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .eq("review_month", MUSIC_LIBRARY_REVIEW_DATE)
        .limit(1)
        .execute()
    )
    row = (existing.data or [None])[0]
    now_value = now_jst().isoformat()
    payload = {
        "family_key": current_family_key(),
        "member_key": current_member_key(),
        "review_month": MUSIC_LIBRARY_REVIEW_DATE,
        "review_json": {"_record_type": "music_library", "items": normalized},
        "updated_at": now_value,
    }
    if row:
        (
            client.table(MONTHLY_TABLE)
            .update(payload)
            .eq("id", row["id"])
            .eq("family_key", current_family_key())
            .eq("member_key", current_member_key())
            .execute()
        )
    else:
        payload["created_at"] = now_value
        client.table(MONTHLY_TABLE).insert(payload).execute()
    normalized = _sorted_music_library_v469(normalized)
    st.session_state[_music_library_session_key()] = normalized
    return normalized


def save_music_to_library(playback):
    item = _normalize_music_library_item(playback)
    if not item:
        raise ValueError("保存できるYouTube音楽が設定されていません。")
    meta = fetch_youtube_oembed(item.get("youtube_url"))
    if meta:
        item["title"] = str(meta.get("title") or item.get("title") or "").strip()
        item["author_name"] = str(meta.get("author_name") or item.get("author_name") or "").strip()
    if not item.get("title"):
        item["title"] = f"YouTube音楽 {item['video_id']}"
    item["saved_at"] = now_jst().isoformat()

    items = get_saved_music_library(force=True)
    preset_key = (item["video_id"], int(item["start_seconds"]), int(item["end_seconds"]))
    items = [
        x for x in items
        if (
            str(x.get("video_id") or ""),
            int(x.get("start_seconds") or 0),
            int(x.get("end_seconds") or (int(x.get("start_seconds") or 0) + 20)),
        ) != preset_key
    ]
    items.sort(key=lambda row: str(row.get("saved_at") or ""), reverse=True)
    items.insert(0, item)
    _write_saved_music_library(items)
    return item



# ============================================================
# Experience cards (v497)
# ============================================================
# Comparison categories are intentionally fixed and fairly narrow. The AI may choose
# from this list but may not invent a new comparison bucket. Ambiguous experiences are
# kept as comparison-excluded rather than forcing, for example, taiyaki and pudding
# into one broad sweets category.
EXPERIENCE_SNACK_COMPARE_CATEGORIES_V497 = (
    "たい焼き", "プリン", "団子", "ソフトクリーム", "アイスクリーム", "ケーキ",
    "ドーナツ", "クレープ", "パフェ", "シュークリーム", "カステラ", "どら焼き",
    "大福", "まんじゅう", "羊羹", "せんべい", "クッキー", "チョコレート",
    "ゼリー", "かき氷", "パン",
)
EXPERIENCE_TOURISM_COMPARE_CATEGORIES_V497 = (
    "公園", "神社", "寺", "博物館", "科学館", "水族館", "動物園", "展望スポット",
    "商店街", "市場", "鉄道スポット", "水辺", "庭園", "城・史跡", "遊園地", "体験施設",
)
EXPERIENCE_COMPARE_EXCLUDED_V497 = "比較対象外"
EXPERIENCE_COMPARE_CATEGORIES_V497 = (
    *EXPERIENCE_SNACK_COMPARE_CATEGORIES_V497,
    *EXPERIENCE_TOURISM_COMPARE_CATEGORIES_V497,
    EXPERIENCE_COMPARE_EXCLUDED_V497,
)
EXPERIENCE_AUTO_CANDIDATE_LIMIT_V497 = 8
EXPERIENCE_RECENT_PHOTO_LIMIT_V497 = 24
EXPERIENCE_AUTO_PHOTO_MAX_V497 = 3
EXPERIENCE_MANUAL_PHOTO_MAX_V497 = 4


def _experience_state_session_key_v497():
    return f"_experience_card_state_v497_{current_family_key()}_{current_member_key()}"


def _normalize_experience_card_v497(raw):
    if not isinstance(raw, dict):
        return None
    card_id = str(raw.get("id") or "").strip()
    if not card_id:
        return None
    experience_type = str(raw.get("experience_type") or "その他").strip()
    if experience_type not in {"おやつ", "観光", "その他"}:
        experience_type = "その他"
    compare_category = str(raw.get("compare_category") or EXPERIENCE_COMPARE_EXCLUDED_V497).strip()
    if compare_category not in EXPERIENCE_COMPARE_CATEGORIES_V497:
        compare_category = EXPERIENCE_COMPARE_EXCLUDED_V497
    photo_ids = []
    for value in raw.get("photo_ids") or []:
        value = str(value or "").strip()
        if value and value not in photo_ids:
            photo_ids.append(value[:100])
        if len(photo_ids) >= EXPERIENCE_MANUAL_PHOTO_MAX_V497:
            break
    photo_paths = []
    for value in raw.get("photo_storage_paths") or []:
        value = str(value or "").strip()
        if value and value not in photo_paths:
            photo_paths.append(value[:500])
        if len(photo_paths) >= EXPERIENCE_MANUAL_PHOTO_MAX_V497:
            break
    item = {
        "id": card_id[:80],
        "created_at": str(raw.get("created_at") or "").strip(),
        "trip_date": str(raw.get("trip_date") or "").strip()[:10],
        "trip_id": str(raw.get("trip_id") or "").strip()[:100],
        "experience_type": experience_type,
        "compare_category": compare_category,
        "place_name": str(raw.get("place_name") or "不明").strip()[:120] or "不明",
        "item_name": str(raw.get("item_name") or "不明").strip()[:120] or "不明",
        "child_comment": str(raw.get("child_comment") or "").strip()[:700],
        "raw_transcript": str(raw.get("raw_transcript") or "").strip()[:1200],
        "audio_storage_path": str(raw.get("audio_storage_path") or "").strip()[:500],
        "food_label": str(raw.get("food_label") or "").strip()[:100],
        "place_source": str(raw.get("place_source") or "").strip()[:80],
        "place_google_place_id": str(raw.get("place_google_place_id") or "").strip()[:180],
        "photo_ids": photo_ids,
        "photo_storage_paths": photo_paths,
    }
    if not item["photo_ids"] and not item["photo_storage_paths"]:
        return None
    return item


def get_experience_card_state_v497(force=False):
    cache_key = _experience_state_session_key_v497()
    if not force and isinstance(st.session_state.get(cache_key), dict):
        return dict(st.session_state.get(cache_key) or {})
    result = (
        supabase_client()
        .table(MONTHLY_TABLE)
        .select("id,review_json,updated_at")
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .eq("review_month", EXPERIENCE_CARD_REVIEW_DATE)
        .limit(1)
        .execute()
    )
    row = (result.data or [None])[0] or {}
    payload = row.get("review_json") or {}
    raw_cards = payload.get("cards") if isinstance(payload, dict) else []
    cards, seen = [], set()
    for raw in raw_cards if isinstance(raw_cards, list) else []:
        card = _normalize_experience_card_v497(raw)
        if not card or card["id"] in seen:
            continue
        seen.add(card["id"])
        cards.append(card)
    state = {"version": 1, "cards": cards[:500]}
    st.session_state[cache_key] = state
    return dict(state)


def _write_experience_card_state_v497(state):
    cards, seen = [], set()
    for raw in list((state or {}).get("cards") or [])[:500]:
        card = _normalize_experience_card_v497(raw)
        if not card or card["id"] in seen:
            continue
        seen.add(card["id"])
        cards.append(card)
    now_value = now_jst().isoformat()
    review_json = {
        "_record_type": "experience_cards_v497",
        "version": 1,
        "cards": cards,
        "updated_at": now_value,
    }
    client = supabase_client()
    existing = (
        client.table(MONTHLY_TABLE)
        .select("id")
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .eq("review_month", EXPERIENCE_CARD_REVIEW_DATE)
        .limit(1)
        .execute()
    )
    row = (existing.data or [None])[0]
    payload = {
        "family_key": current_family_key(),
        "member_key": current_member_key(),
        "review_month": EXPERIENCE_CARD_REVIEW_DATE,
        "review_json": review_json,
        "updated_at": now_value,
    }
    if row:
        (
            client.table(MONTHLY_TABLE)
            .update(payload)
            .eq("id", row["id"])
            .eq("family_key", current_family_key())
            .eq("member_key", current_member_key())
            .execute()
        )
    else:
        payload["created_at"] = now_value
        client.table(MONTHLY_TABLE).insert(payload).execute()
    normalized = {"version": 1, "cards": cards}
    st.session_state[_experience_state_session_key_v497()] = normalized
    return normalized


def _experience_used_photo_ids_v497(cards=None):
    if cards is None:
        cards = list(get_experience_card_state_v497().get("cards") or [])
    used = set()
    for card in cards or []:
        for photo_id in (card or {}).get("photo_ids") or []:
            if str(photo_id or "").strip():
                used.add(str(photo_id))
    return used


def _list_recent_experience_photos_v497(limit=EXPERIENCE_RECENT_PHOTO_LIMIT_V497):
    try:
        limit = max(1, min(60, int(limit)))
    except Exception:
        limit = EXPERIENCE_RECENT_PHOTO_LIMIT_V497
    result = (
        supabase_client()
        .table(PHOTO_TABLE)
        .select("id,trip_id,storage_path,captured_at,reflection_json,signals_json")
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .order("captured_at", desc=True)
        .limit(limit)
        .execute()
    )
    return [
        row for row in diary_photos_only(result.data or [])
        if str((row or {}).get("id") or "").strip() and str((row or {}).get("storage_path") or "").strip()
    ]


def _experience_auto_pick_schema_v497(slots):
    return {
        "type": "object",
        "properties": {
            "selected_slots": {
                "type": "array",
                "items": {"type": "string", "enum": list(slots)},
                "minItems": 0,
                "maxItems": EXPERIENCE_AUTO_PHOTO_MAX_V497,
            }
        },
        "required": ["selected_slots"],
        "additionalProperties": False,
    }


def _auto_pick_experience_photo_ids_v497(candidates):
    candidates = [x for x in candidates or [] if isinstance(x, dict)][:EXPERIENCE_AUTO_CANDIDATE_LIMIT_V497]
    if not candidates:
        return []
    loaded, image_items = [], []
    for index, photo in enumerate(candidates, start=1):
        slot = f"P{index}"
        try:
            raw = download_photo(str(photo.get("storage_path") or ""))
            if not raw:
                continue
            vision_bytes = _vision_ready_photo(raw, max_side=900, quality=80)
            captured = str(photo.get("captured_at") or "")[:19]
            loaded.append((slot, photo))
            image_items.append((f"【{slot}】撮影時刻 {captured}", vision_bytes))
        except Exception:
            continue
    if not loaded:
        return []
    slots = [slot for slot, _ in loaded]
    prompt = """
直近に撮影された写真から、親子が今から1枚の「体験カード」にまとめるのに適した写真を0〜3枚選んでください。
写真は新しい順の候補です。同じ一つの体験に属する組み合わせだけを選んでください。

優先例:
- 店の外観・看板 + 食べ物 + 子どもがその食べ物を食べている様子
- 観光スポットの外観・特徴 + 子どもがその場所で体験している様子

絶対に選ばないもの:
- 地図、経路図、線路図、GPS軌跡、ぶらり旅プロジェクトの緑色のルート画面
- アプリ画面、スマートフォン画面、設定画面、スクリーンショット
- 書類、表、グラフ、QRコードなど、体験そのものを写していない画像

ルール:
- 無関係な別の体験を混ぜない。
- 同じような写真が複数ある場合は代表的なものだけにする。
- 食べ物・店・観光・実際の体験が写真から分からない場合は、無理に選ばず selected_slots を空配列にする。
- 写真の内容を説明せず、selected_slots だけ返す。
""".strip()
    try:
        response = ask_json_with_images(
            prompt,
            image_items,
            "burari_experience_photo_pick_v498",
            _experience_auto_pick_schema_v497(slots),
            max_output_tokens=220,
        )
        selected_slots = [str(x) for x in (response or {}).get("selected_slots", [])]
        mapping = {slot: photo for slot, photo in loaded}
        selected = []
        for slot in selected_slots:
            photo = mapping.get(slot)
            photo_id = str((photo or {}).get("id") or "")
            if photo_id and photo_id not in selected:
                selected.append(photo_id)
            if len(selected) >= EXPERIENCE_AUTO_PHOTO_MAX_V497:
                break
        return selected
    except Exception:
        # A wrong auto-pick is worse than asking the parent to choose manually.
        return []

def _experience_card_schema_v497():
    return {
        "type": "object",
        "properties": {
            "experience_type": {"type": "string", "enum": ["おやつ", "観光", "その他"]},
            "compare_category": {"type": "string", "enum": list(EXPERIENCE_COMPARE_CATEGORIES_V497)},
            "place_name": {"type": "string"},
            "item_name": {"type": "string"},
            "child_comment": {"type": "string"},
        },
        "required": ["experience_type", "compare_category", "place_name", "item_name", "child_comment"],
        "additionalProperties": False,
    }


def _experience_card_prompt_v497(raw_transcript):
    snack = "、".join(EXPERIENCE_SNACK_COMPARE_CATEGORIES_V497)
    tourism = "、".join(EXPERIENCE_TOURISM_COMPARE_CATEGORIES_V497)
    return f"""
親子の「体験カード」を作ります。入力は、親が選んだ体験写真と、体験中または直後に録音した発話の文字起こしです。
写真と文字起こしから直接確認できる範囲だけを使ってください。分からないことを補わないでください。

文字起こし:
{str(raw_transcript or '').strip()[:1200]}

比較カテゴリーは人が「同じ種類として比べる」粒度に固定します。次の選択肢以外を作ってはいけません。
おやつ: {snack}
観光: {tourism}
判断できない、またはこの粒度で同種比較に向かない場合: {EXPERIENCE_COMPARE_EXCLUDED_V497}

重要:
- たい焼きとプリンのような別種のおやつを同じ比較カテゴリーにしない。
- たい焼きの餡違いなどは「たい焼き」でよい。
- 観光も、公園と神社のような別種を同じ比較カテゴリーにしない。
- 店名・施設名は写真の看板等から明確に読める場合だけ place_name に書く。不明なら「不明」。
- item_name は正式な商品名・体験名が明確な場合だけ書く。不明なら「不明」。
- child_comment は、文字起こしの中から子どもの感想に当たる部分だけをできるだけ元の言葉のまま短く抜き出す。親の質問や相づちは除く。
- 子どもの発言を特定できない場合は、文字起こしを勝手に要約せず、聞き取れた短い部分だけを書く。感情や評価を創作しない。
""".strip()


def _experience_audio_extension_v497(file_name):
    suffix = Path(str(file_name or "").lower()).suffix.lower().lstrip(".")
    return suffix if suffix in {"wav", "webm", "m4a", "mp4", "ogg", "mp3"} else "webm"


def _upload_experience_audio_v497(raw_bytes, file_name, card_id):
    raw_bytes = bytes(raw_bytes or b"")
    if not raw_bytes:
        return ""
    extension = _experience_audio_extension_v497(file_name)
    logical_mime_type = {
        "wav": "audio/wav", "m4a": "audio/mp4", "mp4": "audio/mp4",
        "ogg": "audio/ogg", "mp3": "audio/mpeg", "webm": "audio/webm",
    }.get(extension, "audio/webm")
    # v512: PHOTO_BUCKET is shared with photos/videos and its MIME allow-list can
    # reject audio/* metadata with Storage 415 invalid_mime. Voice clips elsewhere
    # in this app already solve this by keeping the original audio bytes/extension
    # while using the equivalent bucket-compatible video-container MIME metadata.
    storage_mime_type = _voice_storage_upload_mime(logical_mime_type, file_name)
    path = (
        f"{current_family_key()}/{current_member_key()}/"
        f"_experience_cards/v1/{str(card_id)}.{extension}"
    )
    supabase_client().storage.from_(PHOTO_BUCKET).upload(
        path=path,
        file=raw_bytes,
        file_options={"content-type": storage_mime_type, "cache-control": "3600", "upsert": "true"},
    )
    return path


def create_experience_card_v497(photos, raw_transcript, audio_bytes=b"", audio_name="experience.webm", place_candidate=None, compare_category_hint="", food_label_hint=""):
    photos = [x for x in photos or [] if isinstance(x, dict)][:EXPERIENCE_MANUAL_PHOTO_MAX_V497]
    raw_transcript = str(raw_transcript or "").strip()
    if not photos:
        raise ValueError("体験の写真を1枚以上選んでください。")
    if not raw_transcript:
        raise ValueError("体験の感想を録音してください。")

    image_items = []
    valid_photos = []
    for index, photo in enumerate(photos, start=1):
        path = str(photo.get("storage_path") or "").strip()
        if not path:
            continue
        raw = download_photo(path)
        if not raw:
            continue
        valid_photos.append(photo)
        image_items.append((f"【体験写真{index}】", _vision_ready_photo(raw, max_side=1100, quality=82)))
    if not image_items:
        raise ValueError("選択した写真を読み込めませんでした。")

    result = ask_json_with_images(
        _experience_card_prompt_v497(raw_transcript),
        image_items,
        "burari_experience_card_v497",
        _experience_card_schema_v497(),
        max_output_tokens=520,
    )
    experience_type = str((result or {}).get("experience_type") or "その他").strip()
    if experience_type not in {"おやつ", "観光", "その他"}:
        experience_type = "その他"
    category = str((result or {}).get("compare_category") or EXPERIENCE_COMPARE_EXCLUDED_V497).strip()
    if category not in EXPERIENCE_COMPARE_CATEGORIES_V497:
        category = EXPERIENCE_COMPARE_EXCLUDED_V497
    # Protect cross-domain mistakes even if a model response is syntactically valid.
    if experience_type == "おやつ" and category in EXPERIENCE_TOURISM_COMPARE_CATEGORIES_V497:
        category = EXPERIENCE_COMPARE_EXCLUDED_V497
    if experience_type == "観光" and category in EXPERIENCE_SNACK_COMPARE_CATEGORIES_V497:
        category = EXPERIENCE_COMPARE_EXCLUDED_V497
    if experience_type == "その他":
        category = EXPERIENCE_COMPARE_EXCLUDED_V497

    # v505: the photo-only pass is intentionally narrow and only overrides a valid
    # snack comparison bucket. This keeps taiyaki/pudding classification stable while
    # letting the final card pass use the child's transcript for everything else.
    compare_category_hint = str(compare_category_hint or "").strip()
    if compare_category_hint in EXPERIENCE_SNACK_COMPARE_CATEGORIES_V497:
        experience_type = "おやつ"
        category = compare_category_hint

    place_name = str((result or {}).get("place_name") or "不明").strip()[:120] or "不明"
    place_source = "image" if place_name != "不明" else "unknown"
    place_google_place_id = ""
    if isinstance(place_candidate, dict):
        if bool(place_candidate.get("force_unknown")):
            place_name = "不明"
            place_source = "user_unknown"
        else:
            candidate_name = str(place_candidate.get("name") or "").strip()[:120]
            if candidate_name:
                place_name = candidate_name
                place_source = str(place_candidate.get("source") or "photo_location_search").strip()[:80] or "photo_location_search"
                place_google_place_id = str(place_candidate.get("google_place_id") or "").strip()[:180]

    card_id = uuid.uuid4().hex
    audio_path = _upload_experience_audio_v497(audio_bytes, audio_name, card_id) if audio_bytes else ""
    first = valid_photos[0]
    captured = str(first.get("captured_at") or "")
    trip_date = captured[:10] if re.match(r"^\d{4}-\d{2}-\d{2}", captured) else today_iso()
    card = {
        "id": card_id,
        "created_at": now_jst().isoformat(),
        "trip_date": trip_date,
        "trip_id": str(first.get("trip_id") or ""),
        "experience_type": experience_type,
        "compare_category": category,
        "place_name": place_name,
        "item_name": str((result or {}).get("item_name") or "不明").strip()[:120] or "不明",
        "child_comment": str((result or {}).get("child_comment") or "").strip()[:700] or raw_transcript[:700],
        "food_label": str(food_label_hint or "").strip()[:100],
        "place_source": place_source,
        "place_google_place_id": place_google_place_id,
        "raw_transcript": raw_transcript[:1200],
        "audio_storage_path": audio_path,
        "photo_ids": [str(photo.get("id") or "") for photo in valid_photos if str(photo.get("id") or "")],
        "photo_storage_paths": [str(photo.get("storage_path") or "") for photo in valid_photos if str(photo.get("storage_path") or "")],
    }
    state = get_experience_card_state_v497(force=True)
    state["cards"] = [card] + list(state.get("cards") or [])
    _write_experience_card_state_v497(state)
    return card


def _reset_experience_draft_v497():
    for key in (
        "_experience_show_audio_v497", "_experience_show_photos_v497",
        "_experience_selected_photo_ids_v497", "_experience_auto_pick_done_v497",
        "_experience_audio_bytes_v497", "_experience_audio_name_v497",
        "_experience_audio_digest_v497", "_experience_transcript_v497",
        "_experience_photo_warning_v497", "_experience_photo_fetched_v498",
        "_experience_manual_picker_open_v499", "_experience_selected_photo_ids_v499",
        "_experience_selected_photo_view_mode_v501", "_experience_selected_photo_enlarged_index_v501",
        "_experience_selected_photo_view_mode_v502", "_experience_selected_photo_enlarged_index_v502",
        "_experience_photo_picker_page_v503", "_experience_photo_picker_last_token_v503",
        "_experience_selected_multi_last_token_v503",
        "_experience_store_inference_v505", "_experience_store_choice_v505",
        "_experience_manual_food_open_v509", "_experience_manual_food_query_v509",
        "_experience_manual_food_signature_v509", "_experience_manual_store_inference_v509",
        "_experience_store_effective_inference_v509",
    ):
        st.session_state.pop(key, None)
    st.session_state["_experience_draft_serial_v497"] = int(st.session_state.get("_experience_draft_serial_v497") or 0) + 1


def _toggle_experience_photo_v497(photo_id):
    photo_id = str(photo_id or "").strip()
    if not photo_id:
        return
    selected = [str(x) for x in st.session_state.get("_experience_selected_photo_ids_v497", []) if str(x)]
    if photo_id in selected:
        selected = [x for x in selected if x != photo_id]
    else:
        if len(selected) >= EXPERIENCE_MANUAL_PHOTO_MAX_V497:
            st.session_state["_experience_photo_warning_v497"] = f"写真は最大{EXPERIENCE_MANUAL_PHOTO_MAX_V497}枚まで選べます。"
            return
        selected.append(photo_id)
    st.session_state["_experience_selected_photo_ids_v497"] = selected
    st.session_state["_experience_auto_pick_done_v497"] = True


def _experience_captured_label_v497(value):
    value = str(value or "")
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if dt.tzinfo is not None:
            dt = dt.astimezone(ZoneInfo(APP_TIMEZONE))
        return dt.strftime("%m/%d %H:%M")
    except Exception:
        return value[:16].replace("T", " ")


FIELD_NOTE_KINDS = {
    "curiosity": {
        "emoji": "💡",
        "label": "気になった",
        "prompt": "なにが気になった？",
        "color": "#E8B83F",
    },
    "difficulty": {
        "emoji": "😣",
        "label": "困った",
        "prompt": "どんなことに困った？",
        "color": "#D97B72",
    },
    "good": {
        "emoji": "❤️",
        "label": "よかった",
        "prompt": "なにがよかった？",
        "color": "#5DAE8B",
    },
    "next": {
        "emoji": "🚩",
        "label": "次にやりたい",
        "prompt": "つぎに、なにをやってみたい？",
        "color": "#6B86C4",
    },
}


def _field_note_state_session_key():
    return f"_field_note_state_v390_{current_family_key()}_{current_member_key()}"


def _normalize_field_note_item(raw):
    if not isinstance(raw, dict):
        return None
    kind = str(raw.get("kind") or "").strip().lower()
    if kind not in FIELD_NOTE_KINDS:
        return None
    note_id = str(raw.get("id") or "").strip()
    if not note_id:
        return None
    status = str(raw.get("status") or ("open" if kind == "next" else "recorded")).strip().lower()
    if status not in {"open", "planned", "done", "recorded"}:
        status = "open" if kind == "next" else "recorded"
    location = raw.get("location") if isinstance(raw.get("location"), dict) else {}
    item = {
        "id": note_id[:80],
        "kind": kind,
        "text": str(raw.get("text") or "").strip()[:500],
        "created_at": str(raw.get("created_at") or "").strip(),
        "trip_date": str(raw.get("trip_date") or "").strip()[:10],
        "trip_id": str(raw.get("trip_id") or "").strip()[:100],
        "place_label": str(raw.get("place_label") or "").strip()[:100],
        "location": location,
        "audio_storage_path": str(raw.get("audio_storage_path") or "").strip()[:500],
        "status": status,
        "planned_for_date": str(raw.get("planned_for_date") or "").strip()[:10],
        "planned_for_trip_id": str(raw.get("planned_for_trip_id") or "").strip()[:100],
        "completed_at": str(raw.get("completed_at") or "").strip(),
    }
    if not item["text"] and not item["audio_storage_path"]:
        return None
    return item


def get_field_note_state(force=False, *, nonblocking=False):
    """Load compact field notes from an existing sentinel review row.

    Keeping this in burari_monthly_reviews avoids a database migration while retaining
    normal family/member isolation and cross-device availability.
    v520 can consume a read-ahead Future started before Home renders; the returned
    state and persistence semantics are unchanged.
    """
    cache_key = _field_note_state_session_key()
    if not force and isinstance(st.session_state.get(cache_key), dict):
        return dict(st.session_state.get(cache_key) or {})
    if not force:
        try:
            prefetched = _read_ahead_value_v520("field_notes", block=not nonblocking)
        except Exception:
            prefetched = None
        if isinstance(prefetched, dict):
            st.session_state[cache_key] = prefetched
            return dict(prefetched)
        if nonblocking:
            # Home must not wait on the pending Future or synchronously query the DB.
            # This temporary value is NEVER written to cache, so the next normal
            # rerun can pick up the real state without overwriting user data.
            return {"version": 1, "items": []}
    result = (
        supabase_client()
        .table(MONTHLY_TABLE)
        .select("id,review_json,updated_at")
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .eq("review_month", FIELD_NOTE_REVIEW_DATE)
        .limit(1)
        .execute()
    )
    row = (result.data or [None])[0] or {}
    payload = row.get("review_json") or {}
    raw_items = payload.get("items") if isinstance(payload, dict) else []
    items = []
    seen = set()
    for raw in raw_items if isinstance(raw_items, list) else []:
        item = _normalize_field_note_item(raw)
        if not item or item["id"] in seen:
            continue
        seen.add(item["id"])
        items.append(item)
    state = {"version": 1, "items": items[:400]}
    st.session_state[cache_key] = state
    return dict(state)


def _write_field_note_state(state):
    items = []
    seen = set()
    for raw in list((state or {}).get("items") or [])[:400]:
        item = _normalize_field_note_item(raw)
        if not item or item["id"] in seen:
            continue
        seen.add(item["id"])
        items.append(item)
    now_value = now_jst().isoformat()
    review_json = {
        "_record_type": "field_notes_v390",
        "version": 1,
        "items": items,
        "updated_at": now_value,
    }
    client = supabase_client()
    existing = (
        client.table(MONTHLY_TABLE)
        .select("id")
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .eq("review_month", FIELD_NOTE_REVIEW_DATE)
        .limit(1)
        .execute()
    )
    row = (existing.data or [None])[0]
    payload = {
        "family_key": current_family_key(),
        "member_key": current_member_key(),
        "review_month": FIELD_NOTE_REVIEW_DATE,
        "review_json": review_json,
        "updated_at": now_value,
    }
    if row:
        (
            client.table(MONTHLY_TABLE)
            .update(payload)
            .eq("id", row["id"])
            .eq("family_key", current_family_key())
            .eq("member_key", current_member_key())
            .execute()
        )
    else:
        payload["created_at"] = now_value
        client.table(MONTHLY_TABLE).insert(payload).execute()
    normalized_state = {"version": 1, "items": items}
    st.session_state[_field_note_state_session_key()] = normalized_state
    try:
        _bump_owner_v468(_owner_v468())
    except Exception:
        pass
    return normalized_state


def _field_note_audio_extension(audio_file):
    name = str(getattr(audio_file, "name", "") or "").lower()
    suffix = Path(name).suffix.lower().lstrip(".")
    return suffix if suffix in {"wav", "webm", "m4a", "mp4", "ogg", "mp3"} else "webm"


def _upload_field_note_audio(audio_file, note_id):
    if audio_file is None:
        return ""
    audio_file.seek(0)
    raw = audio_file.read()
    audio_file.seek(0)
    if not raw:
        return ""
    extension = _field_note_audio_extension(audio_file)
    mime_type = {
        "wav": "audio/wav", "m4a": "audio/mp4", "mp4": "audio/mp4",
        "ogg": "audio/ogg", "mp3": "audio/mpeg", "webm": "audio/webm",
    }.get(extension, "audio/webm")
    path = (
        f"{current_family_key()}/{current_member_key()}/"
        f"_field_notes/v1/{str(note_id)}.{extension}"
    )
    supabase_client().storage.from_(PHOTO_BUCKET).upload(
        path=path,
        file=raw,
        file_options={"content-type": mime_type, "cache-control": "3600", "upsert": "true"},
    )
    return path


def _field_note_location(raw_location, trip):
    location = {}
    if isinstance(raw_location, dict):
        try:
            latitude = float(raw_location.get("latitude"))
            longitude = float(raw_location.get("longitude"))
            accuracy = float(raw_location.get("accuracy_m") or 0)
            if -90 <= latitude <= 90 and -180 <= longitude <= 180:
                location = {
                    "source": "gps",
                    "latitude": round(latitude, 7),
                    "longitude": round(longitude, 7),
                    "accuracy_m": round(accuracy, 1) if accuracy > 0 else None,
                    "measured_at": str(raw_location.get("measured_at") or ""),
                }
        except (TypeError, ValueError):
            location = {}
    place_label = ""
    if location:
        try:
            place_label = reverse_geocode_rough(location["latitude"], location["longitude"])
        except Exception:
            place_label = ""
    if not place_label:
        place_label = str((trip or {}).get("destination") or "").strip()
    if location:
        location["place_label"] = place_label
    else:
        location = {"source": "manual_destination" if place_label else "unavailable", "place_label": place_label}
    return location


def save_field_note(kind, text_value="", audio_file=None, raw_location=None):
    kind = str(kind or "").strip().lower()
    if kind not in FIELD_NOTE_KINDS:
        raise ValueError("記録の種類を確認できませんでした。")
    text_value = str(text_value or "").strip()
    if audio_file is not None and not text_value:
        text_value = transcribe_audio(
            audio_file,
            context=f"東京ぶらり旅の外出中に残した『{FIELD_NOTE_KINDS[kind]['label']}』の短いひとことです。",
        )
    if not text_value:
        raise ValueError("声か文字のどちらかで、ひとこと残してください。")
    trip = ensure_today_trip()
    note_id = uuid.uuid4().hex
    audio_path = _upload_field_note_audio(audio_file, note_id) if audio_file is not None else ""
    location = _field_note_location(raw_location, trip)
    item = {
        "id": note_id,
        "kind": kind,
        "text": text_value[:500],
        "created_at": now_jst().isoformat(),
        "trip_date": today_iso(),
        "trip_id": str(trip.get("id") or ""),
        "place_label": str(location.get("place_label") or "")[:100],
        "location": location,
        "audio_storage_path": audio_path,
        "status": "open" if kind == "next" else "recorded",
        "planned_for_date": "",
        "planned_for_trip_id": "",
        "completed_at": "",
    }
    state = get_field_note_state(force=True)
    state["items"] = [item] + list(state.get("items") or [])
    _write_field_note_state(state)
    return item


def pending_next_actions(*, nonblocking=False):
    state = get_field_note_state(nonblocking=nonblocking)
    return [
        item for item in list(state.get("items") or [])
        if item.get("kind") == "next" and item.get("status") in {"open", "planned"}
    ]


def field_notes_for_trip(trip_id="", trip_date=""):
    state = get_field_note_state()
    trip_id = str(trip_id or "").strip()
    trip_date = str(trip_date or "").strip()[:10]
    rows = []
    for item in state.get("items") or []:
        same_trip = bool(trip_id and str(item.get("trip_id") or "") == trip_id)
        legacy_same_day = bool(not item.get("trip_id") and trip_date and str(item.get("trip_date") or "") == trip_date)
        if same_trip or legacy_same_day:
            rows.append(item)
    return rows


def render_trip_field_notes(trip):
    trip = trip or {}
    try:
        items = field_notes_for_trip(trip.get("id"), trip.get("trip_date"))
    except Exception:
        items = []
    if not items:
        return
    st.markdown("#### 外出中のひとこと")
    audio_paths = [str(x.get("audio_storage_path") or "") for x in items if x.get("audio_storage_path")]
    try:
        audio_urls = signed_photo_url_map(audio_paths, expires_in=1800) if audio_paths else {}
    except Exception:
        audio_urls = {}
    for index, item in enumerate(items):
        meta = FIELD_NOTE_KINDS.get(item.get("kind"), FIELD_NOTE_KINDS["curiosity"])
        place = str(item.get("place_label") or "").strip()
        st.markdown(
            f"""
            <div class="talk-card" style="margin:.28rem 0; border-left:4px solid {meta['color']};">
              <div class="small-note">{meta['emoji']} {html.escape(meta['label'])}{'　📍 ' + html.escape(place) if place else ''}</div>
              <div class="big-text" style="margin-top:.28rem;">{html.escape(str(item.get('text') or ''))}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        audio_path = str(item.get("audio_storage_path") or "")
        if audio_path and audio_urls.get(audio_path):
            st.audio(audio_urls[audio_path])


def preferred_next_action(active_place="", *, nonblocking=False):
    items = pending_next_actions(nonblocking=nonblocking)
    if not items:
        return None
    place_key = re.sub(r"\s+|周辺|付近", "", str(active_place or "")).lower()
    if place_key:
        for item in items:
            item_place = re.sub(r"\s+|周辺|付近", "", str(item.get("place_label") or "")).lower()
            if item_place and (place_key in item_place or item_place in place_key):
                enriched = dict(item)
                enriched["near_current_place"] = True
                return enriched
    return dict(items[0])


def update_next_action(note_id, action):
    action = str(action or "").strip().lower()
    state = get_field_note_state(force=True)
    found = None
    for item in state.get("items") or []:
        if str(item.get("id") or "") != str(note_id or "") or item.get("kind") != "next":
            continue
        if action == "plan":
            trip = ensure_today_trip()
            item["status"] = "planned"
            item["planned_for_date"] = today_iso()
            item["planned_for_trip_id"] = str(trip.get("id") or "")
        elif action == "done":
            item["status"] = "done"
            item["completed_at"] = now_jst().isoformat()
        elif action == "reopen":
            item["status"] = "open"
            item["completed_at"] = ""
        else:
            raise ValueError("更新内容を確認できませんでした。")
        found = item
        break
    if found is None:
        raise ValueError("『次にやりたい』の記録が見つかりませんでした。")
    _write_field_note_state(state)
    return found


def delete_field_note(note_id):
    state = get_field_note_state(force=True)
    target = next((x for x in state.get("items") or [] if str(x.get("id") or "") == str(note_id or "")), None)
    state["items"] = [x for x in state.get("items") or [] if str(x.get("id") or "") != str(note_id or "")]
    _write_field_note_state(state)
    audio_path = str((target or {}).get("audio_storage_path") or "")
    if audio_path:
        try:
            supabase_client().storage.from_(PHOTO_BUCKET).remove([audio_path])
        except Exception:
            pass


def _format_music_time_v472(total_seconds):
    """Display music positions/durations as minutes and seconds; never change stored data."""
    try:
        value = max(0, int(total_seconds or 0))
    except (TypeError, ValueError, OverflowError):
        value = 0
    minutes, seconds = divmod(value, 60)
    return f"{minutes}\u5206{seconds}\u79d2"


def music_library_label(item):
    item = item if isinstance(item, dict) else {}
    title = str(item.get("title") or item.get("video_id") or "保存した音楽").strip()
    author = str(item.get("author_name") or "").strip()
    start_seconds = int(item.get("start_seconds") or 0)
    end_seconds = int(item.get("end_seconds") or (start_seconds + 20))
    prefix = f"{title} / {author}" if author else title
    return f"{_format_music_time_v472(end_seconds - start_seconds)}｜{prefix}（{_format_music_time_v472(start_seconds)}〜{_format_music_time_v472(end_seconds)}）"


def apply_music_library_item(month_key, review, item):
    item = _normalize_music_library_item(item)
    if not item:
        raise ValueError("保存した音楽を読み込めませんでした。")
    state = _monthly_replay_state(month_key, review)
    st.session_state[state["url_key"]] = item["youtube_url"]
    st.session_state[state["start_key"]] = int(item["start_seconds"])
    st.session_state[state["end_key"]] = int(item["end_seconds"])
    st.session_state[state["reason_key"]] = str(item.get("reason") or "")
    st.session_state[state["confidence_key"]] = str(item.get("confidence") or "saved")
    st.session_state[state["title_key"]] = str(item.get("title") or "")
    playback = dict(item)
    playback["updated_at"] = now_jst().isoformat()
    playback["source"] = "saved_library_preview"
    # v333: selecting saved music only changes the current audition. The movie/review
    # is not persisted until an explicit movie-save action is used.
    set_monthly_preview_playback(month_key, playback)
    st.session_state[f"monthly_replay_applied_{month_key}"] = {
        "start_seconds": int(item["start_seconds"]),
        "end_seconds": int(item["end_seconds"]),
    }
    return playback


def format_mmss(total_seconds):
    try:
        total_seconds = max(0, int(total_seconds))
    except Exception:
        total_seconds = 0
    minutes, seconds = divmod(total_seconds, 60)
    hours, minutes = divmod(minutes, 60)
    if hours:
        return f"{hours}:{minutes:02d}:{seconds:02d}"
    return f"{minutes}:{seconds:02d}"


def parse_youtube_video_id(value):
    value = str(value or "").strip()
    if not value:
        return ""
    if len(value) == 11 and all(ch.isalnum() or ch in {"-", "_"} for ch in value):
        return value
    try:
        parsed = urlparse(value)
    except Exception:
        return ""
    host = str(parsed.netloc or "").lower()
    path = str(parsed.path or "")
    query = parse_qs(parsed.query or "")
    video_id = ""
    if "youtu.be" in host:
        video_id = path.strip("/").split("/")[0]
    elif "youtube.com" in host or "youtube-nocookie.com" in host:
        if path == "/watch":
            video_id = (query.get("v") or [""])[0]
        elif path.startswith("/embed/"):
            video_id = path.split("/embed/", 1)[1].split("/")[0]
        elif path.startswith("/shorts/"):
            video_id = path.split("/shorts/", 1)[1].split("/")[0]
        elif path.startswith("/live/"):
            video_id = path.split("/live/", 1)[1].split("/")[0]
    video_id = "".join(ch for ch in str(video_id) if ch.isalnum() or ch in {"-", "_"})
    return video_id if 8 <= len(video_id) <= 15 else ""


def youtube_watch_url(video_id):
    video_id = str(video_id or "").strip()
    return f"https://www.youtube.com/watch?v={video_id}" if video_id else ""


def youtube_embed_url(video_id, start_seconds=0, end_seconds=0, autoplay=False):
    video_id = str(video_id or "").strip()
    if not video_id:
        return ""
    params = {
        "start": max(0, int(start_seconds or 0)),
        "autoplay": 1 if autoplay else 0,
        "controls": 1,
        "rel": 0,
        "modestbranding": 1,
        "playsinline": 1,
    }
    end_seconds = int(end_seconds or 0)
    if end_seconds > params["start"]:
        params["end"] = end_seconds
    return f"https://www.youtube.com/embed/{video_id}?{urlencode(params)}"


def fetch_youtube_oembed(url):
    url = str(url or "").strip()
    if not url:
        return {}
    api_url = "https://www.youtube.com/oembed?" + urlencode({"url": url, "format": "json"})
    request = Request(api_url, headers={"User-Agent": "Mozilla/5.0"})
    try:
        with urlopen(request, timeout=6) as response:
            data = json.loads(response.read().decode("utf-8", "ignore"))
        if isinstance(data, dict):
            return {
                "title": str(data.get("title") or "").strip(),
                "author_name": str(data.get("author_name") or "").strip(),
            }
    except Exception:
        return {}
    return {}


def guess_monthly_replay_window(youtube_url, month_key, review):
    meta = fetch_youtube_oembed(youtube_url)
    themes = []
    if isinstance(review, dict):
        for item in review.get("findings", []) or []:
            if isinstance(item, dict):
                theme = str(item.get("theme") or "").strip()
                if theme:
                    themes.append(theme)
    review_hint = " / ".join(themes[:3]) or str((review or {}).get("opening") or "").strip() or "特記事項なし"
    schema = {
        "type": "object",
        "properties": {
            "start_seconds": {"type": "integer"},
            "end_seconds": {"type": "integer"},
            "reason": {"type": "string"},
            "confidence": {"type": "string"},
        },
        "required": ["start_seconds", "end_seconds", "reason", "confidence"],
        "additionalProperties": False,
    }
    title = str(meta.get("title") or "").strip()
    author = str(meta.get("author_name") or "").strip()
    scope_label = str((review or {}).get("_scope_label") or month_key).strip()
    prompt = f"""
あなたは、写真振り返りで使うYouTube音楽の『おすすめ区間』を提案します。
目的は、アプリ内で9:16の写真スライドを見返すときに、耳に残りやすい部分を短く使うことです。

入力:
- 振り返り対象: {scope_label}
- YouTube URL: {youtube_url}
- 分かる場合のタイトル: {title or '不明'}
- 分かる場合の投稿者: {author or '不明'}
- 振り返り要点: {review_hint}

ルール:
- できるだけサビ・フック・いちばん印象に残りやすい部分を優先する。
- 曲や動画の正確な構成が分からない場合は、一般的なポップスの流れをもとに慎重に推測する。
- 使う長さは12〜25秒。理想は18〜22秒。
- start_seconds は0以上600以下。
- end_seconds は start_seconds より後にする。
- reason は日本語で60文字以内、簡潔に。
- confidence は low / medium / high のいずれか。
- 実在確認できないことを断定しない。推測であることを前提に、もっとも無難な候補を1つだけ返す。
""".strip()
    try:
        result = ask_json(prompt, "burari_monthly_replay_window", schema, 280)
    except Exception:
        result = {}
    start = max(0, min(600, int(result.get("start_seconds") or 48)))
    end = int(result.get("end_seconds") or (start + 20))
    if end <= start:
        end = start + 20
    end = max(start + 12, min(start + 25, end))
    end = min(620, end)
    reason = str(result.get("reason") or "一般的なサビ位置をもとに推測しました。").strip()
    confidence = str(result.get("confidence") or "low").strip().lower()
    if confidence not in {"low", "medium", "high"}:
        confidence = "low"
    return {
        "youtube_url": youtube_url,
        "video_id": parse_youtube_video_id(youtube_url),
        "title": title,
        "author_name": author,
        "start_seconds": start,
        "end_seconds": end,
        "reason": reason,
        "confidence": confidence,
        "updated_at": now_jst().isoformat(),
        "source": "ai_guess",
    }


def _monthly_replay_selected_photos(bundle, limit=None):
    """Return replay photos in chronological order.

    v325: replay movies no longer impose a fixed photo-count ceiling.  ``limit`` is
    retained only for backward compatibility with any old caller; normal replay paths
    pass no limit and therefore include every available photo.
    """
    trip_map = {str(t.get("id")): t for t in (bundle or {}).get("trips", []) if isinstance(t, dict) and t.get("id")}
    photos = [p for p in (bundle or {}).get("photos", []) if isinstance(p, dict)]
    photos.sort(key=lambda p: (
        str(trip_map.get(str(p.get("trip_id")), {}).get("trip_date") or ""),
        str(p.get("captured_at") or ""),
        str(p.get("id") or ""),
    ))
    if limit is not None:
        try:
            limit_value = int(limit)
        except (TypeError, ValueError):
            limit_value = 0
        if limit_value > 0 and len(photos) > limit_value:
            step = len(photos) / float(limit_value)
            picked = []
            seen = set()
            for idx in range(limit_value):
                item = photos[min(int(idx * step), len(photos) - 1)]
                key = str(item.get("id") or idx)
                if key not in seen:
                    picked.append(item)
                    seen.add(key)
            photos = picked or photos[:limit_value]
    return photos, trip_map


def _monthly_replay_photo_caption(photo, trip, index):
    label_bits = []
    trip_date = str((trip or {}).get("trip_date") or "").strip()
    place = str(photo_location_label(photo) or (trip or {}).get("destination") or "").strip()
    if trip_date:
        label_bits.append(trip_date)
    if place:
        label_bits.append(place)
    return " / ".join(label_bits) or f"写真{index}"


def _replay_primary_people(people, width, height):
    """Keep visually prominent people while ignoring tiny/partial edge background detections.

    This is used only for replay framing. It never identifies who a person is; it ranks
    detector boxes by visible size, centrality, and whether the box is clipped by an image edge.
    """
    width = max(1.0, float(width or 1))
    height = max(1.0, float(height or 1))
    image_area = width * height
    ranked = []
    for item in list(people or []):
        if not isinstance(item, dict):
            continue
        try:
            x1, y1, x2, y2 = [float(v) for v in item.get("box")]
        except Exception:
            continue
        box_w = max(1.0, x2 - x1)
        box_h = max(1.0, y2 - y1)
        area_ratio = max(0.0, min(1.0, (box_w * box_h) / image_area))
        cx = (x1 + x2) / 2.0
        cy = (y1 + y2) / 2.0
        dx = abs((cx / width) - 0.5)
        dy = abs((cy / height) - 0.5)
        center_distance = min(1.0, ((dx * dx + dy * dy) ** 0.5) / 0.70710678)
        centrality = 1.0 - center_distance
        edge_count = sum([
            x1 <= width * 0.012,
            y1 <= height * 0.012,
            x2 >= width * 0.988,
            y2 >= height * 0.988,
        ])
        edge_penalty = 1.0 if edge_count == 0 else (0.64 if edge_count == 1 else 0.40)
        kind_bonus = 1.04 if str(item.get("kind") or "") == "face" else 1.0
        prominence = area_ratio * (0.68 + 0.32 * centrality) * edge_penalty * kind_bonus
        ranked.append({
            **item,
            "_area_ratio": area_ratio,
            "_prominence": prominence,
            "_edge_count": int(edge_count),
        })
    if not ranked:
        return []
    ranked.sort(key=lambda row: (row.get("_prominence", 0.0), row.get("_area_ratio", 0.0)), reverse=True)
    top = ranked[0]
    top_prominence = max(1e-9, float(top.get("_prominence") or 0.0))
    top_area = max(1e-9, float(top.get("_area_ratio") or 0.0))
    selected = [top]
    for item in ranked[1:]:
        prominence = float(item.get("_prominence") or 0.0)
        area_ratio = float(item.get("_area_ratio") or 0.0)
        edge_count = int(item.get("_edge_count") or 0)
        # A second/third person remains a main subject when they are materially sized
        # relative to the strongest subject. Tiny edge-clipped passers-by do not constrain zoom.
        comparable = prominence >= top_prominence * 0.40 and area_ratio >= max(0.014, top_area * 0.30)
        materially_large = area_ratio >= max(0.055, top_area * 0.52)
        edge_background = edge_count >= 1 and prominence < top_prominence * 0.58 and area_ratio < top_area * 0.58
        if (comparable or materially_large) and not edge_background:
            selected.append(item)
    return selected[:4]


@st.cache_data(ttl=86400, show_spinner=False, max_entries=2500)
def _replay_photo_framing_meta(storage_path, _raw=None):
    """Choose replay framing without altering the stored photo.

    Portrait photos retain the established 9:16 cover behavior.
    Landscape/square photos fit their full width; person detection never decides
    which family member is allowed to remain in the movie frame.
    """
    default = {
        "fit": "cover",
        "position_x": 50.0,
        "position_y": 50.0,
        "use_backdrop": False,
        "person_count": 0,
        "primary_person_count": 0,
        "orientation": "unknown",
        "zoom": 1.0,
        "focus_x": 50.0,
        "focus_y": 50.0,
        "source_ratio": 1.0,
        "source_width": 0,
        "source_height": 0,
    }
    path = str(storage_path or "").strip()
    if not path:
        return default
    try:
        raw = _raw if _raw is not None else download_photo(path)
        if not raw:
            return default
        from PIL import Image, ImageOps
        with Image.open(io.BytesIO(raw)) as image:
            src = ImageOps.exif_transpose(image).convert("RGB")
            width, height = src.size
            if width <= 0 or height <= 0:
                return default
            source_ratio = float(width) / float(height)
            orientation = "portrait" if height > width else ("landscape" if width > height else "square")
            # Live replay photo URLs are requested at max 1920 px. Use that delivered-size
            # ceiling when the browser later computes quality-safe zoom from stage width.
            delivered_scale = min(1.0, 1920.0 / float(max(width, height)))
            delivered_width = max(1, int(round(width * delivered_scale)))
            delivered_height = max(1, int(round(height * delivered_scale)))
            base = {
                **default,
                "orientation": orientation,
                "source_ratio": round(source_ratio, 6),
                "source_width": delivered_width,
                "source_height": delivered_height,
            }

            if height > width:
                return base
            # Whole landscape/square photographs preserve every person even when
            # side faces, overlapping bodies or seated people evade detection.
            return {**base, 'fit': 'smart', 'zoom': 1.0, 'focus_x': 50.0, 'focus_y': 50.0}

    except Exception:
        # No fixed pixel quality fallback: preserve dimensions when possible and let the
        # browser decide the final quality cap from the actual rendered stage size.
        try:
            from PIL import Image, ImageOps
            raw = _raw if _raw is not None else download_photo(path)
            if raw:
                with Image.open(io.BytesIO(raw)) as image:
                    src = ImageOps.exif_transpose(image)
                    if src.width > 0 and src.height > 0 and src.height <= src.width:
                        source_ratio = float(src.width) / float(src.height)
                        delivered_scale = min(1.0, 1920.0 / float(max(src.width, src.height)))
                        return {
                            **default,
                            "fit": "smart",
                            "orientation": "landscape" if src.width > src.height else "square",
                            "source_ratio": round(source_ratio, 6),
                            "source_width": max(1, int(round(src.width * delivered_scale))),
                            "source_height": max(1, int(round(src.height * delivered_scale))),
                            "zoom": 1.0,
                            "focus_x": 50.0,
                            "focus_y": 50.0,
                            "use_backdrop": False,
                        }
        except Exception:
            pass
        return default



def _refresh_replay_photo_metadata_v448(photos):
    """Reload current owned photo rows before replay assembly.

    Replay must reflect the feeling/tag that is on the photo *now*. Do not repair
    or follow a historical Good Moments/source tag here: that could replace a tag
    the user changed later in Diary/Photos. The live PHOTO_TABLE row is therefore
    the final authority for replay border/badge state. Large AI-tag scopes are read
    in bounded batches so one very large ``in`` filter cannot break movie creation.
    If refresh fails, keep the already-loaded rows rather than blocking playback.
    """
    rows = [dict(photo) for photo in (photos or []) if isinstance(photo, dict)]
    if not rows:
        return rows
    photo_ids = [str(photo.get("id") or "").strip() for photo in rows]
    photo_ids = [photo_id for photo_id in photo_ids if photo_id]
    if not photo_ids:
        return rows

    # v561: shared/owner replay sections can request the exact same photo set twice in
    # one script run. Cache only for that run, so DB/tag mutations on the next rerun
    # remain authoritative while duplicate 200-500ms SELECTs disappear.
    run_id_v561 = int(st.session_state.get("_performance_current_run_v457") or 0)
    run_cache_key_v561 = "_replay_metadata_run_cache_v561"
    run_cache_v561 = st.session_state.get(run_cache_key_v561)
    if not isinstance(run_cache_v561, dict) or int(run_cache_v561.get("run") or -1) != run_id_v561:
        run_cache_v561 = {"run": run_id_v561, "items": {}}
        st.session_state[run_cache_key_v561] = run_cache_v561
    ids_key_v561 = hashlib.sha1("|".join(photo_ids).encode("utf-8")).hexdigest()
    cached_rows_v561 = (run_cache_v561.get("items") or {}).get(ids_key_v561)
    if isinstance(cached_rows_v561, list):
        return [dict(row) for row in cached_rows_v561]

    started = time.perf_counter()
    fresh_rows = []
    try:
        client = supabase_client()
        family, member = current_family_key(), current_member_key()
        chunks = [photo_ids[offset:offset + 100] for offset in range(0, len(photo_ids), 100)]
        def fetch(chunk):
            batch = (client.table(PHOTO_TABLE)
                     .select("id,trip_id,storage_path,captured_at,reflection_json,signals_json")
                     .in_("id", chunk).eq("family_key", family).eq("member_key", member)
                     .execute()).data or []
            return [row for row in batch if isinstance(row, dict)]
        batches = _read_executor_v467().map(fetch, chunks) if len(chunks) > 1 else map(fetch, chunks)
        for batch in batches:
            fresh_rows.extend(batch)
        fresh_map = {
            str(row.get("id") or ""): row
            for row in fresh_rows
            if isinstance(row, dict) and row.get("id")
        }
        result = [dict(fresh_map.get(str(photo.get("id") or "")) or photo) for photo in rows]
        _perf_log_v457(
            "replay:refresh_photo_metadata",
            started_at=started,
            meta={"requested": len(photo_ids), "fresh": len(fresh_map), "batches": max(1, (len(photo_ids) + 99) // 100)},
        )
        try:
            run_cache_v561.setdefault("items", {})[ids_key_v561] = [dict(row) for row in result]
        except Exception:
            pass
        return result
    except Exception:
        _perf_log_v457(
            "replay:refresh_photo_metadata",
            started_at=started,
            meta={"requested": len(photo_ids), "fresh": len(fresh_rows), "fallback": True},
        )
        return rows


def _replay_framing_map_v467(paths, photos=None):
    unique = tuple(dict.fromkeys(str(path or "") for path in paths))
    known = {}
    for photo in photos or []:
        frame = _json_frame_v468(photo)
        if frame:
            known[str(photo.get("storage_path") or "")] = frame
    missing = [path for path in unique if path not in known]
    if missing:
        values = _framing_executor_v467().map(_replay_photo_framing_meta, missing) if len(missing) > 1 else map(_replay_photo_framing_meta, missing)
        known.update(zip(missing, values))
        _queue_framing_rows_v468(photos or [], computed=known, limit=len(missing))
    return {path: known[path] for path in unique}



def build_monthly_replay_photo_items(bundle, limit=None):
    total_started = time.perf_counter()
    photos, trip_map = _monthly_replay_selected_photos(bundle, limit=limit)
    if not photos:
        return []

    photos = _refresh_replay_photo_metadata_v448(photos)
    paths = [str(p.get("storage_path") or "").strip() for p in photos]
    paths = [path for path in paths if path]
    voice_paths = [photo_voice_note_storage_path(photo) for photo in photos]
    voice_paths = [path for path in voice_paths if path]

    sign_started = time.perf_counter()
    signed_map = {}
    voice_signed_map = {}
    # v325: process signing in bounded batches while keeping the total photo count unlimited.
    combined_paths = tuple(dict.fromkeys(paths + voice_paths))
    signed_all = signed_photo_url_map(combined_paths, expires_in=1800)
    signed_map = {path: signed_all[path] for path in paths if path in signed_all}
    voice_signed_map = {path: signed_all[path] for path in voice_paths if path in signed_all}
    _perf_log_v457(
        "replay:sign_media_urls",
        started_at=sign_started,
        meta={"photos": len(paths), "voices": len(voice_paths), "signed": len(signed_map), "voice_signed": len(voice_signed_map)},
    )

    # Framing keeps the exact v433 smart person/quality semantics. The diagnostic log
    # records one aggregate timing rather than one row per photo, which avoids turning
    # broad AI-tag movies into a logging workload.
    assemble_started = time.perf_counter()
    framing_map = _replay_framing_map_v467([str(p.get("storage_path") or "") for p in photos], photos=photos)
    items = []
    for idx, photo in enumerate(photos, start=1):
        url = photo_display_url(photo, signed_map=signed_map, max_px=1920, quality=90)
        if not url:
            continue
        trip = trip_map.get(str(photo.get("trip_id")), {})
        emotion = photo_selected_tag_meta(photo)
        voice_meta = photo_voice_note_meta(photo)
        voice_path = str(voice_meta.get("storage_path") or "").strip()
        voice_url = str(voice_signed_map.get(voice_path) or "")
        # v489: signed URLs are the fast path. If Storage signing transiently misses a
        # short voice note, embed only that missing clip as a data URL so a visible
        # voice-bearing photo never becomes silently unplayable. The fallback is rare
        # and bounded to already-selected replay photos, so ordinary replays stay light.
        if voice_path and not voice_url:
            try:
                voice_raw = download_photo(voice_path)
                if voice_raw:
                    voice_mime = str(
                        voice_meta.get("storage_mime_type")
                        or voice_meta.get("mime_type")
                        or "audio/mp4"
                    ).strip() or "audio/mp4"
                    voice_url = f"data:{voice_mime};base64," + base64.b64encode(voice_raw).decode("ascii")
            except Exception:
                voice_url = ""
        framing = framing_map[str(photo.get("storage_path") or "")]
        items.append({
            "photo_id": str(photo.get("id") or ""),
            "storage_path": str(photo.get("storage_path") or ""),
            "captured_at": str(photo.get("captured_at") or ""),
            "url": url,
            "caption": _monthly_replay_photo_caption(photo, trip, idx),
            "emotion": str(emotion.get("key") or ""),
            "emotion_label": str(emotion.get("label") or ""),
            "emotion_emoji": str(emotion.get("emoji") or ""),
            "emotion_color": str(emotion.get("color") or ""),
            "favorite": photo_favorite_is_enabled(photo),
            "replay_fit": str(framing.get("fit") or "cover"),
            "replay_position_x": float(framing.get("position_x") or 50.0),
            "replay_position_y": float(framing.get("position_y") or 50.0),
            "replay_use_backdrop": False,
            "replay_person_count": int(framing.get("person_count") or 0),
            "replay_primary_person_count": int(framing.get("primary_person_count") or 0),
            "replay_orientation": str(framing.get("orientation") or "unknown"),
            "replay_zoom": float(framing.get("zoom") or 1.0),
            "replay_source_width": int(framing.get("source_width") or 0),
            "replay_source_height": int(framing.get("source_height") or 0),
            "replay_focus_x": float(framing.get("focus_x") or framing.get("position_x") or 50.0),
            "replay_focus_y": float(framing.get("focus_y") or framing.get("position_y") or 50.0),
            "replay_source_ratio": float(framing.get("source_ratio") or 1.0),
            "has_voice": bool(voice_path and voice_url),
            "voice_url": voice_url,
            "voice_transcript": str(voice_meta.get("transcript") or ""),
            "voice_duration_ms": _voice_duration_value_ms_v469(voice_meta),
        })
    _perf_log_v457(
        "replay:framing_and_items",
        started_at=assemble_started,
        meta={"source": len(photos), "items": len(items), "voices": len(voice_paths)},
    )
    _perf_log_v457(
        "replay:build_photo_items_total",
        started_at=total_started,
        meta={"source": len(photos), "items": len(items)},
    )
    return items


PHOTO_CURATION_SCHEMA = {
    "type": "object",
    "properties": {
        "picks": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "candidate_index": {"type": "integer"},
                    "category": {"type": "integer"},
                    "score": {"type": "integer"},
                    "reason": {"type": "string"},
                },
                "required": ["candidate_index", "category", "score", "reason"],
                "additionalProperties": False,
            },
        },
    },
    "required": ["picks"],
    "additionalProperties": False,
}


def replay_photo_curation_state_key(scope_key):
    return f"_replay_photo_curation_{scope_key}"


def get_replay_photo_curation(scope_key):
    value = st.session_state.get(replay_photo_curation_state_key(scope_key))
    return value if isinstance(value, dict) else {}


def clear_replay_photo_curation(scope_key):
    st.session_state.pop(replay_photo_curation_state_key(scope_key), None)


def replay_photo_curation_target_count(total_count):
    total = max(0, int(total_count or 0))
    if total <= 0:
        return 0
    if total <= 5:
        return 1
    if total <= 8:
        return 2
    return max(1, int(round(total / 3.0)))


def replay_photo_curation_candidate_limit(total_count, target_count):
    total = max(0, int(total_count or 0))
    target = max(0, int(target_count or 0))
    if total <= 0:
        return 0
    if total <= 36:
        return total
    # Keep the AI input bounded while still letting it compare a broad enough slice
    # to approximate the requested "about one-third" reduction.
    desired = max(36, target * 3)
    return min(total, max(36, min(desired, 72)))


def _replay_photo_candidates(bundle, max_candidates=None):
    photos, trip_map = _monthly_replay_selected_photos(bundle)
    if not max_candidates or len(photos) <= max_candidates:
        return photos, trip_map
    max_candidates = max(1, int(max_candidates))
    if max_candidates >= len(photos):
        return photos, trip_map

    favorites = [photo for photo in photos if photo_favorite_is_enabled(photo)]
    favorite_ids = {str(photo.get("id") or "") for photo in favorites if str(photo.get("id") or "")}
    remaining_slots = max(0, max_candidates - len(favorites))
    nonfavorites = [photo for photo in photos if str(photo.get("id") or "") not in favorite_ids]

    picked_nonfavorites = []
    if remaining_slots > 0 and nonfavorites:
        step = len(nonfavorites) / float(remaining_slots)
        seen = set()
        for idx in range(remaining_slots):
            photo = nonfavorites[min(int(idx * step), len(nonfavorites) - 1)]
            key = str(photo.get("id") or idx)
            if key not in seen:
                seen.add(key)
                picked_nonfavorites.append(photo)

    keep_ids = {str(photo.get("id") or "") for photo in favorites + picked_nonfavorites}
    # Return in the original chronological order while guaranteeing every favorite.
    picked = [photo for photo in photos if str(photo.get("id") or "") in keep_ids]
    return picked or photos[:max_candidates], trip_map


def _fallback_replay_curation(photos, max_selected=12):
    if not photos:
        return []
    max_selected = max(1, int(max_selected or 1))
    if len(photos) <= max_selected:
        return [str(photo.get("id") or "") for photo in photos if photo.get("id")]
    step = len(photos) / float(max_selected)
    picked = []
    seen = set()
    for idx in range(max_selected):
        photo = photos[min(int(idx * step), len(photos) - 1)]
        key = str(photo.get("id") or "")
        if key and key not in seen:
            seen.add(key)
            picked.append(key)
    return picked


def generate_replay_photo_curation(scope_key, period_label, bundle, max_candidates=None, max_selected=None):
    all_photos, _ = _monthly_replay_selected_photos(bundle)
    total_source_count = len(all_photos)
    if total_source_count <= 0:
        payload = {"active": False, "selected_photo_ids": [], "picks": [], "source_count": 0, "target_count": 0, "favorite_count": 0}
        st.session_state[replay_photo_curation_state_key(scope_key)] = payload
        return payload

    favorite_photos = [photo for photo in all_photos if photo_favorite_is_enabled(photo)]
    favorite_ids = [str(photo.get("id") or "") for photo in favorite_photos if str(photo.get("id") or "")]
    favorite_id_set = set(favorite_ids)
    base_target = int(max_selected or replay_photo_curation_target_count(total_source_count) or 1)
    # Favorites are never discarded. If they exceed one third, favorites take priority.
    target_selected = max(base_target, len(favorite_ids))
    target_selected = min(target_selected, total_source_count)
    candidate_limit = int(max_candidates or replay_photo_curation_candidate_limit(total_source_count, target_selected) or total_source_count)
    candidate_photos, trip_map = _replay_photo_candidates(bundle, max_candidates=candidate_limit)
    if not candidate_photos:
        payload = {"active": False, "selected_photo_ids": [], "picks": [], "source_count": total_source_count, "target_count": target_selected, "favorite_count": len(favorite_ids)}
        st.session_state[replay_photo_curation_state_key(scope_key)] = payload
        return payload

    image_items = []
    candidate_meta = []
    valid_photos = []
    for idx, photo in enumerate(candidate_photos, start=1):
        path = str(photo.get("storage_path") or "").strip()
        if not path:
            continue
        try:
            raw = download_photo(path)
        except Exception:
            raw = b""
        if not raw:
            continue
        raw = _vision_ready_photo(raw, max_side=640, quality=72)
        trip = trip_map.get(str(photo.get("trip_id")), {})
        caption = _monthly_replay_photo_caption(photo, trip, idx)
        photo_id = str(photo.get("id") or "")
        is_favorite = photo_id in favorite_id_set
        candidate_meta.append({
            "candidate_index": idx,
            "photo_id": photo_id,
            "caption": caption,
            "favorite": is_favorite,
        })
        valid_photos.append(photo)
        favorite_label = " ★お気に入り（採用確定）" if is_favorite else ""
        image_items.append((f"候補{idx}{favorite_label}: {caption}", raw))

    if not valid_photos:
        payload = {"active": False, "selected_photo_ids": [], "picks": [], "source_count": total_source_count, "target_count": target_selected, "favorite_count": len(favorite_ids)}
        st.session_state[replay_photo_curation_state_key(scope_key)] = payload
        return payload

    valid_ids = {str(photo.get("id") or "") for photo in valid_photos}
    favorite_ids = [pid for pid in favorite_ids if pid in valid_ids]
    favorite_id_set = set(favorite_ids)
    target_selected = min(max(target_selected, len(favorite_ids)), len(valid_photos))
    additional_needed = max(0, target_selected - len(favorite_ids))

    result = {"picks": []}
    if additional_needed > 0:
        prompt_lines = [
            "東京ぶらり旅の振り返りムービー用に、候補写真の中から見返す価値が高い写真を厳選してください。",
            "子どもの写真として、映りがよく、感情が伝わり、成長や未来を感じる写真を優先してください。",
            "厳選基準は次の3つです。",
            "1. カメラ目線で、本人がはっきり映り、感情表現がしっかりしている写真。",
            "2. カメラ目線ではなく、何かに夢中になっていたり、頑張っている最中が伝わる写真。",
            "3. 人と人との絆や関わりが感じられる写真。",
            "どの基準でも、単なる記念写真より、自分で考えている・挑戦している・やりきった・関わり合っているなど、この子の成長や未来が感じられる写真を高く評価してください。",
            "ピンぼけ、被写体が小さすぎる、暗すぎる、表情や行動が読み取りにくい、ほぼ同じ場面の重複写真は優先度を下げてください。",
            "★お気に入りと表示された写真はユーザー指定で採用確定です。追加選抜ではお気に入り写真を選ばず、それ以外から選んでください。",
            f"候補は全部で{len(candidate_meta)}枚です。1〜{len(candidate_meta)}の候補番号で答えてください。",
            f"お気に入り{len(favorite_ids)}枚はすでに採用済みです。残り{additional_needed}枚を選び、合計がおおむね元枚数の1/3になるようにしてください。",
            "3つの基準が極端に偏りすぎないようにしつつ、最終的には総合的に最も良い写真を優先してください。",
            "似た写真を重複して選ばず、時系列も偏りすぎないようにしてください。",
            "category は 1〜3 の整数、score は 1〜100 の整数、reason は短く簡潔にしてください。",
        ]
        result = ask_json_with_images("\n".join(prompt_lines), image_items, "curate_replay_photos", PHOTO_CURATION_SCHEMA, 1200)

    by_index = {meta["candidate_index"]: meta for meta in candidate_meta}
    picks = []
    seen_ids = set()

    # Favorite photos are inserted first and cannot be removed by the AI ranking.
    for meta in candidate_meta:
        photo_id = str(meta.get("photo_id") or "")
        if not photo_id or photo_id not in favorite_id_set or photo_id in seen_ids:
            continue
        picks.append({
            "candidate_index": int(meta.get("candidate_index") or 0),
            "photo_id": photo_id,
            "category": 4,
            "score": 100,
            "reason": "お気に入りに登録",
            "caption": str(meta.get("caption") or ""),
        })
        seen_ids.add(photo_id)

    raw_picks = [pick for pick in (result.get("picks") or []) if isinstance(pick, dict)]
    try:
        raw_picks = sorted(raw_picks, key=lambda x: int(x.get("score") or 0), reverse=True)
    except Exception:
        pass
    for pick in raw_picks:
        try:
            candidate_index = int(pick.get("candidate_index"))
        except Exception:
            continue
        meta = by_index.get(candidate_index)
        if not meta:
            continue
        photo_id = str(meta.get("photo_id") or "")
        if not photo_id or photo_id in seen_ids or photo_id in favorite_id_set:
            continue
        try:
            category = int(pick.get("category") or 0)
        except Exception:
            category = 0
        if category not in {1, 2, 3}:
            category = 2
        try:
            score = int(pick.get("score") or 0)
        except Exception:
            score = 0
        score = max(0, min(100, score))
        picks.append({
            "candidate_index": candidate_index,
            "photo_id": photo_id,
            "category": category,
            "score": score,
            "reason": str(pick.get("reason") or "").strip(),
            "caption": str(meta.get("caption") or ""),
        })
        seen_ids.add(photo_id)
        if len(picks) >= target_selected:
            break

    if len(picks) < target_selected:
        fallback_ids = _fallback_replay_curation(valid_photos, max_selected=target_selected)
        for photo_id in fallback_ids:
            photo_id = str(photo_id or "")
            if not photo_id or photo_id in seen_ids:
                continue
            meta = next((m for m in candidate_meta if str(m.get("photo_id") or "") == photo_id), None)
            if not meta:
                continue
            picks.append({
                "candidate_index": int(meta.get("candidate_index") or 0),
                "photo_id": photo_id,
                "category": 2,
                "score": 60,
                "reason": "自動補完",
                "caption": str(meta.get("caption") or ""),
            })
            seen_ids.add(photo_id)
            if len(picks) >= target_selected:
                break

    all_order = {str(photo.get("id") or ""): idx for idx, photo in enumerate(all_photos)}
    ordered_picks = sorted(picks, key=lambda x: all_order.get(str(x.get("photo_id") or ""), 10**9))
    selected_photo_ids = [p.get("photo_id") for p in ordered_picks if p.get("photo_id")]
    payload = {
        "active": bool(selected_photo_ids),
        "period_label": str(period_label or ""),
        "selected_photo_ids": selected_photo_ids,
        "picks": ordered_picks,
        "generated_at": now_jst().isoformat(),
        "candidate_count": len(candidate_photos),
        "source_count": total_source_count,
        "target_count": target_selected,
        "favorite_count": len(favorite_ids),
        "source_photo_ids": [str(photo.get("id") or "") for photo in all_photos if str(photo.get("id") or "")],
    }
    st.session_state[replay_photo_curation_state_key(scope_key)] = payload
    return payload


def apply_replay_photo_curation(scope_key, all_photo_items):
    state = get_replay_photo_curation(scope_key)
    selected_ids = [str(x) for x in (state.get("selected_photo_ids") or []) if str(x or "").strip()]
    if not state.get("active") or not selected_ids:
        return list(all_photo_items or []), {}
    # A curation was calculated from a particular source set. If photos were later
    # added/removed (including through a new AI tag), discard the stale subset so
    # every newly eligible photo appears without requiring another button press.
    current_count = len(all_photo_items or [])
    try:
        source_count = int(state.get("source_count") or 0)
    except (TypeError, ValueError):
        source_count = 0
    current_ids = [
        str(item.get("photo_id") or "").strip()
        for item in (all_photo_items or [])
        if isinstance(item, dict) and str(item.get("photo_id") or "").strip()
    ]
    source_ids = [str(value or "").strip() for value in (state.get("source_photo_ids") or [])]
    source_ids = [value for value in source_ids if value]
    source_changed = source_ids != current_ids if source_ids else source_count != current_count
    if source_changed:
        clear_replay_photo_curation(scope_key)
        return list(all_photo_items or []), {}
    selected_set = set(selected_ids)
    # A favorite added after an earlier curation run must still appear immediately.
    for item in (all_photo_items or []):
        if isinstance(item, dict) and bool(item.get("favorite")):
            photo_id = str(item.get("photo_id") or "").strip()
            if photo_id:
                selected_set.add(photo_id)
    curated = [item for item in (all_photo_items or []) if str(item.get("photo_id") or "") in selected_set]
    return curated or list(all_photo_items or []), state


def render_replay_photo_curation_controls(scope_key, period_label, bundle, all_photo_items):
    state = get_replay_photo_curation(scope_key)
    active_count = len(state.get("selected_photo_ids") or [])
    total_count = len(all_photo_items or [])
    target_count = replay_photo_curation_target_count(total_count)
    with st.container(border=True):
        st.markdown("#### ✨ 写真厳選モード")
        if state.get("active") and active_count:
            st.success(f"厳選中です。{total_count}枚から {active_count}枚を表示しています。")
        cols = st.columns(3)
        with cols[0]:
            if st.button("✨ 写真厳選モードにする", key=f"replay_curation_on_{scope_key}", type="primary", use_container_width=True):
                try:
                    with st.spinner("写真を厳選しています…"):
                        payload = generate_replay_photo_curation(scope_key, period_label, bundle, max_selected=target_count)
                    count = len(payload.get("selected_photo_ids") or [])
                    if count:
                        st.success(f"{count}枚を厳選しました。")
                    else:
                        st.warning("厳選できる写真が見つかりませんでした。")
                    st.rerun()
                except Exception as exc:
                    st.error("写真を厳選できませんでした。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))
        with cols[1]:
            if st.button("↻ もう一度厳選", key=f"replay_curation_retry_{scope_key}", use_container_width=True, disabled=not bool(all_photo_items)):
                try:
                    with st.spinner("写真を厳選しています…"):
                        payload = generate_replay_photo_curation(scope_key, period_label, bundle, max_selected=target_count)
                    count = len(payload.get("selected_photo_ids") or [])
                    if count:
                        st.success(f"{count}枚を選び直しました。")
                    st.rerun()
                except Exception as exc:
                    st.error("写真を厳選できませんでした。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))
        with cols[2]:
            if st.button("すべての写真に戻す", key=f"replay_curation_clear_{scope_key}", use_container_width=True, disabled=not bool(state.get("active"))):
                clear_replay_photo_curation(scope_key)
                st.success("通常表示に戻しました。")
                st.rerun()

        picks = [x for x in (state.get("picks") or []) if isinstance(x, dict)]
        if picks:
            with st.expander("厳選した写真の理由を見る"):
                category_names = {1: "① カメラ目線", 2: "② 夢中・頑張り中", 3: "③ 絆", 4: "★ お気に入り"}
                for idx, pick in enumerate(picks, start=1):
                    label = category_names.get(int(pick.get("category") or 0), "② 夢中・頑張り中")
                    reason = str(pick.get("reason") or "").strip() or "-"
                    caption = str(pick.get("caption") or "").strip()
                    st.markdown(f"- {idx}. {label} / {caption} / 理由: {reason}")


def render_replay_voice_embed_section(scope_key, photo_items, photo_row_map):
    options = [str(item.get("photo_id") or "") for item in (photo_items or []) if str(item.get("photo_id") or "").strip()]
    if not options:
        return
    with st.container(border=True):
        st.markdown("#### 🎙 写真に声を埋め込む")

        select_key = f"replay_voice_photo_{scope_key}"
        selected_photo_id = st.selectbox(
            "声をつける写真",
            options=options,
            format_func=lambda pid: next((f"{idx + 1}. {item.get('caption') or '写真'}" for idx, item in enumerate(photo_items) if str(item.get('photo_id') or '') == str(pid)), str(pid)),
            key=select_key,
        )
        selected_photo = photo_row_map.get(str(selected_photo_id), {})
        voice_meta = photo_voice_note_meta(selected_photo)
        voice_path = str(voice_meta.get("storage_path") or "").strip()
        if voice_path:
            try:
                signed = signed_photo_url_map((voice_path,), expires_in=1800)
                voice_url = str(signed.get(voice_path) or "")
            except Exception:
                voice_url = ""
            if voice_url:
                st.audio(voice_url)
            transcript = str(voice_meta.get("transcript") or "").strip()
            if transcript:
                st.caption(f"文字起こし: {transcript}")
            if st.button("この写真の声を削除", key=f"replay_voice_delete_{scope_key}_{selected_photo_id}", use_container_width=True):
                try:
                    delete_photo_voice_note(selected_photo_id)
                    st.success("声メモを削除しました。")
                    st.rerun()
                except Exception as exc:
                    st.error("声メモを削除できませんでした。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))

        audio_file = far_field_audio_input("この写真に声を録音", key=f"replay_voice_input_{scope_key}_{selected_photo_id}")
        if audio_file is not None:
            try:
                audio_file.seek(0)
                preview = audio_file.read()
                audio_file.seek(0)
            except Exception:
                preview = None
            if preview:
                st.audio(preview)

        if st.button("この写真に声を保存", key=f"replay_voice_save_{scope_key}_{selected_photo_id}", type="primary", use_container_width=True):
            if audio_file is None:
                st.error("先に声を録音してください。")
            else:
                try:
                    with st.spinner("声メモを保存しています…"):
                        save_photo_voice_note(selected_photo_id, audio_file, auto_transcribe=True)
                    st.success("声メモを保存しました。")
                    st.rerun()
                except Exception as exc:
                    st.error("声メモを保存できませんでした。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))


def monthly_family_share_info(review):
    if not isinstance(review, dict):
        return {}
    share = review.get("_family_share") or {}
    return dict(share) if isinstance(share, dict) else {}


def monthly_family_share_is_enabled(review):
    return bool(monthly_family_share_info(review).get("shared"))


def build_monthly_family_share_photo_snapshot(bundle, limit=None):
    """Store lightweight references; current photo rows remain authoritative for tags."""
    photos, trip_map = _monthly_replay_selected_photos(bundle, limit=limit)
    photos = _refresh_replay_photo_metadata_v448(photos)
    snapshots = []
    for idx, photo in enumerate(photos, start=1):
        storage_path = str(photo.get("storage_path") or "").strip()
        if not storage_path:
            continue
        trip = trip_map.get(str(photo.get("trip_id")), {})
        emotion = photo_selected_tag_meta(photo)
        voice_meta = photo_voice_note_meta(photo)
        framing = _replay_photo_framing_meta(storage_path)
        snapshots.append({
            "photo_id": str(photo.get("id") or ""),
            "storage_path": storage_path,
            "caption": _monthly_replay_photo_caption(photo, trip, idx),
            "emotion": str(emotion.get("key") or ""),
            "emotion_label": str(emotion.get("label") or ""),
            "emotion_emoji": str(emotion.get("emoji") or ""),
            "emotion_color": str(emotion.get("color") or ""),
            "replay_fit": str(framing.get("fit") or "cover"),
            "replay_position_x": float(framing.get("position_x") or 50.0),
            "replay_position_y": float(framing.get("position_y") or 50.0),
            "replay_use_backdrop": False,
            "replay_person_count": int(framing.get("person_count") or 0),
            "replay_primary_person_count": int(framing.get("primary_person_count") or 0),
            "replay_orientation": str(framing.get("orientation") or "unknown"),
            "replay_zoom": float(framing.get("zoom") or 1.0),
            "replay_source_width": int(framing.get("source_width") or 0),
            "replay_source_height": int(framing.get("source_height") or 0),
            "replay_focus_x": float(framing.get("focus_x") or framing.get("position_x") or 50.0),
            "replay_focus_y": float(framing.get("focus_y") or framing.get("position_y") or 50.0),
            "replay_source_ratio": float(framing.get("source_ratio") or 1.0),
            "voice_storage_path": str(voice_meta.get("storage_path") or ""),
            "voice_transcript": str(voice_meta.get("transcript") or ""),
            "voice_duration_ms": _voice_duration_value_ms_v469(voice_meta),
        })
    return snapshots


def build_family_shared_replay_photo_items(share):
    share = share if isinstance(share, dict) else {}
    snapshots = [x for x in (share.get("photos") or []) if isinstance(x, dict)]
    paths = [str(x.get("storage_path") or "").strip() for x in snapshots]
    paths = [x for x in paths if x]
    if not paths:
        return []

    # v448: a shared replay should also show the owner's *current* photo feeling,
    # not the feeling copied into the movie share payload at share/diary time.
    current_photo_by_path = {}
    owner_member_key = str(share.get("shared_by_member_key") or "").strip()
    if owner_member_key:
        try:
            current_rows = (
                supabase_client().table(PHOTO_TABLE)
                .select("id,storage_path,reflection_json")
                .in_("storage_path", paths)
                .eq("family_key", current_family_key())
                .eq("member_key", owner_member_key)
                .execute()
            ).data or []
            current_photo_by_path = {
                str(row.get("storage_path") or "").strip(): row
                for row in current_rows
                if isinstance(row, dict) and str(row.get("storage_path") or "").strip()
            }
        except Exception:
            current_photo_by_path = {}

    voice_paths = [str(x.get("voice_storage_path") or "").strip() for x in snapshots]
    voice_paths = [x for x in voice_paths if x]
    try:
        signed_map = signed_photo_url_map(paths, expires_in=1800)
    except Exception:
        signed_map = {}
    try:
        voice_signed_map = signed_photo_url_map(voice_paths, expires_in=1800) if voice_paths else {}
    except Exception:
        voice_signed_map = {}
    framing_map = _replay_framing_map_v467(paths)
    items = []
    for snap in snapshots:
        path = str(snap.get("storage_path") or "").strip()
        if not path:
            continue
        url = str(signed_map.get(path) or "")
        if not url:
            try:
                raw = download_photo(path)
                if raw:
                    url = "data:image/jpeg;base64," + base64.b64encode(raw).decode("ascii")
            except Exception:
                url = ""
        if not url:
            continue
        voice_path = str(snap.get("voice_storage_path") or "").strip()
        current_photo = current_photo_by_path.get(path)
        current_emotion = photo_selected_tag_meta(current_photo) if isinstance(current_photo, dict) else {}
        # Recompute from the original image so older shared snapshots that stored the
        # v429 blurred/contain framing automatically receive the current smart framing.
        framing = framing_map[path]
        items.append({
            "url": url,
            "caption": str(snap.get("caption") or ""),
            "emotion": str(current_emotion.get("key") if current_emotion else snap.get("emotion") or ""),
            "emotion_label": str(current_emotion.get("label") if current_emotion else snap.get("emotion_label") or ""),
            "emotion_emoji": str(current_emotion.get("emoji") if current_emotion else snap.get("emotion_emoji") or ""),
            "emotion_color": str(current_emotion.get("color") if current_emotion else snap.get("emotion_color") or ""),
            "replay_fit": str(framing.get("fit") or "cover"),
            "replay_position_x": float(framing.get("position_x") or 50.0),
            "replay_position_y": float(framing.get("position_y") or 50.0),
            "replay_use_backdrop": False,
            "replay_person_count": int(framing.get("person_count") or 0),
            "replay_primary_person_count": int(framing.get("primary_person_count") or 0),
            "replay_orientation": str(framing.get("orientation") or "unknown"),
            "replay_zoom": float(framing.get("zoom") or 1.0),
            "replay_source_width": int(framing.get("source_width") or 0),
            "replay_source_height": int(framing.get("source_height") or 0),
            "replay_focus_x": float(framing.get("focus_x") or framing.get("position_x") or 50.0),
            "replay_focus_y": float(framing.get("focus_y") or framing.get("position_y") or 50.0),
            "replay_source_ratio": float(framing.get("source_ratio") or 1.0),
            "has_voice": bool(voice_path),
            "voice_url": str(voice_signed_map.get(voice_path) or ""),
            "voice_transcript": str(snap.get("voice_transcript") or ""),
            "voice_duration_ms": _voice_duration_value_ms_v469(snap),
        })
    return items


def _monthly_family_share_payload(month_key, period_label, bundle, previous_share=None):
    previous_share = previous_share if isinstance(previous_share, dict) else {}
    now_value = now_jst().isoformat()
    return {
        "version": 2,
        "shared": True,
        "month_key": str(month_key or ""),
        "period_label": str(period_label or format_month_label(month_key)),
        "shared_by_member_key": current_member_key(),
        "shared_by_member_name": current_member_name(),
        "shared_at": str(previous_share.get("shared_at") or now_value),
        "updated_at": now_value,
        "photos": build_monthly_family_share_photo_snapshot(bundle),
    }


def set_monthly_family_share(month_key, period_label, bundle, review, enabled=True):
    if not MOVIE_SHARING_ENABLED_V468:
        raise ValueError("Movie sharing is disabled; saved movies are retained.")
    updated = dict(review or {})
    if enabled:
        previous = monthly_family_share_info(updated)
        payload = _monthly_family_share_payload(month_key, period_label, bundle, previous_share=previous)
        if not payload.get("photos"):
            raise ValueError("家族に共有できる写真がありません。")
        updated["_family_share"] = payload
    else:
        updated.pop("_family_share", None)
    save_monthly_review(month_key, updated)
    st.session_state[f"monthly_review_{month_key}"] = updated
    return updated


def carry_monthly_family_share(refreshed_review, previous_review, month_key, period_label, bundle):
    refreshed = dict(refreshed_review or {})
    previous = monthly_family_share_info(previous_review)
    if previous.get("shared"):
        refreshed["_family_share"] = _monthly_family_share_payload(
            month_key,
            period_label,
            bundle,
            previous_share=previous,
        )
    return refreshed


def _coerce_review_json(value):
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return dict(parsed) if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    return {}


@st.cache_resource(show_spinner=False)
def _movie_share_runtime_v555():
    """Process-wide recipient lookup/media-prep cache. Nothing starts at app startup."""
    return {
        "lock": threading.RLock(),
        # One bounded worker keeps family-share preparation from competing with UI work.
        "io": ThreadPoolExecutor(max_workers=1, thread_name_prefix="burari-movie-share"),
        "states": {},
    }


def _movie_share_owner_v555():
    return (str(SUPABASE_URL), current_family_key(), current_member_key())


def _movie_share_state_v555(runtime, owner):
    with runtime["lock"]:
        state = runtime["states"].get(owner)
        if state is None:
            state = {
                "rows": [],
                "future": None,
                "fetched_at": 0.0,
                "error": "",
                "started_at": 0.0,
                "metadata_ready": False,
                "media_total": 0,
                "media_ready": 0,
                "media_failed": 0,
                # Keep prepared payloads across Review re-entry when the share version did not change.
                "prepared_cache": {},
            }
            runtime["states"][owner] = state
        if len(runtime["states"]) > 24:
            for key in list(runtime["states"]):
                if len(runtime["states"]) <= 20:
                    break
                item = runtime["states"].get(key) or {}
                future = item.get("future")
                if key != owner and (future is None or future.done()):
                    runtime["states"].pop(key, None)
        return state


def _fetch_family_shared_movies_worker_v555(owner, limit=120):
    """Fetch only metadata for movies explicitly shared by other family members."""
    _url, family_key, member_key = owner
    if not (SUPABASE_URL and SUPABASE_SECRET_KEY and family_key):
        return []
    from supabase import create_client
    client = create_client(SUPABASE_URL, SUPABASE_SECRET_KEY)
    requested = max(1, min(240, int(limit or 120)))
    scan_limit = max(240, min(900, requested * 6))
    result = (
        client.table(MONTHLY_TABLE)
        .select("id,member_key,review_month,review_json,created_at,updated_at")
        .eq("family_key", family_key)
        .order("updated_at", desc=True)
        .limit(scan_limit)
        .execute()
    )
    movies = []
    for row in result.data or []:
        if not isinstance(row, dict):
            continue
        owner_member_key = str(row.get("member_key") or "").strip()
        if not owner_member_key or owner_member_key == member_key:
            continue
        review = _coerce_review_json(row.get("review_json"))
        if not review:
            continue
        if str(review.get("_record_type") or "").strip().lower() in {"music_library", "video_moment_factor_settings"}:
            continue
        share = monthly_family_share_info(review)
        if not bool(share.get("shared")):
            continue
        playback = get_monthly_playback(review)
        if not monthly_playback_is_ready(playback):
            continue
        scope_type = str(review.get("_review_scope_type") or "").strip().lower()
        is_tag = scope_type in {"tag", "ai_tag"}
        if is_tag and not bool(review.get("_tag_movie_saved")):
            continue
        month_key = str(row.get("review_month") or "")[:7]
        period_label = str(share.get("period_label") or "").strip()
        if not period_label:
            period_label = _owned_replay_movie_period_label(review, month_key)
        member_name = str(share.get("shared_by_member_name") or owner_member_key).strip() or owner_member_key
        shared_at = str(share.get("updated_at") or share.get("shared_at") or row.get("updated_at") or "").strip()
        photo_count = len([x for x in (share.get("photos") or []) if isinstance(x, dict)])
        movies.append({
            "id": str(row.get("id") or ""),
            "month_key": month_key,
            "period_label": period_label or "振り返りムービー",
            "movie_type": "タグ別" if is_tag else "月別",
            "photo_count": photo_count,
            "received": True,
            "shared": True,
            "source_member_key": owner_member_key,
            "source_member_name": member_name,
            "shared_at": shared_at,
            "saved_at": shared_at,
            "updated_at": str(row.get("updated_at") or ""),
            "playback": playback,
            "review": review,
            "share": share,
            "_media_ready_v556": False,
        })
        if len(movies) >= requested:
            break
    movies.sort(
        key=lambda item: (
            _shared_movie_time_value(item.get("shared_at") or item.get("updated_at")),
            str(item.get("id") or ""),
        ),
        reverse=True,
    )
    return movies[:requested]


def _shared_movie_prepare_key_v556(item):
    item = item if isinstance(item, dict) else {}
    share = item.get("share") if isinstance(item.get("share"), dict) else {}
    stamp = str(share.get("updated_at") or share.get("shared_at") or item.get("updated_at") or "")
    raw = "|".join([
        str(item.get("id") or ""),
        str(item.get("source_member_key") or ""),
        stamp,
        str(len([x for x in (share.get("photos") or []) if isinstance(x, dict)])),
    ])
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:32]


def _sign_shared_media_urls_v556(client, storage_paths, expires_in=1800):
    paths = tuple(dict.fromkeys(str(x or "").strip() for x in (storage_paths or ()) if str(x or "").strip()))
    if not paths:
        return {}
    bucket = client.storage.from_(PHOTO_BUCKET)
    result = {}
    try:
        if hasattr(bucket, "create_signed_urls"):
            response = bucket.create_signed_urls(list(paths), int(expires_in))
            rows = response
            if isinstance(response, dict):
                rows = response.get("data") or response.get("signedURLs") or response.get("signed_urls") or []
            elif hasattr(response, "data"):
                rows = getattr(response, "data") or []
            if isinstance(rows, list):
                for idx, row in enumerate(rows):
                    path = ""
                    if isinstance(row, dict):
                        path = str(row.get("path") or row.get("name") or "").strip()
                    if not path and idx < len(paths):
                        path = paths[idx]
                    url = _signed_url_from_value(row)
                    if path and url:
                        result[path] = url
    except Exception:
        result = {}
    for path in paths:
        if path in result:
            continue
        try:
            url = _signed_url_from_value(bucket.create_signed_url(path, int(expires_in)))
            if url:
                result[path] = url
        except Exception:
            pass
    return result


def _prepare_family_shared_movie_media_worker_v556(owner, item):
    """Prepare everything the shared replay player needs without touching Streamlit/session state."""
    _url, family_key, _viewer_member_key = owner
    item = dict(item or {})
    share = item.get("share") if isinstance(item.get("share"), dict) else {}
    snapshots = [dict(x) for x in (share.get("photos") or []) if isinstance(x, dict)]
    if not snapshots:
        return []

    from supabase import create_client
    client = create_client(SUPABASE_URL, SUPABASE_SECRET_KEY)
    paths = [str(x.get("storage_path") or "").strip() for x in snapshots]
    paths = [x for x in paths if x]
    voice_paths = [str(x.get("voice_storage_path") or "").strip() for x in snapshots]
    voice_paths = [x for x in voice_paths if x]
    combined = tuple(dict.fromkeys(paths + voice_paths))
    signed_all = _sign_shared_media_urls_v556(client, combined, expires_in=1800)

    current_photo_by_path = {}
    source_member_key = str(item.get("source_member_key") or share.get("shared_by_member_key") or "").strip()
    if source_member_key and paths:
        try:
            rows = []
            for offset in range(0, len(paths), 100):
                chunk = paths[offset:offset + 100]
                batch = (
                    client.table(PHOTO_TABLE)
                    .select("id,storage_path,reflection_json")
                    .in_("storage_path", chunk)
                    .eq("family_key", family_key)
                    .eq("member_key", source_member_key)
                    .execute()
                ).data or []
                rows.extend(x for x in batch if isinstance(x, dict))
            current_photo_by_path = {
                str(row.get("storage_path") or "").strip(): row
                for row in rows
                if str(row.get("storage_path") or "").strip()
            }
        except Exception:
            current_photo_by_path = {}

    items = []
    for snap in snapshots:
        path = str(snap.get("storage_path") or "").strip()
        if not path:
            continue
        url = str(signed_all.get(path) or "")
        if not url:
            # Rare fallback is still background work. It never blocks the Play action.
            try:
                raw = client.storage.from_(PHOTO_BUCKET).download(path)
                if raw:
                    url = "data:image/jpeg;base64," + base64.b64encode(raw).decode("ascii")
            except Exception:
                url = ""
        if not url:
            continue
        current_photo = current_photo_by_path.get(path)
        current_emotion = photo_selected_tag_meta(current_photo) if isinstance(current_photo, dict) else {}
        voice_path = str(snap.get("voice_storage_path") or "").strip()
        items.append({
            "url": url,
            "caption": str(snap.get("caption") or ""),
            "emotion": str(current_emotion.get("key") if current_emotion else snap.get("emotion") or ""),
            "emotion_label": str(current_emotion.get("label") if current_emotion else snap.get("emotion_label") or ""),
            "emotion_emoji": str(current_emotion.get("emoji") if current_emotion else snap.get("emotion_emoji") or ""),
            "emotion_color": str(current_emotion.get("color") if current_emotion else snap.get("emotion_color") or ""),
            # Shared snapshots already persist replay framing. Reusing it avoids expensive
            # image-analysis/download work in the family-share background pipeline.
            "replay_fit": str(snap.get("replay_fit") or "cover"),
            "replay_position_x": float(snap.get("replay_position_x") or 50.0),
            "replay_position_y": float(snap.get("replay_position_y") or 50.0),
            "replay_use_backdrop": bool(snap.get("replay_use_backdrop") or False),
            "replay_person_count": int(snap.get("replay_person_count") or 0),
            "replay_primary_person_count": int(snap.get("replay_primary_person_count") or 0),
            "replay_orientation": str(snap.get("replay_orientation") or "unknown"),
            "replay_zoom": float(snap.get("replay_zoom") or 1.0),
            "replay_source_width": int(snap.get("replay_source_width") or 0),
            "replay_source_height": int(snap.get("replay_source_height") or 0),
            "replay_focus_x": float(snap.get("replay_focus_x") or snap.get("replay_position_x") or 50.0),
            "replay_focus_y": float(snap.get("replay_focus_y") or snap.get("replay_position_y") or 50.0),
            "replay_source_ratio": float(snap.get("replay_source_ratio") or 1.0),
            "has_voice": bool(voice_path),
            "voice_url": str(signed_all.get(voice_path) or ""),
            "voice_transcript": str(snap.get("voice_transcript") or ""),
            "voice_duration_ms": _voice_duration_value_ms_v469(snap),
        })
    return items


def _fetch_and_prefetch_family_shared_movies_worker_v556(owner, limit, runtime, state):
    """Background-only pipeline: metadata first, then replay media preparation newest-first."""
    rows = _fetch_family_shared_movies_worker_v555(owner, limit=limit)
    now = time.monotonic()
    with runtime["lock"]:
        state["rows"] = [dict(x) for x in rows]
        state["fetched_at"] = now
        state["metadata_ready"] = True
        state["media_total"] = len(rows)
        state["media_ready"] = 0
        state["media_failed"] = 0
        state["error"] = ""
        prepared_cache = state.setdefault("prepared_cache", {})

    for index, row in enumerate(rows):
        key = _shared_movie_prepare_key_v556(row)
        prepared = None
        with runtime["lock"]:
            cached = prepared_cache.get(key)
            if isinstance(cached, dict):
                try:
                    if now - float(cached.get("at") or 0.0) < 1200.0 and isinstance(cached.get("items"), list):
                        prepared = list(cached.get("items") or [])
                except Exception:
                    prepared = None
        error = ""
        if prepared is None:
            try:
                prepared = _prepare_family_shared_movie_media_worker_v556(owner, row)
            except Exception as exc:
                prepared = []
                error = f"{type(exc).__name__}: {exc}"
        with runtime["lock"]:
            current_rows = state.get("rows") or []
            if index < len(current_rows) and str(current_rows[index].get("id") or "") == str(row.get("id") or ""):
                current_rows[index]["_prepared_photo_items_v556"] = list(prepared or [])
                current_rows[index]["_media_ready_v556"] = bool(prepared)
                current_rows[index]["_media_error_v556"] = error
                current_rows[index]["_prepare_key_v556"] = key
            if prepared:
                prepared_cache[key] = {"at": time.monotonic(), "items": list(prepared)}
                state["media_ready"] = int(state.get("media_ready") or 0) + 1
            else:
                state["media_failed"] = int(state.get("media_failed") or 0) + 1
            # Bound memory while retaining the newest reusable payloads.
            if len(prepared_cache) > 160:
                oldest = sorted(
                    prepared_cache.items(), key=lambda kv: float((kv[1] or {}).get("at") or 0.0)
                )[: len(prepared_cache) - 140]
                for old_key, _old_value in oldest:
                    prepared_cache.pop(old_key, None)
    with runtime["lock"]:
        return {
            "rows": [dict(x) for x in (state.get("rows") or [])],
            "media_total": int(state.get("media_total") or 0),
            "media_ready": int(state.get("media_ready") or 0),
            "media_failed": int(state.get("media_failed") or 0),
        }


def _harvest_family_shared_movie_future_v555(runtime, state):
    """Consume a finished family-share pipeline Future without blocking the UI thread."""
    with runtime["lock"]:
        future = state.get("future")
    if future is None or not future.done():
        return False
    try:
        payload = future.result(timeout=0)
        error = ""
    except Exception as exc:
        payload = None
        error = f"{type(exc).__name__}: {exc}"
    with runtime["lock"]:
        if state.get("future") is future:
            state["future"] = None
            if isinstance(payload, dict) and isinstance(payload.get("rows"), list):
                state["rows"] = [dict(x) for x in payload.get("rows") or []]
                state["fetched_at"] = time.monotonic()
                state["media_total"] = int(payload.get("media_total") or len(state["rows"]))
                state["media_ready"] = int(payload.get("media_ready") or 0)
                state["media_failed"] = int(payload.get("media_failed") or 0)
            elif isinstance(payload, list):
                state["rows"] = list(payload)
                state["fetched_at"] = time.monotonic()
            state["error"] = error
    return True


def start_family_shared_movie_lookup_v555(force=False, limit=120):
    """Start metadata + media preparation in the background and return immediately."""
    runtime = _movie_share_runtime_v555()
    owner = _movie_share_owner_v555()
    state = _movie_share_state_v555(runtime, owner)
    _harvest_family_shared_movie_future_v555(runtime, state)
    now = time.monotonic()
    with runtime["lock"]:
        future = state.get("future")
        if future is not None and not future.done():
            return True
        age = now - float(state.get("fetched_at") or 0.0)
        # Reuse prepared signed URLs for a short Review session; entering Review explicitly
        # with force=True still performs a fresh share check.
        if not force and state.get("fetched_at") and 0.0 <= age < 300.0:
            return False
        state["error"] = ""
        state["started_at"] = now
        state["metadata_ready"] = False
        state["media_total"] = 0
        state["media_ready"] = 0
        state["media_failed"] = 0
        state["future"] = runtime["io"].submit(
            _fetch_and_prefetch_family_shared_movies_worker_v556,
            owner,
            limit,
            runtime,
            state,
        )
        return True


def family_shared_movie_snapshot_v555(start_if_needed=False, limit=120):
    """Return the latest non-blocking snapshot; media preparation remains background-only."""
    runtime = _movie_share_runtime_v555()
    owner = _movie_share_owner_v555()
    state = _movie_share_state_v555(runtime, owner)
    _harvest_family_shared_movie_future_v555(runtime, state)
    if start_if_needed:
        start_family_shared_movie_lookup_v555(force=False, limit=limit)
        _harvest_family_shared_movie_future_v555(runtime, state)
    with runtime["lock"]:
        future = state.get("future")
        return [dict(x) for x in (state.get("rows") or [])], bool(future is not None and not future.done()), str(state.get("error") or "")


def family_shared_movie_progress_v556():
    runtime = _movie_share_runtime_v555()
    owner = _movie_share_owner_v555()
    state = _movie_share_state_v555(runtime, owner)
    _harvest_family_shared_movie_future_v555(runtime, state)
    with runtime["lock"]:
        return {
            "metadata_ready": bool(state.get("metadata_ready")),
            "total": int(state.get("media_total") or 0),
            "ready": int(state.get("media_ready") or 0),
            "failed": int(state.get("media_failed") or 0),
            "pending": bool(state.get("future") is not None and not state.get("future").done()),
        }


def list_family_shared_monthly_reviews(limit=24):
    """Compatibility helper: non-blocking snapshot only; never starts a Home/startup query."""
    rows, _pending, _error = family_shared_movie_snapshot_v555(start_if_needed=False, limit=limit)
    return rows[:max(1, int(limit or 24))]


def _owned_replay_movie_period_label(review, month_key):
    review = review if isinstance(review, dict) else {}
    scope_type = str(review.get("_review_scope_type") or "").strip().lower()
    if scope_type in {"tag", "ai_tag"}:
        label = str(review.get("_scope_label") or review.get("_tag_label") or "").strip()
        if label:
            return label
        tags = _normalize_tag_review_selection(review.get("_ai_tag_keys") or [])
        if tags:
            mode = str(review.get("_ai_tag_match_mode") or "any").lower()
            return tag_review_scope_label(tags, mode)
        return "タグ別の振り返り"
    return format_month_label(month_key) if month_key else "月別の振り返り"


def list_own_replay_movies(limit=120):
    """Return all saved/created replay movies for the signed-in personal account.

    Monthly movies are rows with a persisted playback window. AI-tag movies are shown
    only after the user has explicitly saved the dynamic movie. Drafts and settings
    records are intentionally excluded.
    """
    cache_key = _account_cache_key("own_movies_v468", int(limit))
    cached = _session_cache_get(cache_key, max_age_seconds=90)
    if cached is not None:
        return cached
    requested = max(1, min(300, int(limit or 120)))
    result = (
        supabase_client()
        .table(MONTHLY_TABLE)
        .select("id,review_month,review_json,created_at,updated_at")
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .order("updated_at", desc=True)
        .limit(max(180, requested * 4))
        .execute()
    )
    rows = result.data or []
    movies = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        review = _coerce_review_json(row.get("review_json"))
        if not review:
            continue
        record_type = str(review.get("_record_type") or "").strip().lower()
        if record_type in {"music_library", "video_moment_factor_settings"}:
            continue

        playback = get_monthly_playback(review)
        if not monthly_playback_is_ready(playback):
            continue

        month_key = str(row.get("review_month") or "")[:7]
        scope_type = str(review.get("_review_scope_type") or "").strip().lower()
        is_tag = scope_type in {"tag", "ai_tag"}
        if is_tag and not bool(review.get("_tag_movie_saved")):
            continue

        share = monthly_family_share_info(review)
        shared = bool(share.get("shared"))
        period_label = _owned_replay_movie_period_label(review, month_key)
        photo_count = 0
        if is_tag:
            try:
                photo_count = max(0, int(review.get("_tag_movie_photo_count") or 0))
            except Exception:
                photo_count = 0
        if not photo_count and shared:
            photo_count = len([x for x in (share.get("photos") or []) if isinstance(x, dict)])

        movies.append({
            "id": str(row.get("id") or ""),
            "month_key": month_key,
            "period_label": period_label or "振り返りムービー",
            "movie_type": "タグ別" if is_tag else "月別",
            "photo_count": photo_count,
            "shared": shared,
            "shared_at": str(share.get("shared_at") or ""),
            "saved_at": str(review.get("_tag_movie_saved_at") or row.get("updated_at") or row.get("created_at") or ""),
            "updated_at": str(row.get("updated_at") or ""),
            "playback": playback,
            "review": review,
            "share": share,
        })

    movies.sort(
        key=lambda item: (
            _shared_movie_time_value(item.get("saved_at") or item.get("updated_at")),
            str(item.get("id") or ""),
        ),
        reverse=True,
    )
    return _session_cache_set(cache_key, movies[:requested])


def _bundle_from_owned_photo_ids(photo_ids):
    """Rebuild a saved movie bundle from owned photo ids without rerunning AI tagging."""
    ordered_ids = []
    seen = set()
    for value in photo_ids or []:
        photo_id = str(value or "").strip()
        if photo_id and photo_id not in seen:
            seen.add(photo_id)
            ordered_ids.append(photo_id)
    if not ordered_ids:
        return {"trips": [], "diaries": [], "photos": []}

    client = supabase_client()
    rows = []
    for offset in range(0, len(ordered_ids), 100):
        chunk = ordered_ids[offset:offset + 100]
        batch = (
            client.table(PHOTO_TABLE)
            .select("id,trip_id,storage_path,captured_at,reflection_json,signals_json")
            .eq("family_key", current_family_key())
            .eq("member_key", current_member_key())
            .in_("id", chunk)
            .execute()
        ).data or []
        rows.extend(row for row in batch if isinstance(row, dict))

    by_id = {str(row.get("id") or ""): row for row in rows}
    photos = [by_id[photo_id] for photo_id in ordered_ids if photo_id in by_id]
    trip_ids = []
    trip_seen = set()
    for photo in photos:
        trip_id = str(photo.get("trip_id") or "").strip()
        if trip_id and trip_id not in trip_seen:
            trip_seen.add(trip_id)
            trip_ids.append(trip_id)

    trips = []
    for offset in range(0, len(trip_ids), 100):
        chunk = trip_ids[offset:offset + 100]
        if not chunk:
            continue
        batch = (
            client.table(TRIP_TABLE)
            .select("*")
            .eq("family_key", current_family_key())
            .eq("member_key", current_member_key())
            .in_("id", chunk)
            .execute()
        ).data or []
        trips.extend(row for row in batch if isinstance(row, dict))
    return {"trips": trips, "diaries": [], "photos": photos}


def _owned_replay_movie_bundle(month_key, review):
    """Load the photo bundle used when toggling family sharing from the movie library."""
    review = review if isinstance(review, dict) else {}
    scope_type = str(review.get("_review_scope_type") or "").strip().lower()
    if scope_type in {"tag", "ai_tag"}:
        tags = _normalize_tag_review_selection(review.get("_ai_tag_keys") or [])
        if not tags:
            raise ValueError("このタグ別ムービーの写真条件を確認できませんでした。")
        match_mode = str(review.get("_ai_tag_match_mode") or "any").lower()
        source = get_tag_review_source()
        bundle = tag_review_bundle(source, tags, match_mode)
        return tag_movie_bundle_from_snapshot(bundle, review)

    if not month_key:
        raise ValueError("この月別ムービーの対象月を確認できませんでした。")
    return get_month_bundle(month_key)


def _invalidate_family_shared_movie_runtime_v557(family_key=None):
    """Drop recipient-side family-share snapshots after a verified share/unshare write.

    Running background futures are intentionally not joined or cancelled. Their state object is
    detached from the runtime map, so a later Review entry creates a fresh state and performs a
    fresh lookup instead of reusing stale metadata.
    """
    target_family = str(family_key or current_family_key() or "default").strip() or "default"
    try:
        runtime = _movie_share_runtime_v555()
        with runtime["lock"]:
            states = runtime.get("states") or {}
            for owner in list(states.keys()):
                try:
                    owner_family = str(owner[1] or "").strip()
                except Exception:
                    owner_family = ""
                if owner_family == target_family:
                    states.pop(owner, None)
    except Exception:
        pass


def _read_owned_replay_movie_review_v557(client, row_id):
    result = (
        client.table(MONTHLY_TABLE)
        .select("id,review_month,review_json,updated_at")
        .eq("id", str(row_id or "").strip())
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .limit(1)
        .execute()
    )
    row = (result.data or [None])[0]
    if not isinstance(row, dict) or not row.get("id"):
        raise ValueError("対象のムービーが見つかりませんでした。")
    return row, _coerce_review_json(row.get("review_json"))


def _verify_owned_replay_movie_share_v559(client, row_id, enabled, expected_write_token=""):
    """Read back the exact persisted write; stale pre-existing share state is not accepted."""
    expected_write_token = str(expected_write_token or "").strip()
    for attempt in range(4):
        row, review = _read_owned_replay_movie_review_v557(client, row_id)
        share = monthly_family_share_info(review)
        if enabled:
            photos = [x for x in (share.get("photos") or []) if isinstance(x, dict)]
            sender_key = str(share.get("shared_by_member_key") or "").strip()
            persisted_token = str(share.get("_write_token_v559") or "").strip()
            if (
                bool(share.get("shared"))
                and sender_key == current_member_key()
                and bool(photos)
                and expected_write_token
                and persisted_token == expected_write_token
            ):
                return row, review
        else:
            if not share or not bool(share.get("shared")):
                return row, review
        if attempt < 3:
            time.sleep(0.12 * (attempt + 1))
    if enabled:
        raise RuntimeError("共有情報を保存後に再取得しましたが、今回の共有書き込みを確認できませんでした。")
    raise RuntimeError("共有解除を保存後に再取得しましたが、解除済み状態を確認できませんでした。")


def set_owned_replay_movie_share(row_id, enabled=True):
    """Toggle family sharing and verify the persisted Supabase state before returning.

    This path is used only after the user explicitly taps Share/Unshare in Review. A successful
    return therefore means the DB row was written and read back with the requested state.
    """
    if not MOVIE_SHARING_ENABLED_V468:
        raise ValueError("Movie sharing is disabled; saved movies are retained.")
    row_id = str(row_id or "").strip()
    if not row_id:
        raise ValueError("共有設定を変更するムービーを確認できませんでした。")

    client = supabase_client()
    row, review = _read_owned_replay_movie_review_v557(client, row_id)
    month_key = str(row.get("review_month") or "")[:7]
    playback = get_monthly_playback(review)
    if not monthly_playback_is_ready(playback):
        raise ValueError("保存済みのムービー設定を確認できませんでした。")

    if enabled:
        if str(review.get("_review_scope_type") or "").strip().lower() in {"tag", "ai_tag"} and not bool(review.get("_tag_movie_saved")):
            raise ValueError("このタグ別ムービーはまだ保存されていません。")
        bundle = _owned_replay_movie_bundle(month_key, review)
        period_label = _owned_replay_movie_period_label(review, month_key)
        previous = monthly_family_share_info(review)
        payload = _monthly_family_share_payload(month_key, period_label, bundle, previous_share=previous)
        photos = [x for x in (payload.get("photos") or []) if isinstance(x, dict)]
        if not photos:
            raise ValueError("家族に共有できる写真がありません。")
        payload["shared"] = True
        payload["shared_by_member_key"] = current_member_key()
        payload["shared_by_member_name"] = current_member_name()
        expected_write_token = uuid.uuid4().hex
        payload["_write_token_v559"] = expected_write_token
        review["_family_share"] = payload
    else:
        expected_write_token = ""
        review.pop("_family_share", None)

    now_value = now_jst().isoformat()
    update_result = (
        client.table(MONTHLY_TABLE)
        .update({"review_json": review, "updated_at": now_value})
        .eq("id", row_id)
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .execute()
    )
    # Some Supabase client versions return an empty data list for UPDATE even when the write
    # succeeds. Do not infer success from the response body; always verify with a fresh SELECT.
    _ = update_result
    verified_row, verified_review = _verify_owned_replay_movie_share_v559(
        client, row_id, bool(enabled), expected_write_token=expected_write_token
    )

    if month_key:
        st.session_state[f"monthly_review_{month_key}"] = dict(verified_review)
    st.session_state.pop("_home_shared_movie_check_v341", None)
    _invalidate_fast_db_cache()
    _invalidate_family_shared_movie_runtime_v557(current_family_key())
    return verified_review


def unshare_owned_replay_movie(row_id):
    """Backward-compatible helper retained for existing callers."""
    return set_owned_replay_movie_share(row_id, enabled=False)


def _shared_movie_list_time_label(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=ZoneInfo(APP_TIMEZONE))
        return parsed.astimezone(ZoneInfo(APP_TIMEZONE)).strftime("%Y/%m/%d %H:%M")
    except Exception:
        return raw.replace("T", " ")[:16]


def open_owned_replay_movie_from_library(item, edit=False):
    """Open one saved movie for playback, or open its music editor when edit=True."""
    item = item if isinstance(item, dict) else {}
    month_key = str(item.get("month_key") or "").strip()[:7]
    review = dict(item.get("review") or {}) if isinstance(item.get("review"), dict) else {}
    if not month_key or not review:
        raise ValueError("開くムービーの情報を確認できませんでした。")

    st.session_state[f"monthly_review_{month_key}"] = review
    if edit:
        st.session_state[f"monthly_music_settings_open_{month_key}"] = True
        st.session_state[f"_music_settings_focus_v471_{month_key}"] = uuid.uuid4().hex
        st.session_state.pop(f"monthly_time_settings_open_{month_key}", None)
    scope_type = str(review.get("_review_scope_type") or "").strip().lower()
    if scope_type in {"tag", "ai_tag"}:
        tags = _normalize_tag_review_selection(review.get("_ai_tag_keys") or [])
        if not tags:
            fallback_tag = normalize_ai_photo_tag(review.get("_tag_label") or review.get("_ai_tag_key") or "")
            if fallback_tag:
                tags = [fallback_tag]
        if not tags:
            raise ValueError("このタグ別ムービーのタグ条件を確認できませんでした。")
        mode = str(review.get("_ai_tag_match_mode") or "any").lower()
        if mode not in {"any", "all"} or len(tags) <= 1:
            mode = "any"
        st.session_state["_ai_tag_review_active_tags_v330"] = list(tags)
        st.session_state["_ai_tag_review_match_mode_v330"] = mode
        _set_page_state("review_tag", history_mode="push")
        return

    st.session_state["monthly_selector"] = month_key
    _set_page_state("review_monthly", history_mode="push")


def delete_owned_replay_movie(row_id):
    """Delete only the saved replay association; keep source photos/diaries/AI review."""
    row_id = str(row_id or "").strip()
    if not row_id:
        raise ValueError("削除するムービーを確認できませんでした。")

    client = supabase_client()
    result = (
        client.table(MONTHLY_TABLE)
        .select("id,review_month,review_json")
        .eq("id", row_id)
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .limit(1)
        .execute()
    )
    row = (result.data or [None])[0]
    if not isinstance(row, dict) or not row.get("id"):
        raise ValueError("削除するムービーが見つかりませんでした。")

    month_key = str(row.get("review_month") or "")[:7]
    review = _coerce_review_json(row.get("review_json"))
    scope_type = str(review.get("_review_scope_type") or "").strip().lower()

    # A movie shared with family must stop being visible to recipients when deleted.
    review.pop("_family_share", None)
    review.pop("_playback", None)
    if scope_type in {"tag", "ai_tag"}:
        review.pop("_tag_movie_photo_ids", None)
        review.pop("_tag_movie_membership_mode", None)
        review.pop("_tag_movie_membership_updated_at", None)
        review.pop("_tag_movie_saved_at", None)
        review["_tag_movie_saved"] = False
        review["_tag_movie_draft"] = False

    now_value = now_jst().isoformat()
    (
        client.table(MONTHLY_TABLE)
        .update({"review_json": review, "updated_at": now_value})
        .eq("id", row_id)
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .execute()
    )

    if month_key:
        st.session_state[f"monthly_review_{month_key}"] = review
        discard_monthly_preview_playback(month_key)
        try:
            clear_replay_photo_curation(month_key)
        except Exception:
            pass
        state = _monthly_replay_state(month_key, review)
        for state_key in (
            state.get("url_key"),
            state.get("start_key"),
            state.get("end_key"),
            state.get("reason_key"),
            state.get("confidence_key"),
            state.get("title_key"),
            f"monthly_replay_applied_{month_key}",
            f"monthly_music_settings_open_{month_key}",
            f"monthly_time_settings_open_{month_key}",
        ):
            if state_key:
                st.session_state.pop(state_key, None)
    st.session_state.pop("_home_shared_movie_check_v341", None)
    _invalidate_fast_db_cache()
    return review


