def render_pending_video_ai_review():
    """Review AI picks before the recorded video is persisted."""
    pending = st.session_state.get("_pending_video_ai_review")
    if not isinstance(pending, dict):
        return False
    selections = list(pending.get("selections") or [])[:VIDEO_AI_MAX_SELECTIONS]
    if len(selections) < VIDEO_AI_MAX_SELECTIONS or not pending.get("video_raw") or not pending.get("poster_raw"):
        st.session_state.pop("_pending_video_ai_review", None)
        return False

    st.markdown("### 撮影した動画")
    st.caption("AIセレクションを確認中です。まだこの動画は保存されていません。")
    st.video(pending["video_raw"], format=str(pending.get("mime_type") or "video/webm"))

    save_col, retry_col = st.columns([3, 1], gap="small")
    with save_col:
        save_video_clicked = st.button(
            "この動画を残す",
            type="primary",
            use_container_width=True,
            key="pending_ai_video_save",
        )
    with retry_col:
        retry_video_clicked = st.button(
            "撮り直す",
            use_container_width=True,
            key="pending_ai_video_retry",
        )

    if retry_video_clicked:
        st.session_state.pop("_pending_video_ai_review", None)
        st.session_state.pop("_pending_video_ai_review_digest", None)
        st.session_state.capture_serial += 1
        st.session_state["_camera_auto_start_video"] = True
        st.rerun()

    if save_video_clicked:
        try:
            trip = ensure_today_trip()
            capture_source = str(pending.get("source") or "video_camera")
            location = build_photo_location(
                pending.get("location"),
                trip,
                capture_source=capture_source,
            )
            with st.spinner("動画を残しています…"):
                saved_video = upload_video(
                    trip["id"],
                    pending["video_raw"],
                    pending["poster_raw"],
                    mime_type=pending.get("mime_type"),
                    duration_ms=pending.get("duration_ms"),
                    location=location,
                    captured_at=pending.get("captured_at"),
                    capture_source=capture_source,
                )

            ai_selection_ok = False
            if isinstance(saved_video, dict) and saved_video.get("id"):
                try:
                    with st.spinner(f"選んだ{VIDEO_AI_MAX_SELECTIONS}枚を保存しています…"):
                        saved_video = store_preselected_video_ai_selection(
                            saved_video,
                            selections,
                            candidate_count=pending.get("candidate_count"),
                        )
                    ai_selection_ok = True
                except Exception as selection_exc:
                    mark_video_ai_selection_error(saved_video, selection_exc)

            if isinstance(saved_video, dict) and saved_video.get("id"):
                st.session_state[f"_camera_recent_photo_{trip['id']}"] = saved_video["id"]

            previous_count = st.session_state.get("_home_today_photo_count")
            try:
                previous_count = int(previous_count) if previous_count is not None else 0
            except Exception:
                previous_count = 0
            st.session_state["_home_today_photo_count"] = previous_count + 1
            place_label = str((location or {}).get("place_label") or trip.get("destination") or "").strip()
            if place_label:
                st.session_state["_home_today_place"] = place_label

            st.session_state.pop("_pending_video_ai_review", None)
            st.session_state.pop("_pending_video_ai_review_digest", None)
            st.session_state.capture_serial += 1
            st.session_state["_camera_notice"] = (
                f"動画を保存し、AIセレクション{VIDEO_AI_MAX_SELECTIONS}枚も保存しました。"
                if ai_selection_ok else
                "動画を保存しました。AIセレクションの保存には失敗しました。"
            )
            st.rerun()
        except Exception as exc:
            st.error("動画を保存できませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    st.markdown("##### AIが選んだセレクション")
    columns = st.columns(3, gap="small")
    for index, selected in enumerate(selections):
        rank = index + 1
        frame = selected.get("frame") or {}
        image_bytes = frame.get("image_bytes")
        timestamp_ms = max(0, int(frame.get("timestamp_ms") or 0))
        quality = _video_selection_quality_label(selected.get("primary_quality"))
        reason = str(selected.get("reason") or "").strip()
        caption = f"{timestamp_ms / 1000:.1f}秒・{quality}"
        if reason:
            caption += f"\n{reason}"
        best_label = "★ BEST" if rank == 1 else f"SELECT {rank}"
        with columns[index % 3]:
            if image_bytes:
                data_url = "data:image/jpeg;base64," + base64.b64encode(image_bytes).decode("ascii")
                st.markdown(
                    '<div style="width:100%;aspect-ratio:1/1;overflow:hidden;border-radius:12px;background:rgba(128,128,128,.08);">'
                    f'<img src="{data_url}" alt="AIセレクション {rank}" style="display:block;width:100%;height:100%;object-fit:cover;" />'
                    '</div>',
                    unsafe_allow_html=True,
                )
            else:
                st.caption("画像を表示できません")
            if rank == 1:
                st.markdown("**★ AI BEST**")
            st.caption(caption)
            if st.button(
                "大きく見る",
                use_container_width=True,
                key=f"pending_ai_video_view_{rank}",
            ):
                show_pending_video_ai_selection_dialog(image_bytes, best_label, caption)

    return True


def trip_label(trip):
    """Label a diary candidate, including a custom saved title when present."""
    trip = trip or {}
    trip_id = trip.get("id")
    photos = []
    diary = None
    if trip_id:
        try:
            photos = list_trip_photos(trip_id)
        except Exception:
            photos = []
        try:
            diary = get_diary_for_trip(trip_id)
        except Exception:
            diary = None
    title = diary_display_title(diary, trip, photos=photos)
    return f"{trip.get('trip_date', '')}　{title}"


def render_pending_thumbnail_grid(trip_id, photos, max_count=None, trip=None):
    """Three-across pending still-photo thumbnails."""
    subset = diary_photos_only(photos)
    if max_count is not None:
        subset = subset[: max(0, int(max_count))]
    if not subset:
        return None

    paths = tuple(str(photo.get("storage_path") or "") for photo in subset if photo.get("storage_path"))
    signed = signed_photo_url_map(paths) if paths else {}
    cards = []
    photo_ids = []
    for photo in subset:
        pid = str(photo.get("id") or "")
        if not pid:
            continue
        conversation = _stored_photo_conversation(photo)
        talked = _conversation_has_child_words(conversation)
        src = photo_display_url(photo, signed, max_px=360, quality=74)
        cards.append(
            {
                "id": pid,
                "src": src,
                "talked": bool(talked),
                "emotion": photo_selected_tag_values(photo)[0],
                "parenting": photo_selected_tag_values(photo)[1],
                "location": str(photo_location_label(photo) or ""),
                "shared": photo_family_share_is_enabled(photo),
                "is_video": False,
            }
        )
        photo_ids.append(pid)

    if not cards:
        return None

    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None:
        serial_key = f"pending_gallery_serial_{trip_id}"
        serial = int(st.session_state.get(serial_key) or 0)
        result = gallery_component(
            data={"photos": cards, "allow_share": True, "family_key": current_family_key(), "member_key": current_member_key(), "pending_param": PENDING_EMOTION_QUERY_PARAM},
            key=f"pending_gallery_{trip_id}_{serial}_{_current_ui_refresh_epoch()}",
            on_photo_id_change=lambda: None,
            on_delete_photo_id_change=lambda: None,
            on_share_photo_change=lambda: None,
        )
        if handle_photo_family_share_event(result, photo_ids, serial_key=serial_key):
            return None
        delete_clicked = str(getattr(result, "delete_photo_id", "") or "")
        if delete_clicked in photo_ids:
            st.session_state[serial_key] = serial + 1
            confirm_photo_delete_dialog(
                trip_id,
                delete_clicked,
                photos=subset,
                is_pending=True,
                trip=trip,
            )
            return None

        clicked = str(getattr(result, "photo_id", "") or "")
        if clicked in photo_ids:
            st.session_state[serial_key] = serial + 1
            return clicked
        return None

    # Fallback for old component runtimes. Preserve the same orange/gray meaning and make photos openable.
    cols = st.columns(3)
    for idx, card in enumerate(cards):
        with cols[idx % 3]:
            border = "#F59E0B" if card["talked"] else "#AEB6C2"
            background = "rgba(245,158,11,.18)" if card["talked"] else "rgba(174,182,194,.20)"
            if card["src"]:
                st.markdown(
                    f'<div style="padding:4px;border:3px solid {border};background:{background};border-radius:12px;">'
                    f'<img src="{html.escape(card["src"], quote=True)}" style="display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:8px;" />'
                    '</div>',
                    unsafe_allow_html=True,
                )
            if st.button(
                "写真を開く",
                use_container_width=True,
                key=f"pending_photo_fallback_open_{trip_id}_{card['id']}",
            ):
                return card["id"]
            if st.button(
                "×",
                key=f"pending_photo_fallback_delete_{trip_id}_{card['id']}",
                help="この写真を削除",
            ):
                confirm_photo_delete_dialog(
                    trip_id,
                    card["id"],
                    photos=subset,
                    is_pending=True,
                    trip=trip,
                )
    return None

def render_small_gallery(photos, max_count=None, columns=3):
    """Render history still photos with persisted feeling borders/icons."""
    subset = diary_photos_only(photos)
    if max_count is not None:
        subset = subset[:max_count]
    if not subset:
        return
    column_count = max(1, min(int(columns or 3), 3))
    paths = tuple(str(photo.get("storage_path") or "") for photo in subset if photo.get("storage_path"))
    signed = signed_photo_url_map(paths) if paths else {}
    cards = []
    for photo in subset:
        src = photo_display_url(photo, signed, max_px=520, quality=78)
        if not src:
            continue
        location = str(photo_location_label(photo) or "").strip()
        location_html = (
            f'<div style="font-size:10px;opacity:.65;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">📍 {html.escape(location)}</div>'
            if location else ""
        )
        meta = photo_selected_tag_meta(photo)
        border = meta.get("color") or "#AEB6C2"
        emoji = meta.get("emoji") or ""
        badge = (
            f'<div style="position:absolute;right:7px;bottom:7px;min-width:27px;height:27px;padding:0 4px;border-radius:999px;background:rgba(255,255,255,.90);display:flex;align-items:center;justify-content:center;font-size:19px;box-shadow:0 2px 7px rgba(0,0,0,.22);">{emoji}</div>'
            if emoji else ""
        )
        cards.append(
            f'<div style="min-width:0;"><div style="position:relative;padding:4px;border:3px solid {border};border-radius:12px;">'
            f'<img src="{html.escape(src, quote=True)}" loading="lazy" decoding="async" fetchpriority="low" '
            f'style="display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:8px;" />{badge}</div>{location_html}</div>'
        )
    if cards:
        st.markdown(
            f'<div style="display:grid;grid-template-columns:repeat({column_count},minmax(0,1fr));gap:6px;width:100%;">'
            + "".join(cards) + "</div>",
            unsafe_allow_html=True,
        )

def render_diary_single_photo_voice_editor(trip_id, photo, target_state_key, context_key):
    """Attach or replace one short real voice note from a saved diary single-photo view."""
    photo = photo if isinstance(photo, dict) else {}
    photo_id = str(photo.get("id") or "").strip()
    if not photo_id:
        return

    with st.container(border=True):
        st.markdown("##### 🎙 この写真に声を残す")

        voice_meta = photo_voice_note_meta(photo)
        voice_path = str(voice_meta.get("storage_path") or "").strip()
        if voice_path:
            try:
                signed = signed_photo_url_map((voice_path,), expires_in=1800)
                voice_url = str(signed.get(voice_path) or "")
            except Exception:
                voice_url = ""
            if voice_url:
                st.audio(voice_url)
            transcript = str(voice_meta.get("transcript") or "").strip()
            if transcript:
                st.caption(f"文字起こし: {transcript}")

        audio_file = far_field_audio_input(
            "この写真に声を録音",
            key=f"diary_voice_input_{context_key}_{photo_id}",
        )
        if audio_file is not None:
            try:
                audio_file.seek(0)
                preview = audio_file.read()
                audio_file.seek(0)
            except Exception:
                preview = None
            if preview:
                st.audio(preview)

        left, right = st.columns(2, gap="small")
        with left:
            if st.button(
                "この写真に声を保存",
                key=f"diary_voice_save_{context_key}_{photo_id}",
                type="primary",
                use_container_width=True,
            ):
                if audio_file is None:
                    st.error("先に声を録音してください。")
                else:
                    try:
                        with st.spinner("声を保存しています…"):
                            save_photo_voice_note(photo_id, audio_file, auto_transcribe=True)
                        st.success("この写真に声を保存しました。")
                        st.rerun()
                    except Exception as exc:
                        st.error("声を保存できませんでした。")
                        with st.expander("保護者向け詳細"):
                            st.code(str(exc))
        with right:
            if voice_path:
                if st.button(
                    "保存済みの声を削除",
                    key=f"diary_voice_delete_{context_key}_{photo_id}",
                    use_container_width=True,
                ):
                    try:
                        delete_photo_voice_note(photo_id)
                        st.success("この写真の声を削除しました。")
                        st.rerun()
                    except Exception as exc:
                        st.error("声を削除できませんでした。")
                        with st.expander("保護者向け詳細"):
                            st.code(str(exc))
            else:
                if st.button(
                    "閉じる",
                    key=f"diary_voice_close_{context_key}_{photo_id}",
                    use_container_width=True,
                ):
                    st.session_state.pop(target_state_key, None)
                    st.rerun()

        if voice_path:
            if st.button(
                "声の編集を閉じる",
                key=f"diary_voice_close_existing_{context_key}_{photo_id}",
                use_container_width=True,
            ):
                st.session_state.pop(target_state_key, None)
                st.rerun()


def render_history_photo_viewer(photos, trip_id):
    """Read-only daily diary viewer with grid / one-photo-at-a-time modes."""
    photos = diary_photos_only(photos)
    if not photos:
        return
    if _sync_moments_metadata_into_saved_photos_v417(photos):
        photos = diary_photos_only(list_trip_photos(trip_id))

    # v229: make the display-mode control explicit on each saved daily diary.
    # The existing browser gallery already supports previous/next and swipe in single mode.
    st.markdown("#### この日の写真")
    render_photo_favorite_notice()
    view_mode = "3列一覧"
    if len(photos) >= 1:
        mode_key = f"history_photo_view_mode_{trip_id}"
        if st.session_state.get(mode_key) == "1枚ずつ拡大":
            st.session_state[mode_key] = "1枚ずつ表示"
        view_mode = st.radio(
            "写真の表示方法",
            ["3列一覧", "1枚ずつ表示"],
            index=1 if len(photos) == 1 else 0,
            horizontal=True,
            key=mode_key,
            label_visibility="collapsed",
        )
    single_mode = view_mode == "1枚ずつ表示"

    paths = tuple(str(photo.get("storage_path") or "") for photo in photos if photo.get("storage_path"))
    signed = signed_photo_url_map(paths) if paths else {}
    voice_paths = tuple(photo_voice_note_storage_path(photo) for photo in photos if photo_voice_note_storage_path(photo))
    voice_signed = signed_photo_url_map(voice_paths, expires_in=1800) if voice_paths else {}
    cards = []
    photo_ids = []
    for photo in photos:
        pid = str(photo.get("id") or "")
        if not pid:
            continue
        cards.append(
            {
                "id": pid,
                "src": photo_display_url(photo, signed, max_px=1600 if single_mode else 520, quality=92 if single_mode else 80),
                "emotion": photo_selected_tag_values(photo)[0],
                "parenting": photo_selected_tag_values(photo)[1],
                "location": str(photo_location_label(photo) or ""),
                "tags": photo_ai_tags(photo)[:12],
                "shared": photo_family_share_is_enabled(photo),
                "favorite": photo_favorite_is_enabled(photo),
                "has_voice": bool(photo_voice_note_storage_path(photo)),
                "voice_url": str(voice_signed.get(photo_voice_note_storage_path(photo)) or ""),
                "voice_transcript": str(photo_voice_note_meta(photo).get("transcript") or ""),
            }
        )
        photo_ids.append(pid)

    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None and cards:
        serial_key = f"history_photo_share_serial_{trip_id}"
        serial = int(st.session_state.get(serial_key) or 0)
        result = gallery_component(
            data={
                "photos": cards,
                "single": single_mode,
                "allow_delete": False,
                "allow_emotion": False,
                "allow_share": True,
                "allow_voice": single_mode,
                "allow_voice_preview": single_mode,
                "allow_favorite": single_mode,
                "carousel_key": f"history_{trip_id}",
                "family_key": current_family_key(),
                "member_key": current_member_key(),
                "pending_param": PENDING_EMOTION_QUERY_PARAM,
            },
            key=f"history_photo_fast_v352_{trip_id}_{serial}_{_current_ui_refresh_epoch()}_{'single' if single_mode else 'grid'}",
            on_share_photo_change=lambda: None,
            on_voice_photo_id_change=lambda: None,
            on_favorite_photo_change=lambda: None,
        )
        if handle_photo_family_share_event(result, photo_ids, serial_key=serial_key):
            return
        if handle_photo_favorite_event(result, photo_ids, serial_key=serial_key):
            return
        voice_target_key = f"_history_voice_photo_target_{trip_id}"
        voice_clicked = str(getattr(result, "voice_photo_id", "") or "")
        if single_mode and voice_clicked in photo_ids:
            st.session_state[voice_target_key] = voice_clicked
            st.session_state[serial_key] = serial + 1
        voice_target = str(st.session_state.get(voice_target_key) or "")
        if single_mode and voice_target in photo_ids:
            target_photo = next((photo for photo in photos if str(photo.get("id") or "") == voice_target), None)
            if target_photo:
                render_diary_single_photo_voice_editor(trip_id, target_photo, voice_target_key, f"history_{trip_id}")
        elif not single_mode:
            st.session_state.pop(voice_target_key, None)
        return

    # Old-runtime fallback: keep the same one-photo-at-a-time behavior without the v2 component.
    fallback = photos
    if single_mode:
        index_key = f"history_photo_enlarged_index_{trip_id}"
        try:
            index = int(st.session_state.get(index_key) or 0)
        except Exception:
            index = 0
        index = max(0, min(index, len(photos) - 1))
        st.session_state[index_key] = index
        prev_col, count_col, next_col = st.columns([1, 1.25, 1], gap="small")
        with prev_col:
            if st.button("◀ 前へ", use_container_width=True, disabled=index <= 0, key=f"history_photo_prev_{trip_id}"):
                st.session_state[index_key] = max(0, index - 1)
                st.rerun()
        with count_col:
            st.markdown(f'<div style="text-align:center;padding:.55rem .2rem;font-weight:800;">{index + 1} / {len(photos)}</div>', unsafe_allow_html=True)
        with next_col:
            if st.button("次へ ▶", use_container_width=True, disabled=index >= len(photos) - 1, key=f"history_photo_next_{trip_id}"):
                st.session_state[index_key] = min(len(photos) - 1, index + 1)
                st.rerun()
        fallback = [photos[index]]

    cols = st.columns(1 if single_mode else 3, gap="small")
    for idx, photo in enumerate(fallback):
        with cols[idx % len(cols)]:
            src = photo_display_url(photo, signed, max_px=1600 if single_mode else 420, quality=92 if single_mode else 76)
            if src:
                favorite = photo_favorite_is_enabled(photo)
                star = "★" if favorite else "☆"
                star_color = "#FFD54A" if favorite else "#FFFFFF"
                st.markdown(
                    f'<div style="position:relative;"><img src="{html.escape(src, quote=True)}" style="display:block;width:100%;max-height:70vh;object-fit:contain;border-radius:10px;" />'
                    f'<span style="position:absolute;left:8px;top:8px;font-size:22px;color:{star_color};text-shadow:0 1px 4px rgba(0,0,0,.65);">{star}</span></div>',
                    unsafe_allow_html=True,
                )
            if single_mode:
                _render_rotation_buttons_v616(photo.get("id"), "history_"+str(photo.get("id")))
                favorite = photo_favorite_is_enabled(photo)
                if st.button(
                    "★ お気に入りタグを解除" if favorite else "☆ お気に入りタグに登録",
                    use_container_width=True,
                    key=f"history_photo_favorite_fallback_{trip_id}_{photo.get('id')}",
                ):
                    set_photo_favorite(photo.get("id"), enabled=not favorite)
                    st.session_state["_photo_favorite_notice"] = "★ お気に入りタグに登録しました。" if not favorite else "お気に入りタグを解除しました。"
                    st.rerun()
            shared = photo_family_share_is_enabled(photo)
            if st.button(
                "✓ 家族に共有中（解除）" if shared else "👨‍👩‍👦 家族に共有",
                use_container_width=True,
                key=f"history_photo_share_fallback_{trip_id}_{photo.get('id')}_{'single' if single_mode else 'grid'}",
            ):
                set_photo_family_share(photo.get("id"), enabled=not shared)
                st.session_state["_photo_family_share_notice"] = "この写真と選んだ感情を家族に共有しました。" if not shared else "この写真の家族共有を解除しました。"
                st.rerun()


    if single_mode and fallback:
        voice_target_key = f"_history_voice_photo_target_{trip_id}"
        st.session_state[voice_target_key] = str(fallback[0].get("id") or "")
        render_diary_single_photo_voice_editor(trip_id, fallback[0], voice_target_key, f"history_fallback_{trip_id}")


def render_diary_photo_gallery(trip_id, photos, state=None):
    """Show diary still photos in a three-column clickable grid."""
    photos = diary_photos_only(photos)
    if not photos:
        return None

    st.markdown("#### この日の写真")

    paths = tuple(str(photo.get("storage_path") or "") for photo in photos if photo.get("storage_path"))
    signed = signed_photo_url_map(paths) if paths else {}
    cards = []
    photo_ids = []
    for photo in photos:
        pid = photo.get("id")
        if not pid:
            continue
        item = (state or {}).get("items", {}).get(pid, {}) if isinstance(state, dict) else {}
        conversation = item.get("conversation") or _stored_photo_conversation(photo)
        talked = _conversation_has_child_words(conversation)
        location_label = photo_location_label(photo)
        src = photo_display_url(photo, signed, max_px=420, quality=76)

        cards.append(
            {
                "id": str(pid),
                "src": src,
                "talked": bool(talked),
                "emotion": photo_selected_tag_values(photo)[0],
                "parenting": photo_selected_tag_values(photo)[1],
                "location": str(location_label or ""),
                "shared": photo_family_share_is_enabled(photo),
                "is_video": False,
            }
        )
        photo_ids.append(str(pid))

    if not cards:
        return None

    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None:
        serial_key = f"diary_gallery_serial_{trip_id}"
        serial = int(st.session_state.get(serial_key) or 0)
        result = gallery_component(
            data={"photos": cards, "allow_share": True, "family_key": current_family_key(), "member_key": current_member_key(), "pending_param": PENDING_EMOTION_QUERY_PARAM},
            key=f"diary_gallery_{trip_id}_{serial}_{_current_ui_refresh_epoch()}",
            on_photo_id_change=lambda: None,
            on_delete_photo_id_change=lambda: None,
            on_share_photo_change=lambda: None,
        )
        if handle_photo_family_share_event(result, photo_ids, serial_key=serial_key):
            return None
        delete_clicked = str(getattr(result, "delete_photo_id", "") or "")
        if delete_clicked in photo_ids:
            # Reset the component immediately so the same delete event is not emitted
            # again while the confirmation dialog is open.
            st.session_state[serial_key] = serial + 1
            confirm_photo_delete_dialog(trip_id, delete_clicked, photos=photos)
            return None

        clicked = str(getattr(result, "photo_id", "") or "")
        if clicked in photo_ids:
            # Reset the component before the gallery is shown again so the previous
            # click does not immediately reopen the same photo.
            st.session_state[serial_key] = serial + 1
            return clicked
        return None

    # Fallback for environments where the v2 component is unavailable.
    cols = st.columns(3)
    for idx, card in enumerate(cards):
        with cols[idx % 3]:
            if card["src"]:
                st.markdown(
                    f'<img src="{card["src"]}" style="width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:10px;" />',
                    unsafe_allow_html=True,
                )
            action_cols = st.columns([1, 3])
            with action_cols[0]:
                if st.button("×", key=f"diary_photo_fallback_delete_{trip_id}_{card['id']}", help="この写真を削除"):
                    confirm_photo_delete_dialog(trip_id, card["id"], photos=photos)
            with action_cols[1]:
                if st.button("写真を開く", use_container_width=True, key=f"diary_photo_fallback_{trip_id}_{card['id']}"):
                    return card["id"]
    return None


def open_diary_photo_talk(trip_id, photo_id, state):
    """Switch from the gallery to one photo's conversation screen."""
    photo_ids = list(state.get("photo_ids") or [])
    if photo_id not in photo_ids:
        return False
    state["selected_photo_id"] = photo_id
    state["photo_index"] = photo_ids.index(photo_id)
    state["audio_bytes"] = None
    state["audio_pending"] = False
    state["answer_serial"] = int(state.get("answer_serial") or 0) + 1
    st.session_state[f"diary_selected_photo_{trip_id}"] = photo_id
    st.session_state[f"diary_talk_photo_{trip_id}"] = photo_id
    return True


