# ============================================================
# v585: Nearby events during selected seven-day window (web-search grounded)
# ============================================================
# Searches are initiated only from this dedicated page. The Home screen does not
# perform event searches, and a category change never reloads another category.
EVENT_SEARCH_CATEGORIES_V570 = {
    "スポーツ": "地域のスポーツ大会、試合観戦、体験大会、マラソン、親子参加型スポーツ",
    "文化": "文化祭、展覧会の期間限定企画、コンサート、舞台、伝統芸能、博物館の催し",
    "その他": "地域のお祭り、マルシェ、科学イベント、ワークショップ、地域行事",
}
EVENT_SEARCH_MAX_PER_CATEGORY_V570 = 10
# v576: 「一覧」 is a category selector, not a display mode. It reuses the three
# existing category futures/cache entries; no extra all-category paid search.
EVENT_SEARCH_ALL_CATEGORY_V576 = "一覧"
EVENT_SEARCH_ALL_MAX_V576 = EVENT_SEARCH_MAX_PER_CATEGORY_V570 * len(EVENT_SEARCH_CATEGORIES_V570)
EVENT_SEARCH_CACHE_SECONDS_V570 = 20 * 60
EVENT_SEARCH_NEGATIVE_CACHE_SECONDS_V572 = 90
# v584: Respect a strict budget for user-initiated event searches.
# One hosted-search request per category (3 for the combined 「一覧」 search),
# and at most one billable web-search tool invocation inside each response.
# No paid candidate follow-up or paid venue-geocoding calls are automatic.
EVENT_SEARCH_WEB_CALLS_PER_CATEGORY_V584 = 1
EVENT_SEARCH_CACHE_TODAY_V584 = 3 * 60 * 60
EVENT_SEARCH_CACHE_FUTURE_V584 = 12 * 60 * 60
EVENT_SEARCH_CACHE_EMPTY_V584 = 15 * 60
# v573: Expand publisher coverage adaptively, not on Home or on unrelated pages.
# Three extra source-family searches run only if initial results lack breadth/depth.
EVENT_SEARCH_SUPPLEMENT_MIN_SITES_V573 = 4
EVENT_SEARCH_SUPPLEMENT_MIN_LOCATED_V573 = 5
EVENT_SEARCH_MODEL_V570 = str(secret("EVENT_SEARCH_MODEL", "gpt-4.1-mini") or "gpt-4.1-mini")
# v577: Targeted verification is only run when discovered candidates are missing
# date/source evidence and fewer than ten usable events survive. Up to two paid
# follow-up searches per category, never a background crawler.
EVENT_SEARCH_FOLLOWUP_LIMIT_V577 = 12
EVENT_SEARCH_FUTURE_FOLLOWUP_LIMIT_V578 = 18
EVENT_SEARCH_FOLLOWUP_BATCH_V577 = 6
EVENT_SEARCH_FOLLOWUP_MAX_CALLS_V577 = 2
EVENT_SEARCH_FUTURE_FOLLOWUP_MAX_CALLS_V578 = 3

# v575: Date selection ends one calendar month after today (same day of next month,
# or that month's last day if there is no matching day). Search/cache keys stay unchanged.
def _events_last_selectable_day_v575(today):
    year, month = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
    following_month_start = date(year + 1, 1, 1) if month == 12 else date(year, month + 1, 1)
    last_day = (following_month_start - timedelta(days=1)).day
    return date(year, month, min(today.day, last_day))


def _events_selected_date_v574():
    value = st.session_state.get("_events_date_v574")
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, str):
        try:
            return date.fromisoformat(value)
        except ValueError:
            pass
    return now_jst().date()


def _events_display_day_v574(day_value):
    value = day_value if isinstance(day_value, date) else date.fromisoformat(str(day_value))
    return value.strftime("%Y/%m/%d") + "（" + "月火水木金土日"[value.weekday()] + "）"


def _events_clean_clock_v574(value):
    """Only confirmed local HH:MM clock times are eligible for a public schedule."""
    raw = unicodedata.normalize("NFKC", str(value or "").strip())
    match = re.fullmatch(r"([01]?\d|2[0-3]):([0-5]\d)", raw)
    if not match:
        return ""
    return f"{int(match.group(1)):02d}:{match.group(2)}"


def _events_schedule_v574(raw):
    """Use model-sourced explicit times; retain old v573 'time' answer compatibility."""
    start = _events_clean_clock_v574(raw.get("start_time"))
    end = _events_clean_clock_v574(raw.get("end_time"))
    legacy = unicodedata.normalize("NFKC", str(raw.get("time") or ""))[:80]
    clocks = re.findall(r"(?<!\d)(?:[01]?\d|2[0-3]):[0-5]\d", legacy)
    if not start and clocks:
        start = _events_clean_clock_v574(clocks[0])
    if not end and len(clocks) > 1:
        end = _events_clean_clock_v574(clocks[1])
    if start and end:
        label = f"{start}～{end}"
    elif start:
        label = f"{start}開始（終了時刻未掲載）"
    elif end:
        label = f"終了 {end}（開始時刻未掲載）"
    else:
        label = "時間未掲載"
    return {"time": start, "start_time": start, "end_time": end, "time_label": label}


def _events_day_evidence_v574(raw, sought):
    """When a particular occurrence date is provided, reject a different occurrence."""
    event_day = str(raw.get("event_date") or "").strip()
    if not event_day:
        return True  # v573 older search rows may carry only a confirmed date range
    try:
        return date.fromisoformat(event_day) == date.fromisoformat(str(sought))
    except ValueError:
        return False


# v581: Never search, cite, or display events sourced from these domains.
# The hostname check also covers www. and other subdomains, but not lookalikes.
EVENT_SEARCH_BLOCKED_DOMAINS_V581 = ("koko.tokyo",)


def _events_source_blocked_v581(value):
    try:
        hostname = (urlparse(str(value or "").strip()).hostname or "").lower().rstrip(".")
        return any(hostname == domain or hostname.endswith("." + domain)
                   for domain in EVENT_SEARCH_BLOCKED_DOMAINS_V581)
    except (ValueError, TypeError):
        return False


def _events_url_key_v570(value):
    """Stable, strict source link identity: never trust an uncited AI event."""
    try:
        parsed = urlparse(str(value or "").strip())
        if parsed.scheme != "https" or not parsed.hostname:
            return ""
        host = parsed.hostname.lower().removeprefix("www.")
        if _events_source_blocked_v581(value):
            return ""
        if host in {"localhost", "127.0.0.1", "0.0.0.0"}:
            return ""
        path = (parsed.path or "/").rstrip("/") or "/"
        # Query parameters that identify individual event pages are part of the
        # source identity. Tracking parameters are ignored to permit citation
        # URLs with UTM suffixes to match the same event page.
        unique_keys = {"id", "event_id", "eventid", "article_id", "pid", "eid", "p", "item_id", "post_id"}
        unique_params = parse_qs(parsed.query, keep_blank_values=False)
        qualifiers = sorted((k.lower(), v[0][:100]) for k, v in unique_params.items()
                            if k.lower() in unique_keys and v)
        return host + path + ("?" + urlencode(qualifiers) if qualifiers else "")
    except Exception:
        return ""


def _events_source_urls_v570(response):
    """Collect sources actually returned by the Responses hosted web_search tool."""
    urls = set()
    for item in list(getattr(response, "output", None) or []):
        action = getattr(item, "action", None)
        if isinstance(item, dict):
            action = item.get("action", action)
        sources = action.get("sources") if isinstance(action, dict) else getattr(action, "sources", None)
        for source in list(sources or []):
            url = source.get("url") if isinstance(source, dict) else getattr(source, "url", None)
            key = _events_url_key_v570(url)
            if key:
                urls.add(key)
        contents = item.get("content", []) if isinstance(item, dict) else getattr(item, "content", [])
        for content in list(contents or []):
            annotations = content.get("annotations", []) if isinstance(content, dict) else getattr(content, "annotations", [])
            for annotation in list(annotations or []):
                url = annotation.get("url") if isinstance(annotation, dict) else getattr(annotation, "url", None)
                key = _events_url_key_v570(url)
                if key:
                    urls.add(key)
    return urls


def _events_decode_json_v570(raw):
    """Accept plain JSON or a JSON code fence without executing model text."""
    value = str(raw or "").strip()
    if value.startswith("```"):
        value = re.sub(r"^```(?:json)?\s*", "", value, count=1, flags=re.IGNORECASE)
        value = re.sub(r"\s*```$", "", value)
    value = value[value.find("{"):] if "{" in value else ""
    if not value:
        return {}
    try:
        parsed, _ = json.JSONDecoder().raw_decode(value)
        return parsed if isinstance(parsed, dict) else {}
    except (ValueError, TypeError):
        return {}


@functools.lru_cache(maxsize=350)
def _events_venue_google_location_v570(venue, address, lat_rough, lon_rough, radius_km):
    """Resolve an actual venue, NOT an event date, with the existing optional Places key."""
    if not GOOGLE_PLACES_API_KEY or not venue:
        return None
    center_lat, center_lon = float(lat_rough), float(lon_rough)
    data = json.dumps({
        "textQuery": (str(venue) + " " + str(address)).strip()[:220],
        "languageCode": "ja", "maxResultCount": 3,
        "locationBias": {"circle": {"center": {"latitude": center_lat, "longitude": center_lon},
                                     "radius": float(min(50000, max(1000, radius_km * 1000)))}},
    }, ensure_ascii=False).encode("utf-8")
    req = Request("https://places.googleapis.com/v1/places:searchText", data=data, method="POST", headers={
        "Content-Type": "application/json; charset=UTF-8",
        "X-Goog-Api-Key": GOOGLE_PLACES_API_KEY,
        "X-Goog-FieldMask": "places.displayName,places.formattedAddress,places.location,places.businessStatus",
    })
    try:
        with urlopen(req, timeout=6.5) as response:
            items = list((json.loads(response.read().decode("utf-8")) or {}).get("places") or [])
    except Exception:
        return None
    target = re.sub(r"\s+", "", unicodedata.normalize("NFKC", str(venue)).casefold())
    candidates = []
    for row in items:
        if not isinstance(row, dict) or str(row.get("businessStatus") or "") == "CLOSED_PERMANENTLY":
            continue
        place = row.get("location") if isinstance(row.get("location"), dict) else {}
        try:
            plat, plon = float(place["latitude"]), float(place["longitude"])
            distance = _nearby_haversine_m(center_lat, center_lon, plat, plon)
        except (KeyError, TypeError, ValueError):
            continue
        if distance > float(radius_km) * 1000:
            continue
        raw_name = row.get("displayName") or {}
        name = raw_name.get("text") if isinstance(raw_name, dict) else str(raw_name)
        found = re.sub(r"\s+", "", unicodedata.normalize("NFKC", str(name)).casefold())
        # Avoid silently using a nearby but unrelated venue.
        if not target or not found or (target not in found and found not in target):
            continue
        candidates.append((distance, plat, plon))
    if not candidates:
        return None
    candidates.sort()
    return (candidates[0][1], candidates[0][2])


@functools.lru_cache(maxsize=180)
def _events_venue_osm_location_v570(venue, address):
    """Nominatim venue lookup, then address-only fallback, inside the 1 req/sec lock."""
    full = (str(venue) + " " + str(address)).strip()[:160]
    addr = str(address or "").strip()[:160]
    if not full:
        return None
    queries = [full]
    if addr and addr != full:
        queries.append(addr)
    for index, query in enumerate(queries):
        if index:
            time.sleep(1.1)  # The caller holds the shared Nominatim lock.
        req = Request("https://nominatim.openstreetmap.org/search?" + urlencode({
            "q": query, "format": "jsonv2", "limit": 2, "countrycodes": "jp", "accept-language": "ja",
        }), headers={"User-Agent": "TokyoBurariApp/1.0 (user-initiated event search)", "Accept": "application/json"})
        try:
            with urlopen(req, timeout=5.0) as response:
                rows = json.loads(response.read().decode("utf-8"))
            if isinstance(rows, list) and rows:
                return (float(rows[0]["lat"]), float(rows[0]["lon"]))
        except Exception:
            continue
    return None


def _events_geocode_missing_v570(items, *, day, category, lat, lon, radius_km, sources):
    """Confirm date/citation first; location lookup failure must not erase a cited event.

    Locations not resolved by bounded Places/Nominatim are retained with no coordinates.
    Rendering labels those as distance-unverified and deliberately offers no walking route.
    """
    verified = _events_prefilter_v571(items, day=day, sources=sources)
    ready, unresolved = [], []
    for raw in verified:
        item = dict(raw)
        accepted = _events_validate_one_v570(item, day=day, category=category,
                                              lat=lat, lon=lon, radius_km=radius_km, sources=sources)
        if accepted:
            ready.append(item)
        elif _events_missing_location_v572(item):
            unresolved.append(item)
        # Coordinates that are present but outside the radius are not treated as unknown.

    max_queries = 12 if GOOGLE_PLACES_API_KEY else 4
    lookup = unresolved[:max_queries]
    if GOOGLE_PLACES_API_KEY and lookup:
        with ThreadPoolExecutor(max_workers=3, thread_name_prefix="burari-event-geo") as pool:
            futures = {pool.submit(_events_venue_google_location_v570,
                                   str(item.get("venue") or ""), str(item.get("address") or ""),
                                   round(float(lat), 2), round(float(lon), 2), int(radius_km)): item
                       for item in lookup}
            for future in as_completed(futures):
                try:
                    coords = future.result()
                except Exception:
                    coords = None
                if coords:
                    item = futures[future]
                    item["latitude"], item["longitude"] = coords
                    # Geocoded venues outside the radius are excluded below.
    elif lookup:
        for item in lookup:
            with _events_nominatim_lock_v570:
                global _events_nominatim_last_at_v570
                elapsed = time.monotonic() - _events_nominatim_last_at_v570
                if elapsed < 1.1:
                    time.sleep(1.1 - elapsed)
                coords = _events_venue_osm_location_v570(
                    str(item.get("venue") or ""), str(item.get("address") or ""))
                _events_nominatim_last_at_v570 = time.monotonic()
            if coords:
                item["latitude"], item["longitude"] = coords

    # The caller validates every item again; known out-of-radius coordinates stay excluded.
    return ready + unresolved


def _events_missing_location_v572(raw):
    """Only genuinely absent coordinates qualify for the no-distance fallback."""
    return raw.get("latitude") in (None, "", "null") or raw.get("longitude") in (None, "", "null")


_events_nominatim_lock_v570 = threading.Lock()
_events_nominatim_last_at_v570 = 0.0


def _events_validate_one_v570(raw, *, day, category, lat, lon, radius_km, sources):
    """Never show an undated, remote, or unreferenced entry as a today's event."""
    if not isinstance(raw, dict):
        return None
    title = re.sub(r"\s+", " ", str(raw.get("title") or "")).strip()[:150]
    venue = re.sub(r"\s+", " ", str(raw.get("venue") or "")).strip()[:120]
    source_url = str(raw.get("source_url") or "").strip()
    source_key = _events_url_key_v570(source_url)
    if not title or not venue or not source_key or source_key not in sources:
        return None
    start_day = str(raw.get("start_date") or "").strip()
    end_day = str(raw.get("end_date") or start_day).strip() or start_day
    try:
        start = date.fromisoformat(start_day)
        end = date.fromisoformat(end_day)
        sought = date.fromisoformat(day)
    except (TypeError, ValueError):
        return None
    if not start <= sought <= end or (end - start).days > EVENTS_VERIFIED_PERIOD_MAX_DAYS_V588 or not _events_day_evidence_v574(raw, day):
        return None
    try:
        plat = float(raw.get("latitude"))
        plon = float(raw.get("longitude"))
    except (TypeError, ValueError):
        return None
    if not (20.0 < plat < 46.5 and 122.0 < plon < 154.5):
        return None
    distance_m = _nearby_haversine_m(lat, lon, plat, plon)
    if not math.isfinite(distance_m) or distance_m > radius_km * 1000.0:
        return None
    if _events_child_meta_v587(raw)["child_audience"] == "大人限定":
        return None
    schedule = _events_schedule_v574(raw)
    short = re.sub(r"\s+", " ", str(raw.get("description") or "")).strip()[:155]
    return {
        "title": title, "venue": venue, "address": str(raw.get("address") or "").strip()[:180],
        "start_date": start_day, "end_date": end_day, **schedule,
        "description": short, "category": category, "source_url": source_url,
        "latitude": plat, "longitude": plon, "distance_m": int(round(distance_m)),
        "source_rechecked": bool(raw.get("source_rechecked")),
        **_events_child_meta_v587(raw),
    }


def _events_validate_unlocated_v572(raw, *, day, category, sources):
    """Show source/date-confirmed events as references, never as in-radius matches."""
    if not isinstance(raw, dict) or not _events_missing_location_v572(raw):
        return None
    key = _events_url_key_v570(raw.get("source_url"))
    if not key or key not in sources:
        return None
    title = re.sub(r"\s+", " ", str(raw.get("title") or "")).strip()[:150]
    venue = re.sub(r"\s+", " ", str(raw.get("venue") or "")).strip()[:120]
    if not title or not venue:
        return None
    start = str(raw.get("start_date") or "").strip()
    end = str(raw.get("end_date") or start).strip() or start
    try:
        begin, finish, sought = date.fromisoformat(start), date.fromisoformat(end), date.fromisoformat(day)
    except (ValueError, TypeError):
        return None
    if not begin <= sought <= finish or (finish - begin).days > EVENTS_VERIFIED_PERIOD_MAX_DAYS_V588 or not _events_day_evidence_v574(raw, day):
        return None
    if _events_child_meta_v587(raw)["child_audience"] == "大人限定":
        return None
    return {
        "title": title, "venue": venue, "address": str(raw.get("address") or "").strip()[:180],
        "start_date": start, "end_date": end, **_events_schedule_v574(raw),
        "description": re.sub(r"\s+", " ", str(raw.get("description") or "")).strip()[:155],
        "category": category, "source_url": str(raw.get("source_url") or "").strip(),
        "latitude": None, "longitude": None, "distance_m": None,
        "source_rechecked": bool(raw.get("source_rechecked")),
        **_events_child_meta_v587(raw),
    }


def _events_source_plans_v571(category, latitude, longitude):
    """Primary five source families, with more named publishers per family in v573."""
    near_tokyo = 35.35 <= float(latitude) <= 36.05 and 139.15 <= float(longitude) <= 140.15
    government = ["lg.jp", "go.jp"] + (["tokyo.jp", "gotokyo.org",
                                           "tokyo-kodomo-hp.metro.tokyo.lg.jp"] if near_tokyo else [])
    specialists = {
        "スポーツ": ["sportsentry.ne.jp", "runnet.jp", "moshicom.com", "tokyo-sports.or.jp",
                  "jleague.jp", "bleague.jp", "japan-sports.or.jp", "tef.or.jp", "jfa.jp", "npb.jp"],
        "文化": ["tokyoartbeat.com", "artagenda.jp", "museum.or.jp", "eplus.jp",
                 "t.pia.jp", "gotokyo.org", "rekibun.or.jp", "kahaku.go.jp", "tnm.jp"],
        "その他": ["gotokyo.org", "peatix.com", "eventregist.com", "walkerplus.com",
                   "iko-yo.net", "enjoytokyo.jp", "eventbank.jp", "tokyo-eventplus.com"],
    }
    family_domains = ["iko-yo.net", "walkerplus.com", "peatix.com", "asoview.com",
                      "eventregist.com", "kokuchpro.com"]
    if near_tokyo:
        family_domains += ["tokyo-eventplus.com", "kodomoto.info"]
    return [
        {"name": "自治体・観光公式", "domains": government,
         "focus": "自治体の当日イベントカレンダー、区市町村の催し、公共スポーツ施設、観光協会の公式案内。"},
        {"name": "会場・主催者公式", "domains": None,
         "focus": "近隣の競技場、文化施設、図書館、科学館、公園管理者、商業施設、主催団体の個別告知を直接確認。イベントまとめページだけに偏らない。"},
        {"name": "分野別専門サイト", "domains": specialists[category],
         "focus": ("競技大会、試合日程、地域スポーツ団体、子どもの参加・観戦行事。"
                   if category == "スポーツ" else "美術館・博物館の特別展示、舞台、音楽、伝統芸能、文化施設の個別イベント。"
                   if category == "文化" else "地域祭り、ものづくり、科学体験、街歩き、地域交流イベント。")},
        {"name": "親子・地域イベント情報", "domains": family_domains,
         "focus": "複数の地域イベント掲載サイトから、指定日に実施する現地開催の個別イベントページを探索。"},
        {"name": "近隣地域・補完探索", "domains": None,
         "focus": "検索地点の周辺市区町村、駅周辺の地区イベント、学校公開行事や地域スポーツ、商店街、文化祭を追加探索。前述の情報源だけに偏らない。"},
    ]



