def _render_saved_experience_cards_v513(cards):
    """Render saved experience cards as a compact mobile-friendly list."""
    cards = [card for card in (cards or []) if isinstance(card, dict)]
    if not cards:
        st.info("作成済みの体験カードはまだありません。")
        return

    per_page = 12
    page_count = max(1, math.ceil(len(cards) / per_page))
    page_key = "_experience_saved_cards_page_v513"
    try:
        current_page = int(st.session_state.get(page_key) or 0)
    except Exception:
        current_page = 0
    current_page = max(0, min(current_page, page_count - 1))
    st.session_state[page_key] = current_page

    visible_cards = cards[current_page * per_page:(current_page + 1) * per_page]
    paths = []
    for card in visible_cards:
        first_path = next(iter(card.get("photo_storage_paths") or []), "")
        if first_path:
            paths.append(first_path)
    try:
        signed = signed_photo_url_map(paths, expires_in=1800) if paths else {}
    except Exception:
        signed = {}

    st.caption(f"{len(cards)}件の体験カード")
    for card in visible_cards:
        first_path = next(iter(card.get("photo_storage_paths") or []), "")
        image_url = ""
        if first_path:
            image_url = signed.get(first_path) or photo_display_url(
                {"storage_path": first_path}, signed_map=signed, max_px=360, quality=78
            )

        category = str(card.get("compare_category") or EXPERIENCE_COMPARE_EXCLUDED_V497)
        place = str(card.get("place_name") or "不明")
        experience_type = str(card.get("experience_type") or "体験")
        item_name = str(card.get("item_name") or "不明")
        category_label = category if category != EXPERIENCE_COMPARE_EXCLUDED_V497 else ("おやつ" if experience_type == "おやつ" else experience_type)
        headline = f"{place}　{category_label}"
        meta_parts = [str(card.get("trip_date") or "")]
        if experience_type == "おやつ":
            meta_parts.append(f"商品名：{item_name}")
        meta = "　".join([x for x in meta_parts if x])
        comment = str(card.get("child_comment") or "").strip()

        if image_url:
            image_html = (
                f'<img src="{html.escape(str(image_url), quote=True)}" '
                'style="width:88px;height:88px;flex:0 0 88px;object-fit:cover;border-radius:12px;background:rgba(128,128,128,.08);" />'
            )
        else:
            image_html = (
                '<div style="width:88px;height:88px;flex:0 0 88px;border-radius:12px;'
                'background:rgba(128,128,128,.08);display:flex;align-items:center;justify-content:center;'
                'font-size:1.5rem;">📝</div>'
            )
        st.markdown(
            f"""
            <div style="display:flex;gap:10px;align-items:flex-start;border:1px solid rgba(128,128,128,.18);border-radius:15px;padding:9px;margin:8px 0;background:rgba(128,128,128,.025);">
              {image_html}
              <div style="min-width:0;flex:1;">
                <div style="font-size:.98rem;font-weight:850;line-height:1.35;">{html.escape(headline)}</div>
                <div style="font-size:.70rem;opacity:.66;margin-top:3px;line-height:1.35;">{html.escape(meta)}</div>
                <div style="font-size:.86rem;font-weight:620;margin-top:7px;line-height:1.48;">「{html.escape(comment)}」</div>
              </div>
            </div>
            """,
            unsafe_allow_html=True,
        )

    if page_count > 1:
        st.caption(f"{current_page + 1} / {page_count}ページ")
        prev_col, next_col = st.columns(2, gap="small")
        with prev_col:
            if st.button("← 前のカード", use_container_width=True, disabled=current_page <= 0, key=f"experience_saved_prev_v513_{current_page}"):
                st.session_state[page_key] = max(0, current_page - 1)
                st.rerun(scope="app")
        with next_col:
            if st.button("次のカード →", use_container_width=True, disabled=current_page >= page_count - 1, key=f"experience_saved_next_v513_{current_page}"):
                st.session_state[page_key] = min(page_count - 1, current_page + 1)
                st.rerun(scope="app")


def page_experience_v503():
    saved_cards_view = bool(st.session_state.get("_experience_saved_cards_view_v513"))
    if saved_cards_view:
        page_top("📚 作成済み体験カード", "これまで作成した体験カードを確認できます。")
    else:
        page_top("📝 体験を残す", "体験の感想と、選んだ写真から1つの体験カードを作ります。")
    _app_css_v473(
        """
        <style>
        .st-key-experience_input_pair_v499 [data-testid="stHorizontalBlock"]{gap:.55rem!important;align-items:stretch!important;}
        .st-key-experience_input_pair_v499 [data-testid="stColumn"]{min-width:0!important;}
        .st-key-experience_input_pair_v499 div.stButton>button{min-height:58px!important;font-weight:800!important;white-space:normal!important;}
        .st-key-experience_create_v499 div.stButton>button{min-height:54px!important;font-size:1.02rem!important;font-weight:850!important;}
        .experience-status-v499{font-size:.76rem;opacity:.72;margin:.20rem 0 .30rem;line-height:1.35;}
        .experience-card-v499{border:1px solid rgba(128,128,128,.16);border-radius:15px;padding:.70rem .76rem;margin:.55rem 0;background:rgba(128,128,128,.035);}
        .experience-card-title-v499{font-size:1.02rem;font-weight:850;line-height:1.32;}
        .experience-card-meta-v499{font-size:.72rem;opacity:.66;margin-top:.18rem;line-height:1.35;}
        .experience-card-comment-v499{font-size:.90rem;font-weight:650;margin-top:.42rem;line-height:1.5;}
        .experience-photo-label-v499{font-size:.67rem;opacity:.68;margin-top:.12rem;line-height:1.3;}
        </style>
        """
    )

    notice = st.session_state.pop("_experience_notice_v497", None)
    if notice:
        st.success(notice)

    owner_token = f"{current_family_key()}::{current_member_key()}"
    if st.session_state.get("_experience_draft_owner_v497") != owner_token:
        _reset_experience_draft_v497()
        st.session_state["_experience_draft_owner_v497"] = owner_token

    try:
        card_state = get_experience_card_state_v497()
        cards = list(card_state.get("cards") or [])
    except Exception as exc:
        cards = []
        st.warning("体験カードの保存状態を読み込めませんでした。")
        with st.expander("保護者向け詳細"):
            st.code(str(exc))

    if saved_cards_view:
        if st.button("← 体験を残すに戻る", use_container_width=True, key="experience_saved_cards_back_v513"):
            st.session_state.pop("_experience_saved_cards_view_v513", None)
            st.rerun(scope="app")
        _render_saved_experience_cards_v513(cards)
        return

    if st.button(
        f"📚 作成済み体験カードを見る（{len(cards)}件）",
        use_container_width=True,
        disabled=not bool(cards),
        key="experience_open_saved_cards_v513",
    ):
        st.session_state["_experience_saved_cards_view_v513"] = True
        st.session_state["_experience_saved_cards_page_v513"] = 0
        st.rerun(scope="app")

    used_ids = _experience_used_photo_ids_v497(cards)
    transcript = str(st.session_state.get("_experience_transcript_v497") or "").strip()
    selected_key = "_experience_selected_photo_ids_v499"
    selected_ids = [str(x) for x in st.session_state.get(selected_key, []) if str(x)][:EXPERIENCE_MANUAL_PHOTO_MAX_V497]
    st.session_state[selected_key] = selected_ids

    with st.container(key="experience_input_pair_v499"):
        left, right = st.columns(2, gap="small")
        with left:
            if st.button(
                "🎤 体験の感想",
                type="secondary",
                use_container_width=True,
                key="experience_show_audio_button_v499",
            ):
                st.session_state["_experience_show_audio_v497"] = not bool(st.session_state.get("_experience_show_audio_v497"))
            st.markdown(
                f'<div class="experience-status-v499">{"✓ 録音済み" if transcript else "感想を短く録音"}</div>',
                unsafe_allow_html=True,
            )
        with right:
            if st.button(
                "📷 体験の写真",
                type="secondary",
                use_container_width=True,
                key="experience_open_manual_photos_v500",
            ):
                st.session_state["_experience_manual_picker_open_v499"] = not bool(
                    st.session_state.get("_experience_manual_picker_open_v499")
                )
            photo_status = f"✓ {len(selected_ids)}枚 選択済み" if selected_ids else "押して写真を選ぶ"
            st.markdown(
                f'<div class="experience-status-v499">{html.escape(photo_status)}</div>',
                unsafe_allow_html=True,
            )

    # v499: nothing is auto-selected. Load photos only after the picker was opened,
    # or when we need to render already-selected photos.
    picker_open = bool(st.session_state.get("_experience_manual_picker_open_v499"))
    recent_photos = []
    recent_by_id = {}
    if picker_open or selected_ids:
        try:
            recent_photos = _experience_manual_photo_rows_v499()
            recent_by_id = {
                str(photo.get("id") or ""): photo
                for photo in recent_photos
                if str(photo.get("id") or "")
            }
        except Exception as exc:
            st.warning("最近の写真を読み込めませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    # If a selected photo is no longer in the filtered recent window, fetch it directly
    # from the normal recent list before dropping it. This preserves a parent's manual choice.
    missing_selected = [photo_id for photo_id in selected_ids if photo_id not in recent_by_id]
    if missing_selected:
        try:
            fallback_rows = _experience_photo_library_rows_v503()
            for photo in fallback_rows:
                photo_id = str((photo or {}).get("id") or "")
                if photo_id in missing_selected:
                    recent_by_id[photo_id] = photo
        except Exception:
            pass

    selected_ids = [photo_id for photo_id in selected_ids if photo_id in recent_by_id]
    st.session_state[selected_key] = selected_ids

    # v502: do not use st.columns(3) for the selected-photo preview.
    # Streamlit stacks those columns vertically on narrow Android screens, which made
    # a single selected image look like a full-width enlarged photo. Reuse the same
    # diary/photo gallery component as the rest of the app so the mobile layout stays
    # a true 3-column grid. Tapping a thumbnail switches to the normal enlarged view.
    selected_photos = [recent_by_id[photo_id] for photo_id in selected_ids if photo_id in recent_by_id]
    if selected_photos:
        paths = [str(photo.get("storage_path") or "") for photo in selected_photos]
        try:
            signed_map = signed_photo_url_map(paths, expires_in=1800)
        except Exception:
            signed_map = {}

        view_mode_key = "_experience_selected_photo_view_mode_v502"
        index_key = "_experience_selected_photo_enlarged_index_v502"
        view_mode = str(st.session_state.get(view_mode_key) or "一覧モード")
        if view_mode not in {"一覧モード", "拡大モード"}:
            view_mode = "一覧モード"
            st.session_state[view_mode_key] = view_mode

        try:
            enlarged_index = int(st.session_state.get(index_key) or 0)
        except Exception:
            enlarged_index = 0
        enlarged_index = max(0, min(enlarged_index, len(selected_photos) - 1))
        st.session_state[index_key] = enlarged_index

        if view_mode == "拡大モード":
            if st.button(
                "← 3枚一覧に戻る",
                use_container_width=True,
                key=f"experience_selected_back_to_grid_v502_{enlarged_index}",
            ):
                st.session_state[view_mode_key] = "一覧モード"
                st.rerun(scope="app")

            prev_col, count_col, next_col = st.columns([1, 1.15, 1], gap="small")
            with prev_col:
                if st.button(
                    "◀ 前へ",
                    use_container_width=True,
                    disabled=enlarged_index <= 0,
                    key=f"experience_selected_prev_v502_{enlarged_index}",
                ):
                    st.session_state[index_key] = max(0, enlarged_index - 1)
                    st.rerun(scope="app")
            with count_col:
                st.markdown(
                    f'<div style="text-align:center;padding:.55rem .1rem;font-weight:800;">{enlarged_index + 1} / {len(selected_photos)}</div>',
                    unsafe_allow_html=True,
                )
            with next_col:
                if st.button(
                    "次へ ▶",
                    use_container_width=True,
                    disabled=enlarged_index >= len(selected_photos) - 1,
                    key=f"experience_selected_next_v502_{enlarged_index}",
                ):
                    st.session_state[index_key] = min(len(selected_photos) - 1, enlarged_index + 1)
                    st.rerun(scope="app")

            photo = selected_photos[enlarged_index]
            url = photo_display_url(photo, signed_map=signed_map, max_px=1400, quality=90)
            if url:
                st.image(url, use_container_width=True)
            st.markdown(
                f'<div class="experience-photo-label-v499">{html.escape(_experience_captured_label_v497(photo.get("captured_at")))}</div>',
                unsafe_allow_html=True,
            )
        else:
            photo_rows=[]
            photo_ids=[]
            for photo in selected_photos:
                photo_id=str(photo.get("id") or "")
                if not photo_id:
                    continue
                photo_rows.append({
                    "id":photo_id,
                    "src":photo_display_url(photo,signed_map=signed_map,max_px=420,quality=76),
                    "meta":_experience_captured_label_v497(photo.get("captured_at")),
                    "used":False,
                })
                photo_ids.append(photo_id)
            multi_component=_get_experience_photo_multi_component_v503()
            if multi_component is not None and photo_rows:
                result=multi_component(
                    data={"mode":"selected","photos":photo_rows,"selected_ids":[],"max_select":EXPERIENCE_MANUAL_PHOTO_MAX_V497},
                    key=f"experience_selected_multi_v503_{int(st.session_state.get('_experience_draft_serial_v497') or 1)}_{len(photo_rows)}",
                    on_photo_open_change=lambda:None,
                    on_batch_remove_change=lambda:None,
                )
                open_payload=getattr(result,"photo_open",None) if result is not None else None
                if isinstance(open_payload,dict):
                    token=str(open_payload.get("token") or "")
                    last=str(st.session_state.get("_experience_selected_multi_last_token_v503") or "")
                    photo_id=str(open_payload.get("photo_id") or "")
                    if token and token!=last and photo_id in photo_ids:
                        st.session_state["_experience_selected_multi_last_token_v503"]=token
                        st.session_state[index_key]=photo_ids.index(photo_id)
                        st.session_state[view_mode_key]="拡大モード"
                        st.rerun(scope="app")
                remove_payload=getattr(result,"batch_remove",None) if result is not None else None
                if isinstance(remove_payload,dict):
                    token=str(remove_payload.get("token") or "")
                    last=str(st.session_state.get("_experience_selected_multi_last_token_v503") or "")
                    remove_ids=[str(x) for x in (remove_payload.get("photo_ids") or []) if str(x)]
                    remove_set=set(x for x in remove_ids if x in photo_ids)
                    if token and token!=last and remove_set:
                        st.session_state["_experience_selected_multi_last_token_v503"]=token
                        st.session_state[selected_key]=[x for x in selected_ids if x not in remove_set]
                        st.session_state[index_key]=0
                        st.rerun(scope="app")
            elif photo_rows:
                items=[]
                for row in photo_rows:
                    src=str(row.get("src") or "")
                    if not src:
                        continue
                    meta=html.escape(str(row.get("meta") or ""))
                    items.append(
                        '<div style="min-width:0;">'
                        f'<div style="aspect-ratio:1/1;overflow:hidden;border-radius:10px;background:rgba(128,128,128,.06);">'
                        f'<img src="{html.escape(src,quote=True)}" loading="lazy" decoding="async" style="display:block;width:100%;height:100%;object-fit:cover;" />'
                        '</div>'
                        f'<div style="font-size:8px;opacity:.68;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{meta}</div>'
                        '</div>'
                    )
                st.markdown('<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;width:100%;">'+''.join(items)+'</div>',unsafe_allow_html=True)

    # v505/v509: once photos are selected and the picker is closed, infer the food and
    # search around the photos' saved GPS. The parent can override the food with a
    # compact manual entry; a manual value re-runs the same nearby-store search using
    # the typed food as the authoritative query.
    store_inference = {}
    selected_store_candidate = None
    experience_flow_create_requested = False
    store_choice_key = "_experience_store_choice_v505"
    if selected_photos and not picker_open:
        signature = hashlib.sha1("|".join(selected_ids).encode("utf-8")).hexdigest()[:16]

        # A food override belongs only to the exact currently selected photo set.
        manual_signature = str(st.session_state.get("_experience_manual_food_signature_v509") or "")
        if manual_signature and manual_signature != signature:
            for key in (
                "_experience_manual_food_query_v509",
                "_experience_manual_food_signature_v509",
                "_experience_manual_store_inference_v509",
                "_experience_store_effective_inference_v509",
            ):
                st.session_state.pop(key, None)
            st.session_state.pop(store_choice_key, None)

        cached_inference = st.session_state.get("_experience_store_inference_v505")
        if not isinstance(cached_inference, dict) or str(cached_inference.get("signature") or "") != signature:
            st.session_state.pop(store_choice_key, None)
            try:
                with st.spinner("写真と撮影場所からお店候補を探しています…"):
                    fresh_inference = infer_experience_store_candidates_v505(selected_photos)
            except Exception as exc:
                fresh_inference = {
                    "is_food": False,
                    "food_label": "",
                    "compare_category": EXPERIENCE_COMPARE_EXCLUDED_V497,
                    "candidates": [],
                    "reason": "inference_error",
                    "detail": str(exc)[:180],
                }
            fresh_inference["signature"] = signature
            st.session_state["_experience_store_inference_v505"] = fresh_inference
            cached_inference = fresh_inference
        auto_inference = dict(cached_inference or {})

        manual_query = ""
        if str(st.session_state.get("_experience_manual_food_signature_v509") or "") == signature:
            manual_query = str(st.session_state.get("_experience_manual_food_query_v509") or "").strip()

        # Small manual-entry control next to the food inference. Keep it optional so
        # the normal flow still needs no extra action when the AI guess is correct.
        auto_food_label = str(auto_inference.get("food_label") or "").strip()
        auto_compare_hint = str(auto_inference.get("compare_category") or "").strip()
        info_col, manual_col = st.columns([4.25, 1.05], gap="small")
        with info_col:
            if manual_query:
                manual_category = _experience_manual_compare_category_v509(manual_query)
                if manual_category in EXPERIENCE_SNACK_COMPARE_CATEGORIES_V497:
                    st.caption(f"手入力『{manual_query}』で検索中です。比較カテゴリー：{manual_category}")
                else:
                    st.caption(f"手入力『{manual_query}』で検索中です。")
            elif auto_food_label:
                if auto_compare_hint in EXPERIENCE_SNACK_COMPARE_CATEGORIES_V497:
                    st.caption(f"写真から『{auto_food_label}』と推定しました。比較カテゴリー：{auto_compare_hint}")
                else:
                    st.caption(f"写真から『{auto_food_label}』と推定しました。")
            else:
                st.caption("写真から食べ物を判定できない場合は、手入力できます。")
        with manual_col:
            if st.button(
                "手入力",
                type="secondary",
                use_container_width=True,
                key=f"experience_manual_food_open_v509_{signature}",
            ):
                st.session_state["_experience_manual_food_open_v509"] = not bool(
                    st.session_state.get("_experience_manual_food_open_v509")
                )

        if bool(st.session_state.get("_experience_manual_food_open_v509")):
            with st.form(key=f"experience_manual_food_form_v509_{signature}", clear_on_submit=False):
                typed_food = st.text_input(
                    "食べ物を手入力",
                    value=manual_query or auto_food_label,
                    placeholder="例：たい焼き",
                    max_chars=100,
                )
                rerun_manual = st.form_submit_button("この内容で再検索", use_container_width=True)
            if rerun_manual:
                typed_food = str(typed_food or "").strip()
                if typed_food:
                    st.session_state["_experience_manual_food_query_v509"] = typed_food
                    st.session_state["_experience_manual_food_signature_v509"] = signature
                    st.session_state.pop("_experience_manual_store_inference_v509", None)
                    st.session_state.pop("_experience_store_effective_inference_v509", None)
                    st.session_state.pop(store_choice_key, None)
                    st.session_state["_experience_manual_food_open_v509"] = False
                    st.rerun(scope="app")
                else:
                    st.warning("食べ物を入力してください。")

        # Manual input takes precedence. Cache by photo signature + typed query so a
        # normal Streamlit rerun does not repeat the Places search.
        if manual_query:
            manual_cache_key = hashlib.sha1(f"{signature}|{manual_query}".encode("utf-8")).hexdigest()[:20]
            manual_cached = st.session_state.get("_experience_manual_store_inference_v509")
            if not isinstance(manual_cached, dict) or str(manual_cached.get("manual_cache_key") or "") != manual_cache_key:
                try:
                    with st.spinner(f"『{manual_query}』でお店候補を再検索しています…"):
                        manual_cached = infer_experience_store_candidates_manual_v509(
                            selected_photos,
                            manual_query,
                            base_inference=auto_inference,
                        )
                except Exception as exc:
                    manual_cached = {
                        "is_food": True,
                        "food_label": manual_query,
                        "compare_category": _experience_manual_compare_category_v509(manual_query),
                        "candidates": [],
                        "reason": "inference_error",
                        "detail": str(exc)[:180],
                        "manual_override": True,
                    }
                manual_cached["signature"] = signature
                manual_cached["manual_cache_key"] = manual_cache_key
                st.session_state["_experience_manual_store_inference_v509"] = manual_cached
            store_inference = dict(manual_cached or {})
        else:
            store_inference = auto_inference

        st.session_state["_experience_store_effective_inference_v509"] = dict(store_inference or {})

        if bool(store_inference.get("is_food")):
            food_label = str(store_inference.get("food_label") or "").strip()
            compare_hint = str(store_inference.get("compare_category") or "").strip()
            candidates = [
                x for x in (store_inference.get("candidates") or [])
                if isinstance(x, dict) and str(x.get("name") or "").strip()
            ]
            st.markdown("#### お店の候補")
            reason = str(store_inference.get("reason") or "")
            if candidates:
                options = [str(x.get("id") or f"candidate_{i}") for i, x in enumerate(candidates)] + ["__unknown__"]
                label_map = {}
                candidate_by_id = {}
                for i, candidate in enumerate(candidates):
                    option_id = str(candidate.get("id") or f"candidate_{i}")
                    distance = int(candidate.get("distance_m") or 0)
                    distance_text = f"（約{distance}m）" if distance > 0 else ""
                    label_map[option_id] = f"{str(candidate.get('name') or '').strip()}{distance_text}"
                    candidate_by_id[option_id] = candidate
                label_map["__unknown__"] = "わからない"
                choice = st.radio(
                    "候補から選択",
                    options,
                    index=0,
                    format_func=lambda value: label_map.get(value, str(value)),
                    key=store_choice_key,
                    label_visibility="collapsed",
                )
                selected_store_candidate = candidate_by_id.get(str(choice))
                if manual_query:
                    st.caption("手入力した食べ物と撮影位置から候補を絞り直しました。")
                else:
                    st.caption("写真の内容と撮影位置から候補を絞っています。正しければ操作不要です。違う場合だけ選び直してください。")

                # v511: keep the experience flow visible immediately after the parent
                # chooses a store. If a comment is already recorded, this CTA can
                # create the card directly. Otherwise it opens the comment recorder
                # directly below this section so the parent does not have to hunt for
                # the next action elsewhere on the page.
                if st.button(
                    "体験を残す",
                    type="primary",
                    use_container_width=True,
                    key=f"experience_store_continue_v511_{signature}",
                ):
                    if transcript and selected_ids:
                        experience_flow_create_requested = True
                    else:
                        st.session_state["_experience_show_audio_v497"] = True
                        st.session_state["_experience_flow_hint_v511"] = "続けて体験の感想を録音してください。"
            elif reason == "no_photo_location":
                st.caption("この写真には利用できる撮影位置情報がないため、お店候補は表示できません。")
            elif reason in {"no_candidates", "no_food_query"}:
                st.caption("撮影場所の近くから一致するお店候補を絞れませんでした。店名は不明のまま体験カードを作れます。")
            elif reason in {"vision_error", "inference_error"}:
                st.caption("お店候補の推定に失敗しました。店名は不明のまま体験カードを作れます。")

    flow_hint = st.session_state.pop("_experience_flow_hint_v511", None)
    if flow_hint:
        st.info(flow_hint)

    if st.session_state.get("_experience_show_audio_v497") or transcript:
        serial = int(st.session_state.get("_experience_draft_serial_v497") or 1)
        audio_file = far_field_audio_input(
            "感想を話す",
            key=f"experience_audio_input_v499_{serial}",
        )
        if audio_file is not None:
            digest = audio_digest(audio_file)
            if digest and digest != str(st.session_state.get("_experience_audio_digest_v497") or ""):
                try:
                    audio_file.seek(0)
                    raw_audio = audio_file.read()
                    audio_file.seek(0)
                    with st.spinner("感想を聞き取っています…"):
                        text_value = transcribe_audio(
                            audio_file,
                            context="東京ぶらり旅で体験した直後の感想です。主に5〜6歳の子どもの発話を、その言い回しを残して聞き取ってください。",
                        )
                    st.session_state["_experience_audio_bytes_v497"] = bytes(raw_audio)
                    st.session_state["_experience_audio_name_v497"] = str(getattr(audio_file, "name", "experience.webm") or "experience.webm")
                    st.session_state["_experience_audio_digest_v497"] = digest
                    st.session_state["_experience_transcript_v497"] = str(text_value or "").strip()
                    transcript = str(text_value or "").strip()
                except Exception as exc:
                    st.error("感想を聞き取れませんでした。もう一度録音してください。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))
        transcript = str(st.session_state.get("_experience_transcript_v497") or "").strip()
        if transcript:
            st.markdown(f"**感想**　「{html.escape(transcript)}」", unsafe_allow_html=True)

    warning = st.session_state.pop("_experience_photo_warning_v497", None)
    if warning:
        st.warning(warning)

    if picker_open:
        st.markdown("#### 写真を選ぶ")
        st.caption("候補は『これまで撮った写真』と同じ一覧です。通常タップは1枚選んで閉じます。長押しすると複数選択できます。")
        if recent_photos:
            per_page=18
            page_count=max(1,math.ceil(len(recent_photos)/per_page))
            page_key="_experience_photo_picker_page_v503"
            try:
                current_page=int(st.session_state.get(page_key) or 0)
            except Exception:
                current_page=0
            current_page=max(0,min(current_page,page_count-1))
            st.session_state[page_key]=current_page
            start_index=current_page*per_page
            visible_photos=recent_photos[start_index:start_index+per_page]
            paths=[str(photo.get("storage_path") or "") for photo in visible_photos]
            try:
                manual_signed=signed_photo_url_map(paths,expires_in=1800)
            except Exception:
                manual_signed={}
            picker_rows=[]
            for photo in visible_photos:
                photo_id=str(photo.get("id") or "")
                if not photo_id:
                    continue
                url=photo_display_url(photo,signed_map=manual_signed,max_px=360,quality=78)
                if not url:
                    continue
                picker_rows.append({
                    "id":photo_id,
                    "src":url,
                    "meta":_experience_captured_label_v497(photo.get("captured_at")),
                    "used":photo_id in used_ids,
                })
            component=_get_experience_photo_multi_component_v503()
            if component is not None and picker_rows:
                result=component(
                    data={
                        "mode":"picker",
                        "photos":picker_rows,
                        "selected_ids":selected_ids,
                        "max_select":EXPERIENCE_MANUAL_PHOTO_MAX_V497,
                    },
                    key=f"experience_photo_picker_v503_{int(st.session_state.get('_experience_draft_serial_v497') or 1)}_{current_page}",
                    on_single_select_change=lambda:None,
                    on_batch_select_change=lambda:None,
                )
                single_payload=getattr(result,"single_select",None) if result is not None else None
                if isinstance(single_payload,dict):
                    token=str(single_payload.get("token") or "")
                    last=str(st.session_state.get("_experience_photo_picker_last_token_v503") or "")
                    photo_id=str(single_payload.get("photo_id") or "")
                    all_ids={str(row.get("id") or "") for row in recent_photos}
                    if token and token!=last and photo_id in all_ids:
                        current=[str(x) for x in st.session_state.get(selected_key,[]) if str(x)]
                        want_selected=bool(single_payload.get("selected"))
                        if want_selected and photo_id not in current:
                            if len(current)<EXPERIENCE_MANUAL_PHOTO_MAX_V497:
                                current.append(photo_id)
                            else:
                                st.session_state["_experience_photo_warning_v497"]=(f"写真は最大{EXPERIENCE_MANUAL_PHOTO_MAX_V497}枚まで選べます。")
                        elif (not want_selected) and photo_id in current:
                            current=[x for x in current if x!=photo_id]
                        st.session_state[selected_key]=current
                        st.session_state["_experience_photo_picker_last_token_v503"]=token
                        st.session_state["_experience_manual_picker_open_v499"]=False
                        st.rerun(scope="app")
                batch_payload=getattr(result,"batch_select",None) if result is not None else None
                if isinstance(batch_payload,dict):
                    token=str(batch_payload.get("token") or "")
                    last=str(st.session_state.get("_experience_photo_picker_last_token_v503") or "")
                    all_ids={str(row.get("id") or "") for row in recent_photos}
                    picked=[]
                    for value in batch_payload.get("selected_ids") or []:
                        photo_id=str(value or "")
                        if photo_id in all_ids and photo_id not in picked:
                            picked.append(photo_id)
                        if len(picked)>=EXPERIENCE_MANUAL_PHOTO_MAX_V497:
                            break
                    if token and token!=last:
                        st.session_state[selected_key]=picked
                        st.session_state["_experience_photo_picker_last_token_v503"]=token
                        st.session_state["_experience_manual_picker_open_v499"]=False
                        st.rerun(scope="app")
            elif picker_rows:
                st.info("写真選択UIを読み込めませんでした。画面を開き直してください。")
            else:
                st.info("このページに表示できる写真がありません。")

            if page_count>1:
                st.caption(f"{current_page+1} / {page_count}ページ　（1ページ18枚）")
                prev_col,next_col=st.columns(2,gap="small")
                with prev_col:
                    if st.button("← 前の写真",use_container_width=True,disabled=current_page<=0,key=f"experience_picker_prev_v503_{current_page}"):
                        st.session_state[page_key]=max(0,current_page-1)
                        st.rerun(scope="app")
                with next_col:
                    if st.button("次の写真 →",use_container_width=True,disabled=current_page>=page_count-1,key=f"experience_picker_next_v503_{current_page}"):
                        st.session_state[page_key]=min(page_count-1,current_page+1)
                        st.rerun(scope="app")
        else:
            st.info("選べる写真がありません。先に写真を撮ってください。")

    can_create = bool(transcript and selected_ids)
    with st.container(key="experience_create_v499"):
        create_clicked = st.button(
            "体験カードを作る",
            type="primary",
            use_container_width=True,
            disabled=not can_create,
            key="experience_create_card_button_v499",
        )
    if not can_create:
        missing = []
        if not transcript:
            missing.append("体験の感想")
        if not selected_ids:
            missing.append("体験の写真")
        if missing:
            st.caption("・".join(missing) + "を用意すると作成できます。")

    if create_clicked or experience_flow_create_requested:
        if not recent_by_id:
            try:
                rows = _experience_photo_library_rows_v503()
                recent_by_id = {
                    str(photo.get("id") or ""): photo
                    for photo in rows
                    if str(photo.get("id") or "")
                }
            except Exception:
                recent_by_id = {}
        photos_for_card = [recent_by_id[x] for x in selected_ids if x in recent_by_id]
        try:
            with st.spinner("体験カードを作っています…"):
                inference_for_card = st.session_state.get("_experience_store_effective_inference_v509")
                if not isinstance(inference_for_card, dict):
                    inference_for_card = st.session_state.get("_experience_store_inference_v505")
                if not isinstance(inference_for_card, dict):
                    inference_for_card = {}
                place_for_card = selected_store_candidate
                if bool(inference_for_card.get("is_food")) and str(st.session_state.get("_experience_store_choice_v505") or "") == "__unknown__":
                    place_for_card = {"force_unknown": True}
                card = create_experience_card_v497(
                    photos_for_card,
                    transcript,
                    audio_bytes=st.session_state.get("_experience_audio_bytes_v497") or b"",
                    audio_name=st.session_state.get("_experience_audio_name_v497") or "experience.webm",
                    place_candidate=place_for_card,
                    compare_category_hint=str(inference_for_card.get("compare_category") or ""),
                    food_label_hint=str(inference_for_card.get("food_label") or ""),
                )
            category = str(card.get("compare_category") or "")
            category_suffix = f"・{category}" if category and category != EXPERIENCE_COMPARE_EXCLUDED_V497 else ""
            _reset_experience_draft_v497()
            st.session_state["_experience_notice_v497"] = f"体験カードを1件保存しました{category_suffix}。"
            st.rerun(scope="app")
        except Exception as exc:
            st.error("体験カードを作成できませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))



def page_experience_v498():
    page_top("📝 体験を残す", "体験の感想と写真から、あとで比べられる体験カードを作ります。")
    _app_css_v473(
        """
        <style>
        .st-key-experience_input_pair_v498 [data-testid="stHorizontalBlock"]{gap:.55rem!important;align-items:stretch!important;}
        .st-key-experience_input_pair_v498 [data-testid="stColumn"]{min-width:0!important;}
        .st-key-experience_input_pair_v498 div.stButton>button{min-height:58px!important;font-weight:800!important;white-space:normal!important;}
        .st-key-experience_create_v498 div.stButton>button{min-height:54px!important;font-size:1.02rem!important;font-weight:850!important;}
        .experience-status-v498{font-size:.76rem;opacity:.72;margin:.20rem 0 .30rem;line-height:1.35;}
        .experience-card-v498{border:1px solid rgba(128,128,128,.16);border-radius:15px;padding:.70rem .76rem;margin:.55rem 0;background:rgba(128,128,128,.035);}
        .experience-card-title-v498{font-size:1.02rem;font-weight:850;line-height:1.32;}
        .experience-card-meta-v498{font-size:.72rem;opacity:.66;margin-top:.18rem;line-height:1.35;}
        .experience-card-comment-v498{font-size:.90rem;font-weight:650;margin-top:.42rem;line-height:1.5;}
        .experience-photo-label-v498{font-size:.67rem;opacity:.68;margin-top:.12rem;line-height:1.3;}
        </style>
        """
    )

    notice = st.session_state.pop("_experience_notice_v497", None)
    if notice:
        st.success(notice)

    owner_token = f"{current_family_key()}::{current_member_key()}"
    if st.session_state.get("_experience_draft_owner_v497") != owner_token:
        _reset_experience_draft_v497()
        st.session_state["_experience_draft_owner_v497"] = owner_token

    try:
        card_state = get_experience_card_state_v497()
        cards = list(card_state.get("cards") or [])
    except Exception as exc:
        cards = []
        st.warning("体験カードの保存状態を読み込めませんでした。")
        with st.expander("保護者向け詳細"):
            st.code(str(exc))

    used_ids = _experience_used_photo_ids_v497(cards)
    transcript = str(st.session_state.get("_experience_transcript_v497") or "").strip()
    photo_fetched = bool(st.session_state.get("_experience_photo_fetched_v498"))
    if not photo_fetched:
        # Ignore any v497 auto-pick left in the Streamlit session. v498 only obtains
        # photos after the parent explicitly presses the photo button.
        st.session_state.pop("_experience_selected_photo_ids_v497", None)
        st.session_state.pop("_experience_auto_pick_done_v497", None)

    selected_ids = [
        str(x) for x in st.session_state.get("_experience_selected_photo_ids_v497", [])
        if str(x)
    ][:EXPERIENCE_MANUAL_PHOTO_MAX_V497] if photo_fetched else []

    photo_clicked = False
    with st.container(key="experience_input_pair_v498"):
        left, right = st.columns(2, gap="small")
        with left:
            if st.button(
                "🎤 体験の感想",
                type="secondary",
                use_container_width=True,
                key="experience_show_audio_button_v498",
            ):
                st.session_state["_experience_show_audio_v497"] = not bool(st.session_state.get("_experience_show_audio_v497"))
            st.markdown(
                f'<div class="experience-status-v498">{"✓ 録音済み" if transcript else "感想を短く録音"}</div>',
                unsafe_allow_html=True,
            )
        with right:
            photo_clicked = st.button(
                "📷 体験の写真",
                type="secondary",
                use_container_width=True,
                key="experience_fetch_photos_button_v498",
            )
            if photo_fetched and selected_ids:
                photo_status = f"✓ {len(selected_ids)}枚 選択済み"
            elif photo_fetched:
                photo_status = "写真を選択してください"
            else:
                photo_status = "押すと最近の写真から自動取得"
            st.markdown(
                f'<div class="experience-status-v498">{html.escape(photo_status)}</div>',
                unsafe_allow_html=True,
            )

    recent_photos = []
    recent_by_id = {}

    def _load_recent_photos_v498():
        try:
            rows = _list_recent_experience_photos_v497()
            return rows, {str(photo.get("id") or ""): photo for photo in rows if str(photo.get("id") or "")}
        except Exception as exc:
            st.warning("最近の写真を読み込めませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))
            return [], {}

    if photo_clicked:
        recent_photos, recent_by_id = _load_recent_photos_v498()
        auto_candidates = [
            photo for photo in recent_photos
            if str(photo.get("id") or "") not in used_ids
        ]
        picked = []
        if auto_candidates:
            with st.spinner("体験の写真を選んでいます…"):
                picked = _auto_pick_experience_photo_ids_v497(auto_candidates)
        st.session_state["_experience_selected_photo_ids_v497"] = picked
        st.session_state["_experience_photo_fetched_v498"] = True
        st.session_state["_experience_auto_pick_done_v497"] = True
        st.session_state["_experience_show_photos_v497"] = not bool(picked)
        photo_fetched = True
        selected_ids = list(picked)
    elif photo_fetched or st.session_state.get("_experience_show_photos_v497"):
        recent_photos, recent_by_id = _load_recent_photos_v498()

    if recent_by_id:
        selected_ids = [
            str(x) for x in st.session_state.get("_experience_selected_photo_ids_v497", [])
            if str(x) in recent_by_id
        ][:EXPERIENCE_MANUAL_PHOTO_MAX_V497]
        st.session_state["_experience_selected_photo_ids_v497"] = selected_ids

    # v498: display obtained photos immediately below the photo button row.
    if photo_fetched:
        selected_photos = [recent_by_id[photo_id] for photo_id in selected_ids if photo_id in recent_by_id]
        if selected_photos:
            paths = [str(photo.get("storage_path") or "") for photo in selected_photos]
            try:
                signed_map = signed_photo_url_map(paths, expires_in=1800)
            except Exception:
                signed_map = {}
            preview_cols = st.columns(min(3, max(1, len(selected_photos))), gap="small")
            for index, photo in enumerate(selected_photos):
                with preview_cols[index % len(preview_cols)]:
                    url = photo_display_url(photo, signed_map=signed_map, max_px=360, quality=76)
                    if url:
                        st.image(url, use_container_width=True)
                    st.markdown(
                        f'<div class="experience-photo-label-v498">{html.escape(_experience_captured_label_v497(photo.get("captured_at")))}</div>',
                        unsafe_allow_html=True,
                    )
            if st.button(
                "写真を選び直す",
                use_container_width=True,
                key="experience_open_manual_photos_v498",
            ):
                st.session_state["_experience_show_photos_v497"] = not bool(st.session_state.get("_experience_show_photos_v497"))
                st.rerun(scope="app")
        elif recent_photos:
            st.caption("体験に合う写真を自動で特定できませんでした。下から写真を選んでください。")
        else:
            st.info("最近の写真がありません。先に写真を撮ってから体験カードを作成してください。")

    if st.session_state.get("_experience_show_audio_v497") or transcript:
        serial = int(st.session_state.get("_experience_draft_serial_v497") or 1)
        audio_file = far_field_audio_input(
            "感想を話す",
            key=f"experience_audio_input_v498_{serial}",
        )
        if audio_file is not None:
            digest = audio_digest(audio_file)
            if digest and digest != str(st.session_state.get("_experience_audio_digest_v497") or ""):
                try:
                    audio_file.seek(0)
                    raw_audio = audio_file.read()
                    audio_file.seek(0)
                    with st.spinner("感想を聞き取っています…"):
                        text_value = transcribe_audio(
                            audio_file,
                            context="東京ぶらり旅で体験した直後の感想です。主に5〜6歳の子どもの発話を、その言い回しを残して聞き取ってください。",
                        )
                    st.session_state["_experience_audio_bytes_v497"] = bytes(raw_audio)
                    st.session_state["_experience_audio_name_v497"] = str(getattr(audio_file, "name", "experience.webm") or "experience.webm")
                    st.session_state["_experience_audio_digest_v497"] = digest
                    st.session_state["_experience_transcript_v497"] = str(text_value or "").strip()
                    transcript = str(text_value or "").strip()
                except Exception as exc:
                    st.error("感想を聞き取れませんでした。もう一度録音してください。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))
        transcript = str(st.session_state.get("_experience_transcript_v497") or "").strip()
        if transcript:
            st.markdown(f"**感想**　「{html.escape(transcript)}」", unsafe_allow_html=True)

    warning = st.session_state.pop("_experience_photo_warning_v497", None)
    if warning:
        st.warning(warning)

    if st.session_state.get("_experience_show_photos_v497"):
        if not recent_photos:
            recent_photos, recent_by_id = _load_recent_photos_v498()
        st.markdown("#### 写真を選ぶ")
        st.caption("自動選択が違う場合だけ変更してください。使用済み写真も手動では再利用できます。")
        if recent_photos:
            paths = [str(photo.get("storage_path") or "") for photo in recent_photos[:18]]
            try:
                manual_signed = signed_photo_url_map(paths, expires_in=1800)
            except Exception:
                manual_signed = {}
            for start in range(0, min(18, len(recent_photos)), 3):
                cols = st.columns(3, gap="small")
                for offset, col in enumerate(cols):
                    pos = start + offset
                    if pos >= min(18, len(recent_photos)):
                        continue
                    photo = recent_photos[pos]
                    photo_id = str(photo.get("id") or "")
                    with col:
                        url = photo_display_url(photo, signed_map=manual_signed, max_px=300, quality=74)
                        if url:
                            st.image(url, use_container_width=True)
                        used_label = "・使用済み" if photo_id in used_ids else ""
                        st.caption(f"{_experience_captured_label_v497(photo.get('captured_at'))}{used_label}")
                        is_selected = photo_id in selected_ids
                        st.button(
                            "✓ 選択中" if is_selected else "選ぶ",
                            type="primary" if is_selected else "secondary",
                            use_container_width=True,
                            key=f"experience_pick_photo_v498_{photo_id}",
                            on_click=_toggle_experience_photo_v497,
                            args=(photo_id,),
                        )

    can_create = bool(transcript and selected_ids)
    with st.container(key="experience_create_v498"):
        create_clicked = st.button(
            "体験カードを作る",
            type="primary",
            use_container_width=True,
            disabled=not can_create,
            key="experience_create_card_button_v498",
        )
    if not can_create:
        missing = []
        if not transcript:
            missing.append("体験の感想")
        if not selected_ids:
            missing.append("体験の写真")
        if missing:
            st.caption("・".join(missing) + "を用意すると作成できます。")

    if create_clicked:
        if not recent_by_id:
            recent_photos, recent_by_id = _load_recent_photos_v498()
        photos_for_card = [recent_by_id[x] for x in selected_ids if x in recent_by_id]
        try:
            with st.spinner("体験カードを作っています…"):
                card = create_experience_card_v497(
                    photos_for_card,
                    transcript,
                    audio_bytes=st.session_state.get("_experience_audio_bytes_v497") or b"",
                    audio_name=st.session_state.get("_experience_audio_name_v497") or "experience.webm",
                )
            category = str(card.get("compare_category") or "")
            category_suffix = f"・{category}" if category and category != EXPERIENCE_COMPARE_EXCLUDED_V497 else ""
            _reset_experience_draft_v497()
            st.session_state["_experience_notice_v497"] = f"体験カードを保存しました{category_suffix}。"
            st.rerun(scope="app")
        except Exception as exc:
            st.error("体験カードを作成できませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    if cards:
        st.divider()
        st.markdown("#### これまでの体験カード")
        card_paths = []
        for card in cards[:8]:
            paths = list(card.get("photo_storage_paths") or [])
            if paths:
                card_paths.append(paths[0])
        try:
            card_signed = signed_photo_url_map(card_paths, expires_in=1800) if card_paths else {}
        except Exception:
            card_signed = {}
        for card in cards[:8]:
            first_path = next(iter(card.get("photo_storage_paths") or []), "")
            image_col, text_col = st.columns([.82, 2.18], gap="small")
            with image_col:
                if first_path:
                    url = card_signed.get(first_path) or photo_display_url({"storage_path": first_path}, signed_map=card_signed, max_px=320, quality=74)
                    if url:
                        st.image(url, use_container_width=True)
            with text_col:
                category = str(card.get("compare_category") or EXPERIENCE_COMPARE_EXCLUDED_V497)
                place = str(card.get("place_name") or "不明")
                item_name = str(card.get("item_name") or "不明")
                if str(card.get("experience_type") or "") == "おやつ":
                    headline = f"{place}　{category if category != EXPERIENCE_COMPARE_EXCLUDED_V497 else 'おやつ'}"
                else:
                    headline = f"{place}　{category if category != EXPERIENCE_COMPARE_EXCLUDED_V497 else str(card.get('experience_type') or '体験')}"
                item_line = f"商品名：{item_name}" if str(card.get("experience_type") or "") == "おやつ" else ""
                st.markdown(
                    f"""
                    <div class="experience-card-v498">
                      <div class="experience-card-title-v498">{html.escape(headline)}</div>
                      <div class="experience-card-meta-v498">{html.escape(str(card.get('trip_date') or ''))}{('　' + html.escape(item_line)) if item_line else ''}</div>
                      <div class="experience-card-comment-v498">「{html.escape(str(card.get('child_comment') or ''))}」</div>
                    </div>
                    """,
                    unsafe_allow_html=True,
                )

