_VIDEO_LIBRARY_GRID_JS = r"""
export default function(component) {
  const { parentElement, data, setTriggerValue } = component;
  const grid = parentElement.querySelector('#video-library-grid');
  if (!grid) return;

  grid.replaceChildren();
  const videos = Array.isArray(data?.videos) ? data.videos.slice(0, 9) : [];

  for (let index = 0; index < 9; index += 1) {
    const video = videos[index];
    if (!video) {
      const empty = document.createElement('div');
      empty.className = 'video-library-empty';
      grid.appendChild(empty);
      continue;
    }

    const id = String(video.id || '');
    const card = document.createElement('div');
    card.className = 'video-library-card';

    const openButton = document.createElement('button');
    openButton.type = 'button';
    openButton.className = 'video-library-open';
    openButton.setAttribute('aria-label', `${String(video.title || '動画')}を見る`);

    const imageWrap = document.createElement('div');
    imageWrap.className = 'video-library-image-wrap';
    if (video.src) {
      const img = document.createElement('img');
      img.src = String(video.src);
      img.alt = '動画サムネイル';
      img.loading = 'lazy';
      img.decoding = 'async';
      img.fetchPriority = 'low';
      imageWrap.appendChild(img);
    } else {
      const placeholder = document.createElement('div');
      placeholder.className = 'video-library-placeholder';
      placeholder.textContent = '動画';
      imageWrap.appendChild(placeholder);
    }

    const play = document.createElement('div');
    play.className = 'video-library-play';
    play.textContent = '▶';
    imageWrap.appendChild(play);

    const info = document.createElement('div');
    info.className = 'video-library-info';

    const title = document.createElement('div');
    title.className = 'video-library-title';
    title.textContent = String(video.title || '');
    info.appendChild(title);

    const meta = document.createElement('div');
    meta.className = 'video-library-meta';
    meta.textContent = String(video.meta || '');
    info.appendChild(meta);

    const status = document.createElement('div');
    status.className = 'video-library-status';
    status.textContent = String(video.status || '');
    info.appendChild(status);

    openButton.appendChild(imageWrap);
    openButton.appendChild(info);
    openButton.addEventListener('click', () => {
      if (id) setTriggerValue('open_video_id', id);
    });

    const deleteButton = document.createElement('button');
    deleteButton.type = 'button';
    deleteButton.className = 'video-library-delete';
    deleteButton.textContent = '×';
    deleteButton.setAttribute('aria-label', `${String(video.title || '動画')}を削除`);
    deleteButton.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (id) setTriggerValue('delete_video_id', id);
    });

    card.appendChild(openButton);
    card.appendChild(deleteButton);
    grid.appendChild(card);
  }
}
"""

video_library_grid_component = None
_video_library_grid_component_initialized = False


def _get_video_library_grid_component():
    global video_library_grid_component, _video_library_grid_component_initialized
    if _video_library_grid_component_initialized:
        return video_library_grid_component
    _video_library_grid_component_initialized = True
    try:
        video_library_grid_component = st.components.v2.component(
            "tokyo_burari_video_library_grid_v128",
            html=_VIDEO_LIBRARY_GRID_HTML,
            css=_VIDEO_LIBRARY_GRID_CSS,
            js=_perf_instrument_js_v466(_VIDEO_LIBRARY_GRID_JS),
        )
    except Exception:
        video_library_grid_component = None
    return video_library_grid_component


def page_videos():
    delete_notice = st.session_state.pop("_video_delete_notice", None)
    if delete_notice:
        st.success(delete_notice)

    page_top(
        "🎞️ 動画保管庫",
        "保存された元動画を3×3で確認できます。動画を押すと再生、右上の×で削除できます。",
    )

    try:
        videos = list_member_videos_for_moments(limit=500)
    except Exception as exc:
        st.error("動画保管庫を読み込めませんでした。")
        with st.expander("保護者向け詳細"):
            st.code(str(exc))
        return

    _render_vault_usage_v468(len(videos))

    repair_notice = st.session_state.pop("_video_storage_repair_notice", None)
    if repair_notice:
        st.success(repair_notice)
    _render_video_storage_repair_panel(len(videos))

    if not videos:
        st.info("DBに登録された動画はありません。上の「Storage実体を確認」で、未登録の動画が残っていないか確認できます。")
        return

    batch_failures = st.session_state.pop("_video_batch_delete_failures", None)
    if batch_failures:
        with st.expander("削除できなかった動画の詳細"):
            for title, detail in list(batch_failures):
                st.write(f"・{title}")
                st.code(detail)

    render_video_batch_delete_controls(videos)

    # Nine videos per page keeps the vault as an exact 3×3 grid on both desktop
    # and mobile. The custom component never collapses the three columns.
    per_page = 9
    page_count = max(1, (len(videos) + per_page - 1) // per_page)
    page_key = "_video_library_grid_page"
    try:
        current_page = int(st.session_state.get(page_key) or 0)
    except Exception:
        current_page = 0
    current_page = max(0, min(current_page, page_count - 1))
    st.session_state[page_key] = current_page

    start_index = current_page * per_page
    visible_videos = videos[start_index:start_index + per_page]
    cards = []
    poster_paths = [str(v.get("storage_path") or "").strip() for v in visible_videos]
    try:
        poster_urls = signed_photo_url_map(poster_paths)
    except Exception:
        poster_urls = {}
    for local_index, video_row in enumerate(visible_videos):
        metadata = photo_media_metadata(video_row)
        size_value = max(0, int(metadata.get("video_size_bytes") or 0))
        duration_ms = max(0, int(metadata.get("video_duration_ms") or 0))
        detail_parts = []
        if duration_ms:
            detail_parts.append(f"{max(1, round(duration_ms / 1000))}秒")
        if size_value:
            detail_parts.append(format_storage_size(size_value))

        selection = metadata.get("ai_selection") or {}
        status_label = ""
        if isinstance(selection, dict):
            status = video_ai_effective_status(video_row)
            if status == "processing":
                stage = str(selection.get("stage") or "").strip().lower()
                status_label = "✨ 30FPS解析を準備中" if stage == "candidate_preparation" else "✨ いい瞬間を解析中"
            elif status in {"", "waiting_candidates"}:
                status_label = "✨ 自動処理を開始待ち"
            elif status == "ready":
                status_label = "✨ いい瞬間を確認できます"
            elif status == "reviewed":
                status_label = "✓ いい瞬間を確認済み"
            elif status == "error":
                status_label = "AI選定は未完了"

        poster_path = str(video_row.get("storage_path") or "").strip()
        preview_url = photo_display_url(video_row, signed_map=poster_urls)
        if not preview_url and poster_path:
            try:
                preview_url = thumbnail_photo_data_url(poster_path, max_px=520, quality=82)
            except Exception:
                preview_url = ""

        cards.append(
            {
                "id": str(video_row.get("id") or ""),
                "src": preview_url,
                "title": _moments_video_title(video_row),
                "meta": " ／ ".join(detail_parts),
                "status": status_label,
            }
        )

    grid_component = _get_video_library_grid_component()
    handled_action = False
    if grid_component is not None:
        serial_key = "_video_library_grid_serial"
        serial = int(st.session_state.get(serial_key) or 0)
        result = grid_component(
            data={"videos": cards},
            key=f"video_library_grid_{current_page}_{serial}_{_current_ui_refresh_epoch()}",
            on_open_video_id_change=lambda: None,
            on_delete_video_id_change=lambda: None,
        )
        open_video_id = str(getattr(result, "open_video_id", None) or "").strip()
        delete_video_id = str(getattr(result, "delete_video_id", None) or "").strip()

        if delete_video_id:
            target = next((row for row in visible_videos if str(row.get("id") or "") == delete_video_id), None)
            if target:
                st.session_state[serial_key] = serial + 1
                show_video_delete_dialog(target)
                handled_action = True
        elif open_video_id:
            target = next((row for row in visible_videos if str(row.get("id") or "") == open_video_id), None)
            if target:
                metadata = photo_media_metadata(target)
                detail_parts = []
                duration_ms = max(0, int(metadata.get("video_duration_ms") or 0))
                size_value = max(0, int(metadata.get("video_size_bytes") or 0))
                if duration_ms:
                    detail_parts.append(f"{max(1, round(duration_ms / 1000))}秒")
                if size_value:
                    detail_parts.append(format_storage_size(size_value))
                st.session_state[serial_key] = serial + 1
                show_video_library_dialog(target, _moments_video_title(target), " ／ ".join(detail_parts))
                handled_action = True
    else:
        # Fallback for older Streamlit runtimes. Keep three columns and place an ×
        # control at the upper-right area of each card.
        for row_start in range(0, per_page, 3):
            row_columns = st.columns(3, gap="small")
            for offset in range(3):
                item_index = row_start + offset
                with row_columns[offset]:
                    if item_index >= len(visible_videos):
                        st.write("")
                        continue
                    video_row = visible_videos[item_index]
                    card = cards[item_index]
                    _, delete_col = st.columns([5, 1], gap="small")
                    with delete_col:
                        if st.button(
                            "×",
                            key=f"video_fallback_delete_{current_page}_{item_index}_{video_row.get('id')}",
                            help="この動画を削除",
                        ):
                            show_video_delete_dialog(video_row)
                    if card.get("src"):
                        st.image(card["src"], use_container_width=True)
                    st.caption(card.get("title") or "")
                    if st.button(
                        "見る",
                        use_container_width=True,
                        key=f"video_fallback_open_{current_page}_{item_index}_{video_row.get('id')}",
                    ):
                        show_video_library_dialog(video_row, card.get("title") or "", card.get("meta") or "")

    if page_count > 1 and not handled_action:
        st.caption(f"{current_page + 1} / {page_count}ページ　（1ページ9本）")
        prev_col, next_col = st.columns(2, gap="small")
        with prev_col:
            if st.button(
                "← 前の9本",
                use_container_width=True,
                disabled=current_page <= 0,
                key=f"video_grid_prev_{current_page}",
            ):
                st.session_state[page_key] = max(0, current_page - 1)
                st.rerun()
        with next_col:
            if st.button(
                "次の9本 →",
                use_container_width=True,
                disabled=current_page >= page_count - 1,
                key=f"video_grid_next_{current_page}",
            ):
                st.session_state[page_key] = min(page_count - 1, current_page + 1)
                st.rerun()


def page_moments():
    delete_notice = st.session_state.pop("_video_delete_notice", None)
    if delete_notice:
        st.success(delete_notice)

    page_top(
        "✨ いい瞬間",
        "AIが切り出した写真を、動画1本ずつ確認します。",
    )

    notice = st.session_state.pop("_moments_notice", None)
    if notice:
        st.success(notice)
    bulk_delete_detail = st.session_state.pop("_moments_bulk_delete_error_detail", None)
    if bulk_delete_detail:
        with st.expander("削除できなかった動画の詳細"):
            st.code(str(bulk_delete_detail))

    try:
        videos = list_member_videos_for_moments(limit=300)
    except Exception as exc:
        st.error("動画の一覧を読み込めませんでした。")
        with st.expander("保護者向け詳細"):
            st.code(str(exc))
        return

    if not videos:
        st.info("まだ動画がありません。動画を撮影すると、保存後にAIがいい瞬間を探します。")
        return

    pending, ready, reviewed = [], [], []
    for video in videos:
        selection = photo_media_metadata(video).get("ai_selection") or {}
        if not isinstance(selection, dict):
            selection = {}
        status = video_ai_effective_status(video)
        if status == "reviewed":
            reviewed.append(video)
        elif status == "ready" and video_ai_selection_items(video):
            ready.append(video)
        else:
            pending.append(video)

    st.markdown("**使い方**　①写真を見る → ②残したい写真に気持ち・声を付ける → ③日記に残す")
    st.caption(f"確認待ち {len(ready)}本　／　処理中 {len(pending)}本　／　確認済み {len(reviewed)}本")

    mode_options = []
    if ready or pending:
        mode_options.append("これから確認")
    if reviewed:
        mode_options.append("確認済みを見る")
    if not mode_options:
        st.info("現在表示できるいい瞬間はありません。")
        return

    mode_key = "_moments_page_mode_v387"
    if st.session_state.get(mode_key) not in mode_options:
        st.session_state[mode_key] = mode_options[0]
    if len(mode_options) > 1:
        mode = st.radio(
            "表示する動画",
            mode_options,
            horizontal=True,
            key=mode_key,
            label_visibility="collapsed",
        )
    else:
        mode = mode_options[0]
        st.session_state[mode_key] = mode

    if mode == "これから確認":
        if ready:
            index_key = "_moments_ready_index_v387"
            try:
                ready_index = int(st.session_state.get(index_key) or 0)
            except Exception:
                ready_index = 0
            ready_index = max(0, min(ready_index, len(ready) - 1))
            st.session_state[index_key] = ready_index
            current_video = ready[ready_index]

            st.divider()
            st.markdown("### いま確認する動画")
            if len(ready) > 1:
                nav_left, nav_center, nav_right = st.columns([1, 1.35, 1], gap="small")
                with nav_left:
                    if st.button(
                        "← 前の動画",
                        use_container_width=True,
                        disabled=ready_index <= 0,
                        key=f"moments_ready_prev_v506_{ready_index}_{len(ready)}",
                    ):
                        st.session_state[index_key] = max(0, ready_index - 1)
                        st.rerun()
                with nav_center:
                    st.markdown(
                        f'<div style="text-align:center;padding:.65rem 0;font-weight:800;">{ready_index + 1} / {len(ready)}本</div>',
                        unsafe_allow_html=True,
                    )
                with nav_right:
                    if st.button(
                        "次の動画 →",
                        use_container_width=True,
                        disabled=ready_index >= len(ready) - 1,
                        key=f"moments_ready_next_v506_{ready_index}_{len(ready)}",
                    ):
                        st.session_state[index_key] = min(len(ready) - 1, ready_index + 1)
                        st.rerun()
            else:
                st.caption("1 / 1本")
            st.caption(_moments_video_title(current_video))
            _render_moments_picker(current_video, ready_index)

            if st.button(
                "今回は写真を残さない",
                use_container_width=True,
                key=f"moments_no_choice_v387_{current_video.get('id')}",
            ):
                try:
                    with st.spinner("この動画を確認済みにしています…"):
                        record_video_ai_no_choice(current_video)
                    st.session_state[index_key] = 0
                    st.session_state["_moments_notice"] = "この動画では写真を残さず、次の動画へ進みました。"
                    st.rerun()
                except Exception as exc:
                    st.error("確認済みにできませんでした。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))

            render_video_delete_controls(
                current_video,
                f"moments_ready_delete_{current_video.get('id')}",
                begin_label="🗑 いい瞬間を残さず動画を削除",
                confirm_label="写真を残さず削除",
                success_message="候補写真を残さず、動画を削除しました。",
            )
        else:
            st.info("確認できる写真は現在ありません。AIの切り取り処理が終わるとここに表示されます。")

        if pending:
            st.divider()
            with st.expander(f"処理中の動画を見る（{len(pending)}本）"):
                for idx, video in enumerate(pending[:20], start=1):
                    selection = photo_media_metadata(video).get("ai_selection") or {}
                    status = str((selection or {}).get("status") or "").lower()
                    label = "処理中" if status != "error" else "エラー"
                    st.write(f"{idx}. {_moments_video_title(video)}　— {label}")
                    focus_error = str((selection or {}).get("last_error") or "")
                    if status == "error" and focus_error.startswith("ピント"):
                        st.warning(focus_error)
                    if status == "error" and _video_ai_reroll_pending_v596(selection):
                        st.warning("新しい100枚を作成できませんでした。前の候補は表示していません。")
                        if st.button("もう一度作成する", key=f"moments_retry_reroll_v596_{video.get('id')}"):
                            try:
                                request_video_ai_reroll(video, record_rejection=False)
                                st.session_state["_moments_notice"] = "新しい100枚を作成しています。"
                                st.rerun()
                            except Exception as exc:
                                st.error("再作成を開始できませんでした。")
                                st.code(_safe_error_text(exc, 240))
                    render_video_delete_controls(
                        video,
                        f"moments_pending_delete_{video.get('id')}_{idx}",
                        begin_label="🗑 この動画を削除",
                        confirm_label="処理を止めて削除",
                        success_message="切り抜き処理を止め、動画を削除しました。",
                    )
                if st.button("状態を更新", use_container_width=True, key="moments_pending_refresh_v387"):
                    st.rerun()
        return

    # Reviewed mode: keep management separate from the main review flow and show
    # only one video at a time, which is both clearer and much lighter on mobile.
    if reviewed:
        st.divider()
        st.markdown("### 確認済みの動画")
        reviewed_index_key = "_moments_reviewed_repick_index_v387"
        try:
            reviewed_index = int(st.session_state.get(reviewed_index_key) or 0)
        except Exception:
            reviewed_index = 0
        reviewed_index = max(0, min(reviewed_index, len(reviewed) - 1))
        st.session_state[reviewed_index_key] = reviewed_index

        nav_left, nav_center, nav_right = st.columns([1, 1.6, 1], gap="small")
        with nav_left:
            if st.button("← 前", use_container_width=True, disabled=reviewed_index <= 0, key="moments_reviewed_prev_v387"):
                st.session_state[reviewed_index_key] = max(0, reviewed_index - 1)
                st.rerun()
        with nav_center:
            st.markdown(
                f'<div style="text-align:center;padding:.65rem 0;font-weight:800;">{reviewed_index + 1} / {len(reviewed)}本</div>',
                unsafe_allow_html=True,
            )
        with nav_right:
            if st.button("次 →", use_container_width=True, disabled=reviewed_index >= len(reviewed) - 1, key="moments_reviewed_next_v387"):
                st.session_state[reviewed_index_key] = min(len(reviewed) - 1, reviewed_index + 1)
                st.rerun()

        current_reviewed = reviewed[reviewed_index]
        st.caption(_moments_video_title(current_reviewed))
        _render_moments_picker(current_reviewed, 1000 + reviewed_index)
        render_video_delete_controls(
            current_reviewed,
            f"moments_reviewed_delete_{current_reviewed.get('id')}",
            begin_label="🗑 この元動画を削除",
            confirm_label="元動画を削除",
            success_message="元動画を削除しました。日記に残した写真はそのままです。",
        )

        st.divider()
        with st.expander("確認済み動画の整理"):
            bulk_delete_key = "_moments_delete_all_reviewed_confirm_v387"
            if not st.session_state.get(bulk_delete_key):
                if st.button(
                    "🗑 確認済みの元動画を一斉削除",
                    use_container_width=True,
                    key="moments_delete_all_reviewed_begin_v387",
                ):
                    st.session_state[bulk_delete_key] = True
                    st.rerun()
            else:
                delete_col, cancel_col = st.columns([1.35, .85], gap="small")
                with delete_col:
                    if st.button("一斉削除する", type="primary", use_container_width=True, key="moments_delete_all_reviewed_yes_v387"):
                        deleted, failures = 0, []
                        with st.spinner("確認済み動画を削除しています…"):
                            for reviewed_video in list(reviewed):
                                try:
                                    delete_video_and_related_data(reviewed_video)
                                    deleted += 1
                                except Exception as exc:
                                    failures.append(f"{_moments_video_title(reviewed_video)}: {_safe_error_text(exc, 240)}")
                        st.session_state.pop(bulk_delete_key, None)
                        st.session_state[reviewed_index_key] = 0
                        if failures:
                            st.session_state["_moments_notice"] = f"確認済み動画を{deleted}本削除しました。{len(failures)}本は削除できませんでした。"
                            st.session_state["_moments_bulk_delete_error_detail"] = "\n".join(failures[:12])
                        else:
                            st.session_state["_moments_notice"] = f"確認済み動画{deleted}本を一斉削除しました。日記に残した写真はそのままです。"
                        reload_current_page_after_action()
                with cancel_col:
                    if st.button("やめる", use_container_width=True, key="moments_delete_all_reviewed_no_v387"):
                        st.session_state.pop(bulk_delete_key, None)
                        st.rerun()


def render_diary_title_editor(trip_id, current_title, key_prefix):
    """Show the rename text field only after an explicit user action.

    v450 keeps ordinary diary review completely free of text inputs, so Android does
    not reopen or retain the software keyboard just because a saved day is displayed.
    """
    editor_key = f"_diary_title_editor_open_v450_{trip_id}"
    if not st.session_state.get(editor_key):
        if st.button(
            "✏️ 日記の名前を変更",
            use_container_width=True,
            key=f"{key_prefix}_title_open_v450_{trip_id}",
        ):
            st.session_state[editor_key] = True
            st.rerun()
        return

    with st.container(border=True):
        st.markdown("##### ✏️ 日記の名前を変更")
        with st.form(f"{key_prefix}_title_form_v450_{trip_id}", clear_on_submit=False, border=False):
            edited_title = st.text_input(
                "日記の名前",
                value=str(current_title or ""),
                key=f"{key_prefix}_title_input_v450_{trip_id}",
            )
            save_col, cancel_col = st.columns(2, gap="small")
            with save_col:
                save_title_clicked = st.form_submit_button("保存", type="primary", use_container_width=True)
            with cancel_col:
                cancel_title_clicked = st.form_submit_button("やめる", use_container_width=True)

        if cancel_title_clicked:
            st.session_state.pop(editor_key, None)
            st.rerun()

        if save_title_clicked:
            try:
                saved_title = update_diary_title(trip_id, edited_title)
                st.session_state.preferred_diary_trip_id = trip_id
                st.session_state.pop(editor_key, None)
                st.session_state["_diary_notice"] = f"日記の名前を「{saved_title}」に変更しました。"
                st.rerun()
            except Exception as exc:
                st.error("日記の名前を変更できませんでした。")
                with st.expander("保護者向け詳細"):
                    st.code(str(exc))


def _select_diary_trip_v452(trip_id):
    """Persist the selected saved diary day before a full-page rerun."""
    selected = str(trip_id or "").strip()
    st.session_state.preferred_diary_trip_id = selected or None
    st.session_state.pop("_pending_diary_open_trip_id", None)
    # Clear transient per-day drill-down state so the newly selected day opens at its
    # photo gallery instead of inheriting a detail/photo state from the previous day.
    for key in list(st.session_state.keys()):
        key_text = str(key)
        if key_text.startswith((
            "diary_talk_photo_",
            "diary_selected_photo_",
            "diary_existing_photo_view_",
        )):
            st.session_state.pop(key, None)


@st.dialog("振り返る日を選ぶ")
def render_diary_day_picker_v452(ids, label_map, selected_trip_id=None):
    """Button-only day picker that closes into a full Diary rerun after selection."""
    current = str(selected_trip_id or "").strip()
    for value in ids or []:
        trip_id = str(value or "").strip()
        if not trip_id:
            continue
        label = str((label_map or {}).get(trip_id) or trip_id)
        button_label = f"✓ {label}" if trip_id == current else label
        if st.button(
            button_label,
            type="primary" if trip_id == current else "secondary",
            use_container_width=True,
            key=f"diary_day_picker_v452_{trip_id}",
        ):
            _select_diary_trip_v452(trip_id)
            # st.dialog is a fragment: an ordinary button interaction reruns only the
            # dialog. Force a full-app rerun so page_diary recomputes trip_id/photos and
            # the dialog closes with the selected day's gallery visible immediately.
            st.rerun()


@st.fragment
def render_recent_camera_photo_emotion(trip):
    """Show the latest saved media; still photos can be tagged by tapping the image."""
    trip_id = (trip or {}).get("id")
    if not trip_id:
        return
    recent_key = f"_camera_recent_photo_{trip_id}"
    photo_id = st.session_state.get(recent_key)
    if not photo_id:
        return

    photos = list_trip_photos(trip_id)
    photo = next((p for p in photos if p.get("id") == photo_id), None)
    if not photo:
        st.session_state.pop(recent_key, None)
        return

    st.divider()
    is_video = photo_is_video(photo)
    st.markdown("#### 今撮った動画" if is_video else "#### 今撮った写真")
    if is_video:
        if not render_saved_media_preview(
            photo,
            image_alt="今撮った動画の代表画像",
            delete_key_prefix="recent_camera",
        ):
            st.warning("撮影した動画のプレビューを表示できませんでした。")
        return

    location_label = photo_location_label(photo)

    path = str(photo.get("storage_path") or "")
    signed = signed_photo_url_map((path,)) if path else {}
    src = photo_display_url(photo, signed, max_px=720, quality=82)
    card = {
        "id": str(photo_id),
        "src": src,
        "emotion": photo_selected_tag_values(photo)[0],
        "parenting": photo_selected_tag_values(photo)[1],
        "location": str(location_label or ""),
        "shared": photo_family_share_is_enabled(photo),
        "favorite": photo_favorite_is_enabled(photo),
    }
    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None:
        serial_key = f"recent_emotion_serial_{photo_id}"
        serial = int(st.session_state.get(serial_key) or 0)
        result = gallery_component(
            data={"photos": [card], "single": True, "allow_delete": True, "allow_emotion": True, "allow_share": True, "allow_favorite": True, "mode_by_photo": st.session_state.get(f"_recent_icon_modes_{photo_id}") or {}, "family_key": current_family_key(), "member_key": current_member_key(), "pending_param": PENDING_EMOTION_QUERY_PARAM},
            key=f"recent_emotion_{photo_id}_{serial}_{_current_ui_refresh_epoch()}",
            on_delete_photo_id_change=lambda: None,
            on_share_photo_change=lambda: None,
            on_favorite_photo_change=lambda: None,
        )
        if handle_photo_family_share_event(result, [str(photo_id)], serial_key=serial_key):
            return
        if handle_photo_favorite_event(result, [str(photo_id)], serial_key=serial_key):
            return
        delete_clicked = str(getattr(result, "delete_photo_id", "") or "")
        if delete_clicked == str(photo_id):
            st.session_state[serial_key] = serial + 1
            confirm_photo_delete_dialog(
                trip_id,
                photo_id,
                photos=photos,
                is_pending=True,
                trip=trip,
            )
        return

    # Fallback for runtimes without Streamlit v2 components.
    if src:
        meta = photo_selected_tag_meta(photo)
        border = meta.get("color") or "#AEB6C2"
        emoji = meta.get("emoji") or ""
        badge = (
            f'<span style="position:absolute;right:10px;bottom:10px;background:rgba(255,255,255,.90);border-radius:999px;padding:3px 6px;font-size:22px;">{emoji}</span>'
            if emoji else ""
        )
        st.markdown(
            f'<div style="position:relative;padding:5px;border:3px solid {border};border-radius:14px;max-width:360px;margin:0 auto;">'
            f'<img src="{html.escape(src, quote=True)}" style="display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:9px;" />{badge}</div>',
            unsafe_allow_html=True,
        )
    render_enlarged_photo_favorite_control(photo, f"recent_photo_favorite_v424_{trip_id}")
    if st.button("写真の気持ちを次へ", use_container_width=True, key=f"recent_emotion_fallback_{photo_id}"):
        update_photo_emotion(photo_id, next_photo_emotion_key(photo_emotion_key(photo)), trip_id=trip_id)
        st.rerun()


# ============================================================
# Gallery import duplicate markers (v444)
# ============================================================
def gallery_import_marker_payload_v444(max_items=5000):
    """Return compact identifiers for gallery photos already imported by this member."""
    cache_key = _account_cache_key("gallery_import_markers_v444", int(max_items))
    cached = _session_cache_get(cache_key, max_age_seconds=30)
    if isinstance(cached, dict):
        return cached
    identity_hashes = set()
    fingerprints = set()
    try:
        rows = list_member_still_photos_for_tags(max_items=max_items)
    except Exception:
        rows = []
    for row in rows:
        if not isinstance(row, dict) or photo_is_video(row):
            continue
        reflection = row.get("reflection_json") or {}
        if not isinstance(reflection, dict):
            continue
        if str(reflection.get("capture_source") or "") not in {"gallery", "gallery_batch"}:
            continue
        meta = reflection.get("import_metadata") or {}
        if not isinstance(meta, dict):
            continue
        fingerprint = str(meta.get("source_fingerprint") or "").strip()
        if fingerprint:
            fingerprints.add(fingerprint[:100])
        name = str(meta.get("original_name") or "").strip().lower()
        source = str(meta.get("capture_time_source") or "").strip()
        raw = str(meta.get("capture_time_raw") or "").strip()
        if name and source and raw:
            identity = f"{name}|{source}|{raw}"
            identity_hashes.add(hashlib.sha256(identity.encode("utf-8", errors="ignore")).hexdigest()[:24])
    payload = {"identity_hashes": sorted(identity_hashes), "fingerprints": sorted(fingerprints)}
    return _session_cache_set(cache_key, payload)


# ============================================================
# Page: Trip / camera
# ============================================================
def page_trip(*, gallery_inline=False):
    if not gallery_inline:
        st.button("←", key="camera_back_parent", help="1つ前の階層に戻る",
                  on_click=_navigate_to_parent_callback)

    notice = st.session_state.pop("_camera_notice", None)
    if notice:
        st.success(notice)
    camera_warning = st.session_state.pop("_camera_warning_v507", None)
    if camera_warning:
        st.warning(camera_warning)
    batch_error = st.session_state.pop("_camera_batch_error_v441", None)
    if batch_error:
        with st.expander("保存できなかった写真の詳細"):
            st.code(str(batch_error))
    if not gallery_inline:
        render_photo_family_share_notice()
        render_photo_favorite_notice()

    gallery_only = gallery_inline or bool(st.session_state.get("_camera_gallery_only_v601"))
    if gallery_only and not gallery_inline:
        st.markdown("### 🖼️ すでに撮った写真から選ぶ（複数可）")
        st.caption("写真を選んで確認し、保存してください。手動登録では過去の撮影日も選べます。")
    camera_component = _get_live_camera_component()
    if camera_component is None:
        st.error("ライブカメラ機能に必要なStreamlitのバージョンが古いです。requirements.txtを更新してください。")
        return

    auto_start = False if gallery_inline else bool(st.session_state.pop("_camera_auto_start", False))
    auto_start_video = False if gallery_inline else bool(st.session_state.pop("_camera_auto_start_video", False))
    prepare_video_now = False if gallery_inline else bool(st.session_state.pop("_camera_prepare_video_v394", False))
    entry_mode = "photo" if gallery_inline else str(st.session_state.get("_camera_entry_mode_v394") or "photo")
    needs_video_setup = bool(auto_start_video or prepare_video_now or entry_mode == "video")
    active_snapshot = st.session_state.get("_active_trip_snapshot")
    if not isinstance(active_snapshot, dict) or active_snapshot.get("trip_date") != today_iso() or active_snapshot.get("status") != "active":
        active_snapshot = None

    # Photo mode avoids every video-only network call. Video capacity and its signed
    # upload destination are prepared only after the user requests video.
    video_capacity = {
        "allowed": False,
        "message": "動画を選んだときに保存先を準備します。",
        "remaining_bytes": None,
    }
    video_unavailable_reason = "prepare_on_demand"
    video_reservation = {}
    video_allowed = False
    video_capacity_message = str(video_capacity["message"])
    camera_trip = active_snapshot
    if needs_video_setup:
        try:
            video_capacity = video_recording_capacity_status()
            video_allowed = bool(video_capacity.get("allowed"))
            video_capacity_message = str(video_capacity.get("message") or "")
            if not video_allowed:
                video_unavailable_reason = "quota"
                st.warning(video_capacity_message or "動画の保存容量が不足しています。")
        except Exception as exc:
            video_allowed = False
            video_unavailable_reason = "capacity_check"
            video_capacity_message = "動画の保存容量を確認できないため、動画撮影を一時停止しています。"
            with st.expander("動画容量チェックの詳細"):
                st.code(str(exc))

    if needs_video_setup and video_allowed:
        try:
            camera_trip = camera_trip or ensure_today_trip()
            video_reservation = get_camera_video_upload_reservation(
                camera_trip["id"],
                st.session_state.capture_serial,
            )
        except Exception as exc:
            video_allowed = False
            video_unavailable_reason = "storage_setup"
            video_capacity_message = "保存容量ではなく、動画のアップロード先を準備できないため撮影を開始できません。"
            st.error(video_capacity_message)
            st.caption(f"Supabaseキー：{_supabase_secret_key_kind()} / Bucket：{PHOTO_BUCKET}")
            with st.expander("動画保存先の準備エラー", expanded=True):
                st.code(_safe_error_text(exc, 900))

    camera_trip_key = str((camera_trip or {}).get("id") or "pending")
    browser_video_max_bytes = VIDEO_MAX_BYTES
    remaining_for_recording = video_capacity.get("remaining_bytes")
    if remaining_for_recording is not None:
        try:
            browser_video_max_bytes = min(VIDEO_MAX_BYTES, max(0, int(remaining_for_recording)))
        except Exception:
            browser_video_max_bytes = VIDEO_MAX_BYTES
    try:
        gallery_marker_payload_v444 = gallery_import_marker_payload_v444(max_items=5000)
    except Exception:
        gallery_marker_payload_v444 = {"identity_hashes": [], "fingerprints": []}

    result = camera_component(
        data={
            "gallery_only": gallery_only,
            "auto_start": auto_start,
            "auto_start_mode": "video" if auto_start_video else ("photo" if auto_start else ""),
            "video_allowed": video_allowed,
            "video_prepare_available": not needs_video_setup,
            "video_capacity_message": video_capacity_message,
            "video_unavailable_reason": video_unavailable_reason,
            "video_max_bytes": browser_video_max_bytes,
            "video_upload_signed_url": str(video_reservation.get("signed_url") or ""),
            "video_upload_storage_path": str(video_reservation.get("storage_path") or ""),
            "video_upload_fallback_signed_url": str(video_reservation.get("fallback_signed_url") or ""),
            "video_upload_fallback_storage_path": str(video_reservation.get("fallback_storage_path") or ""),
            "video_candidate_sheet_signed_url": str(video_reservation.get("candidate_sheet_signed_url") or ""),
            "video_candidate_sheet_storage_path": str(video_reservation.get("candidate_sheet_path") or ""),
            "gallery_import_identity_hashes": list(gallery_marker_payload_v444.get("identity_hashes") or []),
            "gallery_import_fingerprints": list(gallery_marker_payload_v444.get("fingerprints") or []),
        },
        key=f"{'diary_import_v602' if gallery_inline else 'live_camera_v445'}_{camera_trip_key}_{st.session_state.capture_serial}_{_current_ui_refresh_epoch()}",
        on_photo_change=lambda: None,
        on_photo_batch_change=lambda: None,
        on_video_change=lambda: None,
        on_video_prepare_change=lambda: None,
        on_camera_error_change=lambda: None,
    )

    payload = getattr(result, "photo", None)
    batch_payload = getattr(result, "photo_batch", None)
    video_payload = getattr(result, "video", None)
    video_prepare = getattr(result, "video_prepare", None)
    camera_error = getattr(result, "camera_error", None)

    if isinstance(video_prepare, dict):
        request_token = str(video_prepare.get("requested_at") or "")
        if request_token and request_token != str(st.session_state.get("_camera_video_prepare_token_v394") or ""):
            st.session_state["_camera_video_prepare_token_v394"] = request_token
            # Each explicit photo->video transition gets a fresh one-shot upload path.
            clear_camera_video_upload_reservation()
            st.session_state.capture_serial += 1
            st.session_state["_camera_prepare_video_v394"] = True
            st.session_state["_camera_auto_start_video"] = True
            st.session_state["_camera_entry_mode_v394"] = "video"
            st.rerun(scope="app")

    if camera_error:
        message = camera_error.get("message") if isinstance(camera_error, dict) else str(camera_error)
        detail = str(camera_error.get("detail") or "").strip() if isinstance(camera_error, dict) else ""
        collision_text = f"{message or ''} {detail}".lower()
        storage_collision = any(token in collision_text for token in (
            "keyalreadyexists", "resource already exists", '"duplicate"', "statuscode\":\"409", "storage 409",
        ))
        if storage_collision:
            # The current Blob could not be committed because its one-shot destination
            # had already been consumed. Rotate the reservation immediately so the next
            # recording cannot repeat the same 409 forever.
            clear_camera_video_upload_reservation()
            st.session_state.capture_serial += 1
            st.session_state["_camera_entry_mode_v394"] = "video"
            st.session_state["_camera_auto_start_video"] = True
            st.session_state["_camera_warning_v507"] = (
                "動画の保存先が重複していたため、自動的に新しい保存先へ切り替えました。"
                "直前の動画は保存されていないため、もう一度撮影してください。"
            )
            st.rerun(scope="app")
        if message:
            st.warning(message)
        if isinstance(camera_error, dict):
            if detail and detail not in str(message or ""):
                with st.expander("動画保存エラーの詳細", expanded=True):
                    st.code(detail)

    if (
        isinstance(video_payload, dict)
        and video_payload.get("upload_complete")
        and video_payload.get("video_storage_path")
    ):
        save_stage = "アップロード済み動画の確認"
        video_saved = False
        uploaded_video_path = str(video_payload.get("video_storage_path") or "").strip()
        try:
            reservation = st.session_state.get("_camera_video_upload_reservation_v116")
            if not isinstance(reservation, dict):
                raise ValueError("動画の保存予約を確認できませんでした。")
            reserved_video_path = str(reservation.get("storage_path") or "").strip()
            if uploaded_video_path != reserved_video_path:
                # A Streamlit rerun can recreate the reservation object while the browser
                # is finishing a direct upload. The uploaded path itself was originally
                # minted by this server, so accept it when it is still inside the current
                # signed-in member and trip prefix. This also makes registration resilient
                # to a stale reservation without weakening cross-member isolation.
                safe_prefix = (
                    f"{current_family_key()}/{current_member_key()}/"
                    f"{str(reservation.get('trip_id') or '')}/"
                )
                if not (
                    uploaded_video_path.startswith(safe_prefix)
                    and _storage_path_is_original_video(
                        uploaded_video_path,
                        video_payload.get("mime_type"),
                    )
                ):
                    raise ValueError("動画の保存先が撮影前の予約と一致しません。")

            save_stage = "代表画像の読み込み"
            poster_raw = b""
            try:
                poster_raw = decode_camera_data_url(video_payload.get("poster_data_url"))
            except Exception:
                # The original video is already safely in Storage. If the compact
                # poster value was dropped by the component runtime, reuse the first
                # valid AI still rather than failing the whole video registration.
                for frame_item in video_payload.get("candidate_frames") or []:
                    if not isinstance(frame_item, dict):
                        continue
                    try:
                        poster_raw = decode_camera_data_url(frame_item.get("data_url"))
                    except Exception:
                        poster_raw = b""
                    if poster_raw:
                        break
                # A missing poster must not invalidate an already-uploaded original.
                # register_browser_uploaded_video() creates a neutral placeholder.

            video_size = max(0, int(video_payload.get("video_size_bytes") or 0))
            recording_id = str(video_payload.get("recording_id") or "").strip()
            digest_source = f"{uploaded_video_path}|{video_size}|{recording_id}"
            digest = hashlib.sha1(digest_source.encode("utf-8")).hexdigest()
            digest_key = "saved_camera_video_digest_current"
            if st.session_state.get(digest_key) != digest:
                save_stage = "動画記録の登録"
                trip = ensure_today_trip()
                if str(trip.get("id") or "") != str(reservation.get("trip_id") or ""):
                    raise ValueError("動画の保存先と現在のぶらり旅が一致しません。")
                capture_source = str(video_payload.get("source") or "video_camera")
                location = build_photo_location(
                    video_payload.get("location"),
                    trip,
                    capture_source=capture_source,
                )

                with st.spinner("動画を保管庫に登録しています…"):
                    saved_video = register_browser_uploaded_video(
                        trip["id"],
                        uploaded_video_path,
                        video_size,
                        poster_raw,
                        mime_type=video_payload.get("mime_type"),
                        duration_ms=video_payload.get("duration_ms"),
                        location=location,
                        captured_at=video_payload.get("captured_at"),
                        capture_source=capture_source,
                        capture_width=video_payload.get("capture_width"),
                        capture_height=video_payload.get("capture_height"),
                        capture_frame_rate=video_payload.get("capture_frame_rate"),
                        video_bitrate_bps=video_payload.get("video_bitrate_bps"),
                        has_audio=video_payload.get("has_audio"),
                        audio_bitrate_bps=video_payload.get("audio_bitrate_bps"),
                    )

                video_saved = True
                st.session_state[digest_key] = digest
                if isinstance(saved_video, dict) and saved_video.get("id"):
                    st.session_state[f"_camera_recent_photo_{trip['id']}"] = saved_video["id"]
                    st.session_state[f"_camera_show_recent_v394_{trip['id']}"] = False
                try:
                    _home_video_counts_cached.clear()
                except Exception:
                    pass

                # Legacy compatibility: prefer a browser contact sheet when one exists in
                # the browser while/just after recording. This makes ffmpeg optional.
                ai_status = "queued_recovery"
                if isinstance(saved_video, dict) and saved_video.get("id"):
                    sheet_path = str(video_payload.get("candidate_sheet_path") or "").strip()
                    sheet_manifest = [x for x in (video_payload.get("candidate_manifest") or []) if isinstance(x, dict)]
                    reserved_sheet = str(reservation.get("candidate_sheet_path") or "").strip()
                    if sheet_path and reserved_sheet and sheet_path == reserved_sheet and sheet_manifest:
                        try:
                            saved_video = store_video_ai_candidate_sheet(
                                saved_video,
                                sheet_path,
                                sheet_manifest,
                                columns=video_payload.get("candidate_sheet_columns") or 15,
                                rows=video_payload.get("candidate_sheet_rows") or 0,
                            )
                            ai_status = "queued"
                        except Exception:
                            ai_status = "queued_recovery"
                    if ai_status == "queued_recovery":
                        try:
                            saved_video = mark_video_ai_waiting_candidates(
                                saved_video,
                                "ブラウザ候補を確認できないため、自動復旧を準備しています。",
                            )
                        except Exception:
                            pass

                if ai_status in {"queued", "queued_recovery"} and isinstance(saved_video, dict) and saved_video.get("id"):
                    # The original video is already committed. Queue Good Moments and
                    # immediately return control to the camera/UI; never wait here.
                    try:
                        launch_video_ai_background_job(saved_video)
                    except Exception as background_exc:
                        ai_status = "queued_recovery"
                        try:
                            reflection = dict(photo_media_metadata(saved_video))
                            selection = reflection.get("ai_selection") or {}
                            if not isinstance(selection, dict):
                                selection = {}
                            selection["status"] = "waiting_candidates"
                            selection["stage"] = "candidate_preparation"
                            selection["last_error"] = str(background_exc)[:240]
                            selection["updated_at"] = now_jst().isoformat()
                            selection["pipeline_mode"] = "offline_fixed500ms_max120_v591"
                            reflection["ai_selection"] = selection
                            _write_photo_reflection(saved_video["id"], reflection)
                        except Exception:
                            pass

                previous_count = st.session_state.get("_home_today_photo_count")
                try:
                    previous_count = int(previous_count) if previous_count is not None else 0
                except Exception:
                    previous_count = 0
                st.session_state["_home_today_photo_count"] = previous_count + 1
                place_label = str((location or {}).get("place_label") or trip.get("destination") or "").strip()
                if place_label:
                    st.session_state["_home_today_place"] = place_label

                clear_camera_video_upload_reservation()
                st.session_state["_browser_last_camera_open_at"] = time.time() * 1000.0
                st.session_state["_browser_last_camera_mode"] = "video"
                st.session_state["_camera_entry_mode_v394"] = "photo"
                st.session_state.capture_serial += 1
                if ai_status in {"queued", "queued_recovery"}:
                    notice = "動画を保管庫に保存しました。いい瞬間はバックグラウンドで作成します。操作を続けられます。"
                else:
                    notice = "動画を保管庫に保存しました。いい瞬間を自動で作成しました。"
                st.session_state["_camera_notice"] = notice
                poster_raw = b""
                if isinstance(video_payload, dict):
                    video_payload["poster_data_url"] = ""
                    video_payload["candidate_frames"] = []
                reload_current_page_after_action()
        except Exception as exc:
            if video_saved:
                st.warning("動画本体は保管庫に保存済みです。保存後の処理だけ完了できませんでした。")
            else:
                detail = str(exc).strip().replace("\n", " ")
                if len(detail) > 220:
                    detail = detail[:217] + "..."
                st.error(f"動画を保存できませんでした。処理段階：{save_stage}" + (f" ／ {detail}" if detail else ""))
                # The Blob was already uploaded directly by the browser. Remove it if
                # registration failed, so the next recording can safely reuse the same
                # signed reservation without leaving an orphaned object.
                if uploaded_video_path:
                    try:
                        cleanup_trip_id = str(
                            (reservation.get("trip_id") if isinstance(reservation if 'reservation' in locals() else None, dict) else None)
                            or (camera_trip or {}).get("id")
                            or ""
                        )
                        cleanup_prefix = f"{current_family_key()}/{current_member_key()}/{cleanup_trip_id}/"
                        if (
                            cleanup_trip_id
                            and uploaded_video_path.startswith(cleanup_prefix)
                            and _storage_path_is_original_video(
                                uploaded_video_path,
                                video_payload.get("mime_type"),
                            )
                        ):
                            supabase_client().storage.from_(PHOTO_BUCKET).remove([uploaded_video_path])
                            _invalidate_video_storage_audit_cache()
                    except Exception:
                        pass
            with st.expander("保護者向け詳細"):
                st.code(f"処理段階: {save_stage}\n{exc}")

    if isinstance(batch_payload, dict) and isinstance(batch_payload.get("items"), list):
        batch_items = [item for item in batch_payload.get("items") if isinstance(item, dict) and item.get("data_url")][:20]
        if batch_items:
            batch_id = str(batch_payload.get("batch_id") or "").strip()
            if not batch_id:
                identity = "|".join(
                    f"{str(item.get('name') or '')}:{str(item.get('captured_at') or '')}:{len(str(item.get('data_url') or ''))}"
                    for item in batch_items
                )
                batch_id = hashlib.sha1(identity.encode("utf-8", errors="ignore")).hexdigest()[:24]
            batch_state_key = "_saved_camera_batch_digests_v441"
            batch_state = st.session_state.get(batch_state_key)
            if not isinstance(batch_state, dict):
                batch_state = {}
            already_saved = set(str(x) for x in (batch_state.get(batch_id) or []) if str(x))
            newly_saved = 0
            today_saved_count = 0
            duplicate_count = 0
            failures = []
            last_saved_photo = None
            last_saved_trip = None
            import_trip_cache = {}
            progress_slot = st.empty()
            try:
                for index, item in enumerate(batch_items, start=1):
                    progress_slot.caption(f"写真をまとめて保存しています… {index}/{len(batch_items)}")
                    raw = b""
                    try:
                        raw = decode_camera_data_url(item.get("data_url"))
                        if not raw:
                            raise ValueError("画像データが空です。")
                        digest = hashlib.sha1(raw).hexdigest()
                        if digest in already_saved:
                            duplicate_count += 1
                            item["data_url"] = ""
                            continue
                        capture_source = "gallery_batch"
                        trip = get_or_create_gallery_import_trip_v443(
                            item.get("captured_at"),
                            cache=import_trip_cache,
                        )
                        location = build_photo_location(
                            item.get("location"),
                            trip,
                            capture_source=capture_source,
                        )
                        import_meta = item.get("import_metadata") if isinstance(item.get("import_metadata"), dict) else {}
                        safe_import_meta = {
                            "capture_time_source": str(import_meta.get("capture_time_source") or "")[:60],
                            "capture_time_raw": str(import_meta.get("capture_time_raw") or "")[:80],
                            "capture_time_offset": str(import_meta.get("capture_time_offset") or "")[:20],
                            "original_name": str(import_meta.get("original_name") or "")[:180],
                            "original_type": str(import_meta.get("original_type") or "")[:80],
                            "original_size_bytes": max(0, int(import_meta.get("original_size_bytes") or 0)),
                            "original_last_modified_ms": max(0, int(import_meta.get("original_last_modified_ms") or 0)),
                            "source_fingerprint": str(import_meta.get("source_fingerprint") or "")[:100],
                            "exif_gps": bool(import_meta.get("exif_gps")),
                        }
                        safe_import_meta = {key: value for key, value in safe_import_meta.items() if value not in {"", None, False}}
                        saved_photo = upload_photo(
                            trip["id"],
                            raw,
                            location=location,
                            captured_at=item.get("captured_at"),
                            capture_source=capture_source,
                            extra_reflection={"import_metadata": safe_import_meta} if safe_import_meta else None,
                        )
                        already_saved.add(digest)
                        batch_state[batch_id] = list(already_saved)
                        # Keep only a small number of recent batch receipts in session state.
                        while len(batch_state) > 8:
                            try:
                                batch_state.pop(next(iter(batch_state)))
                            except Exception:
                                break
                        st.session_state[batch_state_key] = batch_state
                        newly_saved += 1
                        if str(trip.get("trip_date") or "") == today_iso():
                            today_saved_count += 1
                        if isinstance(saved_photo, dict) and saved_photo.get("id"):
                            last_saved_photo = saved_photo
                            last_saved_trip = trip
                        item["data_url"] = ""
                    except Exception as item_exc:
                        failures.append(
                            f"{index}枚目（{str(item.get('name') or '写真')}）: {str(item_exc)[:160]}"
                        )
                    finally:
                        raw = b""
            finally:
                progress_slot.empty()

            if newly_saved > 0:
                if (
                    isinstance(last_saved_photo, dict)
                    and last_saved_photo.get("id")
                    and isinstance(last_saved_trip, dict)
                    and last_saved_trip.get("id")
                ):
                    st.session_state[f"_camera_recent_photo_{last_saved_trip['id']}"] = last_saved_photo["id"]
                    st.session_state[f"_camera_show_recent_v394_{last_saved_trip['id']}"] = False
                if today_saved_count > 0:
                    previous_count = st.session_state.get("_home_today_photo_count")
                    try:
                        previous_count = int(previous_count) if previous_count is not None else 0
                    except Exception:
                        previous_count = 0
                    st.session_state["_home_today_photo_count"] = previous_count + today_saved_count
                st.session_state["_browser_last_camera_open_at"] = time.time() * 1000.0
                st.session_state["_browser_last_camera_mode"] = "photo"
                st.session_state["_camera_entry_mode_v394"] = "photo"
                st.session_state.capture_serial += 1

            if failures:
                st.session_state["_camera_notice"] = (
                    f"写真を{newly_saved}枚保存しました。{len(failures)}枚は保存できませんでした。"
                    if newly_saved
                    else f"写真を保存できませんでした（{len(failures)}枚）。"
                )
                st.session_state["_camera_batch_error_v441"] = "\n".join(failures[:10])
            elif newly_saved:
                st.session_state["_camera_notice"] = f"写真を{newly_saved}枚まとめて保存しました。"
            elif duplicate_count:
                st.session_state["_camera_notice"] = "選んだ写真はすでにこの一括保存で処理済みです。"

            for item in batch_items:
                item["data_url"] = ""
            if newly_saved or duplicate_count:
                reload_current_page_after_action()
            elif failures:
                st.error("複数の写真を保存できませんでした。")
                with st.expander("保護者向け詳細"):
                    st.code("\n".join(failures[:10]))

    if isinstance(payload, dict) and payload.get("data_url"):
        try:
            raw = decode_camera_data_url(payload["data_url"])
            digest = hashlib.sha1(raw).hexdigest()
            digest_key = "saved_camera_digest_current"
            if st.session_state.get(digest_key) != digest:
                capture_source = str(payload.get("source") or "camera")
                if capture_source == "gallery":
                    trip = get_or_create_gallery_import_trip_v443(payload.get("captured_at"))
                else:
                    trip = ensure_today_trip()
                location = build_photo_location(
                    payload.get("location"),
                    trip,
                    capture_source=capture_source,
                )

                initial_emotion = normalize_photo_emotion_key(payload.get("emotion"))
                initial_parenting = normalize_parenting_tag_key(payload.get("parenting"))
                if initial_emotion and initial_parenting:
                    # v168 clients send only one; stale clients are normalized to one as well.
                    initial_parenting = ""
                extra_reflection = {}
                if initial_emotion:
                    extra_reflection["emotion"] = photo_emotion_record(
                        initial_emotion,
                        source="child_tap_camera_review_v162",
                    )
                if initial_parenting:
                    extra_reflection["parenting_tag"] = parenting_tag_record(
                        initial_parenting,
                        source="parent_tap_camera_review_v162",
                    )
                import_meta = payload.get("import_metadata") if isinstance(payload.get("import_metadata"), dict) else {}
                if capture_source == "gallery" and import_meta:
                    safe_import_meta = {
                        "capture_time_source": str(import_meta.get("capture_time_source") or "")[:60],
                        "capture_time_raw": str(import_meta.get("capture_time_raw") or "")[:80],
                        "capture_time_offset": str(import_meta.get("capture_time_offset") or "")[:20],
                        "original_name": str(import_meta.get("original_name") or "")[:180],
                        "original_type": str(import_meta.get("original_type") or "")[:80],
                        "original_size_bytes": max(0, int(import_meta.get("original_size_bytes") or 0)),
                        "original_last_modified_ms": max(0, int(import_meta.get("original_last_modified_ms") or 0)),
                        "source_fingerprint": str(import_meta.get("source_fingerprint") or "")[:100],
                        "exif_gps": bool(import_meta.get("exif_gps")),
                    }
                    safe_import_meta = {key: value for key, value in safe_import_meta.items() if value not in {"", None, False}}
                    if safe_import_meta:
                        extra_reflection["import_metadata"] = safe_import_meta
                if not extra_reflection:
                    extra_reflection = None

                with st.spinner("写真を残しています…"):
                    saved_photo = upload_photo(
                        trip["id"],
                        raw,
                        location=location,
                        captured_at=payload.get("captured_at"),
                        capture_source=capture_source,
                        extra_reflection=extra_reflection,
                    )

                st.session_state[digest_key] = digest
                if isinstance(saved_photo, dict) and saved_photo.get("id"):
                    st.session_state[f"_camera_recent_photo_{trip['id']}"] = saved_photo["id"]
                    st.session_state[f"_camera_show_recent_v394_{trip['id']}"] = False

                if str(trip.get("trip_date") or "") == today_iso():
                    previous_count = st.session_state.get("_home_today_photo_count")
                    try:
                        previous_count = int(previous_count) if previous_count is not None else 0
                    except Exception:
                        previous_count = 0
                    st.session_state["_home_today_photo_count"] = previous_count + 1
                    place_label = str((location or {}).get("place_label") or trip.get("destination") or "").strip()
                    if place_label:
                        st.session_state["_home_today_place"] = place_label

                st.session_state["_browser_last_camera_open_at"] = time.time() * 1000.0
                st.session_state["_browser_last_camera_mode"] = "photo"
                st.session_state["_camera_entry_mode_v394"] = "photo"
                st.session_state.capture_serial += 1
                st.session_state["_camera_notice"] = "写真を保存しました。"
                raw = b""
                payload["data_url"] = ""
                reload_current_page_after_action()
        except Exception as exc:
            st.error("写真を保存できませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    if gallery_inline:
        return

    trip = st.session_state.get("_active_trip_snapshot")
    if isinstance(trip, dict) and trip.get("id"):
        recent_id = st.session_state.get(f"_camera_recent_photo_{trip['id']}")
        if recent_id:
            if st.button(
                "今保存した写真・動画を確認",
                use_container_width=True,
                key=f"camera_show_recent_v394_{recent_id}",
            ):
                st.session_state[f"_camera_show_recent_v394_{trip['id']}"] = True
            if st.session_state.get(f"_camera_show_recent_v394_{trip['id']}"):
                render_recent_camera_photo_emotion(trip)

    st.button(
        "🖼️ これまで撮った写真の一覧を見る",
        type="primary",
        use_container_width=True,
        key="camera_open_all_photos_v418",
        on_click=_open_photo_library_callback_v418,
        args=("camera",),
    )


@st.fragment
def render_diary_emotion_gallery(trip_id, photos, trip=None, is_pending=False):
    """Render still photos with emotion editing and an optional saved-diary viewer mode."""
    photos = diary_photos_only(photos)
    if not photos:
        return
    if _sync_moments_metadata_into_saved_photos_v417(photos):
        photos = diary_photos_only(list_trip_photos(trip_id))
    st.markdown("#### この日の写真")
    render_photo_favorite_notice()
    counts, selected = photo_emotion_counts(photos)
    summary = photo_emotion_summary_text(photos)

    # v365: both saved diaries and the pre-diary "この日の写真" view can switch
    # between a compact grid and one-photo enlarged mode. Pending photos keep their
    # editing controls; only the presentation changes.
    if is_pending:
        mode_key = f"diary_pending_photo_view_mode_v365_{trip_id}"
        current_mode = str(st.session_state.get(mode_key) or "").strip()
        if current_mode not in {"一覧モード", "拡大モード"}:
            st.session_state[mode_key] = "一覧モード"
        view_mode = st.radio(
            "写真の表示方法",
            ["一覧モード", "拡大モード"],
            horizontal=True,
            key=mode_key,
            label_visibility="collapsed",
        )
        single_mode = view_mode == "拡大モード"
    else:
        mode_key = f"diary_saved_photo_view_mode_{trip_id}"
        if st.session_state.get(mode_key) == "1枚ずつ拡大":
            st.session_state[mode_key] = "1枚ずつ表示"
        view_mode = st.radio(
            "写真の表示方法",
            ["3列一覧", "1枚ずつ表示"],
            index=1 if len(photos) == 1 else 0,
            horizontal=True,
            key=mode_key,
            label_visibility="collapsed",
        )
        single_mode = view_mode == "1枚ずつ表示"

    # v180: enlarged mode keeps all photos in one browser component. The component
    # swaps the visible card locally and preloads neighboring images, avoiding a rerun
    # for every Previous/Next tap.
    displayed_photos = photos
    paths = tuple(str(photo.get("storage_path") or "") for photo in displayed_photos if photo.get("storage_path"))
    signed = signed_photo_url_map(paths) if paths else {}
    voice_paths = tuple(photo_voice_note_storage_path(photo) for photo in displayed_photos if photo_voice_note_storage_path(photo))
    voice_signed = signed_photo_url_map(voice_paths, expires_in=1800) if voice_paths else {}
    cards = []
    photo_ids = []
    for photo in displayed_photos:
        pid = str(photo.get("id") or "")
        if not pid:
            continue
        cards.append(
            {
                "id": pid,
                "src": photo_display_url(photo, signed, max_px=1400 if single_mode else 520, quality=90 if single_mode else 80),
                "emotion": photo_selected_tag_values(photo)[0],
                "parenting": photo_selected_tag_values(photo)[1],
                "location": str(photo_location_label(photo) or ""),
                "tags": photo_ai_tags(photo)[:12],
                "shared": photo_family_share_is_enabled(photo),
                "favorite": photo_favorite_is_enabled(photo),
                "has_voice": bool(photo_voice_note_storage_path(photo)),
                "voice_url": str(voice_signed.get(photo_voice_note_storage_path(photo)) or ""),
                "voice_transcript": str(photo_voice_note_meta(photo).get("transcript") or ""),
            }
        )
        photo_ids.append(pid)

    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None and cards:
        serial_key = f"diary_emotion_gallery_serial_{trip_id}_{'pending' if is_pending else 'saved'}"
        serial = int(st.session_state.get(serial_key) or 0)
        result = gallery_component(
            data={"photos": cards, "single": single_mode, "allow_delete": True, "allow_batch_delete": bool(is_pending and not single_mode), "allow_emotion": True, "allow_share": True, "allow_voice": bool(single_mode and not is_pending), "allow_voice_preview": bool(single_mode), "allow_favorite": bool(single_mode), "carousel_key": f"diary_saved_{trip_id}", "mode_by_photo": st.session_state.get(f"_diary_icon_modes_{trip_id}") or {}, "family_key": current_family_key(), "member_key": current_member_key(), "pending_param": PENDING_EMOTION_QUERY_PARAM},
            key=f"diary_emotion_gallery_{trip_id}_{serial}_{_current_ui_refresh_epoch()}_{'single' if single_mode else 'grid'}_v365",
            on_delete_photo_id_change=lambda: None,
            on_share_photo_change=lambda: None,
            on_voice_photo_id_change=lambda: None,
            on_favorite_photo_change=lambda: None,
            on_batch_delete_photos_change=lambda: None,
        )
        if handle_photo_family_share_event(result, photo_ids, serial_key=serial_key):
            return
        if handle_photo_favorite_event(result, photo_ids, serial_key=serial_key):
            return
        batch_delete_payload = getattr(result, "batch_delete_photos", None)
        if is_pending and isinstance(batch_delete_payload, dict):
            token = str(batch_delete_payload.get("token") or "")
            last_key = f"_pending_diary_batch_delete_token_v504_{trip_id}"
            last_token = str(st.session_state.get(last_key) or "")
            selected_ids = []
            valid_set = set(photo_ids)
            for value in batch_delete_payload.get("photo_ids") or []:
                photo_id = str(value or "")
                if photo_id in valid_set and photo_id not in selected_ids:
                    selected_ids.append(photo_id)
            if token and token != last_token and selected_ids:
                st.session_state[last_key] = token
                st.session_state[serial_key] = serial + 1
                confirm_pending_photo_batch_delete_dialog_v504(
                    trip_id,
                    selected_ids,
                    photos=photos,
                    trip=trip,
                )
                return
        delete_clicked = str(getattr(result, "delete_photo_id", "") or "")
        if delete_clicked in photo_ids:
            st.session_state[serial_key] = serial + 1
            confirm_photo_delete_dialog(
                trip_id,
                delete_clicked,
                photos=photos,
                is_pending=is_pending,
                trip=trip,
            )
            return

        voice_target_key = f"_diary_saved_voice_photo_target_{trip_id}"
        voice_clicked = str(getattr(result, "voice_photo_id", "") or "")
        if single_mode and not is_pending and voice_clicked in photo_ids:
            st.session_state[voice_target_key] = voice_clicked
            st.session_state[serial_key] = serial + 1
        voice_target = str(st.session_state.get(voice_target_key) or "")
        if single_mode and not is_pending and voice_target in photo_ids:
            target_photo = next((photo for photo in displayed_photos if str(photo.get("id") or "") == voice_target), None)
            if target_photo:
                render_diary_single_photo_voice_editor(trip_id, target_photo, voice_target_key, f"diary_saved_{trip_id}")
        elif not single_mode or is_pending:
            st.session_state.pop(voice_target_key, None)
        return

    # Fallback for old component runtimes.
    fallback_displayed = displayed_photos
    if single_mode and displayed_photos:
        fallback_index_key = f"diary_saved_photo_enlarged_index_{trip_id}"
        try:
            fallback_index = int(st.session_state.get(fallback_index_key) or 0)
        except Exception:
            fallback_index = 0
        fallback_index = max(0, min(fallback_index, len(displayed_photos) - 1))
        prev_col, count_col, next_col = st.columns([1, 1.25, 1], gap="small")
        with prev_col:
            if st.button("◀ 前へ", use_container_width=True, disabled=fallback_index <= 0, key=f"diary_saved_photo_prev_{trip_id}"):
                st.session_state[fallback_index_key] = max(0, fallback_index - 1)
                st.rerun()
        with count_col:
            st.markdown(f'<div style="text-align:center;padding:.55rem .2rem;font-weight:800;">{fallback_index + 1} / {len(displayed_photos)}</div>', unsafe_allow_html=True)
        with next_col:
            if st.button("次へ ▶", use_container_width=True, disabled=fallback_index >= len(displayed_photos) - 1, key=f"diary_saved_photo_next_{trip_id}"):
                st.session_state[fallback_index_key] = min(len(displayed_photos) - 1, fallback_index + 1)
                st.rerun()
        fallback_displayed = [displayed_photos[fallback_index]]
    fallback_columns = 1 if single_mode else 3
    cols = st.columns(fallback_columns, gap="small")
    for index, photo in enumerate(fallback_displayed):
        with cols[index % fallback_columns]:
            src = photo_display_url(photo, signed, max_px=1400 if single_mode else 420, quality=90 if single_mode else 76)
            meta = photo_selected_tag_meta(photo)
            border = meta.get("color") or "#AEB6C2"
            emoji = meta.get("emoji") or ""
            if src:
                badge = (
                    f'<span style="position:absolute;right:7px;bottom:7px;background:rgba(255,255,255,.90);border-radius:999px;padding:2px 5px;font-size:19px;">{emoji}</span>'
                    if emoji else ""
                )
                image_style = "display:block;width:100%;max-height:68vh;object-fit:contain;border-radius:8px;" if single_mode else "display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:8px;"
                favorite = photo_favorite_is_enabled(photo)
                star = "★" if favorite else ("☆" if single_mode else "")
                favorite_badge = (
                    f'<span style="position:absolute;left:8px;top:8px;font-size:22px;color:{"#FFD54A" if favorite else "#FFFFFF"};text-shadow:0 1px 4px rgba(0,0,0,.65);">{star}</span>'
                    if star else ""
                )
                st.markdown(
                    f'<div style="position:relative;padding:4px;border:3px solid {border};border-radius:12px;">'
                    f'<img src="{html.escape(src, quote=True)}" loading="lazy" decoding="async" style="{image_style}" />{badge}{favorite_badge}</div>',
                    unsafe_allow_html=True,
                )
            if single_mode:
                _render_rotation_buttons_v616(photo.get("id"), "diary_fallback_"+str(trip_id)+"_"+str(photo.get("id")))
                favorite = photo_favorite_is_enabled(photo)
                if st.button(
                    "★ お気に入りタグを解除" if favorite else "☆ お気に入りタグに登録",
                    use_container_width=True,
                    key=f"diary_favorite_fallback_{trip_id}_{photo.get('id')}",
                ):
                    set_photo_favorite(photo.get("id"), enabled=not favorite)
                    st.session_state["_photo_favorite_notice"] = "★ お気に入りに追加しました。" if not favorite else "お気に入りを解除しました。"
                    st.rerun()
            if st.button(
                "気持ちを次へ",
                use_container_width=True,
                key=f"emotion_fallback_{trip_id}_{photo.get('id')}_{'pending' if is_pending else 'saved'}_{'single' if single_mode else 'grid'}",
            ):
                update_photo_emotion(
                    photo.get("id"),
                    next_photo_emotion_key(photo_emotion_key(photo)),
                    trip_id=trip_id,
                )
                st.rerun()
            shared = photo_family_share_is_enabled(photo)
            if st.button(
                "✓ 共有中（解除）" if shared else "👨‍👩‍👦 家族に共有",
                use_container_width=True,
                key=f"diary_emotion_share_{trip_id}_{photo.get('id')}_{'pending' if is_pending else 'saved'}_{'single' if single_mode else 'grid'}",
            ):
                set_photo_family_share(photo.get("id"), enabled=not shared)
                st.session_state["_photo_family_share_notice"] = "この写真と選んだ感情を家族に共有しました。" if not shared else "この写真の家族共有を解除しました。"
                st.rerun()
            if st.button(
                "×",
                key=f"diary_emotion_delete_{trip_id}_{photo.get('id')}_{'pending' if is_pending else 'saved'}_{'single' if single_mode else 'grid'}",
                help="この写真を削除",
            ):
                confirm_photo_delete_dialog(
                    trip_id,
                    photo.get("id"),
                    photos=photos,
                    is_pending=is_pending,
                    trip=trip,
                )


    if single_mode and not is_pending and fallback_displayed:
        voice_target_key = f"_diary_saved_voice_photo_target_{trip_id}"
        st.session_state[voice_target_key] = str(fallback_displayed[0].get("id") or "")
        render_diary_single_photo_voice_editor(trip_id, fallback_displayed[0], voice_target_key, f"diary_saved_fallback_{trip_id}")


def render_family_shared_individual_photos():
    """Load family-shared photos only when the user explicitly opens them."""
    open_key = "_family_shared_individual_open_v456"
    if not st.session_state.get(open_key):
        if st.button(
            "👨‍👩‍👦 家族の共有写真",
            use_container_width=True,
            key="family_shared_individual_open_v456",
        ):
            st.session_state[open_key] = True
            st.rerun()
        return False

    if st.button(
        "閉じる",
        use_container_width=True,
        key="family_shared_individual_close_v456",
    ):
        st.session_state.pop(open_key, None)
        st.rerun()

    shared_photos = list_family_shared_photos(limit=90)
    if not shared_photos:
        st.info("共有された写真はありません。")
        return False

    st.markdown(f"#### 👨‍👩‍👦 家族の共有写真（{len(shared_photos)}枚）")
    view_mode = "3列一覧"
    if len(shared_photos) > 1:
        view_mode = st.radio(
            "共有写真の表示モード",
            ["3列一覧", "1枚ずつ拡大"],
            horizontal=True,
            key="family_shared_photo_view_mode_v456",
            label_visibility="collapsed",
        )
    paths = tuple(str(photo.get("storage_path") or "") for photo in shared_photos if photo.get("storage_path"))
    signed = signed_photo_url_map(paths) if paths else {}
    cards = []
    for photo in shared_photos:
        pid = str(photo.get("id") or "")
        if not pid:
            continue
        owner = str(photo.get("_shared_owner_name") or photo.get("_shared_owner_key") or "家族").strip()
        captured = str(photo.get("captured_at") or "").strip()
        captured_label = captured[:10] if len(captured) >= 10 else captured
        tag_meta = photo_selected_tag_meta(photo)
        tag_text = ""
        if tag_meta.get("key"):
            tag_text = f"{tag_meta.get('emoji') or ''} {tag_meta.get('label') or ''}".strip()
        meta_text = f"👨‍👩‍👦 {owner}さん" + (f" ・ {captured_label}" if captured_label else "") + (f" ・ {tag_text}" if tag_text else "")
        cards.append({
            "id": pid,
            "src": photo_display_url(photo, signed, max_px=1400 if view_mode == "1枚ずつ拡大" else 420, quality=90 if view_mode == "1枚ずつ拡大" else 76),
            "emotion": photo_selected_tag_values(photo)[0],
            "parenting": photo_selected_tag_values(photo)[1],
            "emotion_label": str(tag_meta.get("label") or ""),
            "emotion_emoji": str(tag_meta.get("emoji") or ""),
            "emotion_color": str(tag_meta.get("color") or ""),
            "location": str(photo_location_label(photo) or ""),
            "tags": photo_ai_tags(photo)[:12],
            "shared_meta": meta_text,
        })

    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None and cards:
        gallery_component(
            data={
                "photos": cards,
                "single": view_mode == "1枚ずつ拡大",
                "allow_delete": False,
                "allow_emotion": False,
                "allow_share": False,
                "carousel_key": "family_shared_individual_v456",
                "family_key": current_family_key(),
                "member_key": current_member_key(),
                "pending_param": PENDING_EMOTION_QUERY_PARAM,
            },
            key=f"family_shared_individual_photos_v456_{_current_ui_refresh_epoch()}_{'large' if view_mode == '1枚ずつ拡大' else 'grid'}",
        )
    else:
        columns = 1 if view_mode == "1枚ずつ拡大" else 3
        cols = st.columns(columns, gap="small")
        for index, card in enumerate(cards):
            with cols[index % columns]:
                if card.get("src"):
                    border = str(card.get("emotion_color") or "#AEB6C2")
                    emoji = str(card.get("emotion_emoji") or "")
                    label = str(card.get("emotion_label") or "")
                    badge = (
                        f'<span style="position:absolute;right:9px;bottom:9px;background:rgba(255,255,255,.92);border-radius:999px;padding:4px 7px;font-size:16px;font-weight:800;">{html.escape(emoji)} {html.escape(label)}</span>'
                        if emoji or label else ""
                    )
                    st.markdown(
                        f'<div style="position:relative;padding:4px;border:3px solid {html.escape(border, quote=True)};border-radius:12px;">'
                        f'<img src="{html.escape(str(card["src"]), quote=True)}" loading="lazy" decoding="async" style="display:block;width:100%;max-height:70vh;object-fit:contain;border-radius:8px;" />{badge}</div>',
                        unsafe_allow_html=True,
                    )
                st.caption(str(card.get("shared_meta") or ""))
                if card.get("location"):
                    st.caption(f"📍 {card['location']}")
    return True


