def page_photo_library_v418():
    page_top("🖼️ これまで撮った写真")
    render_photo_favorite_notice()
    render_photo_family_share_notice()
    library_delete_notice = st.session_state.pop("_diary_notice", None)
    if library_delete_notice:
        st.success(str(library_delete_notice))
    batch_failures = st.session_state.pop("_photo_library_batch_delete_failures_v514", None)
    if isinstance(batch_failures, list) and batch_failures:
        with st.expander("削除できなかった写真の詳細"):
            for detail in batch_failures:
                st.code(str(detail))
    try:
        photos = list_member_still_photos_for_tags(max_items=5000)
    except Exception as exc:
        st.error("写真の一覧を読み込めませんでした。")
        with st.expander("保護者向け詳細"):
            st.code(str(exc))
        return

    photos = [photo for photo in photos if isinstance(photo, dict) and not photo_is_video(photo)]
    photos.sort(
        key=lambda photo: (str(photo.get("captured_at") or ""), str(photo.get("id") or "")),
        reverse=True,
    )
    if not photos:
        st.info("まだ保存されている写真はありません。")
        return

    st.caption(f"保存している写真：{len(photos)}枚")
    st.caption("写真を長押しすると複数削除モードになります。")

    pending_open = str(st.session_state.pop('_all_photo_library_pending_open_v621', '') or '')
    if pending_open:
        target = next((i for i, row in enumerate(photos) if str(row.get('id') or '') == pending_open), None)
        if target is not None:
            st.session_state['_all_photo_library_enlarged_index_v419'] = target
            st.session_state['_all_photo_library_view_mode_v419'] = '拡大モード'
    mode_key = "_all_photo_library_view_mode_v419"
    current_mode = str(st.session_state.get(mode_key) or "一覧モード")
    if current_mode not in {"一覧モード", "拡大モード"}:
        current_mode = "一覧モード"
        st.session_state[mode_key] = current_mode
    view_mode = st.radio(
        "写真の表示方法",
        ["一覧モード", "拡大モード"],
        horizontal=True,
        key=mode_key,
        label_visibility="collapsed",
    )

    index_key = "_all_photo_library_enlarged_index_v419"
    try:
        enlarged_index = int(st.session_state.get(index_key) or 0)
    except Exception:
        enlarged_index = 0
    enlarged_index = max(0, min(enlarged_index, len(photos) - 1))
    st.session_state[index_key] = enlarged_index

    if view_mode == "拡大モード":
        prev_col, count_col, next_col = st.columns([1, 1.25, 1], gap="small")
        with prev_col:
            if st.button(
                "◀ 前へ",
                use_container_width=True,
                disabled=enlarged_index <= 0,
                key=f"all_photo_enlarged_prev_v419_{enlarged_index}",
            ):
                st.session_state[index_key] = max(0, enlarged_index - 1)
                st.rerun()
        with count_col:
            st.markdown(
                f'<div style="text-align:center;padding:.55rem .2rem;font-weight:800;">{enlarged_index + 1} / {len(photos)}</div>',
                unsafe_allow_html=True,
            )
        with next_col:
            if st.button(
                "次へ ▶",
                use_container_width=True,
                disabled=enlarged_index >= len(photos) - 1,
                key=f"all_photo_enlarged_next_v419_{enlarged_index}",
            ):
                st.session_state[index_key] = min(len(photos) - 1, enlarged_index + 1)
                st.rerun()

        render_photo_library_single_v420(photos[enlarged_index], enlarged_index + 1, len(photos))
        return

    per_page = 18
    page_count = max(1, math.ceil(len(photos) / per_page))
    page_key = "_all_photo_library_page_v418"
    try:
        current_page = int(st.session_state.get(page_key) or 0)
    except Exception:
        current_page = 0
    current_page = max(0, min(current_page, page_count - 1))
    st.session_state[page_key] = current_page

    start = current_page * per_page
    visible = photos[start:start + per_page]
    paths = tuple(str(photo.get("storage_path") or "") for photo in visible if photo.get("storage_path"))
    try:
        signed = signed_photo_url_map(paths, expires_in=1800) if paths else {}
    except Exception:
        signed = {}


    cards = []
    photo_ids = []
    for local_index, photo in enumerate(visible):
        photo_id = str(photo.get("id") or (start + local_index))
        captured_label = _photo_library_captured_label_v418(photo.get("captured_at"))
        has_voice = bool(photo_voice_note_storage_path(photo))
        cards.append({
            "id": photo_id,
            "src": photo_display_url(photo, signed, max_px=420, quality=76),
            "emotion": photo_selected_tag_values(photo)[0],
            "parenting": photo_selected_tag_values(photo)[1],
            "location": str(photo_location_label(photo) or ""),
            "tags": photo_ai_tags(photo)[:12],
            "favorite": photo_favorite_is_enabled(photo),
            "shared": photo_family_share_is_enabled(photo),
            "has_voice": has_voice,
            "shared_meta": f"{captured_label}{' ・ 🎙 声あり' if has_voice else ''}",
        })
        photo_ids.append(photo_id)

    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None and cards:
        serial_key = f"all_photo_library_controls_serial_v425_{current_page}"
        serial = int(st.session_state.get(serial_key) or 0)
        result = gallery_component(
            data={
                "photos": cards,
                "single": False,
                "allow_delete": True,
                "allow_batch_delete": True,
                "allow_emotion": True,
                "allow_share": True,
                "allow_voice": False,
                "allow_voice_preview": False,
                "allow_favorite": True,
                "open_on_click": True,
                "carousel_key": f"all_photo_library_page_{current_page}_v425",
                "family_key": current_family_key(),
                "member_key": current_member_key(),
                "pending_param": PENDING_EMOTION_QUERY_PARAM,
            },
            key=f"all_photo_library_grid_v425_{current_page}_{serial}_{_current_ui_refresh_epoch()}",
            on_photo_id_change=lambda: None,
            on_delete_photo_id_change=lambda: None,
            on_share_photo_change=lambda: None,
            on_favorite_photo_change=lambda: None,
            on_batch_delete_photos_change=lambda: None,
        )
        if handle_photo_family_share_event(result, photo_ids, serial_key=serial_key):
            return
        if handle_photo_favorite_event(result, photo_ids, serial_key=serial_key):
            return

        batch_delete_payload = getattr(result, "batch_delete_photos", None)
        if isinstance(batch_delete_payload, dict):
            token = str(batch_delete_payload.get("token") or "")
            last_key = f"_photo_library_batch_delete_token_v514_{current_page}"
            last_token = str(st.session_state.get(last_key) or "")
            selected_batch_ids = []
            valid_set = set(photo_ids)
            for value in batch_delete_payload.get("photo_ids") or []:
                photo_id = str(value or "")
                if photo_id in valid_set and photo_id not in selected_batch_ids:
                    selected_batch_ids.append(photo_id)
            if token and token != last_token and selected_batch_ids:
                st.session_state[last_key] = token
                st.session_state[serial_key] = serial + 1
                confirm_photo_library_batch_delete_dialog_v514(
                    selected_batch_ids,
                    photos=visible,
                )
                return

        delete_clicked = str(getattr(result, "delete_photo_id", "") or "")
        if delete_clicked in photo_ids:
            selected_photo = next(
                (row for row in visible if str(row.get("id") or "") == delete_clicked),
                None,
            )
            selected_trip_id = str((selected_photo or {}).get("trip_id") or "")
            if selected_trip_id:
                try:
                    trip_photos = list_trip_photos(selected_trip_id)
                except Exception:
                    trip_photos = None
                try:
                    delete_is_pending = not bool(get_diary_for_trip(selected_trip_id))
                except Exception:
                    delete_is_pending = False
                st.session_state[serial_key] = serial + 1
                confirm_photo_delete_dialog(
                    selected_trip_id,
                    delete_clicked,
                    photos=trip_photos,
                    is_pending=delete_is_pending,
                )
            else:
                st.warning("この写真の保存情報を確認できないため、削除できませんでした。")
            return

        clicked = str(getattr(result, "photo_id", "") or "")
        if clicked in photo_ids:
            _photo_library_queue_open_v621(clicked)
            st.rerun()
    else:
        # Fallback for older component runtimes. Keep three columns where supported.
        for row_start in range(0, len(visible), 3):
            cols = st.columns(3, gap="small")
            for offset in range(3):
                local_index = row_start + offset
                if local_index >= len(visible):
                    continue
                photo = visible[local_index]
                absolute_index = start + local_index
                photo_id = str(photo.get("id") or absolute_index)
                with cols[offset]:
                    src = photo_display_url(photo, signed, max_px=420, quality=76)
                    if src:
                        meta = photo_selected_tag_meta(photo)
                        border = str(meta.get("color") or "#AEB6C2")
                        emoji = str(meta.get("emoji") or "")
                        voice_badge = "🎙" if photo_voice_note_storage_path(photo) else ""
                        badges = " ".join(x for x in (emoji, voice_badge) if x)
                        badge_html = (
                            f'<span style="position:absolute;right:6px;bottom:6px;background:rgba(255,255,255,.92);'
                            f'border-radius:999px;padding:2px 5px;font-size:16px;box-shadow:0 2px 6px rgba(0,0,0,.18);">{html.escape(badges)}</span>'
                            if badges else ""
                        )
                        st.markdown(
                            f'<div style="position:relative;padding:3px;border:3px solid {html.escape(border, quote=True)};border-radius:11px;">'
                            f'<img src="{html.escape(src, quote=True)}" loading="lazy" decoding="async" '
                            f'style="display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:7px;" />{badge_html}</div>',
                            unsafe_allow_html=True,
                        )
                    if st.button(
                        "拡大",
                        use_container_width=True,
                        key=f"all_photo_open_fallback_v420_{current_page}_{photo_id}",
                        on_click=_photo_library_queue_open_v621,
                        args=(photo_id,),
                    ):
                        st.rerun()

    if page_count > 1:
        st.caption(f"{current_page + 1} / {page_count}ページ　（1ページ最大18枚）")
        prev_col, next_col = st.columns(2, gap="small")
        with prev_col:
            if st.button(
                "← 前の写真",
                use_container_width=True,
                disabled=current_page <= 0,
                key=f"all_photo_prev_v418_{current_page}",
            ):
                st.session_state[page_key] = max(0, current_page - 1)
                st.rerun()
        with next_col:
            if st.button(
                "次の写真 →",
                use_container_width=True,
                disabled=current_page >= page_count - 1,
                key=f"all_photo_next_v418_{current_page}",
            ):
                st.session_state[page_key] = min(page_count - 1, current_page + 1)
                st.rerun()



