def _open_gallery_import_v601():
    st.session_state["_camera_gallery_only_v601"] = True
    st.session_state["_camera_entry_mode_v394"] = "photo"
    for key in ("_camera_auto_start", "_camera_auto_start_video", "_camera_prepare_video_v394"):
        st.session_state.pop(key, None)
    _set_page_state("camera", history_mode="push")


def page_diary():
    # Remove transient state from the retired comment/conversation UI. Historical
    # data stays in Supabase for compatibility, but v149 never asks for comments.
    st.session_state.pop("_pending_diary_open_trip_id", None)
    for key in list(st.session_state.keys()):
        key_text = str(key)
        if key_text.startswith("diary_talk_photo_") or key_text.startswith("diary_selected_photo_") or key_text.startswith("reflection_state_"):
            st.session_state.pop(key, None)

    # v443 repair: v441/v442 preserved the real captured_at timestamp but still attached
    # gallery imports to today's trip. Repair only undiarized mismatches once per session.
    repair_notice = st.session_state.pop("_gallery_import_date_repair_notice_v443", None)
    if not st.session_state.get("_gallery_import_date_repair_done_v443"):
        st.session_state["_gallery_import_date_repair_done_v443"] = True
        try:
            repair_result = repair_misdated_gallery_imports_v443()
            moved = int((repair_result or {}).get("moved") or 0)
            if moved > 0:
                st.session_state["_gallery_import_date_repair_notice_v443"] = (
                    f"過去に取り込んだ写真 {moved}枚を、写真の撮影日ごとのぶらり旅へ整理しました。"
                )
                st.rerun()
        except Exception:
            pass

    page_top("📖 日記")
    if repair_notice:
        st.success(str(repair_notice))
    notice = st.session_state.pop("_diary_notice", None)
    if notice:
        st.success(notice)
    batch_failures = st.session_state.pop("_pending_diary_batch_delete_failures_v504", None)
    if isinstance(batch_failures, list) and batch_failures:
        with st.expander("削除できなかった写真の詳細"):
            for detail in batch_failures:
                st.code(str(detail))
    render_photo_family_share_notice()
    render_photo_tag_notices()

    st.button(
        "🖼️ これまで撮った写真の一覧を見る",
        type="primary",
        use_container_width=True,
        key="diary_open_all_photos_v418",
        on_click=_open_photo_library_callback_v418,
        args=("diary",),
    )
    # Share the original image-screen file input, preview, batch selection,
    # duplicate handling and save handlers. No intermediate navigation or new picker.
    page_trip(gallery_inline=True)

    render_family_shared_individual_photos()

    recent_rows, pending_rows = _diary_overview_v468()
    saved_titles = [
        str((row.get("diary") or {}).get("title") or "").strip()
        for row in recent_rows
        if str((row.get("diary") or {}).get("title") or "").strip()
    ]

    if pending_rows:
        st.markdown("#### まだ日記になっていない写真")
        pending_titles = pending_diary_titles(pending_rows, used_titles=saved_titles)
        for item in pending_rows:
            pending_trip = item.get("trip") or {}
            pending_photos = diary_photos_only(item.get("photos") or [])
            pending_id = str(pending_trip.get("id") or "")
            if not pending_id or not pending_photos:
                continue
            pending_title = pending_titles.get(pending_id) or diary_title_for_trip(pending_trip, pending_photos)
            emotion_counts, emotion_selected = photo_emotion_counts(pending_photos)
            st.markdown(
                f"**{html.escape(str(pending_trip.get('trip_date') or ''))}　{html.escape(pending_title)}**　・ 写真 {len(pending_photos)}枚"
            )
            render_diary_emotion_gallery(
                pending_id,
                pending_photos,
                trip=pending_trip,
                is_pending=True,
            )
            if st.button(
                "📖 この写真で日記を作る",
                type="primary",
                use_container_width=True,
                key=f"create_pending_diary_{pending_id}",
            ):
                try:
                    with st.spinner("未タグ写真にはAIタグを付けて、日記を保存しています…"):
                        create_and_save_diary_from_photos(
                            pending_trip,
                            pending_photos,
                            requested_title=pending_title,
                            reason="diary_page_pending_button_v149",
                        )
                    if st.session_state.get("active_trip_id") == pending_id:
                        st.session_state.active_trip_id = None
                        _invalidate_active_trip_snapshot()
                    st.session_state.preferred_diary_trip_id = pending_id
                    st.session_state["_diary_notice"] = "日記を作成して保存しました。"
                    st.rerun()
                except Exception as exc:
                    st.error("日記を作成できませんでした。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))
            st.divider()

    diary_map = {
        str((row.get("diary") or {}).get("trip_id") or ""): row.get("diary") or {}
        for row in recent_rows
        if (row.get("diary") or {}).get("trip_id")
    }
    trips = [row.get("trip") or {} for row in recent_rows if (row.get("trip") or {}).get("id")]
    if not trips:
        if not pending_rows:
            st.info("まだ日記はありません。")
        return

    # v451: The day picker is always newest-first regardless of database/list return order.
    trips = sorted(
        trips,
        key=lambda t: (
            str((t or {}).get("trip_date") or ""),
            str((t or {}).get("started_at") or ""),
            str((t or {}).get("id") or ""),
        ),
        reverse=True,
    )
    ids = [str(t["id"]) for t in trips]
    trip_map = {str(t["id"]): t for t in trips}
    label_map = {
        trip_id_value: f"{trip_map[trip_id_value].get('trip_date', '')}　"
        f"{diary_display_title(diary_map.get(trip_id_value), trip_map[trip_id_value], photos=None)}"
        for trip_id_value in ids
    }
    preferred = str(st.session_state.get("preferred_diary_trip_id") or "").strip()
    trip_id = preferred if preferred in ids else None

    # v450: Streamlit selectbox is searchable and focuses a text input on Android,
    # which can leave the software keyboard covering the diary while reviewing dates.
    # Keep the selected day read-only and open a button-only dialog only when the user
    # explicitly wants to choose another day.
    st.markdown("**振り返る日**")
    if trip_id:
        with st.container(border=True):
            st.markdown(f"**{html.escape(label_map.get(trip_id, trip_id))}**")
    else:
        pass
    if st.button(
        "📅 別の日を選ぶ" if trip_id else "📅 振り返る日を選ぶ",
        use_container_width=True,
        key="diary_open_day_picker_v452",
    ):
        render_diary_day_picker_v452(ids, label_map, selected_trip_id=trip_id)

    if trip_id is None:
        return

    trip_id = str(trip_id)
    trip = trip_map[trip_id]
    photos = diary_photos_only(list_trip_photos(trip_id))
    existing = diary_map.get(trip_id)

    if photos:
        render_ai_photo_tag_action(
            photos,
            key=f"diary_day_{trip_id}",
            scope_label="この日の写真",
        )
        render_diary_emotion_gallery(trip_id, photos, trip=trip, is_pending=False)
    else:
        st.warning("このぶらり旅には写真がありません。")

    render_trip_field_notes(trip)

    if not existing:
        if photos and st.button(
            "📖 この写真で日記を作る",
            type="primary",
            use_container_width=True,
            key=f"create_selected_diary_{trip_id}",
        ):
            try:
                with st.spinner("未タグ写真にはAIタグを付けて、日記を保存しています…"):
                    create_and_save_diary_from_photos(
                        trip,
                        photos,
                        reason="diary_selected_trip_v149",
                    )
                st.session_state.preferred_diary_trip_id = trip_id
                st.session_state["_diary_notice"] = "日記を作成して保存しました。"
                st.rerun()
            except Exception as exc:
                st.error("日記を作成できませんでした。")
                with st.expander("保護者向け詳細"):
                    st.code(str(exc))
        render_diary_delete_controls(trip_id, photos)
        return

    existing_title = diary_display_title(existing, trip, photos=photos)
    st.markdown(
        f"""
        <div class="diary-card">
          <div class="hero-title">{html.escape(existing_title)}</div>
          <div class="big-text">{html.escape(existing.get('diary_text') or '')}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )
    existing_meta = existing.get("ai_meta") or {}

    if photos and st.button(
        "AIにまとめてもらう",
        use_container_width=True,
        key=f"ai_trip_summary_{trip_id}",
    ):
        try:
            with st.spinner("写真と選んだ気持ちを見て、このぶらり旅をまとめています…"):
                summary_result = summarize_burari_from_photos(trip, photos)
                save_burari_ai_summary(trip_id, summary_result)
            st.session_state["_diary_notice"] = "写真と選んだ気持ちからAIのまとめを更新しました。"
            st.rerun()
        except Exception as exc:
            st.error("AIのまとめを作れませんでした。もう一度試してください。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    render_burari_trip_summary(existing_meta)
    render_diary_reflection_summary(existing_meta)
    render_summary_feedback_controls(existing_meta, trip_id, "saved")
    render_diary_title_editor(trip_id, existing_title, "diary_existing")

    if photos and st.button(
        "この日の写真と選んだ気持ちから、日記を作り直す",
        use_container_width=True,
        key=f"recreate_diary_from_emotions_{trip_id}",
    ):
        try:
            with st.spinner("未タグ写真を確認して、日記を作り直しています…"):
                create_and_save_diary_from_photos(
                    trip,
                    photos,
                    requested_title=existing_title,
                    reason="diary_recreate_emotions_v149",
                )
            st.session_state.preferred_diary_trip_id = trip_id
            st.session_state["_diary_notice"] = "写真の気持ちをもとに日記を作り直しました。"
            st.rerun()
        except Exception as exc:
            st.error("日記を作り直せませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    render_diary_delete_controls(trip_id, photos)
    return


def page_history(embedded=False):
    if not embedded:
        page_top("📚 これまでの日記")

    notice = st.session_state.pop("_diary_notice", None)
    if notice:
        st.success(notice)
    render_photo_family_share_notice()
    render_photo_tag_notices()

    rows = list_recent_diaries()
    if not st.session_state.get("history_detail_trip_id"):
        st.button(
            "🏷️ タグから振り返る",
            use_container_width=True,
            key="history_open_tag_review_v456",
            on_click=_go_page_callback,
            args=("review_tag", "push"),
        )

    if not rows:
        st.session_state.pop("history_detail_trip_id", None)
        st.info("まだ日記はありません。")
        return

    detail_trip_id = st.session_state.get("history_detail_trip_id")
    detail_row = next(
        (row for row in rows if row.get("diary", {}).get("trip_id") == detail_trip_id),
        None,
    )
    if detail_trip_id and detail_row is None:
        st.session_state.pop("history_detail_trip_id", None)
        detail_trip_id = None

    # A diary title opens a dedicated detail screen. This makes the bottom
    # navigation unambiguous on a phone: back returns to the history list.
    if detail_row is not None:
        diary = detail_row["diary"]
        trip = detail_row["trip"]
        trip_id = diary["trip_id"]
        photos = diary_photos_only(list_trip_photos(trip_id))
        daily_title = diary_display_title(diary, trip, photos=photos)
        title = f"{trip.get('trip_date', '')}　{daily_title}"

        st.markdown(f"### {html.escape(title)}")
        render_diary_title_editor(trip_id, daily_title, "history_detail")
        render_history_photo_viewer(photos, trip_id)
        st.markdown(
            f"""
            <div class="diary-card">
              <div class="big-text">{html.escape(diary.get('diary_text') or '')}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

        meta = diary.get("ai_meta") or {}
        render_burari_trip_summary(meta)
        render_diary_reflection_summary(meta)
        render_summary_feedback_controls(meta, trip_id, "history")
        emotion_points = meta.get("emotion_points", []) if isinstance(meta, dict) else []
        if emotion_points:
            with st.expander("この振り返りのもとになった気持ち"):
                for point in emotion_points[:4]:
                    st.write("・" + str(point))
        else:
            # Older diaries may still contain pre-v149 comment evidence. Keep it
            # readable for historical compatibility, but new input is emotion-only.
            child_points = meta.get("child_points", []) if isinstance(meta, dict) else []
            if child_points:
                with st.expander("以前のコメント記録"):
                    for point in child_points[:3]:
                        st.write("・" + str(point))

        st.divider()
        back_col, home_col = st.columns(2)
        with back_col:
            with st.container(key="history_back_nav"):
                if st.button(
                    "← 前の画面に戻る",
                    use_container_width=True,
                    key=f"history_back_{trip_id}",
                ):
                    st.session_state.pop("history_detail_trip_id", None)
                    st.rerun()
        with home_col:
            with st.container(key="history_home_nav"):
                st.button(
                    "トップ画面に戻る",
                    use_container_width=True,
                    key=f"history_home_{trip_id}",
                    on_click=_history_home_callback,
                )

        if st.button(
            "🗑 この日記を削除",
            use_container_width=True,
            key=f"history_delete_{trip_id}",
        ):
            confirm_diary_delete_dialog(trip_id, len(photos))
        return

    for row in rows:
        diary = row["diary"]
        trip = row["trip"]
        trip_id = diary["trip_id"]
        # Saved diaries already carry their final title. Avoid one photo query per row.
        daily_title = diary_display_title(diary, trip, photos=None)
        title = f"{trip.get('trip_date', '')}　{daily_title}"
        if st.button(
            title,
            use_container_width=True,
            key=f"history_open_{trip_id}",
        ):
            st.session_state["history_detail_trip_id"] = trip_id
            st.rerun()


def render_monthly_ai_comments(review):
    review = _refresh_dirty_month_on_demand_v468(review)
    if review is None:
        return
    review = review if isinstance(review, dict) else {}
    st.markdown("#### AIからの気づき")
    opening = str(review.get("opening") or "").strip()
    if opening:
        st.markdown(
            f'<div class="monthly-card"><div class="big-text">{html.escape(opening)}</div></div>',
            unsafe_allow_html=True,
        )

    first_question = ""
    for finding in list(review.get("findings", []) or [])[:2]:
        if not isinstance(finding, dict):
            continue
        theme = str(finding.get("theme") or "").strip()
        insight = str(finding.get("evidence") or "").strip()
        if theme:
            st.markdown(f"**{theme}**")
        if insight:
            st.write(insight)
        if not first_question:
            first_question = str(finding.get("ask_child") or "").strip()

    question = first_question or str(review.get("one_question") or "").strip()
    if question:
        st.info(f"ちょっと考えてみる：{question}")

    with st.expander("保護者向けメモ"):
        st.write(review.get("parent_note", ""))
        review_scope_type = str(review.get("_review_scope_type") or "")
        if review_scope_type == "ai_tag":
            tag_display = str(review.get("_tag_label") or review.get("_ai_tag_key") or "選んだAIタグ")
            st.caption(
                f"AIが写真から見える内容を整理した『{tag_display}』タグの写真を、日付・枚数など確認できる範囲で振り返っています。"
                "人物関係・性格・能力などは推測しません。"
            )
        elif review_scope_type == "tag":
            tag_display = str(review.get("_tag_label") or "選んだタグ")
            st.caption(
                f"写真に付けた『{tag_display}』タグの記録を、日付・枚数など確認できる事実の範囲で振り返っています。"
                "性格診断・能力評価・将来予測ではありません。"
            )
        else:
            st.caption(
                "本人が写真ごとに選んだ気持ちの傾向を、断定しすぎない範囲で振り返っています。"
                "性格診断・能力評価・将来予測ではありません。"
            )


