gps_tracker_component_v271 = None
_gps_tracker_component_v271_initialized = False


def _get_gps_tracker_component_v271():
    global gps_tracker_component_v271, _gps_tracker_component_v271_initialized
    if _gps_tracker_component_v271_initialized:
        return gps_tracker_component_v271
    _gps_tracker_component_v271_initialized = True
    try:
        gps_tracker_component_v271 = st.components.v2.component(
            "tokyo_burari_always_gps_v279",
            html=_GPS_TRACKER_HTML,
            css=_GPS_TRACKER_CSS,
            js=_perf_instrument_js_v466(_GPS_TRACKER_JS),
        )
    except Exception:
        gps_tracker_component_v271 = None
    return gps_tracker_component_v271


def _gps_track_prefix(family_key=None, member_key=None):
    family = str(family_key or current_family_key()).strip("/")
    member = str(member_key or current_member_key()).strip("/")
    return f"{family}/{member}/{GPS_TRACK_STORAGE_DIR}".strip("/")


def _gps_track_month_path(month_key, family_key=None, member_key=None):
    safe_month = re.sub(r"[^0-9-]", "", str(month_key or ""))[:7] or now_jst().strftime("%Y-%m")
    return f"{_gps_track_prefix(family_key, member_key)}/{safe_month}.json"


def _coerce_track_point_v271(raw):
    if not isinstance(raw, dict):
        return None
    try:
        lat = float(raw.get("lat")); lon = float(raw.get("lon")); ts_ms = int(float(raw.get("ts_ms")))
    except (TypeError, ValueError):
        return None
    if not (math.isfinite(lat) and math.isfinite(lon) and -90 <= lat <= 90 and -180 <= lon <= 180 and ts_ms > 0):
        return None
    try:
        accuracy = float(raw.get("accuracy_m")) if raw.get("accuracy_m") is not None else None
    except (TypeError, ValueError):
        accuracy = None
    if accuracy is not None and (not math.isfinite(accuracy) or accuracy > max(120.0, GPS_TRACK_MAX_ACCURACY_M * 2.0)):
        return None
    try:
        speed = float(raw.get("speed_mps")) if raw.get("speed_mps") is not None else None
    except (TypeError, ValueError):
        speed = None
    try:
        heading = float(raw.get("heading")) if raw.get("heading") is not None else None
    except (TypeError, ValueError):
        heading = None
    pid = str(raw.get("id") or f"{ts_ms}_{lat:.6f}_{lon:.6f}")[:120]
    source = str(raw.get("source") or "browser_watch").strip().lower()[:40]
    if source not in {"browser_watch", "android_native", "timeline_import"}:
        source = "browser_watch"
    return {
        "id": pid,
        "ts_ms": ts_ms,
        "lat": round(lat, 7),
        "lon": round(lon, 7),
        "accuracy_m": round(accuracy, 1) if isinstance(accuracy, float) and math.isfinite(accuracy) else None,
        "speed_mps": round(speed, 2) if isinstance(speed, float) and math.isfinite(speed) and speed >= 0 else None,
        "heading": round(heading, 1) if isinstance(heading, float) and math.isfinite(heading) else None,
        "session_id": str(raw.get("session_id") or "")[:120],
        "source": source,
    }


def _read_track_month_uncached_v271(month_key, family_key=None, member_key=None):
    path = _gps_track_month_path(month_key, family_key, member_key)
    try:
        raw = supabase_client().storage.from_(GPS_TRACK_BUCKET).download(path)
    except Exception:
        return []
    try:
        payload = json.loads(bytes(raw).decode("utf-8"))
    except Exception:
        return []
    rows = payload.get("points") if isinstance(payload, dict) else payload
    if not isinstance(rows, list):
        return []
    output = []
    for row in rows:
        point = _coerce_track_point_v271(row)
        if point:
            output.append(point)
    return output


@st.cache_data(ttl=45, max_entries=160, show_spinner=False)
def _read_track_month_cached_v271(family_key, member_key, month_key):
    return _read_track_month_uncached_v271(month_key, family_key, member_key)


@st.cache_data(ttl=45, max_entries=32, show_spinner=False)
def _list_track_month_keys_v271(family_key, member_key):
    bucket = supabase_client().storage.from_(GPS_TRACK_BUCKET)
    folder = _gps_track_prefix(family_key, member_key)
    rows = []
    try:
        response = bucket.list(folder, {"limit": 1000, "offset": 0, "sortBy": {"column": "name", "order": "asc"}})
    except TypeError:
        try:
            response = bucket.list(path=folder, options={"limit": 1000, "offset": 0, "sortBy": {"column": "name", "order": "asc"}})
        except Exception:
            response = []
    except Exception:
        response = []
    try:
        rows = _coerce_storage_list_rows(response)
    except Exception:
        rows = response if isinstance(response, list) else []
    months = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        name = str(row.get("name") or "")
        match = re.fullmatch(r"(\d{4}-\d{2})\.json", name)
        if match:
            months.append(match.group(1))
    return tuple(sorted(set(months)))


def _upsert_track_month_v271(month_key, incoming_points):
    family = current_family_key(); member = current_member_key()
    existing = _read_track_month_uncached_v271(month_key, family, member)
    merged = {str(row.get("id") or ""): row for row in existing if row.get("id")}
    unchanged = bool(existing)
    for raw in incoming_points or []:
        point = _coerce_track_point_v271(raw)
        if point:
            if merged.get(point["id"]) != point:
                unchanged = False
            merged[point["id"]] = point
    if unchanged:
        return len(merged)
    points = sorted(merged.values(), key=lambda x: (int(x.get("ts_ms") or 0), str(x.get("id") or "")))
    document = {
        "version": 1,
        "month": str(month_key),
        "family_key": str(family),
        "member_key": str(member),
        "updated_at": now_jst().isoformat(),
        "points": points,
    }
    blob = json.dumps(document, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    path = _gps_track_month_path(month_key, family, member)
    bucket = supabase_client().storage.from_(GPS_TRACK_BUCKET)
    options = {"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0", "upsert": "true"}
    first_error = None
    try:
        bucket.upload(path=path, file=blob, file_options=options)
    except Exception as exc:
        first_error = exc
        try:
            bucket.update(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0"})
        except Exception:
            # Very old storage SDKs can lack upsert/update support. Replace only as
            # the final compatibility fallback; accepted points are still retained in
            # browser localStorage until the server acknowledges this batch.
            try:
                bucket.remove([path])
            except Exception:
                pass
            try:
                bucket.upload(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0"})
            except Exception:
                raise first_error
    return len(points)


@st.cache_resource(show_spinner=False)
def _gps_sync_runtime_v561():
    """One bounded background writer for legacy/browser GPS persistence.

    The UI thread never waits for monthly Storage download/rewrite. A completed ACK is
    harvested on a later natural Streamlit run; until then the device/browser keeps the
    points locally, so a restart remains lossless and idempotent by point id.
    """
    return {
        "lock": threading.RLock(),
        "executor": ThreadPoolExecutor(max_workers=1, thread_name_prefix="burari-gps-save"),
        "owners": {},
    }


def _read_track_month_for_owner_v561(client, month_key, family_key, member_key):
    path = _gps_track_month_path(month_key, family_key, member_key)
    try:
        raw = client.storage.from_(GPS_TRACK_BUCKET).download(path)
        payload = json.loads(bytes(raw).decode("utf-8"))
    except Exception:
        return []
    rows = payload.get("points") if isinstance(payload, dict) else payload
    if not isinstance(rows, list):
        return []
    output = []
    for row in rows:
        point = _coerce_track_point_v271(row)
        if point:
            output.append(point)
    return output


def _upsert_track_month_for_owner_v561(client, family_key, member_key, month_key, incoming_points):
    existing = _read_track_month_for_owner_v561(client, month_key, family_key, member_key)
    merged = {str(row.get("id") or ""): row for row in existing if row.get("id")}
    unchanged = bool(existing)
    for raw in incoming_points or []:
        point = _coerce_track_point_v271(raw)
        if point:
            if merged.get(point["id"]) != point:
                unchanged = False
            merged[point["id"]] = point
    if unchanged:
        return len(merged)
    points = sorted(merged.values(), key=lambda x: (int(x.get("ts_ms") or 0), str(x.get("id") or "")))
    document = {
        "version": 1, "month": str(month_key), "family_key": str(family_key),
        "member_key": str(member_key), "updated_at": now_jst().isoformat(), "points": points,
    }
    blob = json.dumps(document, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    path = _gps_track_month_path(month_key, family_key, member_key)
    bucket = client.storage.from_(GPS_TRACK_BUCKET)
    options = {"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0", "upsert": "true"}
    first_error = None
    try:
        bucket.upload(path=path, file=blob, file_options=options)
    except Exception as exc:
        first_error = exc
        try:
            bucket.update(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0"})
        except Exception:
            try:
                bucket.remove([path])
            except Exception:
                pass
            try:
                bucket.upload(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0"})
            except Exception:
                raise first_error
    return len(points)


def _gps_sync_worker_v561(family_key, member_key, batch):
    received_at_ms = int(time.time() * 1000)
    raw_points = list((batch or {}).get("points") or [])[:GPS_TRACK_BATCH_MAX_POINTS]
    source = str((batch or {}).get("source") or "browser_or_legacy")[:80]
    token = str((batch or {}).get("token") or "")
    cleaned = []
    for raw in raw_points:
        point = _coerce_track_point_v271(raw)
        if point:
            cleaned.append(point)
    if not cleaned:
        return {"status": "no_valid_points", "at_ms": received_at_ms, "source": source, "token": token,
                "received": len(raw_points), "accepted": 0, "ack_ms": 0, "months": 0}
    by_month = {}
    for point in cleaned:
        try:
            dt = datetime.fromtimestamp(float(point["ts_ms"]) / 1000.0, ZoneInfo(APP_TIMEZONE))
        except Exception:
            continue
        by_month.setdefault(dt.strftime("%Y-%m"), []).append(point)
    from supabase import create_client
    client = create_client(SUPABASE_URL, SUPABASE_SECRET_KEY)
    for month_key, rows in by_month.items():
        _upsert_track_month_for_owner_v561(client, family_key, member_key, month_key, rows)
    return {
        "status": "saved", "at_ms": int(time.time() * 1000), "source": source, "token": token,
        "received": len(raw_points), "accepted": len(cleaned),
        "ack_ms": max(int(p.get("ts_ms") or 0) for p in cleaned),
        "min_ts_ms": min(int(p.get("ts_ms") or 0) for p in cleaned),
        "months": len(by_month),
    }


def _gps_sync_enqueue_v561(batch):
    runtime = _gps_sync_runtime_v561()
    owner = (current_family_key(), current_member_key())
    token = str((batch or {}).get("token") or "")
    with runtime["lock"]:
        state = runtime["owners"].setdefault(owner, {"future": None, "token": "", "queued": None, "queued_token": ""})
        future = state.get("future")
        if future is not None and not future.done():
            # The browser/native pending batch is cumulative until ACK. Keeping only the
            # newest batch therefore coalesces work without losing unsaved points.
            if token and token != str(state.get("token") or ""):
                state["queued"] = dict(batch or {})
                state["queued_token"] = token
            return False
        state["future"] = runtime["executor"].submit(_gps_sync_worker_v561, owner[0], owner[1], dict(batch or {}))
        state["token"] = token
        state["queued"] = None
        state["queued_token"] = ""
        return True


def _gps_sync_harvest_v561():
    """Collect completed background saves without ever waiting on a Future."""
    runtime = _gps_sync_runtime_v561()
    owner = (current_family_key(), current_member_key())
    completed = []
    with runtime["lock"]:
        state = runtime["owners"].get(owner)
        if not isinstance(state, dict):
            return []
        future = state.get("future")
        if future is None or not future.done():
            return []
        try:
            completed.append(future.result(timeout=0))
        except Exception as exc:
            completed.append({"status": "error", "at_ms": int(time.time() * 1000),
                              "source": "background", "received": 0, "accepted": 0,
                              "ack_ms": 0, "error_type": type(exc).__name__})
        state["future"] = None
        queued = state.get("queued")
        queued_token = str(state.get("queued_token") or "")
        state["queued"] = None
        state["queued_token"] = ""
        if isinstance(queued, dict) and queued.get("points"):
            state["future"] = runtime["executor"].submit(_gps_sync_worker_v561, owner[0], owner[1], dict(queued))
            state["token"] = queued_token
    for result in completed:
        if not isinstance(result, dict):
            continue
        if str(result.get("status") or "") == "saved":
            try:
                _read_track_month_cached_v271.clear(); _list_track_month_keys_v271.clear()
                _load_all_project_track_points_cached_v561.clear()
            except Exception:
                pass
        st.session_state["_gps_last_sync_v491"] = dict(result)
        if str(result.get("status") or "") == "saved" and int(result.get("ack_ms") or 0) > 0:
            ack_key_v561 = f"_gps_track_ack_v271_{owner[0]}_{owner[1]}"
            token_key_v561 = f"_gps_track_batch_token_v271_{owner[0]}_{owner[1]}"
            st.session_state[ack_key_v561] = max(int(st.session_state.get(ack_key_v561) or 0), int(result.get("ack_ms") or 0))
            if str(result.get("token") or ""):
                st.session_state[token_key_v561] = str(result.get("token") or "")
            _perf_log_v457(
                "gps:sync_batch_saved_background", duration_ms=0,
                meta={"source": str(result.get("source") or "")[:80],
                      "received": int(result.get("received") or 0),
                      "accepted": int(result.get("accepted") or 0)}, force=True,
            )
    return completed


def save_gps_track_batch_v271(batch):
    if not isinstance(batch, dict):
        return 0
    raw_points = batch.get("points") or []
    if not isinstance(raw_points, list):
        return 0
    source = str(batch.get("source") or "browser_or_legacy")[:80]
    received_at_ms = int(time.time() * 1000)
    _perf_log_v457(
        "gps:sync_batch_received",
        duration_ms=0,
        meta={
            "source": source,
            "raw_count": len(raw_points),
            "background_sync": bool(batch.get("background_sync")),
            "max_ts_ms": int(float(batch.get("max_ts_ms") or 0)) if str(batch.get("max_ts_ms") or "").strip() else 0,
        },
        force=True,
    )
    cleaned = []
    for raw in raw_points[:GPS_TRACK_BATCH_MAX_POINTS]:
        point = _coerce_track_point_v271(raw)
        if point:
            cleaned.append(point)
    if not cleaned:
        st.session_state["_gps_last_sync_v491"] = {
            "at_ms": received_at_ms,
            "source": source,
            "received": len(raw_points),
            "accepted": 0,
            "ack_ms": 0,
            "status": "no_valid_points",
        }
        _perf_log_v457("gps:sync_batch_no_valid_points", duration_ms=0,
                       meta={"source": source, "raw_count": len(raw_points)}, force=True)
        return 0
    by_month = {}
    for point in cleaned:
        try:
            dt = datetime.fromtimestamp(float(point["ts_ms"]) / 1000.0, ZoneInfo(APP_TIMEZONE))
        except Exception:
            continue
        by_month.setdefault(dt.strftime("%Y-%m"), []).append(point)
    for month_key, rows in by_month.items():
        _upsert_track_month_v271(month_key, rows)
    _read_track_month_cached_v271.clear()
    _list_track_month_keys_v271.clear()
    ack_ms = max(int(p.get("ts_ms") or 0) for p in cleaned)
    min_ts_ms = min(int(p.get("ts_ms") or 0) for p in cleaned)
    last_sync = {
        "at_ms": int(time.time() * 1000),
        "source": source,
        "received": len(raw_points),
        "accepted": len(cleaned),
        "ack_ms": ack_ms,
        "min_ts_ms": min_ts_ms,
        "months": len(by_month),
        "status": "saved",
    }
    st.session_state["_gps_last_sync_v491"] = last_sync
    _perf_log_v457(
        "gps:sync_batch_saved",
        duration_ms=0,
        meta={
            "source": source,
            "received": len(raw_points),
            "accepted": len(cleaned),
            "months": len(by_month),
            "min_ts_ms": min_ts_ms,
            "ack_ms": ack_ms,
        },
        force=True,
    )
    return ack_ms

def run_always_on_gps_tracker_v271():
    # v561: harvest completed persistence first. This is non-blocking and lets the next
    # natural render carry the ACK without forcing an app rerun.
    _gps_sync_harvest_v561()
    # v495: keep native bridge recovery, make ACK->next-batch recovery resilient, and capture diagnostic status from the
    # Android bridge whenever Burari Project or Settings is opened. No bridge token or coordinate
    # is written to the log; only counts, timestamps, permission/service state and sync results.
    native_android = str(_query_param_scalar("native_android") or "").strip() == "1"
    native_bridge_token = str(_query_param_scalar("native_bridge_token") or "").strip()
    native_mode = bool(native_android and native_bridge_token)
    page = str(st.session_state.get("main_page") or "home")

    component = _get_gps_tracker_component_v271()
    # v492: Persist a non-sensitive probe on every run so the settings log can explain
    # why detailed Android diagnostics are absent. Never store the bridge token itself.
    gps_probe = {
        "checked_at_ms": int(time.time() * 1000),
        "page": page,
        "native_android": bool(native_android),
        "bridge_token_present": bool(native_bridge_token),
        "native_mode": bool(native_mode),
        "component_available": component is not None,
        "diagnostic_requested": bool(native_mode and page in {"review_project", "settings"}),
        "diagnostic_received": False,
    }
    st.session_state["_gps_diag_probe_v492"] = gps_probe
    if component is None:
        _perf_log_v457(
            "gps:component_unavailable",
            duration_ms=0,
            meta={"native_android": native_android, "native_mode": native_mode},
            force=True,
        )
        return
    allow_flush = page != "camera"
    # v561: preserve the Project page's immediate sync on entry, but only once.
    # The old design kept force_flush=True on every rerun and became a recovery pump:
    # one GPS point -> save -> rerun -> next point. A one-shot entry flush keeps the
    # visible behavior without allowing a continuous rerun chain.
    last_tracker_page_v561 = str(st.session_state.get("_gps_tracker_last_page_v561") or "")
    force_flush = bool(page == "review_project" and last_tracker_page_v561 != "review_project")
    st.session_state["_gps_tracker_last_page_v561"] = page
    # v493: Settings needs the same native status snapshot for the visible GPS log,
    # but it must not force-upload GPS points merely because the user opened Settings.
    request_diagnostic = bool(native_mode and page in {"review_project", "settings"})
    activity_guard_enabled = True
    activity_grace_ms = 5 * 60 * 1000
    ack_key = f"_gps_track_ack_v271_{current_family_key()}_{current_member_key()}"
    if force_flush:
        _perf_log_v457(
            "gps:project_bridge_request",
            duration_ms=0,
            meta={
                "native_android": native_android,
                "native_mode": native_mode,
                "bridge_token_present": bool(native_bridge_token),
                "ack_ms": int(st.session_state.get(ack_key) or 0),
            },
            force=True,
        )
    result = component(
        data={
            "native_mode": native_mode,
            "native_bridge_token": native_bridge_token,
            "family_key": current_family_key(),
            "member_key": current_member_key(),
            "min_distance_m": GPS_TRACK_MIN_DISTANCE_M,
            "max_accuracy_m": GPS_TRACK_MAX_ACCURACY_M,
            "flush_point_count": GPS_TRACK_FLUSH_POINT_COUNT,
            "flush_interval_ms": GPS_TRACK_FLUSH_INTERVAL_MS,
            "batch_max_points": GPS_TRACK_BATCH_MAX_POINTS,
            "allow_flush": allow_flush,
            "force_flush": force_flush,
            "request_diagnostic": request_diagnostic,
            "diagnostic_context": page,
            "activity_guard_enabled": activity_guard_enabled,
            "activity_grace_ms": activity_grace_ms,
            "ack_ms": int(st.session_state.get(ack_key) or 0),
        },
        key=f"always_on_gps_tracker_v279_{current_family_key()}_{current_member_key()}",
        on_track_batch_change=lambda: None,
        on_gps_diagnostic_change=lambda: None,
    )

    diagnostic = getattr(result, "gps_diagnostic", None)
    gps_probe = dict(st.session_state.get("_gps_diag_probe_v492") or {})
    gps_probe["result_returned"] = result is not None
    gps_probe["diagnostic_received"] = bool(isinstance(diagnostic, dict) and diagnostic)
    gps_probe["checked_at_ms"] = int(time.time() * 1000)
    st.session_state["_gps_diag_probe_v492"] = gps_probe
    if isinstance(diagnostic, dict):
        diag_token = str(diagnostic.get("token") or "")
        diag_token_key = f"_gps_diag_token_v491_{current_family_key()}_{current_member_key()}"
        if not diag_token or diag_token != str(st.session_state.get(diag_token_key) or ""):
            if diag_token:
                st.session_state[diag_token_key] = diag_token
            clean_diag = {}
            for key in (
                "bridge_path", "bridge_version", "pending_count", "device_total_count",
                "device_latest_ts_ms", "device_latest_accuracy_m", "gps_service_running",
                "service_started_ms", "service_last_callback_ms", "service_last_accepted_ms",
                "fine_location_granted", "coarse_location_granted", "status_error",
                "captured_at_ms",
            ):
                value = diagnostic.get(key)
                if isinstance(value, (str, int, float, bool)) or value is None:
                    clean_diag[key] = value
            clean_diag["received_at_ms"] = int(time.time() * 1000)
            st.session_state["_gps_native_diag_v491"] = clean_diag
            _perf_log_v457("gps:native_diagnostic", duration_ms=0, meta=clean_diag, force=True)

    batch = getattr(result, "track_batch", None)
    if not isinstance(batch, dict) or not batch.get("points"):
        return
    token = str(batch.get("token") or "")
    token_key = f"_gps_track_batch_token_v271_{current_family_key()}_{current_member_key()}"
    if token and token == str(st.session_state.get(token_key) or ""):
        _perf_log_v457(
            "gps:sync_batch_duplicate_seen",
            duration_ms=0,
            meta={"source": str(batch.get("source") or "")[:80], "force_recovery": bool(force_flush)},
            force=True,
        )
        if not force_flush:
            return
        # v495 recovery is intentionally idempotent. If Android returns the same 500
        # rows again, save/upsert them again and issue the same ACK instead of stopping
        # the chain indefinitely. The next component render re-applies ACK first.
    # v561: persistence is queued to the dedicated background writer. The UI thread
    # returns immediately; ACK is published only after a later non-blocking harvest.
    submitted = _gps_sync_enqueue_v561(batch)
    st.session_state["_gps_last_sync_v491"] = {
        "at_ms": int(time.time() * 1000),
        "source": str(batch.get("source") or "")[:80],
        "received": len(batch.get("points") or []),
        "accepted": 0,
        "ack_ms": int(st.session_state.get(ack_key) or 0),
        "status": "queued" if submitted else "queued_coalesced",
    }
    _perf_log_v457(
        "gps:sync_batch_queued", duration_ms=0,
        meta={"source": str(batch.get("source") or "")[:80],
              "count": len(batch.get("points") or []), "submitted": bool(submitted)}, force=True,
    )


@st.cache_data(ttl=15, max_entries=24, show_spinner=False)
def _read_native_track_points_v338(family_key, member_key):
    """Read Android-native GPS rows without involving a browser component.

    v338 writes new Android points to a dedicated Supabase table through a background
    Edge Function. Legacy monthly Storage JSON remains readable, so existing history is
    preserved and both sources are merged below. Missing-table/deployment states simply
    return no native rows, allowing the web app to remain usable during rollout.
    """
    family = str(family_key or "").strip()
    member = str(member_key or "").strip()
    if not family or not member:
        return []
    rows = []
    page_size = 1000
    # Keep retrieval bounded; the final merged render is sampled to the existing map limit.
    max_rows = max(5000, int(GPS_TRACK_RENDER_POINT_LIMIT) * 3)
    offset = 0
    try:
        client = supabase_client()
        while offset < max_rows:
            end = min(max_rows, offset + page_size) - 1
            result = (
                client.table(GPS_NATIVE_TRACK_TABLE_V338)
                .select("id,ts_ms,lat,lon,accuracy_m,speed_mps,heading,session_id,source")
                .eq("family_key", family)
                .eq("member_key", member)
                .order("ts_ms")
                .range(offset, end)
                .execute()
            )
            batch = list(getattr(result, "data", None) or [])
            if not batch:
                break
            for raw in batch:
                point = _coerce_track_point_v271(raw)
                if point:
                    rows.append(point)
            if len(batch) < page_size:
                break
            offset += page_size
    except Exception:
        # The SQL migration/Edge Function may not be deployed yet. Legacy history must
        # continue to work instead of making the whole review page fail.
        return []
    return rows


@st.cache_data(ttl=15, max_entries=24, show_spinner=False)
def _load_all_project_track_points_cached_v561(family, member):
    months = list(_list_track_month_keys_v271(family, member))
    groups = []
    if months:
        worker_count = max(1, min(6, len(months)))
        def load_one(month_key):
            return _read_track_month_cached_v271(family, member, month_key)
        if worker_count == 1:
            groups = [load_one(months[0])]
        else:
            with ThreadPoolExecutor(max_workers=worker_count) as executor:
                groups = list(executor.map(load_one, months))

    # v338 native rows are already cloud-saved by Android WorkManager; reading them here
    # is a normal review-page query and never talks back to the device or triggers GPS sync.
    native_rows = _read_native_track_points_v338(family, member)
    merged = {}
    for rows in groups:
        for row in rows or []:
            if isinstance(row, dict) and row.get("id"):
                merged[str(row.get("id"))] = row
    for row in native_rows or []:
        if isinstance(row, dict) and row.get("id"):
            merged[str(row.get("id"))] = row

    points = sorted(merged.values(), key=lambda x: (int(x.get("ts_ms") or 0), str(x.get("id") or "")))
    if len(points) > GPS_TRACK_RENDER_POINT_LIMIT:
        # Preserve every raw point in its source. Only the map payload is thinned.
        step = max(1, int(math.ceil(len(points) / float(GPS_TRACK_RENDER_POINT_LIMIT))))
        sampled = points[::step]
        if points and (not sampled or sampled[-1].get("id") != points[-1].get("id")):
            sampled.append(points[-1])
        return sampled
    return points


def _load_all_project_track_points_v271():
    return _load_all_project_track_points_cached_v561(current_family_key(), current_member_key())


def _project_points_signature_v561(points):
    rows = [row for row in (points or []) if isinstance(row, dict)]
    if not rows:
        return "0"
    picks = rows[::max(1, len(rows) // 32)]
    material = [str(len(rows)), str(rows[0].get("id") or ""), str(rows[-1].get("id") or "")]
    material.extend(str(row.get("id") or row.get("ts_ms") or "") for row in picks[:40])
    return hashlib.sha1("|".join(material).encode("utf-8")).hexdigest()[:20]


def _project_route_derived_v561(points):
    sig = _project_points_signature_v561(points)
    key = _account_cache_key("project_route_derived_v561")
    cached = st.session_state.get(key)
    if isinstance(cached, dict) and cached.get("signature") == sig:
        value = cached.get("value")
        if isinstance(value, dict):
            return value
    segments = _project_walk_segments_v271(points) if points else []
    fallback_segments = _project_city_fallback_segments_v455(points) if points else []
    value = {
        "segments": segments,
        "fallback_segments": fallback_segments,
        "walk_points": _project_walk_points_v271(segments) if segments else [],
        "fallback_points": _project_walk_points_v271(fallback_segments) if fallback_segments else [],
        "walk_m": _project_walk_distance_m_v271(segments) if segments else 0.0,
    }
    st.session_state[key] = {"signature": sig, "value": value}
    return value


def _project_station_preflight_cached_v561(points, map_points):
    sig = _project_points_signature_v561(points)
    key = _account_cache_key("project_station_preflight_v561")
    cached = st.session_state.get(key)
    if isinstance(cached, dict) and cached.get("signature") == sig:
        value = cached.get("value")
        if isinstance(value, tuple) and len(value) == 2:
            return value, True
    value = _project_station_preflight_v293(points, map_points)
    st.session_state[key] = {"signature": sig, "value": value}
    return value, False


def _project_render_source_dedupe_v384(points):
    """Prefer one GPS stream when Android/native and browser fixes overlap in time.

    Native Android tracking and the older browser watcher can both be present in history.
    If those streams are interleaved, sorting only by timestamp makes the rendered route
    jump back and forth between two slightly different fixes. Keep every raw row in storage,
    but suppress a browser fix for rendering when a reasonably accurate Android fix exists
    at almost the same time and place.
    """
    rows = [row for row in (points or []) if isinstance(row, dict)]
    if not rows:
        return []
    rows = sorted(rows, key=lambda row: (int(row.get("ts_ms") or 0), str(row.get("id") or "")))
    native = []
    for row in rows:
        if str(row.get("source") or "").strip().lower() != "android_native":
            continue
        try:
            ts_ms = int(float(row.get("ts_ms") or 0))
            lat = float(row.get("lat")); lon = float(row.get("lon"))
            accuracy = float(row.get("accuracy_m")) if row.get("accuracy_m") is not None else None
        except (TypeError, ValueError):
            continue
        if ts_ms <= 0 or not (math.isfinite(lat) and math.isfinite(lon)):
            continue
        if accuracy is not None and (not math.isfinite(accuracy) or accuracy > GPS_TRACK_RENDER_MAX_ACCURACY_M):
            continue
        native.append((ts_ms, row))
    if not native:
        return rows

    native_times = [item[0] for item in native]
    output = []
    for row in rows:
        source = str(row.get("source") or "").strip().lower()
        if source != "browser_watch":
            output.append(row)
            continue
        try:
            ts_ms = int(float(row.get("ts_ms") or 0))
            lat = float(row.get("lat")); lon = float(row.get("lon"))
            browser_accuracy = float(row.get("accuracy_m")) if row.get("accuracy_m") is not None else None
        except (TypeError, ValueError):
            output.append(row)
            continue
        index = bisect_left(native_times, ts_ms)
        suppress = False
        for candidate_index in (index - 1, index, index + 1):
            if candidate_index < 0 or candidate_index >= len(native):
                continue
            native_ts, native_row = native[candidate_index]
            if abs(native_ts - ts_ms) > GPS_TRACK_RENDER_SOURCE_OVERLAP_WINDOW_MS_V384:
                continue
            try:
                nlat = float(native_row.get("lat")); nlon = float(native_row.get("lon"))
                dist = _nearby_haversine_m(lat, lon, nlat, nlon)
                native_accuracy = float(native_row.get("accuracy_m")) if native_row.get("accuracy_m") is not None else None
            except (TypeError, ValueError):
                continue
            if dist > GPS_TRACK_RENDER_SOURCE_OVERLAP_DISTANCE_M_V384:
                continue
            # Preserve a materially more accurate browser fix; otherwise native GPS is
            # the canonical stream for the overlapping instant.
            if (
                browser_accuracy is not None
                and native_accuracy is not None
                and browser_accuracy + 10.0 < native_accuracy
            ):
                continue
            suppress = True
            break
        if not suppress:
            output.append(row)
    return output


def _project_clean_track_points_v372(points):
    """Return render-safe GPS points while preserving the raw source data unchanged.

    Urban GPS drift can move a stationary fix by 10-50m. Pairwise speed checks alone
    mistakenly interpret that drift as slow walking and draw a spider-web. This filter
    applies three conservative rules before the glowing route is built:
    1) discard low-accuracy fixes from the route line,
    2) ignore movements smaller than the reported GPS error radius, and
    3) remove short out-and-back spikes whose middle fix is visibly less reliable.
    """
    clean = []
    for raw in _project_render_source_dedupe_v384(points):
        if not isinstance(raw, dict):
            continue
        try:
            lat = float(raw.get("lat")); lon = float(raw.get("lon")); ts_ms = int(float(raw.get("ts_ms") or 0))
        except (TypeError, ValueError):
            continue
        if not (math.isfinite(lat) and math.isfinite(lon) and ts_ms > 0):
            continue
        try:
            accuracy = float(raw.get("accuracy_m")) if raw.get("accuracy_m") is not None else None
        except (TypeError, ValueError):
            accuracy = None
        if accuracy is not None and (not math.isfinite(accuracy) or accuracy > GPS_TRACK_RENDER_MAX_ACCURACY_M):
            # A poor fix is kept in storage but must not pull the visible walking line away.
            continue

        point = dict(raw)
        if not clean:
            clean.append(point)
            continue

        prev = clean[-1]
        try:
            dt = max(0.001, (float(point.get("ts_ms")) - float(prev.get("ts_ms"))) / 1000.0)
            dist = _nearby_haversine_m(float(prev["lat"]), float(prev["lon"]), lat, lon)
        except Exception:
            clean.append(point)
            continue

        try:
            prev_accuracy = float(prev.get("accuracy_m")) if prev.get("accuracy_m") is not None else None
        except (TypeError, ValueError):
            prev_accuracy = None
        accuracy_radius = max(
            float(accuracy) if accuracy is not None else 0.0,
            float(prev_accuracy) if prev_accuracy is not None else 0.0,
        )
        noise_floor = max(
            GPS_TRACK_RENDER_BASE_NOISE_M,
            min(GPS_TRACK_RENDER_MAX_NOISE_M, accuracy_radius * 0.90),
        )
        estimated_speed = dist / dt if dt > 0 else 999.0
        same_session = bool(str(point.get("session_id") or "")) and str(point.get("session_id") or "") == str(prev.get("session_id") or "")
        point_source = str(point.get("source") or "").strip().lower()
        prev_source = str(prev.get("source") or "").strip().lower()
        same_source = bool(point_source) and point_source == prev_source
        stream_contiguous = same_session or (same_source and dt <= 60.0)
        try:
            reported_speed = float(point.get("speed_mps")) if point.get("speed_mps") is not None else None
        except (TypeError, ValueError):
            reported_speed = None

        # v384: session ids can change after an app/WebView restart. For display noise
        # rejection, a short continuation from the same GPS source is still one stream.
        # Use most of the reported accuracy radius: a 15-25m urban wobble should not be
        # interpreted as a walked side street merely because the fix moved 10m.
        slow_or_stationary = estimated_speed <= 1.80 or (reported_speed is not None and reported_speed <= 0.90)
        if stream_contiguous and dist < noise_floor and slow_or_stationary:
            if accuracy is not None and (prev_accuracy is None or accuracy + 4.0 < prev_accuracy):
                clean[-1] = point
            continue
        clean.append(point)

    if len(clean) < 3:
        return clean

    # Remove classic GPS spikes A -> B -> C where B jumps away and the next good fix
    # comes almost back to A. Restrict this to short windows and a worse middle accuracy
    # so genuine out-and-back walking is not broadly erased.
    for _pass in range(2):
        if len(clean) < 3:
            break
        reduced = [clean[0]]
        for idx in range(1, len(clean) - 1):
            a = reduced[-1]
            b = clean[idx]
            c = clean[idx + 1]
            try:
                total_dt = (float(c.get("ts_ms")) - float(a.get("ts_ms"))) / 1000.0
                ab = _nearby_haversine_m(float(a["lat"]), float(a["lon"]), float(b["lat"]), float(b["lon"]))
                bc = _nearby_haversine_m(float(b["lat"]), float(b["lon"]), float(c["lat"]), float(c["lon"]))
                ac = _nearby_haversine_m(float(a["lat"]), float(a["lon"]), float(c["lat"]), float(c["lon"]))
            except Exception:
                reduced.append(b)
                continue
            try:
                a_acc = float(a.get("accuracy_m")) if a.get("accuracy_m") is not None else 18.0
                b_acc = float(b.get("accuracy_m")) if b.get("accuracy_m") is not None else 18.0
                c_acc = float(c.get("accuracy_m")) if c.get("accuracy_m") is not None else 18.0
            except (TypeError, ValueError):
                a_acc = b_acc = c_acc = 18.0
            same_session = (
                bool(str(a.get("session_id") or ""))
                and str(a.get("session_id") or "") == str(b.get("session_id") or "") == str(c.get("session_id") or "")
            )
            source_a = str(a.get("source") or "").strip().lower()
            same_source = bool(source_a) and source_a == str(b.get("source") or "").strip().lower() == str(c.get("source") or "").strip().lower()
            same_stream = same_session or (same_source and 0 < total_dt <= 90.0)
            middle_worse = b_acc >= max(18.0, min(a_acc, c_acc) + 5.0)
            obvious_return_spike = ab >= 34.0 and bc >= 34.0 and ac <= 13.0
            spike = (
                same_stream
                and 0 < total_dt <= 90.0
                and ab >= max(18.0, b_acc * 0.65)
                and bc >= max(18.0, b_acc * 0.65)
                and ac <= max(14.0, min(ab, bc) * 0.38)
                and (middle_worse or obvious_return_spike)
            )
            if spike:
                continue
            reduced.append(b)
        reduced.append(clean[-1])
        clean = reduced
    return clean



def _project_display_walk_segments_v496(points, stations=None):
    """Build a conservative map-only walking line without altering stored GPS/history.

    The authoritative v271 segments remain the basis for distance and station evidence.
    This display path is deliberately stricter around reached stations, where reflected
    GNSS signals can create dozens of plausible-looking 10-50m fixes that form a radial
    spider-web through buildings. Uncertain links are split/omitted rather than invented.
    """
    rows = [row for row in _project_clean_track_points_v372(points) if isinstance(row, dict)]
    centers = []
    for station in stations or []:
        if not isinstance(station, dict):
            continue
        if not bool(station.get("arrived") or station.get("visited")):
            continue
        try:
            lat = float(station.get("lat")); lon = float(station.get("lon"))
        except (TypeError, ValueError):
            continue
        if math.isfinite(lat) and math.isfinite(lon):
            centers.append((lat, lon))

    station_cache = {}
    def near_reached_station(row):
        if not centers:
            return False
        key = str(row.get("id") or "") or f"{row.get('lat')}:{row.get('lon')}"
        if key in station_cache:
            return station_cache[key]
        try:
            lat = float(row.get("lat")); lon = float(row.get("lon"))
        except (TypeError, ValueError):
            station_cache[key] = False
            return False
        hit = False
        for slat, slon in centers:
            try:
                if _nearby_haversine_m(lat, lon, slat, slon) <= float(GPS_TRACK_DISPLAY_STATION_RADIUS_M_V496):
                    hit = True
                    break
            except Exception:
                continue
        station_cache[key] = hit
        return hit

    def row_accuracy(row):
        try:
            value = float(row.get("accuracy_m")) if row.get("accuracy_m") is not None else None
        except (TypeError, ValueError):
            return None
        return value if value is None or math.isfinite(value) else None

    def row_reported_speed(row):
        try:
            value = float(row.get("speed_mps")) if row.get("speed_mps") is not None else None
        except (TypeError, ValueError):
            return None
        return value if value is None or math.isfinite(value) else None

    preliminary = []
    current = []
    prev = None
    quality_dropped = 0
    link_breaks = 0

    for point in rows:
        try:
            lat = float(point.get("lat")); lon = float(point.get("lon")); ts_ms = int(float(point.get("ts_ms") or 0))
        except (TypeError, ValueError):
            continue
        if not (math.isfinite(lat) and math.isfinite(lon) and ts_ms > 0):
            continue
        station_area = near_reached_station(point)
        accuracy = row_accuracy(point)
        max_accuracy = (
            GPS_TRACK_DISPLAY_STATION_MAX_ACCURACY_M_V496
            if station_area else GPS_TRACK_DISPLAY_MAX_ACCURACY_M_V496
        )
        if accuracy is not None and accuracy > float(max_accuracy):
            quality_dropped += 1
            if len(current) >= 2:
                preliminary.append(current)
            current = []
            prev = None
            continue

        if prev is None:
            current = [point]
            prev = point
            continue
        try:
            dt = (float(point.get("ts_ms")) - float(prev.get("ts_ms"))) / 1000.0
            dist = _nearby_haversine_m(float(prev["lat"]), float(prev["lon"]), lat, lon)
        except Exception:
            if len(current) >= 2:
                preliminary.append(current)
            current = [point]
            prev = point
            link_breaks += 1
            continue
        if dt <= 0:
            prev = point
            continue

        prev_station_area = near_reached_station(prev)
        in_station_area = bool(station_area or prev_station_area)
        max_gap = (
            GPS_TRACK_DISPLAY_STATION_MAX_GAP_SECONDS_V496
            if in_station_area else GPS_TRACK_DISPLAY_MAX_GAP_SECONDS_V496
        )
        max_step = (
            GPS_TRACK_DISPLAY_STATION_MAX_STEP_M_V496
            if in_station_area else GPS_TRACK_DISPLAY_MAX_STEP_M_V496
        )
        max_speed = (
            GPS_TRACK_DISPLAY_STATION_MAX_SPEED_MPS_V496
            if in_station_area else GPS_TRACK_DISPLAY_MAX_SPEED_MPS_V496
        )
        # A real 10m-sampled walk should not teleport 50-80m between adjacent fixes.
        # Tighten the allowed jump for short time gaps instead of using one 180m cap.
        dynamic_step = max(24.0, min(float(max_step), 18.0 + dt * 2.35))
        estimated_speed = dist / max(0.001, dt)
        same_session = bool(str(point.get("session_id") or "")) and str(point.get("session_id") or "") == str(prev.get("session_id") or "")
        source = str(point.get("source") or "").strip().lower()
        prev_source = str(prev.get("source") or "").strip().lower()
        same_source = bool(source) and source == prev_source
        restart_ok = (
            not same_session and same_source
            and dt <= min(45.0, float(max_gap))
            and dist <= min(55.0, dynamic_step)
        )
        reported_speed = row_reported_speed(point)
        # Around stations a stationary/near-stationary reported fix that suddenly moves
        # tens of metres is much more likely multipath drift than a genuine walked link.
        stationary_jump = False
        if in_station_area and reported_speed is not None and reported_speed <= 0.75:
            acc_radius = max(12.0, float(accuracy or 0.0), float(row_accuracy(prev) or 0.0))
            stationary_jump = dist > max(20.0, acc_radius * 1.10)

        linked = (
            (same_session or restart_ok)
            and dt <= float(max_gap)
            and dist <= dynamic_step
            and estimated_speed <= float(max_speed)
            and not stationary_jump
        )
        if linked:
            if not current:
                current = [prev]
            current.append(point)
        else:
            if len(current) >= 2:
                preliminary.append(current)
            current = [point]
            link_breaks += 1
        prev = point
    if len(current) >= 2:
        preliminary.append(current)

    def turn_degrees(a, b, c):
        try:
            lat0 = math.radians((float(a["lat"]) + float(b["lat"]) + float(c["lat"])) / 3.0)
            scale_x = 111320.0 * max(0.2, math.cos(lat0))
            scale_y = 111320.0
            bax = (float(a["lon"]) - float(b["lon"])) * scale_x
            bay = (float(a["lat"]) - float(b["lat"])) * scale_y
            bcx = (float(c["lon"]) - float(b["lon"])) * scale_x
            bcy = (float(c["lat"]) - float(b["lat"])) * scale_y
            na = math.hypot(bax, bay); nc = math.hypot(bcx, bcy)
            if na < 1e-6 or nc < 1e-6:
                return 0.0
            cosine = max(-1.0, min(1.0, (bax * bcx + bay * bcy) / (na * nc)))
            interior = math.degrees(math.acos(cosine))
            return max(0.0, 180.0 - interior)
        except Exception:
            return 0.0

    turn_removed = 0
    dwell_removed = 0
    output_rows = []
    for raw_seg in preliminary:
        seg = list(raw_seg)
        # Remove abrupt A-B-C reversals that occur too quickly to represent a normal
        # street corner. A 90-degree street turn is preserved; only near-U-turn spikes go.
        for _ in range(2):
            if len(seg) < 3:
                break
            reduced = [seg[0]]
            for idx in range(1, len(seg) - 1):
                a = reduced[-1]; b = seg[idx]; c = seg[idx + 1]
                try:
                    total_dt = (float(c.get("ts_ms")) - float(a.get("ts_ms"))) / 1000.0
                    ab = _nearby_haversine_m(float(a["lat"]), float(a["lon"]), float(b["lat"]), float(b["lon"]))
                    bc = _nearby_haversine_m(float(b["lat"]), float(b["lon"]), float(c["lat"]), float(c["lon"]))
                    ac = _nearby_haversine_m(float(a["lat"]), float(a["lon"]), float(c["lat"]), float(c["lon"]))
                except Exception:
                    reduced.append(b)
                    continue
                sharp = (
                    0 < total_dt <= float(GPS_TRACK_DISPLAY_SHARP_TURN_WINDOW_SECONDS_V496)
                    and ab >= 14.0 and bc >= 14.0
                    and turn_degrees(a, b, c) >= float(GPS_TRACK_DISPLAY_SHARP_TURN_DEG_V496)
                    and ac <= max(34.0, (ab + bc) * 0.68)
                    and (near_reached_station(a) or near_reached_station(b) or near_reached_station(c))
                )
                if sharp:
                    turn_removed += 1
                    continue
                reduced.append(b)
            reduced.append(seg[-1])
            seg = reduced

        if len(seg) < 2:
            continue

        # Collapse short dense loops around reached stations. These are characteristic
        # of reflected GNSS: large accumulated path, little net displacement, and all
        # fixes remaining inside one small area. Preserve the endpoints but remove the
        # radial interior, so the map never paints a starburst through surrounding blocks.
        keep = [True] * len(seg)
        start = 0
        for end in range(len(seg)):
            try:
                end_ts = float(seg[end].get("ts_ms") or 0)
            except Exception:
                continue
            while start < end:
                try:
                    age = (end_ts - float(seg[start].get("ts_ms") or 0)) / 1000.0
                except Exception:
                    age = 0.0
                if age <= float(GPS_TRACK_DISPLAY_DWELL_WINDOW_SECONDS_V496):
                    break
                start += 1
            if end - start + 1 < 6:
                continue
            try:
                duration = (float(seg[end].get("ts_ms")) - float(seg[start].get("ts_ms"))) / 1000.0
            except Exception:
                continue
            if duration < float(GPS_TRACK_DISPLAY_DWELL_MIN_SECONDS_V496):
                continue
            window = seg[start:end + 1]
            if sum(1 for row in window if near_reached_station(row)) < max(3, int(math.ceil(len(window) * 0.5))):
                continue
            path_m = 0.0
            max_radius = 0.0
            ok = True
            for left, right in zip(window[:-1], window[1:]):
                try:
                    path_m += _nearby_haversine_m(float(left["lat"]), float(left["lon"]), float(right["lat"]), float(right["lon"]))
                except Exception:
                    ok = False; break
            if not ok or path_m < float(GPS_TRACK_DISPLAY_DWELL_PATH_M_V496):
                continue
            try:
                displacement = _nearby_haversine_m(float(window[0]["lat"]), float(window[0]["lon"]), float(window[-1]["lat"]), float(window[-1]["lon"]))
                for row in window[1:]:
                    max_radius = max(max_radius, _nearby_haversine_m(float(window[0]["lat"]), float(window[0]["lon"]), float(row["lat"]), float(row["lon"])))
            except Exception:
                continue
            if (
                displacement <= float(GPS_TRACK_DISPLAY_DWELL_DISPLACEMENT_M_V496)
                and max_radius <= float(GPS_TRACK_DISPLAY_DWELL_RADIUS_M_V496)
                and path_m / max(15.0, displacement) >= 3.0
            ):
                for idx in range(start + 1, end):
                    if keep[idx]:
                        keep[idx] = False
                        dwell_removed += 1

        # Split at removed drift points instead of drawing a chord through the omitted
        # cloud. This intentionally prefers a small gap over a false road/building line.
        piece = []
        for idx, row in enumerate(seg):
            if not keep[idx]:
                if len(piece) >= 2:
                    output_rows.append(piece)
                piece = []
                continue
            if not piece:
                piece = [row]
            else:
                try:
                    gap = _nearby_haversine_m(float(piece[-1]["lat"]), float(piece[-1]["lon"]), float(row["lat"]), float(row["lon"]))
                except Exception:
                    gap = float("inf")
                if gap > float(GPS_TRACK_DISPLAY_MAX_STEP_M_V496):
                    if len(piece) >= 2:
                        output_rows.append(piece)
                    piece = [row]
                else:
                    piece.append(row)
        if len(piece) >= 2:
            output_rows.append(piece)

    output = []
    segment_windows = []
    for seg in output_rows:
        coords = []
        source_rows = []
        for row in seg:
            try:
                coord = [round(float(row["lat"]), 7), round(float(row["lon"]), 7)]
            except Exception:
                continue
            if coords and coord == coords[-1]:
                continue
            coords.append(coord)
            source_rows.append(row)
        if len(coords) >= 2:
            output.append(coords)
            try:
                start_ts_ms = int(float(source_rows[0].get("ts_ms") or 0))
                end_ts_ms = int(float(source_rows[-1].get("ts_ms") or 0))
            except Exception:
                start_ts_ms = end_ts_ms = 0
            segment_windows.append({
                "start_ts_ms": max(0, start_ts_ms),
                "end_ts_ms": max(0, end_ts_ms),
                "point_count": len(source_rows),
                "session_id": str(source_rows[0].get("session_id") or "")[:120] if source_rows else "",
                "source": str(source_rows[0].get("source") or "")[:80] if source_rows else "",
            })
    meta = {
        "input_points": len(rows),
        "preliminary_segments": len(preliminary),
        "display_segments": len(output),
        "display_points": sum(len(seg) for seg in output),
        "quality_dropped": quality_dropped,
        "link_breaks": link_breaks,
        "turn_removed": turn_removed,
        "dwell_removed": dwell_removed,
        "station_centers": len(centers),
        "segment_windows": segment_windows,
    }
    return output, meta

def _project_city_fallback_segments_v455(points):
    """Build map-only urban fallback segments from already-loaded raw GPS points.

    The normal route remains strict (<= GPS_TRACK_RENDER_MAX_ACCURACY_M).  This helper
    only bridges short plausible gaps that contain at least one 45-90m fix.  It performs
    one linear pass, makes no network/API calls, and is capped before being sent to Leaflet.
    """
    # _load_all_project_track_points_v271 already returns timestamp-ordered rows.  Do not
    # run the expensive source-dedupe/sort pipeline a second time just for this fallback.
    rows = [row for row in (points or []) if isinstance(row, dict)]
    if not rows:
        return []

    def parsed(row):
        try:
            lat = float(row.get("lat")); lon = float(row.get("lon")); ts_ms = int(float(row.get("ts_ms") or 0))
            accuracy = float(row.get("accuracy_m")) if row.get("accuracy_m") is not None else 0.0
        except (TypeError, ValueError):
            return None
        if not (math.isfinite(lat) and math.isfinite(lon) and ts_ms > 0 and math.isfinite(accuracy)):
            return None
        if accuracy < 0 or accuracy > GPS_TRACK_CITY_FALLBACK_MAX_ACCURACY_M_V455:
            return None
        return lat, lon, ts_ms, accuracy

    def pair_walk_like(a_row, a, b_row, b):
        alat, alon, ats, _aacc = a
        blat, blon, bts, _bacc = b
        dt = (bts - ats) / 1000.0
        if dt <= 0 or dt > GPS_TRACK_CITY_FALLBACK_MAX_GAP_SECONDS_V455:
            return False
        dist = _nearby_haversine_m(alat, alon, blat, blon)
        if dist > GPS_TRACK_CITY_FALLBACK_MAX_STEP_M_V455:
            return False
        estimated_speed = dist / max(0.001, dt)
        if estimated_speed > GPS_TRACK_CITY_FALLBACK_MAX_SPEED_MPS_V455:
            return False
        same_session = bool(str(b_row.get("session_id") or "")) and str(b_row.get("session_id") or "") == str(a_row.get("session_id") or "")
        source_a = str(a_row.get("source") or "").strip().lower()
        same_source = bool(source_a) and source_a == str(b_row.get("source") or "").strip().lower()
        if not (same_session or same_source):
            return False
        try:
            reported_speed = float(b_row.get("speed_mps")) if b_row.get("speed_mps") is not None else None
        except (TypeError, ValueError):
            reported_speed = None
        if reported_speed is not None and reported_speed > 8.0 and dist > 30.0:
            return False
        return True

    segments = []
    current = []
    current_has_coarse = False
    prev_row = None
    prev_parsed = None

    def finish_current():
        nonlocal current, current_has_coarse
        if current_has_coarse and len(current) >= 2:
            segments.append(current)
        current = []
        current_has_coarse = False

    for row in rows:
        item = parsed(row)
        if item is None:
            finish_current()
            prev_row = None; prev_parsed = None
            continue
        _lat, _lon, _ts, accuracy = item
        is_coarse = accuracy > GPS_TRACK_RENDER_MAX_ACCURACY_M
        if prev_row is None or prev_parsed is None:
            if is_coarse:
                current = [[round(item[0], 7), round(item[1], 7)]]
                current_has_coarse = True
            prev_row, prev_parsed = row, item
            continue

        linked = pair_walk_like(prev_row, prev_parsed, row, item)
        if not linked:
            finish_current()
            if is_coarse:
                current = [[round(item[0], 7), round(item[1], 7)]]
                current_has_coarse = True
            prev_row, prev_parsed = row, item
            continue

        prev_is_coarse = prev_parsed[3] > GPS_TRACK_RENDER_MAX_ACCURACY_M
        if is_coarse or prev_is_coarse:
            if not current:
                current = [[round(prev_parsed[0], 7), round(prev_parsed[1], 7)]]
            coord = [round(item[0], 7), round(item[1], 7)]
            if current[-1] != coord:
                current.append(coord)
            current_has_coarse = True
            # A good fix after a coarse run closes the approximate bridge immediately,
            # preventing a fallback polyline from duplicating a long strict route.
            if not is_coarse:
                finish_current()
        else:
            finish_current()
        prev_row, prev_parsed = row, item
    finish_current()

    total_points = sum(len(seg) for seg in segments)
    if total_points <= GPS_TRACK_CITY_FALLBACK_MAX_POINTS_V455:
        return segments
    # Bound browser payload cost without touching source data.
    ratio = max(1, int(math.ceil(total_points / float(GPS_TRACK_CITY_FALLBACK_MAX_POINTS_V455))))
    out = []
    for seg in segments:
        if len(seg) <= 2:
            out.append(seg)
            continue
        sampled = seg[::ratio]
        if sampled[-1] != seg[-1]:
            sampled.append(seg[-1])
        if len(sampled) >= 2:
            out.append(sampled)
    return out


def _project_gps_diagnostics_v455(points):
    """Compact diagnostics from the in-memory map dataset only; zero extra I/O."""
    today = now_jst().date()
    result = {"today": 0, "strict": 0, "urban": 0, "poor": 0, "latest": None}
    for row in points or []:
        if not isinstance(row, dict):
            continue
        try:
            ts_ms = int(float(row.get("ts_ms") or 0))
            if ts_ms <= 0:
                continue
            dt = datetime.fromtimestamp(ts_ms / 1000.0, ZoneInfo(APP_TIMEZONE))
        except Exception:
            continue
        if result["latest"] is None or ts_ms > int(result["latest"].get("ts_ms") or 0):
            result["latest"] = row
        if dt.date() != today:
            continue
        result["today"] += 1
        try:
            accuracy = float(row.get("accuracy_m")) if row.get("accuracy_m") is not None else None
        except (TypeError, ValueError):
            accuracy = None
        if accuracy is None or accuracy <= GPS_TRACK_RENDER_MAX_ACCURACY_M:
            result["strict"] += 1
        elif accuracy <= GPS_TRACK_CITY_FALLBACK_MAX_ACCURACY_M_V455:
            result["urban"] += 1
        else:
            result["poor"] += 1
    return result


def _project_walk_segments_v271(points):
    segments = []
    current = []
    prev = None
    for point in _project_clean_track_points_v372(points):
        if not isinstance(point, dict):
            continue
        if prev is None:
            prev = point
            continue
        try:
            dt = max(0.001, (float(point.get("ts_ms")) - float(prev.get("ts_ms"))) / 1000.0)
            dist = _nearby_haversine_m(float(prev["lat"]), float(prev["lon"]), float(point["lat"]), float(point["lon"]))
        except Exception:
            prev = point
            current = []
            continue
        reported_speed = point.get("speed_mps")
        try:
            reported_speed = float(reported_speed) if reported_speed is not None else None
        except (TypeError, ValueError):
            reported_speed = None
        estimated_speed = dist / dt if dt > 0 else 999.0
        same_session = bool(str(point.get("session_id") or "")) and str(point.get("session_id") or "") == str(prev.get("session_id") or "")
        point_source = str(point.get("source") or "").strip().lower()
        prev_source = str(prev.get("source") or "").strip().lower()
        same_source = bool(point_source) and point_source == prev_source
        # v384: never bridge Android-native and browser GPS into one line. They can be
        # concurrent measurements of the same walk with different offsets, which was the
        # main source of the radial/zigzag history around large stations such as Osaki.
        # A true app restart may still reconnect when it remains on the same GPS source.
        short_session_restart = (
            not same_session
            and same_source
            and dt <= 75.0
            and dist <= 90.0
            and estimated_speed <= GPS_TRACK_WALK_MAX_SPEED_MPS
        )
        # Android/browser reported speed occasionally spikes while coordinates themselves
        # remain walk-like. Do not discard a valid 10m trace only because one speed field
        # is noisy. A very high reported speed still rejects a large movement.
        implausibly_fast_report = (
            reported_speed is not None
            and reported_speed > 8.0
            and dist > 30.0
        )
        walk_like = (
            (same_session or short_session_restart)
            and dt <= GPS_TRACK_SEGMENT_MAX_GAP_SECONDS
            and dist <= GPS_TRACK_SEGMENT_MAX_JUMP_M
            and estimated_speed <= GPS_TRACK_WALK_MAX_SPEED_MPS
            and not implausibly_fast_report
        )
        if walk_like:
            if not current:
                current = [[round(float(prev["lat"]), 7), round(float(prev["lon"]), 7)]]
            current.append([round(float(point["lat"]), 7), round(float(point["lon"]), 7)])
        else:
            if len(current) >= 2:
                segments.append(current)
            current = []
        prev = point
    if len(current) >= 2:
        segments.append(current)
    return segments


def _project_walk_distance_m_v271(segments):
    total = 0.0
    for segment in segments or []:
        for a, b in zip(segment, segment[1:]):
            try:
                total += _nearby_haversine_m(float(a[0]), float(a[1]), float(b[0]), float(b[1]))
            except Exception:
                pass
    return total


def _project_walk_points_v271(segments):
    points = []
    seen = set()
    for segment in segments or []:
        for pair in segment or []:
            try:
                lat = round(float(pair[0]), 7); lon = round(float(pair[1]), 7)
            except Exception:
                continue
            key = (lat, lon)
            if key in seen:
                continue
            seen.add(key)
            points.append({"id": f"{lat:.7f}_{lon:.7f}", "lat": lat, "lon": lon})
    return points


@st.cache_data(ttl=86400, max_entries=24, show_spinner=False)
def _project_station_candidates_v271(south, west, north, east):
    """Railway stations only.  Bus terminals must never become reached stations."""
    try:
        south = max(-90.0, float(south)); north = min(90.0, float(north))
        west = max(-180.0, float(west)); east = min(180.0, float(east))
    except (TypeError, ValueError):
        return []
    query = f"""[out:json][timeout:8];
(
  nwr["railway"~"^(station|halt)$"]({south:.5f},{west:.5f},{north:.5f},{east:.5f});
);
out center tags;"""
    data, _error = _toilet_overpass_fetch(query, timeout=5.5)
    elements = data.get("elements") if isinstance(data, dict) else []
    stations = []
    seen = set()
    for row in elements or []:
        if not isinstance(row, dict):
            continue
        tags = row.get("tags") if isinstance(row.get("tags"), dict) else {}
        name = str(tags.get("name:ja") or tags.get("name") or "").strip()
        if not name:
            continue
        center = row.get("center") if isinstance(row.get("center"), dict) else {}
        try:
            lat = float(row.get("lat") if row.get("lat") is not None else center.get("lat"))
            lon = float(row.get("lon") if row.get("lon") is not None else center.get("lon"))
        except (TypeError, ValueError):
            continue
        key = (name, round(lat, 5), round(lon, 5))
        if key in seen:
            continue
        seen.add(key)
        stations.append({
            "name": name,
            "lat": lat,
            "lon": lon,
            "osm_type": str(row.get("type") or ""),
            "osm_id": str(row.get("id") or ""),
        })
    return stations


def _project_station_path_simplify_v289(coords, max_points=160):
    coords = list(coords or [])
    if len(coords) <= int(max_points):
        return coords
    step = max(1, int(math.ceil(len(coords) / float(max_points))))
    out = coords[::step]
    if coords[-1] != out[-1]:
        out.append(coords[-1])
    return out


def _project_station_xy_v289(lat, lon, lat0, lon0):
    sy = 111320.0
    sx = 111320.0 * max(0.2, math.cos(math.radians(float(lat0))))
    return ((float(lon) - float(lon0)) * sx, (float(lat) - float(lat0)) * sy)


def _project_station_latlon_v289(x, y, lat0, lon0):
    sy = 111320.0
    sx = 111320.0 * max(0.2, math.cos(math.radians(float(lat0))))
    return [round(float(lat0) + float(y) / sy, 7), round(float(lon0) + float(x) / sx, 7)]


def _project_convex_hull_xy_v289(points):
    pts = sorted(set((round(float(x), 4), round(float(y), 4)) for x, y in (points or [])))
    if len(pts) <= 1:
        return pts
    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]


def _project_percentile_v289(values, q):
    vals = sorted(float(v) for v in (values or []))
    if not vals:
        return 0.0
    if len(vals) == 1:
        return vals[0]
    pos = max(0.0, min(1.0, float(q))) * (len(vals)-1)
    lo = int(math.floor(pos)); hi = int(math.ceil(pos))
    if lo == hi:
        return vals[lo]
    frac = pos - lo
    return vals[lo]*(1-frac) + vals[hi]*frac


def _project_station_axis_v290(points):
    """Principal axis for one geometry only; never mix unrelated rail branches here."""
    pts = [(float(x), float(y)) for x, y in (points or [])]
    if len(pts) < 2:
        return (0.0, 1.0)
    mx = sum(p[0] for p in pts) / len(pts)
    my = sum(p[1] for p in pts) / len(pts)
    xx = sum((p[0] - mx) ** 2 for p in pts) / len(pts)
    yy = sum((p[1] - my) ** 2 for p in pts) / len(pts)
    xy = sum((p[0] - mx) * (p[1] - my) for p in pts) / len(pts)
    angle = 0.5 * math.atan2(2.0 * xy, xx - yy)
    ux, uy = math.cos(angle), math.sin(angle)
    if uy < 0 or (abs(uy) < 1e-9 and ux < 0):
        ux, uy = -ux, -uy
    return ux, uy


def _project_angle_pi_v290(angle):
    a = float(angle) % math.pi
    return a + math.pi if a < 0 else a


def _project_angle_diff_pi_v290(a, b):
    d = abs((_project_angle_pi_v290(a) - _project_angle_pi_v290(b)) % math.pi)
    return min(d, math.pi - d)


def _project_weighted_parallel_axis_v290(descriptors):
    """Circular mean for 180-degree axes using doubled angles."""
    if not descriptors:
        return (0.0, 1.0, math.pi / 2.0)
    s = 0.0
    c = 0.0
    for d in descriptors:
        a = float(d.get("angle") or 0.0)
        w = max(1.0, float(d.get("weight") or d.get("length_m") or 1.0))
        s += w * math.sin(2.0 * a)
        c += w * math.cos(2.0 * a)
    a = 0.5 * math.atan2(s, c)
    if a < 0:
        a += math.pi
    ux, uy = math.cos(a), math.sin(a)
    if uy < 0 or (abs(uy) < 1e-9 and ux < 0):
        ux, uy = -ux, -uy
        a = (a + math.pi) % math.pi
    return ux, uy, a


def _project_path_descriptor_v290(points, station_x=0.0, station_y=0.0):
    pts = [(float(x), float(y)) for x, y in (points or [])]
    if len(pts) < 2:
        return None
    ux, uy = _project_station_axis_v290(pts)
    vx, vy = -uy, ux
    us = [x * ux + y * uy for x, y in pts]
    vs = [x * vx + y * vy for x, y in pts]
    u0 = _project_percentile_v289(us, 0.03)
    u1 = _project_percentile_v289(us, 0.97)
    v0 = _project_percentile_v289(vs, 0.10)
    v1 = _project_percentile_v289(vs, 0.90)
    length_m = max(0.0, u1 - u0)
    width_m = max(0.0, v1 - v0)
    mid_u = (u0 + u1) / 2.0
    mid_v = (v0 + v1) / 2.0
    cx = mid_u * ux + mid_v * vx
    cy = mid_u * uy + mid_v * vy
    center_m = math.hypot(cx - float(station_x), cy - float(station_y))
    angle = math.atan2(uy, ux) % math.pi
    return {
        "points": pts,
        "angle": angle,
        "ux": ux,
        "uy": uy,
        "length_m": length_m,
        "width_m": width_m,
        "cx": cx,
        "cy": cy,
        "center_m": center_m,
        # Long platforms close to the station dominate, but a single huge outlier cannot win alone.
        "weight": max(1.0, min(260.0, length_m)) / (1.0 + (center_m / 190.0) ** 2),
    }


def _project_dominant_parallel_cluster_v290(descriptors, angle_tolerance_deg):
    desc = [d for d in (descriptors or []) if isinstance(d, dict)]
    if not desc:
        return []
    tol = math.radians(float(angle_tolerance_deg))
    best = []
    best_score = -1.0
    for seed in desc:
        cluster = [d for d in desc if _project_angle_diff_pi_v290(d["angle"], seed["angle"]) <= tol]
        if not cluster:
            continue
        total_weight = sum(float(d.get("weight") or 0.0) for d in cluster)
        total_length = sum(min(260.0, float(d.get("length_m") or 0.0)) for d in cluster)
        # Multiple parallel platforms are much stronger evidence than a single branch line.
        score = total_weight + 0.22 * total_length + 18.0 * min(8, len(cluster))
        if score > best_score:
            best_score = score
            best = cluster
    if not best:
        return []
    # One refinement around the weighted cluster direction removes borderline branch lines.
    _ux, _uy, mean_angle = _project_weighted_parallel_axis_v290(best)
    refined = [d for d in best if _project_angle_diff_pi_v290(d["angle"], mean_angle) <= tol * 0.82]
    return refined or best


def _project_station_capsule_v290(u0, u1, v0, half_width, ux, uy):
    vx, vy = -uy, ux
    endpoints = [
        (u0 * ux + v0 * vx, u0 * uy + v0 * vy),
        (u1 * ux + v0 * vx, u1 * uy + v0 * vy),
    ]
    cloud = []
    r = max(1.0, float(half_width))
    for cx, cy in endpoints:
        for i in range(32):
            a = 2.0 * math.pi * i / 32.0
            cloud.append((cx + r * math.cos(a), cy + r * math.sin(a)))
    return _project_convex_hull_xy_v289(cloud)


def _project_point_in_polygon_xy_v290(x, y, polygon):
    if len(polygon or []) < 3:
        return False
    inside = False
    j = len(polygon) - 1
    for i in range(len(polygon)):
        xi, yi = polygon[i]
        xj, yj = polygon[j]
        if ((yi > y) != (yj > y)):
            denom = (yj - yi) if abs(yj - yi) > 1e-12 else 1e-12
            at_x = (xj - xi) * (y - yi) / denom + xi
            if x < at_x:
                inside = not inside
        j = i
    return inside


@st.cache_data(ttl=86400, max_entries=96, show_spinner=False)
def _project_station_corridor_v290(name, lat, lon):
    """Platform-first parallel-cluster robust capsule. Tracks are fallback only."""
    try:
        lat = float(lat)
        lon = float(lon)
    except (TypeError, ValueError):
        return {"arrival_zone": [], "physical_shapes": [], "source": "none"}

    area_r = int(GPS_TRACK_STATION_CORRIDOR_QUERY_RADIUS_M)
    track_r = int(GPS_TRACK_STATION_TRACK_AXIS_RADIUS_M)
    query = f"""[out:json][timeout:10];
(
  way(around:{area_r},{lat:.7f},{lon:.7f})["railway"="platform"];
  relation(around:{area_r},{lat:.7f},{lon:.7f})["railway"="platform"];
  way(around:{area_r},{lat:.7f},{lon:.7f})["building"="train_station"];
  relation(around:{area_r},{lat:.7f},{lon:.7f})["building"="train_station"];
  way(around:{area_r},{lat:.7f},{lon:.7f})["railway"="station"];
  relation(around:{area_r},{lat:.7f},{lon:.7f})["railway"="station"];
  way(around:{track_r},{lat:.7f},{lon:.7f})["railway"~"^(rail|subway|light_rail|monorail)$"];
);
out geom center tags;"""
    data, _error = _toilet_overpass_fetch(query, timeout=7.0)
    elements = data.get("elements") if isinstance(data, dict) else []

    platform_paths = []
    track_paths = []
    other_shapes = []

    def parsed_path(raw):
        out = []
        for node in raw or []:
            if not isinstance(node, dict):
                continue
            try:
                y = float(node.get("lat"))
                x = float(node.get("lon"))
            except (TypeError, ValueError):
                continue
            out.append([round(y, 7), round(x, 7)])
        return out

    def local_path(path, radius_m):
        out = []
        for p in path or []:
            try:
                if _nearby_haversine_m(lat, lon, float(p[0]), float(p[1])) <= float(radius_m):
                    out.append(p)
            except Exception:
                continue
        return out

    for row in elements or []:
        if not isinstance(row, dict):
            continue
        tags = row.get("tags") if isinstance(row.get("tags"), dict) else {}
        railway = str(tags.get("railway") or "")
        building = str(tags.get("building") or "")
        is_track = railway in {"rail", "subway", "light_rail", "monorail"}
        is_platform = railway == "platform"
        role = "track" if is_track else ("platform" if is_platform else ("building" if building == "train_station" else "station"))
        raw_paths = []
        if isinstance(row.get("geometry"), list):
            raw_paths.append(row.get("geometry"))
        if isinstance(row.get("members"), list):
            for member in row.get("members") or []:
                if isinstance(member, dict) and isinstance(member.get("geometry"), list):
                    raw_paths.append(member.get("geometry"))
        for raw in raw_paths:
            path = parsed_path(raw)
            if is_track:
                path = _project_station_path_simplify_v289(local_path(path, track_r), 120)
                if len(path) >= 2:
                    track_paths.append(path)
                continue
            path = _project_station_path_simplify_v289(local_path(path, area_r), 140)
            if len(path) < 2:
                continue
            closed = len(path) >= 4 and _nearby_haversine_m(path[0][0], path[0][1], path[-1][0], path[-1][1]) <= 8.0
            shape = {"kind": "polygon" if closed else "line", "role": role, "coords": path}
            if is_platform:
                platform_paths.append(path)
            else:
                other_shapes.append(shape)

    platform_desc = []
    for path in platform_paths:
        pts = [_project_station_xy_v289(p[0], p[1], lat, lon) for p in path]
        d = _project_path_descriptor_v290(pts)
        if not d:
            continue
        if d["length_m"] < float(GPS_TRACK_STATION_PLATFORM_MIN_LENGTH_M):
            continue
        if d["center_m"] > float(GPS_TRACK_STATION_PLATFORM_MAX_CENTER_M):
            continue
        d["path"] = path
        platform_desc.append(d)

    selected = _project_dominant_parallel_cluster_v290(
        platform_desc, GPS_TRACK_STATION_PLATFORM_CLUSTER_ANGLE_DEG
    )

    source = "platform_parallel_cluster"
    basis_points = []
    selected_shapes = []
    raw_platform_count = len(platform_desc)
    selected_platform_count = len(selected)

    if selected:
        ux, uy, axis_angle = _project_weighted_parallel_axis_v290(selected)
        selected_ids = {id(d) for d in selected}
        for d in selected:
            basis_points.extend(d["points"])
            p = d.get("path") or []
            if len(p) >= 2:
                closed = len(p) >= 4 and _nearby_haversine_m(p[0][0], p[0][1], p[-1][0], p[-1][1]) <= 8.0
                selected_shapes.append({"kind": "polygon" if closed else "line", "role": "platform", "coords": p})
    else:
        # Fallback: cluster each rail path separately. Never PCA all nearby rails together.
        track_desc = []
        for path in track_paths:
            pts = [_project_station_xy_v289(p[0], p[1], lat, lon) for p in path]
            d = _project_path_descriptor_v290(pts)
            if not d or d["length_m"] < 35.0 or d["center_m"] > float(GPS_TRACK_STATION_TRACK_AXIS_RADIUS_M):
                continue
            d["path"] = path
            track_desc.append(d)
        selected_tracks = _project_dominant_parallel_cluster_v290(track_desc, 13.0)
        if selected_tracks:
            ux, uy, axis_angle = _project_weighted_parallel_axis_v290(selected_tracks)
            source = "parallel_track_fallback"
            # Use only a short central portion to avoid following rail branches far from the station.
            for d in selected_tracks:
                basis_points.extend(d["points"])
        else:
            ux, uy, axis_angle = (0.0, 1.0, math.pi / 2.0)
            source = "axis_fallback"

    vx, vy = -uy, ux
    if basis_points and selected:
        us = [x * ux + y * uy for x, y in basis_points]
        vs = [x * vx + y * vy for x, y in basis_points]
        u_lo = _project_percentile_v289(us, 0.04) - float(GPS_TRACK_STATION_PLATFORM_LONG_PAD_M)
        u_hi = _project_percentile_v289(us, 0.96) + float(GPS_TRACK_STATION_PLATFORM_LONG_PAD_M)
        v_lo = _project_percentile_v289(vs, 0.04) - float(GPS_TRACK_STATION_PLATFORM_SIDE_PAD_M)
        v_hi = _project_percentile_v289(vs, 0.96) + float(GPS_TRACK_STATION_PLATFORM_SIDE_PAD_M)
        mid_u = (u_lo + u_hi) / 2.0
        v_mid = (v_lo + v_hi) / 2.0
        half_len = max(
            float(GPS_TRACK_STATION_PLATFORM_MIN_HALF_LENGTH_M),
            min(float(GPS_TRACK_STATION_PLATFORM_MAX_HALF_LENGTH_M), (u_hi - u_lo) / 2.0),
        )
        half_w = max(
            float(GPS_TRACK_STATION_PLATFORM_MIN_HALF_WIDTH_M),
            min(float(GPS_TRACK_STATION_PLATFORM_MAX_HALF_WIDTH_M), (v_hi - v_lo) / 2.0),
        )
        u0 = mid_u - half_len
        u1 = mid_u + half_len
    elif basis_points:
        us = [x * ux + y * uy for x, y in basis_points]
        vs = [x * vx + y * vy for x, y in basis_points]
        # Rail fallback is deliberately conservative: short, narrow, and centered near the station.
        mid_u = max(-25.0, min(25.0, _project_percentile_v289(us, 0.50)))
        v_mid = max(-22.0, min(22.0, _project_percentile_v289(vs, 0.50)))
        half_len = float(GPS_TRACK_STATION_TRACK_FALLBACK_HALF_LENGTH_M)
        half_w = float(GPS_TRACK_STATION_TRACK_FALLBACK_HALF_WIDTH_M)
        u0 = mid_u - half_len
        u1 = mid_u + half_len
    else:
        mid_u = 0.0
        v_mid = 0.0
        half_len = float(GPS_TRACK_STATION_TRACK_FALLBACK_HALF_LENGTH_M)
        half_w = float(GPS_TRACK_STATION_TRACK_FALLBACK_HALF_WIDTH_M)
        u0 = -half_len
        u1 = half_len

    corridor_xy = _project_station_capsule_v290(u0, u1, v_mid, half_w, ux, uy)
    arrival_zone = [_project_station_latlon_v289(x, y, lat, lon) for x, y in corridor_xy]
    axis_deg = (math.degrees(math.atan2(uy, ux)) + 360.0) % 180.0
    physical_shapes = selected_shapes + other_shapes[:12]
    return {
        "arrival_zone": arrival_zone,
        "physical_shapes": physical_shapes[:36],
        "source": source,
        "half_length_m": round(half_len, 1),
        "half_width_m": round(half_w, 1),
        "axis_deg": round(axis_deg, 1),
        "platform_point_count": sum(len(d.get("points") or []) for d in selected),
        "track_point_count": sum(len(p) for p in track_paths),
        "raw_platform_count": raw_platform_count,
        "selected_platform_count": selected_platform_count,
        "method": "platform_parallel_cluster_robust_capsule",
    }


def _project_track_enters_station_zone_v290(points, zone, lat0, lon0):
    if len(zone or []) < 3:
        return False
    poly = [_project_station_xy_v289(p[0], p[1], lat0, lon0) for p in zone]
    for point in points or []:
        try:
            px, py = _project_station_xy_v289(float(point["lat"]), float(point["lon"]), lat0, lon0)
        except Exception:
            continue
        if _project_point_in_polygon_xy_v290(px, py, poly):
            return True
    return False


def _project_stations_near_track_v290(points):
    if not points:
        return []
    lats=[float(p["lat"]) for p in points]; lons=[float(p["lon"]) for p in points]
    south,north=min(lats),max(lats); west,east=min(lons),max(lons)
    pad_lat=0.014; mid_lat=(south+north)/2.0; pad_lon=0.014/max(0.35,math.cos(math.radians(mid_lat)))
    stations=_project_station_candidates_v271(round(south-pad_lat,3),round(west-pad_lon,3),round(north+pad_lat,3),round(east+pad_lon,3))
    output=[]
    for station in stations or []:
        center_best=float("inf")
        for point in points:
            try:
                center_best=min(center_best,_nearby_haversine_m(float(station["lat"]),float(station["lon"]),float(point["lat"]),float(point["lon"])))
            except Exception:
                continue
        if center_best > GPS_TRACK_STATION_NEAR_RADIUS_M:
            continue
        fp=_project_station_corridor_v290(str(station.get("name") or "駅"),float(station["lat"]),float(station["lon"]))
        zone=fp.get("arrival_zone") if isinstance(fp,dict) else []
        arrived=_project_track_enters_station_zone_v290(points,zone,float(station["lat"]),float(station["lon"]))
        name=str(station.get("name") or "駅"); normalized=re.sub(r"\s+","",name)
        if normalized.endswith("駅"):
            normalized=normalized[:-1]
        debug_osaki=normalized=="大崎"
        output.append({"name":name,"lat":round(float(station["lat"]),7),"lon":round(float(station["lon"]),7),
                       "visited":bool(arrived),"arrived":bool(arrived),"distance_m":round(center_best,1),
                       "arrival_zone":zone if (arrived or debug_osaki) else [],
                       "physical_shapes":fp.get("physical_shapes",[]) if arrived else [],
                       "footprint_source":str(fp.get("source") or "none"),"half_length_m":fp.get("half_length_m"),
                       "half_width_m":fp.get("half_width_m"),"axis_deg":fp.get("axis_deg"),
                       "platform_point_count":fp.get("platform_point_count",0),"track_point_count":fp.get("track_point_count",0),
                       "raw_platform_count":fp.get("raw_platform_count",0),"selected_platform_count":fp.get("selected_platform_count",0),
                       "method":fp.get("method",""),"debug_osaki":debug_osaki})
    output.sort(key=lambda x:(not bool(x.get("arrived")),float(x.get("distance_m") or 999999),str(x.get("name") or "")))
    merged=[]
    for row in output:
        norm=re.sub(r"\s+","",str(row.get("name") or "駅")); norm=norm[:-1] if norm.endswith("駅") else norm
        dup=False
        for kept in merged:
            kn=re.sub(r"\s+","",str(kept.get("name") or "駅")); kn=kn[:-1] if kn.endswith("駅") else kn
            if kn != norm:
                continue
            try:
                gap=_nearby_haversine_m(float(row["lat"]),float(row["lon"]),float(kept["lat"]),float(kept["lon"]))
            except Exception:
                gap=999999.0
            if gap < 260.0:
                dup=True
                if bool(row.get("arrived")) and not bool(kept.get("arrived")):
                    kept.update(row)
                elif bool(row.get("debug_osaki")) and not bool(kept.get("debug_osaki")):
                    kept.update(row)
                break
        if not dup:
            merged.append(row)
    return merged[:120]


def _project_slippy_global_pixel_v291(lat, lon, zoom):
    """Web-Mercator global pixel coordinate for the standard 256px OSM tile grid."""
    lat = max(-85.05112878, min(85.05112878, float(lat)))
    lon = max(-180.0, min(180.0, float(lon)))
    scale = float((1 << int(zoom)) * 256)
    x = (lon + 180.0) / 360.0 * scale
    lat_r = math.radians(lat)
    y = (1.0 - math.asinh(math.tan(lat_r)) / math.pi) / 2.0 * scale
    return x, y


@st.cache_data(ttl=86400, max_entries=16, show_spinner=False)
def _project_osm_station_mosaic_v291(lat, lon, zoom=GPS_TRACK_STATION_VISION_ZOOM, tile_radius=GPS_TRACK_STATION_VISION_TILE_RADIUS):
    """Fetch a tiny cached OSM raster mosaic around one station for visual inference."""
    try:
        from PIL import Image
        lat = float(lat); lon = float(lon); zoom = int(zoom); tile_radius = int(tile_radius)
        gx, gy = _project_slippy_global_pixel_v291(lat, lon, zoom)
        tx = int(math.floor(gx / 256.0)); ty = int(math.floor(gy / 256.0))
        left = tx - tile_radius; top = ty - tile_radius
        size_tiles = tile_radius * 2 + 1
        jobs = []
        for yy in range(top, top + size_tiles):
            for xx in range(left, left + size_tiles):
                jobs.append((xx, yy))

        def fetch_one(pair):
            xx, yy = pair
            n = 1 << zoom
            if yy < 0 or yy >= n:
                return pair, None
            wrapped_x = xx % n
            url = f"https://tile.openstreetmap.org/{zoom}/{wrapped_x}/{yy}.png"
            req = Request(url, headers={
                "User-Agent": "TokyoBurariStationVision/1.0",
                "Accept": "image/png,image/*;q=0.8,*/*;q=0.5",
            })
            try:
                with urlopen(req, timeout=5.5) as resp:
                    return pair, resp.read()
            except Exception:
                return pair, None

        fetched = {}
        with ThreadPoolExecutor(max_workers=min(6, len(jobs))) as pool:
            for pair, raw in pool.map(fetch_one, jobs):
                fetched[pair] = raw
        if any(not fetched.get(pair) for pair in jobs):
            return {"ok": False, "error": "tile_fetch_failed"}

        mosaic = Image.new("RGB", (size_tiles * 256, size_tiles * 256), (242, 242, 242))
        for xx, yy in jobs:
            raw = fetched.get((xx, yy))
            with Image.open(io.BytesIO(raw)) as tile:
                tile = tile.convert("RGB")
                mosaic.paste(tile, ((xx - left) * 256, (yy - top) * 256))
        out = io.BytesIO()
        mosaic.save(out, format="PNG", optimize=False)
        center_x = gx - float(left * 256)
        center_y = gy - float(top * 256)
        mpp = 156543.03392804097 * math.cos(math.radians(lat)) / float(1 << zoom)
        return {
            "ok": True,
            "png": out.getvalue(),
            "center_x": round(center_x, 4),
            "center_y": round(center_y, 4),
            "meters_per_pixel": float(mpp),
            "zoom": zoom,
            "width": mosaic.width,
            "height": mosaic.height,
        }
    except Exception as exc:
        return {"ok": False, "error": f"mosaic:{type(exc).__name__}"}


def _project_smooth_profile_v291(values, radius=2):
    values = [float(v) for v in (values or [])]
    if not values:
        return []
    r = max(0, int(radius))
    if r <= 0:
        return values
    out = []
    for i in range(len(values)):
        a = max(0, i-r); b = min(len(values), i+r+1)
        out.append(sum(values[a:b]) / max(1, b-a))
    return out


def _project_station_image_corridor_v291(name, lat, lon):
    """Infer a station capsule from raster rail density/thickening around a known station point."""
    try:
        from PIL import Image, ImageFilter
        lat = float(lat); lon = float(lon)
    except Exception:
        return {"arrival_zone": [], "source": "vision_import_failed", "method": "map_image_rail_density"}

    mosaic = _project_osm_station_mosaic_v291(lat, lon)
    if not isinstance(mosaic, dict) or not mosaic.get("ok") or not mosaic.get("png"):
        fallback = _project_station_corridor_v290(name, lat, lon)
        fallback = dict(fallback or {})
        fallback["source"] = "vision_tile_failed_platform_fallback"
        fallback["method"] = "map_image_failed_platform_fallback"
        fallback["vision_score"] = 0.0
        fallback["vision_threshold"] = None
        return fallback

    try:
        with Image.open(io.BytesIO(mosaic["png"])) as src:
            img = src.convert("RGB")
        hsv = img.convert("HSV")
        rgb_data = list(img.getdata())
        hsv_data = list(hsv.getdata())
        # Pixel score: railways on the standard map are predominantly neutral/dark gray.
        # Pure black label cores are down-weighted; pale roads/background are discarded.
        raw_mask = bytearray(len(rgb_data))
        for i, ((r, g, b), (_h, sat, val)) in enumerate(zip(rgb_data, hsv_data)):
            spread = max(r, g, b) - min(r, g, b)
            # Standard OSM rail strokes are neutral medium/dark grays.  Roads/building
            # fills are generally lighter; label cores are much darker.  Weight the
            # railway-like middle band most strongly and keep a softer antialias band.
            if sat <= 50 and spread <= 24 and 52 <= val <= 162:
                darkness = max(0, 168 - int(val))
                raw_mask[i] = min(255, 122 + darkness)
            elif sat <= 74 and spread <= 38 and 44 <= val <= 176:
                darkness = max(0, 176 - int(val))
                raw_mask[i] = min(168, 58 + darkness // 2)
            elif sat <= 44 and spread <= 20 and 34 <= val < 44:
                raw_mask[i] = 28
            else:
                raw_mask[i] = 0
        mask = Image.frombytes("L", img.size, bytes(raw_mask))
        density = mask.filter(ImageFilter.GaussianBlur(radius=4.2))
        dens = density.load()
        cx = float(mosaic["center_x"]); cy = float(mosaic["center_y"])
        mpp = float(mosaic["meters_per_pixel"])
        radius_m = float(GPS_TRACK_STATION_VISION_RADIUS_M)
        radius_px = radius_m / max(0.05, mpp)

        # Estimate an adaptive high-density threshold in the local station window.
        sampled = []
        step = 3
        x0 = max(0, int(cx-radius_px)); x1 = min(img.width-1, int(cx+radius_px))
        y0 = max(0, int(cy-radius_px)); y1 = min(img.height-1, int(cy+radius_px))
        r2 = radius_px * radius_px
        for py in range(y0, y1+1, step):
            dy = py-cy
            for px in range(x0, x1+1, step):
                dx = px-cx
                if dx*dx + dy*dy <= r2:
                    sampled.append(int(dens[px, py]))
        if len(sampled) < 80:
            raise ValueError("too_few_density_samples")
        p78 = _project_percentile_v289(sampled, 0.78)
        p88 = _project_percentile_v289(sampled, 0.88)
        threshold = max(18.0, min(92.0, p78 + 0.32 * max(0.0, p88-p78)))

        # Weighted covariance of dense neutral pixels gives the dominant rail-bundle axis.
        pts = []
        for py in range(y0, y1+1, 2):
            ym = -(py-cy) * mpp
            for px in range(x0, x1+1, 2):
                score = float(dens[px, py])
                if score < threshold:
                    continue
                xm = (px-cx) * mpp
                rr = math.hypot(xm, ym)
                if rr > radius_m:
                    continue
                radial = max(0.20, 1.0 - (rr / radius_m) ** 1.7)
                w = max(1.0, score-threshold+5.0) * radial
                pts.append((xm, ym, w, score))
        if len(pts) < 60:
            raise ValueError("too_few_rail_pixels")
        sw = sum(p[2] for p in pts)
        mx = sum(p[0]*p[2] for p in pts)/sw
        my = sum(p[1]*p[2] for p in pts)/sw
        xx = sum((p[0]-mx)**2*p[2] for p in pts)/sw
        yy = sum((p[1]-my)**2*p[2] for p in pts)/sw
        xy = sum((p[0]-mx)*(p[1]-my)*p[2] for p in pts)/sw
        angle = 0.5 * math.atan2(2.0*xy, xx-yy)
        ux, uy = math.cos(angle), math.sin(angle)
        if uy < 0 or (abs(uy) < 1e-9 and ux < 0):
            ux, uy = -ux, -uy
        vx, vy = -uy, ux

        # Reproject dense pixels to station coordinates and measure how thick the rail bundle
        # is in successive slices.  This directly implements "where the tracks get thicker".
        u_limit = float(GPS_TRACK_STATION_VISION_U_LIMIT_M)
        v_limit = float(GPS_TRACK_STATION_VISION_V_LIMIT_M)
        bin_m = float(GPS_TRACK_STATION_VISION_BIN_M)
        bin_count = int(math.ceil((2.0*u_limit)/bin_m)) + 1
        slice_vs = [[] for _ in range(bin_count)]
        slice_weight = [0.0 for _ in range(bin_count)]
        projected = []
        for x, y, w, score in pts:
            u = x*ux + y*uy
            v = x*vx + y*vy
            if abs(u) > u_limit or abs(v) > v_limit:
                continue
            bi = int((u + u_limit) / bin_m)
            if 0 <= bi < bin_count:
                slice_vs[bi].append(v)
                slice_weight[bi] += max(1.0, score-threshold+3.0)
                projected.append((u, v, score))

        width_profile = []
        count_profile = []
        for vals, weight in zip(slice_vs, slice_weight):
            if len(vals) >= 4:
                span = _project_percentile_v289(vals, 0.88) - _project_percentile_v289(vals, 0.12)
            else:
                span = 0.0
            width_profile.append(max(0.0, min(2.0*v_limit, span)))
            count_profile.append(float(weight))
        swidth = _project_smooth_profile_v291(width_profile, 2)
        scount = _project_smooth_profile_v291(count_profile, 2)
        if not swidth or max(scount, default=0.0) <= 0:
            raise ValueError("empty_profiles")
        max_count = max(scount) or 1.0
        max_width = max(swidth) or 1.0
        thick_score = [0.64*(c/max_count) + 0.36*(w/max_width) for c, w in zip(scount, swidth)]
        thick_score = _project_smooth_profile_v291(thick_score, 1)

        # Seed from the strongest thickening near the station anchor, not from remote roads.
        centers_u = [-u_limit + (i+0.5)*bin_m for i in range(bin_count)]
        near_idx = [i for i,u in enumerate(centers_u) if abs(u) <= 105.0]
        seed = max(near_idx, key=lambda i: thick_score[i]) if near_idx else max(range(bin_count), key=lambda i: thick_score[i])
        peak = thick_score[seed]
        outer = [thick_score[i] for i,u in enumerate(centers_u) if 155.0 <= abs(u) <= u_limit]
        baseline = _project_percentile_v289(outer, 0.50) if outer else _project_percentile_v289(thick_score, 0.35)
        cut = max(0.24, min(0.72, baseline + 0.34*max(0.0, peak-baseline), peak*0.43))

        left_i = right_i = seed
        misses = 0
        i = seed-1
        while i >= 0:
            if thick_score[i] >= cut:
                left_i = i; misses = 0
            else:
                misses += 1
                if misses >= 2:
                    break
            i -= 1
        misses = 0
        i = seed+1
        while i < bin_count:
            if thick_score[i] >= cut:
                right_i = i; misses = 0
            else:
                misses += 1
                if misses >= 2:
                    break
            i += 1

        u0 = centers_u[left_i] - bin_m/2.0 - float(GPS_TRACK_STATION_VISION_LONG_PAD_M)
        u1 = centers_u[right_i] + bin_m/2.0 + float(GPS_TRACK_STATION_VISION_LONG_PAD_M)
        # If the adaptive slice is too short/long, expand/clip around its measured midpoint.
        mid_u = (u0+u1)/2.0
        half_len = max(float(GPS_TRACK_STATION_VISION_MIN_HALF_LENGTH_M), min(float(GPS_TRACK_STATION_VISION_MAX_HALF_LENGTH_M), (u1-u0)/2.0))
        u0 = mid_u-half_len; u1 = mid_u+half_len

        station_vs = [v for u,v,_score in projected if (u0-8.0) <= u <= (u1+8.0)]
        if len(station_vs) >= 16:
            v_lo = _project_percentile_v289(station_vs, 0.10)
            v_hi = _project_percentile_v289(station_vs, 0.90)
            v_mid = (v_lo+v_hi)/2.0
            half_w = (v_hi-v_lo)/2.0 + float(GPS_TRACK_STATION_VISION_SIDE_PAD_M)
        else:
            v_mid = 0.0
            half_w = float(GPS_TRACK_STATION_VISION_MIN_HALF_WIDTH_M)
        half_w = max(float(GPS_TRACK_STATION_VISION_MIN_HALF_WIDTH_M), min(float(GPS_TRACK_STATION_VISION_MAX_HALF_WIDTH_M), half_w))

        # Prevent labels/buildings from shifting the fitted station far away from the OSM anchor.
        mid_u = max(-52.0, min(52.0, mid_u))
        v_mid = max(-42.0, min(42.0, v_mid))
        u0 = mid_u-half_len; u1 = mid_u+half_len
        capsule_xy = _project_station_capsule_v290(u0, u1, v_mid, half_w, ux, uy)
        zone = [_project_station_latlon_v289(x, y, lat, lon) for x, y in capsule_xy]
        axis_deg = (math.degrees(math.atan2(uy, ux)) + 360.0) % 180.0
        contrast = max(0.0, peak-baseline)
        vision_score = max(0.0, min(1.0, 0.62*peak + 0.38*contrast))
        return {
            "arrival_zone": zone,
            "physical_shapes": [],
            "source": "map_image_rail_density",
            "method": "map_image_station_anchor_plus_rail_bundle_thickening",
            "half_length_m": round(half_len, 1),
            "half_width_m": round(half_w, 1),
            "axis_deg": round(axis_deg, 1),
            "vision_score": round(vision_score, 3),
            "vision_threshold": round(float(threshold), 1),
            "vision_peak": round(float(peak), 3),
            "vision_baseline": round(float(baseline), 3),
            "tile_zoom": int(mosaic.get("zoom") or GPS_TRACK_STATION_VISION_ZOOM),
            "raw_platform_count": 0,
            "selected_platform_count": 0,
            "platform_point_count": 0,
            "track_point_count": len(pts),
        }
    except Exception as exc:
        fallback = _project_station_corridor_v290(name, lat, lon)
        fallback = dict(fallback or {})
        fallback["source"] = "vision_analysis_failed_platform_fallback"
        fallback["method"] = f"map_image_failed:{type(exc).__name__}"
        fallback["vision_score"] = 0.0
        fallback["vision_threshold"] = None
        return fallback


def _station_zone_cache_key_v292(name, lat, lon):
    """Stable station identity. Rounded anchor tolerates tiny OSM coordinate changes."""
    normalized = unicodedata.normalize("NFKC", str(name or "駅")).strip()
    normalized = re.sub(r"\s+", "", normalized) or "駅"
    try:
        lat = round(float(lat), 2)
        lon = round(float(lon), 2)
    except (TypeError, ValueError):
        lat = 0.0
        lon = 0.0
    raw = f"{normalized}|{lat:.2f}|{lon:.2f}".encode("utf-8")
    return hashlib.sha1(raw).hexdigest()[:24]


def _station_zone_cache_path_v292(name, lat, lon):
    return f"{STATION_ZONE_CACHE_DIR}/{_station_zone_cache_key_v292(name, lat, lon)}.json"


def _coerce_station_zone_record_v292(payload):
    if not isinstance(payload, dict):
        return None
    if int(payload.get("schema_version") or 0) != int(STATION_ZONE_CACHE_SCHEMA_VERSION):
        return None
    zone = []
    for raw in (payload.get("arrival_zone") or [])[:STATION_ZONE_CACHE_MAX_POINTS]:
        if not isinstance(raw, (list, tuple)) or len(raw) < 2:
            continue
        try:
            lat = float(raw[0]); lon = float(raw[1])
        except (TypeError, ValueError):
            continue
        if not (math.isfinite(lat) and math.isfinite(lon) and -90 <= lat <= 90 and -180 <= lon <= 180):
            continue
        zone.append([round(lat, 7), round(lon, 7)])
    if len(zone) < 3:
        return None

    out = {
        "arrival_zone": zone,
        "physical_shapes": [],
        "source": str(payload.get("source") or "stored_numeric_station_zone")[:120],
        "method": str(payload.get("method") or "stored_numeric_station_zone")[:160],
        "station_name": str(payload.get("station_name") or "駅")[:120],
        "generated_at": str(payload.get("generated_at") or "")[:80],
        "geometry_hash": str(payload.get("geometry_hash") or "")[:64],
        "estimator_build": str(payload.get("estimator_build") or "")[:40],
    }
    for key in ("half_length_m", "half_width_m", "axis_deg", "vision_score", "vision_threshold", "vision_peak", "vision_baseline"):
        value = payload.get(key)
        if value is None:
            out[key] = None
            continue
        try:
            value = float(value)
            out[key] = round(value, 4) if math.isfinite(value) else None
        except (TypeError, ValueError):
            out[key] = None
    try:
        out["tile_zoom"] = int(payload.get("tile_zoom")) if payload.get("tile_zoom") is not None else None
    except (TypeError, ValueError):
        out["tile_zoom"] = None
    for key in ("raw_platform_count", "selected_platform_count", "platform_point_count", "track_point_count"):
        try:
            out[key] = max(0, int(payload.get(key) or 0))
        except (TypeError, ValueError):
            out[key] = 0
    return out


@st.cache_data(ttl=STATION_ZONE_CACHE_READ_TTL_SECONDS, max_entries=256, show_spinner=False)
def _read_station_zone_record_v292(path):
    try:
        raw = supabase_client().storage.from_(GPS_TRACK_BUCKET).download(str(path))
    except Exception:
        return None
    try:
        payload = json.loads(bytes(raw).decode("utf-8"))
    except Exception:
        return None
    return _coerce_station_zone_record_v292(payload)


def _save_station_zone_record_v292(name, lat, lon, footprint):
    """Persist exact inferred geometry. Only successful image inference is frozen."""
    if not isinstance(footprint, dict):
        return False
    method = str(footprint.get("method") or "")
    zone = footprint.get("arrival_zone") or []
    if not method.startswith("map_image_station_anchor") or len(zone) < 3:
        return False

    clean_zone = []
    for raw in zone[:STATION_ZONE_CACHE_MAX_POINTS]:
        if not isinstance(raw, (list, tuple)) or len(raw) < 2:
            continue
        try:
            p_lat = float(raw[0]); p_lon = float(raw[1])
        except (TypeError, ValueError):
            continue
        if math.isfinite(p_lat) and math.isfinite(p_lon):
            clean_zone.append([round(p_lat, 7), round(p_lon, 7)])
    if len(clean_zone) < 3:
        return False

    geometry_raw = json.dumps(clean_zone, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    document = {
        "schema_version": int(STATION_ZONE_CACHE_SCHEMA_VERSION),
        "station_name": str(name or "駅")[:120],
        "anchor_lat": round(float(lat), 7),
        "anchor_lon": round(float(lon), 7),
        "arrival_zone": clean_zone,
        "half_length_m": footprint.get("half_length_m"),
        "half_width_m": footprint.get("half_width_m"),
        "axis_deg": footprint.get("axis_deg"),
        "vision_score": footprint.get("vision_score"),
        "vision_threshold": footprint.get("vision_threshold"),
        "vision_peak": footprint.get("vision_peak"),
        "vision_baseline": footprint.get("vision_baseline"),
        "tile_zoom": footprint.get("tile_zoom"),
        "raw_platform_count": footprint.get("raw_platform_count", 0),
        "selected_platform_count": footprint.get("selected_platform_count", 0),
        "platform_point_count": footprint.get("platform_point_count", 0),
        "track_point_count": footprint.get("track_point_count", 0),
        "source": str(footprint.get("source") or "map_image_rail_density")[:120],
        "method": method[:160],
        "estimator_build": "v291-map-image-rail-density",
        "generated_at": now_jst().isoformat(),
        "geometry_hash": hashlib.sha1(geometry_raw).hexdigest(),
    }
    blob = json.dumps(document, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    path = _station_zone_cache_path_v292(name, lat, lon)
    bucket = supabase_client().storage.from_(GPS_TRACK_BUCKET)
    options = {"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "3600", "upsert": "true"}
    first_error = None
    try:
        bucket.upload(path=path, file=blob, file_options=options)
    except Exception as exc:
        first_error = exc
        try:
            bucket.update(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "3600"})
        except Exception:
            try:
                bucket.remove([path])
            except Exception:
                pass
            try:
                bucket.upload(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "3600"})
            except Exception:
                if first_error:
                    raise first_error
                raise
    _read_station_zone_record_v292.clear()
    return True


def _project_station_image_corridor_persisted_v292(name, lat, lon):
    """Read the frozen numeric zone first; infer from map pixels only on first success."""
    path = _station_zone_cache_path_v292(name, lat, lon)
    normalized_name = re.sub(r"\s+", "", unicodedata.normalize("NFKC", str(name or "駅")))
    force_rebuild = normalized_name in STATION_ZONE_FORCE_REBUILD_NAMES
    saved = None if force_rebuild else _read_station_zone_record_v292(path)
    if isinstance(saved, dict) and len(saved.get("arrival_zone") or []) >= 3:
        result = dict(saved)
        result["source"] = "stored_numeric_station_zone"
        result["zone_cache_status"] = "loaded"
        result["zone_cache_key"] = _station_zone_cache_key_v292(name, lat, lon)
        return result

    inferred = dict(_project_station_image_corridor_v291(name, lat, lon) or {})
    inferred["zone_cache_status"] = "not_saved"
    inferred["zone_cache_key"] = _station_zone_cache_key_v292(name, lat, lon)
    try:
        if _save_station_zone_record_v292(name, lat, lon, inferred):
            inferred["zone_cache_status"] = "saved"
    except Exception:
        inferred["zone_cache_status"] = "save_failed"
    return inferred


def _project_osaki_forced_debug_v292(points):
    lat=35.61939; lon=139.72849
    fp=_project_station_image_corridor_persisted_v292("大崎駅",lat,lon)
    zone=fp.get("arrival_zone") if isinstance(fp,dict) else []
    arrived=_project_track_enters_station_zone_v290(points,zone,lat,lon)
    center_best=float("inf")
    for point in points or []:
        try:
            center_best=min(center_best,_nearby_haversine_m(lat,lon,float(point["lat"]),float(point["lon"])))
        except Exception:
            continue
    return {"name":"大崎駅","lat":lat,"lon":lon,"visited":bool(arrived),"arrived":bool(arrived),
            "distance_m":round(center_best,1) if math.isfinite(center_best) else None,"arrival_zone":zone,"physical_shapes":[],
            "footprint_source":str(fp.get("source") or "none"),"half_length_m":fp.get("half_length_m"),
            "half_width_m":fp.get("half_width_m"),"axis_deg":fp.get("axis_deg"),
            "platform_point_count":fp.get("platform_point_count",0),"track_point_count":fp.get("track_point_count",0),
            "raw_platform_count":fp.get("raw_platform_count",0),"selected_platform_count":fp.get("selected_platform_count",0),
            "method":fp.get("method",""),"vision_score":fp.get("vision_score",0.0),
            "vision_threshold":fp.get("vision_threshold"),"vision_peak":fp.get("vision_peak"),
            "vision_baseline":fp.get("vision_baseline"),"tile_zoom":fp.get("tile_zoom"),
            "zone_cache_status":fp.get("zone_cache_status",""),"zone_cache_key":fp.get("zone_cache_key",""),
            "geometry_hash":fp.get("geometry_hash",""),"generated_at":fp.get("generated_at",""),
            "debug_osaki":True,"forced_debug":True}


def _station_visit_state_key_v293(family_key, member_key):
    raw = f"{str(family_key or 'default').strip()}|{str(member_key or 'main').strip()}".encode("utf-8")
    return hashlib.sha1(raw).hexdigest()[:28]


def _station_visit_state_path_v293(family_key, member_key):
    return f"{STATION_VISIT_STATE_DIR}/{_station_visit_state_key_v293(family_key, member_key)}.json"


def _station_name_base_v293(name):
    normalized = re.sub(r"\s+", "", unicodedata.normalize("NFKC", str(name or "駅"))).strip()
    if normalized.endswith("駅"):
        normalized = normalized[:-1]
    return normalized or "駅"


def _station_row_key_v293(name, lat, lon):
    # Reuse the global geometry identity so the per-user visit state and the global
    # numeric station-zone cache refer to the same physical station.
    return _station_zone_cache_key_v292(name, lat, lon)


def _station_scan_cell_v293(lat, lon):
    step = float(STATION_SCAN_CELL_DEGREES)
    try:
        lat = float(lat); lon = float(lon)
    except (TypeError, ValueError):
        return ""
    if not (math.isfinite(lat) and math.isfinite(lon)):
        return ""
    return f"{int(math.floor((lat + 90.0) / step))}:{int(math.floor((lon + 180.0) / step))}"


def _clean_station_zone_v293(zone):
    clean = []
    for raw in (zone or [])[:STATION_ZONE_CACHE_MAX_POINTS]:
        if not isinstance(raw, (list, tuple)) or len(raw) < 2:
            continue
        try:
            lat = float(raw[0]); lon = float(raw[1])
        except (TypeError, ValueError):
            continue
        if not (math.isfinite(lat) and math.isfinite(lon) and -90 <= lat <= 90 and -180 <= lon <= 180):
            continue
        clean.append([round(lat, 7), round(lon, 7)])
    return clean


def _coerce_station_state_row_v293(raw):
    if not isinstance(raw, dict):
        return None
    try:
        lat = float(raw.get("lat")); lon = float(raw.get("lon"))
    except (TypeError, ValueError):
        return None
    if not (math.isfinite(lat) and math.isfinite(lon) and -90 <= lat <= 90 and -180 <= lon <= 180):
        return None
    name = str(raw.get("name") or "駅")[:120]
    row = {
        "name": name,
        "lat": round(lat, 7),
        "lon": round(lon, 7),
        "visited": bool(raw.get("arrived") or raw.get("visited")),
        "arrived": bool(raw.get("arrived") or raw.get("visited")),
        "distance_m": None,
        "arrival_zone": _clean_station_zone_v293(raw.get("arrival_zone")),
        "physical_shapes": [],
        "footprint_source": str(raw.get("footprint_source") or raw.get("source") or "saved_station_state")[:120],
        "method": str(raw.get("method") or "")[:160],
        "debug_osaki": bool(raw.get("debug_osaki")),
        "zone_cache_status": str(raw.get("zone_cache_status") or "state_loaded")[:40],
        "zone_cache_key": str(raw.get("zone_cache_key") or _station_row_key_v293(name, lat, lon))[:64],
    }
    value = raw.get("distance_m")
    try:
        value = float(value) if value is not None else None
        row["distance_m"] = round(value, 1) if value is not None and math.isfinite(value) else None
    except (TypeError, ValueError):
        row["distance_m"] = None
    for key in ("half_length_m", "half_width_m", "axis_deg", "vision_score", "vision_threshold", "vision_peak", "vision_baseline"):
        value = raw.get(key)
        try:
            value = float(value) if value is not None else None
            row[key] = round(value, 4) if value is not None and math.isfinite(value) else None
        except (TypeError, ValueError):
            row[key] = None
    for key in ("raw_platform_count", "selected_platform_count", "platform_point_count", "track_point_count"):
        try:
            row[key] = max(0, int(raw.get(key) or 0))
        except (TypeError, ValueError):
            row[key] = 0
    return row


def _station_state_row_document_v293(row):
    normalized = _coerce_station_state_row_v293(row)
    if not normalized:
        return None
    return {
        "name": normalized["name"],
        "lat": normalized["lat"],
        "lon": normalized["lon"],
        "arrived": bool(normalized["arrived"]),
        "distance_m": normalized.get("distance_m"),
        "arrival_zone": normalized.get("arrival_zone") or [],
        "footprint_source": normalized.get("footprint_source") or "",
        "method": normalized.get("method") or "",
        "half_length_m": normalized.get("half_length_m"),
        "half_width_m": normalized.get("half_width_m"),
        "axis_deg": normalized.get("axis_deg"),
        "vision_score": normalized.get("vision_score"),
        "vision_threshold": normalized.get("vision_threshold"),
        "vision_peak": normalized.get("vision_peak"),
        "vision_baseline": normalized.get("vision_baseline"),
        "raw_platform_count": normalized.get("raw_platform_count", 0),
        "selected_platform_count": normalized.get("selected_platform_count", 0),
        "platform_point_count": normalized.get("platform_point_count", 0),
        "track_point_count": normalized.get("track_point_count", 0),
        "debug_osaki": bool(normalized.get("debug_osaki")),
        "zone_cache_status": normalized.get("zone_cache_status") or "",
        "zone_cache_key": normalized.get("zone_cache_key") or "",
    }


@st.cache_data(ttl=STATION_VISIT_STATE_READ_TTL_SECONDS, max_entries=32, show_spinner=False)
def _read_station_visit_state_v293(family_key, member_key):
    path = _station_visit_state_path_v293(family_key, member_key)
    try:
        raw = supabase_client().storage.from_(GPS_TRACK_BUCKET).download(path)
        payload = json.loads(bytes(raw).decode("utf-8"))
    except Exception:
        return None
    if not isinstance(payload, dict) or int(payload.get("schema_version") or 0) != int(STATION_VISIT_STATE_SCHEMA_VERSION):
        return None
    stations = []
    for item in (payload.get("stations") or [])[:STATION_VISIT_STATE_MAX_STATIONS]:
        row = _coerce_station_state_row_v293(item)
        if row:
            stations.append(row)
    cells = []
    seen_cells = set()
    for cell in (payload.get("scan_cells") or [])[:STATION_VISIT_STATE_MAX_SCAN_CELLS]:
        cell = str(cell or "")[:64]
        if cell and cell not in seen_cells:
            seen_cells.add(cell); cells.append(cell)
    try:
        checked = max(0, int(payload.get("checked_through_ts_ms") or 0))
    except (TypeError, ValueError):
        checked = 0
    try:
        gps_count = max(0, int(payload.get("gps_point_count") or 0))
    except (TypeError, ValueError):
        gps_count = 0
    return {
        "checked_through_ts_ms": checked,
        "gps_point_count": gps_count,
        "scan_cells": cells,
        "stations": stations,
        "saved_at": str(payload.get("saved_at") or "")[:80],
    }


def _save_station_visit_state_v293(family_key, member_key, checked_through_ts_ms, gps_point_count, scan_cells, stations):
    rows = []
    for row in (stations or [])[:STATION_VISIT_STATE_MAX_STATIONS]:
        item = _station_state_row_document_v293(row)
        if item:
            rows.append(item)
    document = {
        "schema_version": int(STATION_VISIT_STATE_SCHEMA_VERSION),
        "checked_through_ts_ms": max(0, int(checked_through_ts_ms or 0)),
        "gps_point_count": max(0, int(gps_point_count or 0)),
        "scan_cells": list(dict.fromkeys(str(x) for x in (scan_cells or []) if str(x)))[:STATION_VISIT_STATE_MAX_SCAN_CELLS],
        "stations": rows,
        "saved_at": now_jst().isoformat(),
        "app_build": "v293",
    }
    blob = json.dumps(document, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    path = _station_visit_state_path_v293(family_key, member_key)
    bucket = supabase_client().storage.from_(GPS_TRACK_BUCKET)
    options = {"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "120", "upsert": "true"}
    try:
        bucket.upload(path=path, file=blob, file_options=options)
    except Exception:
        try:
            bucket.update(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "120"})
        except Exception:
            try:
                bucket.remove([path])
            except Exception:
                pass
            bucket.upload(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "120"})
    _read_station_visit_state_v293.clear()
    return True


def _project_walk_raw_points_v293(points):
    """Return render-safe GPS rows that participate in a walk-like edge, preserving ts_ms."""
    output = []
    seen = set()
    prev = None
    for point in _project_clean_track_points_v372(points):
        if not isinstance(point, dict):
            continue
        if prev is None:
            prev = point
            continue
        try:
            dt = max(0.001, (float(point.get("ts_ms")) - float(prev.get("ts_ms"))) / 1000.0)
            dist = _nearby_haversine_m(float(prev["lat"]), float(prev["lon"]), float(point["lat"]), float(point["lon"]))
        except Exception:
            prev = point
            continue
        reported_speed = point.get("speed_mps")
        try:
            reported_speed = float(reported_speed) if reported_speed is not None else None
        except (TypeError, ValueError):
            reported_speed = None
        estimated_speed = dist / dt if dt > 0 else 999.0
        effective_speed = max(reported_speed, estimated_speed) if reported_speed is not None and reported_speed >= 0 else estimated_speed
        same_session = bool(str(point.get("session_id") or "")) and str(point.get("session_id") or "") == str(prev.get("session_id") or "")
        walk_like = (
            same_session
            and dt <= GPS_TRACK_SEGMENT_MAX_GAP_SECONDS
            and dist <= GPS_TRACK_SEGMENT_MAX_JUMP_M
            and effective_speed <= GPS_TRACK_WALK_MAX_SPEED_MPS
        )
        if walk_like:
            for row in (prev, point):
                key = str(row.get("id") or f"{row.get('ts_ms')}|{row.get('lat')}|{row.get('lon')}")
                if key not in seen:
                    seen.add(key); output.append(row)
        prev = point
    return output


def _station_center_best_distance_v293(station, points):
    best = float("inf")
    try:
        s_lat = float(station.get("lat")); s_lon = float(station.get("lon"))
    except Exception:
        return best
    for point in points or []:
        try:
            best = min(best, _nearby_haversine_m(s_lat, s_lon, float(point["lat"]), float(point["lon"])))
        except Exception:
            continue
    return best


def _station_candidates_for_points_v293(points):
    if not points:
        return []
    try:
        lats = [float(p["lat"]) for p in points]
        lons = [float(p["lon"]) for p in points]
    except Exception:
        return []
    south, north = min(lats), max(lats); west, east = min(lons), max(lons)
    pad_lat = float(STATION_PREFLIGHT_DISCOVERY_PAD_M) / 111320.0
    mid_lat = (south + north) / 2.0
    pad_lon = pad_lat / max(0.35, math.cos(math.radians(mid_lat)))
    return _project_station_candidates_v271(
        round(south - pad_lat, 4), round(west - pad_lon, 4),
        round(north + pad_lat, 4), round(east + pad_lon, 4),
    )


def _merge_station_rows_v293(rows):
    ordered = sorted(
        (r for r in (rows or []) if isinstance(r, dict)),
        key=lambda x: (not bool(x.get("arrived")), float(x.get("distance_m") if x.get("distance_m") is not None else 999999.0), str(x.get("name") or "")),
    )
    merged = []
    for row in ordered:
        name_base = _station_name_base_v293(row.get("name"))
        duplicate = None
        for kept in merged:
            if _station_name_base_v293(kept.get("name")) != name_base:
                continue
            try:
                gap = _nearby_haversine_m(float(row["lat"]), float(row["lon"]), float(kept["lat"]), float(kept["lon"]))
            except Exception:
                gap = 999999.0
            if gap < 260.0:
                duplicate = kept
                break
        if duplicate is None:
            merged.append(dict(row)); continue
        prefer = False
        if bool(row.get("debug_osaki")) and not bool(duplicate.get("debug_osaki")):
            prefer = True
        elif bool(row.get("arrived")) and not bool(duplicate.get("arrived")):
            prefer = True
        elif len(row.get("arrival_zone") or []) >= 3 and len(duplicate.get("arrival_zone") or []) < 3:
            prefer = True
        if prefer:
            duplicate.clear(); duplicate.update(dict(row))
        else:
            duplicate["arrived"] = bool(duplicate.get("arrived") or row.get("arrived"))
            duplicate["visited"] = bool(duplicate.get("arrived"))
            candidates = [v for v in (duplicate.get("distance_m"), row.get("distance_m")) if v is not None]
            if candidates:
                duplicate["distance_m"] = min(float(v) for v in candidates)
    return merged[:STATION_VISIT_STATE_MAX_STATIONS]


def _station_row_from_footprint_v293(station, footprint, map_points, debug_osaki=False):
    name = str(station.get("name") or "駅")
    lat = float(station["lat"]); lon = float(station["lon"])
    fp = dict(footprint or {})
    zone = _clean_station_zone_v293(fp.get("arrival_zone"))
    arrived = _project_track_enters_station_zone_v290(map_points, zone, lat, lon) if len(zone) >= 3 else False
    best = _station_center_best_distance_v293({"lat": lat, "lon": lon}, map_points)
    return {
        "name": name,
        "lat": round(lat, 7), "lon": round(lon, 7),
        "visited": bool(arrived), "arrived": bool(arrived),
        "distance_m": round(best, 1) if math.isfinite(best) else None,
        # Keep a prepared zone even before arrival.  This lets later GPS points be tested
        # locally without repeating image analysis.
        "arrival_zone": zone,
        "physical_shapes": [],
        "footprint_source": str(fp.get("source") or "none")[:120],
        "method": str(fp.get("method") or "")[:160],
        "half_length_m": fp.get("half_length_m"), "half_width_m": fp.get("half_width_m"),
        "axis_deg": fp.get("axis_deg"), "vision_score": fp.get("vision_score"),
        "vision_threshold": fp.get("vision_threshold"), "vision_peak": fp.get("vision_peak"),
        "vision_baseline": fp.get("vision_baseline"),
        "platform_point_count": fp.get("platform_point_count", 0), "track_point_count": fp.get("track_point_count", 0),
        "raw_platform_count": fp.get("raw_platform_count", 0), "selected_platform_count": fp.get("selected_platform_count", 0),
        "zone_cache_status": str(fp.get("zone_cache_status") or "")[:40],
        "zone_cache_key": str(fp.get("zone_cache_key") or _station_row_key_v293(name, lat, lon))[:64],
        "debug_osaki": bool(debug_osaki),
    }


