def _photo_legacy_pair_guide_nodes_v545(a_name, b_name, stations):
    """Return non-rendered road-side search guides for photographed station pairs.

    These guides only define where to look *after* a green-free OSM image has already
    been converted into a road mask.  They never become displayed green geometry and
    never authorize travel through non-road pixels.
    """
    a_name = str(a_name or "")
    b_name = str(b_name or "")

    if {a_name, b_name} == {"代々木駅", "原宿駅"}:
        yoyogi = stations.get("代々木駅")
        harajuku = stations.get("原宿駅")
        if not yoyogi or not harajuku:
            return []
        # East-side road corridor around Kita-sando/Jingumae.
        forward = [
            [float(yoyogi[0]), float(yoyogi[1])],
            [35.68175, 139.70325],
            [35.67945, 139.70510],
            [35.67655, 139.70535],
            [35.67365, 139.70495],
            [35.67135, 139.70410],
            [float(harajuku[0]), float(harajuku[1])],
        ]
        return list(reversed(forward)) if a_name == "原宿駅" else forward

    if {a_name, b_name} == {"大崎駅", "品川駅"}:
        osaki = stations.get("大崎駅")
        shinagawa = stations.get("品川駅")
        if not osaki or not shinagawa:
            return []
        # v546: stay on the road corridor immediately beside / just west of the
        # railway alignment through the Gotenyama side rather than searching across
        # the railway yard.  Intermediate points are search hints only.
        forward = [
            [float(osaki[0]), float(osaki[1])],
            [35.62015, 139.72955],
            [35.62110, 139.73045],
            [35.62215, 139.73125],
            [35.62377, 139.73272],
            [35.62485, 139.73370],
            [35.62595, 139.73495],
            [35.62715, 139.73655],
            [float(shinagawa[0]), float(shinagawa[1])],
        ]
        return list(reversed(forward)) if a_name == "品川駅" else forward

    a = stations.get(a_name)
    b = stations.get(b_name)
    return [a, b] if a and b else []


def _photo_legacy_dense_guide_v545(nodes, spacing_m):
    dense = []
    spacing_m = max(4.0, float(spacing_m))
    for node_index, node in enumerate(nodes or []):
        if not isinstance(node, (list, tuple)) or len(node) < 2:
            continue
        current = [float(node[0]), float(node[1])]
        if not dense:
            dense.append(current)
            continue
        prev = dense[-1]
        try:
            dist = max(0.0, float(_nearby_haversine_m(prev[0], prev[1], current[0], current[1])))
        except Exception:
            dist = spacing_m
        steps = max(1, int(math.ceil(dist / spacing_m)))
        for step in range(1, steps + 1):
            t = step / float(steps)
            dense.append([
                prev[0] + (current[0] - prev[0]) * t,
                prev[1] + (current[1] - prev[1]) * t,
            ])
    return dense


def _photo_legacy_image_road_chunks_v543(force_nenne=None):
    """Convert photographed/user-confirmed station-pairs into image-road chunks.

    Normal pairs preserve the existing v543 keys and behaviour.  The problematic
    代々木駅〜原宿駅 and 大崎駅〜品川駅 pairs get dedicated road-side guides and new keys,
    so unrelated completed photo pairs are not reprocessed.  Each guide is used only
    after the untouched map image has been converted into a road mask.
    """
    enabled_for_nenne = _photo_legacy_is_nenne_v543() if force_nenne is None else bool(force_nenne)
    if not enabled_for_nenne:
        return []
    stations = PHOTO_LEGACY_NEW_ACTIVE_STATIONS_V309
    chunks = []
    max_span = max(180.0, float(PROJECT_IMAGE_ROAD_PHOTO_PAIR_MAX_SPAN_M_V543))
    densify_m = max(6.0, float(PROJECT_IMAGE_ROAD_PHOTO_PAIR_DENSIFY_M_V543))
    for pair_index, (a_name, b_name) in enumerate(PHOTO_LEGACY_FIXED_ROUTE_PAIRS_V309, start=1):
        a = stations.get(a_name); b = stations.get(b_name)
        if not a or not b:
            continue

        # v545: Yoyogi-Harajuku needs a road-side search corridor rather than a chord
        # through the rail/park block.  Build overlapping windows so adjacent road-matched
        # chunks share substantial recognized-road geometry and cannot leave a visible gap.
        if {str(a_name), str(b_name)} == {"代々木駅", "原宿駅"}:
            guide_nodes = _photo_legacy_pair_guide_nodes_v545(a_name, b_name, stations)
            dense = _photo_legacy_dense_guide_v545(
                guide_nodes, PROJECT_IMAGE_ROAD_PHOTO_YOYOGI_HARAJUKU_DENSIFY_M_V545
            )
            if len(dense) < 2:
                continue
            point_step_m = max(4.0, float(PROJECT_IMAGE_ROAD_PHOTO_YOYOGI_HARAJUKU_DENSIFY_M_V545))
            max_points = max(8, int(math.floor(float(PROJECT_IMAGE_ROAD_PHOTO_YOYOGI_HARAJUKU_MAX_SPAN_M_V545) / point_step_m)) + 1)
            overlap_points = max(3, int(math.ceil(float(PROJECT_IMAGE_ROAD_PHOTO_YOYOGI_HARAJUKU_OVERLAP_M_V545) / point_step_m)))
            overlap_points = min(max_points - 2, overlap_points)
            start_idx = 0
            part_index = 0
            while start_idx < len(dense) - 1:
                end_idx = min(len(dense), start_idx + max_points)
                window = dense[start_idx:end_idx]
                if len(window) < 2:
                    break
                packed = ";".join(f"{p[0]:.6f},{p[1]:.6f}" for p in window)
                digest = hashlib.sha1(
                    (
                        PROJECT_IMAGE_ROAD_SCHEMA_V531
                        + "|" + PROJECT_IMAGE_ROAD_PHOTO_YOYOGI_HARAJUKU_REVISION_V545
                        + "|" + a_name + ">" + b_name + "|" + packed
                    ).encode("utf-8")
                ).hexdigest()[:18]
                chunks.append({
                    "key": f"p_{pair_index:03d}_yh_{part_index + 1:02d}_{digest}",
                    "source_kind": PROJECT_IMAGE_ROAD_PHOTO_YOYOGI_HARAJUKU_SOURCE_V545,
                    "points": [[round(float(p[0]), 7), round(float(p[1]), 7)] for p in window],
                    "photo_pair_index": pair_index,
                    "photo_pair_total": int(PHOTO_LEGACY_FIXED_ROUTE_PAIR_COUNT_V309),
                    "photo_pair_a": a_name,
                    "photo_pair_b": b_name,
                    "photo_part": part_index + 1,
                    "source_group": f"photo_pair:{pair_index:03d}",
                    "source_part": part_index,
                    "photo_special_guide": "yoyogi_harajuku_roadside_v545",
                })
                if end_idx >= len(dense):
                    break
                start_idx = max(start_idx + 1, end_idx - overlap_points)
                part_index += 1
            # Add the final part-count metadata after all windows are known.
            pair_chunks = [row for row in chunks if row.get("photo_pair_index") == pair_index and row.get("photo_special_guide")]
            for row in pair_chunks:
                row["photo_parts"] = len(pair_chunks)
            continue

        # v546: Osaki-Shinagawa is also searched along a road corridor parallel to the
        # tracks instead of the station-centre chord, which otherwise overlaps the rail
        # right-of-way and can produce broken / missing road matches.
        if {str(a_name), str(b_name)} == {"大崎駅", "品川駅"}:
            guide_nodes = _photo_legacy_pair_guide_nodes_v545(a_name, b_name, stations)
            dense = _photo_legacy_dense_guide_v545(
                guide_nodes, PROJECT_IMAGE_ROAD_PHOTO_OSAKI_SHINAGAWA_DENSIFY_M_V546
            )
            if len(dense) < 2:
                continue
            point_step_m = max(4.0, float(PROJECT_IMAGE_ROAD_PHOTO_OSAKI_SHINAGAWA_DENSIFY_M_V546))
            max_points = max(8, int(math.floor(float(PROJECT_IMAGE_ROAD_PHOTO_OSAKI_SHINAGAWA_MAX_SPAN_M_V546) / point_step_m)) + 1)
            overlap_points = max(3, int(math.ceil(float(PROJECT_IMAGE_ROAD_PHOTO_OSAKI_SHINAGAWA_OVERLAP_M_V546) / point_step_m)))
            overlap_points = min(max_points - 2, overlap_points)
            start_idx = 0
            part_index = 0
            pair_chunks_start = len(chunks)
            while start_idx < len(dense) - 1:
                end_idx = min(len(dense), start_idx + max_points)
                window = dense[start_idx:end_idx]
                if len(window) < 2:
                    break
                packed = ";".join(f"{p[0]:.6f},{p[1]:.6f}" for p in window)
                digest = hashlib.sha1(
                    (
                        PROJECT_IMAGE_ROAD_SCHEMA_V531
                        + "|" + PROJECT_IMAGE_ROAD_PHOTO_OSAKI_SHINAGAWA_REVISION_V546
                        + "|" + a_name + ">" + b_name + "|" + packed
                    ).encode("utf-8")
                ).hexdigest()[:18]
                chunks.append({
                    "key": f"p_{pair_index:03d}_os_{part_index + 1:02d}_{digest}",
                    "source_kind": PROJECT_IMAGE_ROAD_PHOTO_OSAKI_SHINAGAWA_SOURCE_V546,
                    "points": [[round(float(p[0]), 7), round(float(p[1]), 7)] for p in window],
                    "photo_pair_index": pair_index,
                    "photo_pair_total": int(PHOTO_LEGACY_FIXED_ROUTE_PAIR_COUNT_V309),
                    "photo_pair_a": a_name,
                    "photo_pair_b": b_name,
                    "photo_part": part_index + 1,
                    "source_group": f"photo_pair:{pair_index:03d}",
                    "source_part": part_index,
                    "photo_special_guide": "osaki_shinagawa_trackside_v546",
                })
                if end_idx >= len(dense):
                    break
                start_idx = max(start_idx + 1, end_idx - overlap_points)
                part_index += 1
            pair_chunks = chunks[pair_chunks_start:]
            for row in pair_chunks:
                row["photo_parts"] = len(pair_chunks)
            continue

        # Unchanged v543 path for every other pair, preserving their keys/results.
        try:
            total_m = max(1.0, float(_nearby_haversine_m(a[0], a[1], b[0], b[1])))
        except Exception:
            total_m = max_span
        part_count = max(1, int(math.ceil(total_m / max_span)))
        for part_index in range(part_count):
            t0 = part_index / float(part_count)
            t1 = (part_index + 1) / float(part_count)
            lat0 = float(a[0]) + (float(b[0]) - float(a[0])) * t0
            lon0 = float(a[1]) + (float(b[1]) - float(a[1])) * t0
            lat1 = float(a[0]) + (float(b[0]) - float(a[0])) * t1
            lon1 = float(a[1]) + (float(b[1]) - float(a[1])) * t1
            part_m = max(1.0, total_m / float(part_count))
            steps = max(2, int(math.ceil(part_m / densify_m)))
            points = []
            for step in range(steps + 1):
                t = step / float(steps)
                points.append([
                    round(lat0 + (lat1 - lat0) * t, 7),
                    round(lon0 + (lon1 - lon0) * t, 7),
                ])
            packed = ";".join(f"{p[0]:.6f},{p[1]:.6f}" for p in points)
            digest = hashlib.sha1(
                (PROJECT_IMAGE_ROAD_SCHEMA_V531 + "|photo_pair|" + a_name + ">" + b_name + "|" + packed).encode("utf-8")
            ).hexdigest()[:18]
            chunks.append({
                "key": f"p_{pair_index:03d}_{part_index + 1:02d}_{digest}",
                "source_kind": "photo_pair",
                "points": points,
                "photo_pair_index": pair_index,
                "photo_pair_total": int(PHOTO_LEGACY_FIXED_ROUTE_PAIR_COUNT_V309),
                "photo_pair_a": a_name,
                "photo_pair_b": b_name,
                "photo_part": part_index + 1,
                "photo_parts": part_count,
                "source_group": f"photo_pair:{pair_index:03d}",
                "source_part": part_index,
            })
    return chunks


def _photo_legacy_seed_assignment_path_v307(family_key=None):
    family = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(family_key or current_family_key() or "family").strip() or "family")
    return f"{PHOTO_LEGACY_SEED_ASSIGNMENT_DIR_V307}/{family}.json"


@st.cache_data(ttl=60, max_entries=32, show_spinner=False)
def _read_photo_legacy_seed_assignment_v307(family_key):
    path = _photo_legacy_seed_assignment_path_v307(family_key)
    try:
        raw = supabase_client().storage.from_(GPS_TRACK_BUCKET).download(path)
        payload = json.loads(bytes(raw).decode("utf-8"))
    except Exception:
        return {}
    if not isinstance(payload, dict):
        return {}
    if str(payload.get("profile") or "") != PHOTO_LEGACY_NEW_PROFILE_V307:
        return {}
    return payload


def _claim_photo_legacy_seed_v307(family_key, member_key):
    family_key = str(family_key or "").strip()
    member_key = str(member_key or "").strip()
    if not family_key or not member_key or member_key == PHOTO_LEGACY_MAIN_MEMBER_V296:
        return False
    existing = _read_photo_legacy_seed_assignment_v307(family_key)
    assigned = str(existing.get("member_key") or "").strip() if isinstance(existing, dict) else ""
    if assigned:
        return assigned == member_key
    payload = {
        "profile": PHOTO_LEGACY_NEW_PROFILE_V307,
        "family_key": family_key,
        "member_key": member_key,
        "claimed_at_jst": now_jst().isoformat(),
        "source_images": ["1818.jpg", "1820.jpg"],
    }
    blob = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    path = _photo_legacy_seed_assignment_path_v307(family_key)
    bucket = supabase_client().storage.from_(GPS_TRACK_BUCKET)
    options = {"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "60", "upsert": "true"}
    try:
        bucket.upload(path=path, file=blob, file_options=options)
    except Exception:
        try:
            bucket.update(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "60"})
        except Exception:
            # Keep the current session usable even if the assignment file cannot be saved;
            # do not let a storage hiccup block the historical map itself.
            return True
    try:
        _read_photo_legacy_seed_assignment_v307.clear()
    except Exception:
        pass
    return True


def _normalize_photo_legacy_member_label_v541(value):
    normalized = unicodedata.normalize("NFKC", str(value or "")).strip()
    normalized = re.sub(r"\s+", "", normalized)
    return normalized.lower()


def _photo_legacy_is_nenne_v543():
    """True only for the personal account labelled ねんね.

    The current installation uses member_key ``main`` for that account, so display_name
    must be checked before any legacy-main fallback. No other account may receive the
    blue/green photographed route seed.
    """
    try:
        member_key = _normalize_photo_legacy_member_label_v541(current_member_key())
    except Exception:
        member_key = ""
    try:
        member_name = _normalize_photo_legacy_member_label_v541(current_member_name())
    except Exception:
        member_name = ""
    return member_key == "ねんね" or member_name == "ねんね"


def _photo_legacy_profile_v307():
    """Select historical photo seeds without leaking the new wall-map to other users."""
    try:
        member_key = str(current_member_key() or "").strip()
    except Exception:
        return ""
    if not member_key:
        return ""

    # Critical v543 ordering: the screenshot-confirmed account is displayed as
    # ``ねんね (main)``. Therefore the name check must precede the legacy main branch.
    if _photo_legacy_is_nenne_v543():
        if member_key == PHOTO_LEGACY_MAIN_MEMBER_V296:
            return "legacy_main_plus_wallmap_v311"
        return PHOTO_LEGACY_NEW_PROFILE_V307

    if member_key == PHOTO_LEGACY_MAIN_MEMBER_V296:
        return "legacy_main_v296"
    return ""


def _photo_legacy_active_stations_v307():
    profile = _photo_legacy_profile_v307()
    if profile == "legacy_main_v296":
        return PHOTO_LEGACY_STATIONS_V296
    if profile == "legacy_main_plus_wallmap_v311":
        return PHOTO_LEGACY_MAIN_COMBINED_STATIONS_V311
    if profile == PHOTO_LEGACY_NEW_PROFILE_V307:
        return PHOTO_LEGACY_NEW_ACTIVE_STATIONS_V309
    return {}


def _photo_legacy_active_sequences_v307():
    profile = _photo_legacy_profile_v307()
    if profile == "legacy_main_v296":
        return PHOTO_LEGACY_ROUTE_SEQUENCES_V296
    if profile == "legacy_main_plus_wallmap_v311":
        return PHOTO_LEGACY_MAIN_COMBINED_SEQUENCES_V311
    if profile == PHOTO_LEGACY_NEW_PROFILE_V307:
        return PHOTO_LEGACY_NEW_ROUTE_SEQUENCES_V307
    return ()


def _photo_legacy_active_big_stations_v307():
    profile = _photo_legacy_profile_v307()
    if profile == "legacy_main_v296":
        return PHOTO_LEGACY_BIG_STATIONS_V296
    if profile == "legacy_main_plus_wallmap_v311":
        return PHOTO_LEGACY_MAIN_COMBINED_BIG_STATIONS_V311
    if profile == PHOTO_LEGACY_NEW_PROFILE_V307:
        return PHOTO_LEGACY_NEW_BIG_STATIONS_V307
    return set()


def _photo_legacy_enabled_v296():
    return bool(_photo_legacy_profile_v307())


def _photo_legacy_station_axis_v296(name):
    """Return a stable unit axis from the active photographed route graph."""
    name = str(name or "")
    sequences = _photo_legacy_active_sequences_v307()
    stations = _photo_legacy_active_stations_v307()
    for seq in sequences:
        indexes = [i for i, item in enumerate(seq) if item == name]
        if not indexes:
            continue
        i = indexes[0]
        cur = stations.get(name)
        if cur is None:
            break
        prev_name = seq[i - 1] if i > 0 else None
        next_name = seq[i + 1] if i + 1 < len(seq) else None
        # Any sequence that repeats its first station at the end is circular.
        if len(seq) >= 3 and seq[0] == seq[-1]:
            unique = seq[:-1]
            try:
                j = unique.index(name)
                prev_name = unique[(j - 1) % len(unique)]
                next_name = unique[(j + 1) % len(unique)]
            except ValueError:
                pass
        p0 = stations.get(prev_name) if prev_name else None
        p1 = stations.get(next_name) if next_name else None
        lat0, lon0 = cur
        coslat = max(0.2, math.cos(math.radians(lat0)))
        if p0 is not None and p1 is not None:
            dx = (float(p1[1]) - float(p0[1])) * 111320.0 * coslat
            dy = (float(p1[0]) - float(p0[0])) * 111320.0
        elif p1 is not None:
            dx = (float(p1[1]) - lon0) * 111320.0 * coslat
            dy = (float(p1[0]) - lat0) * 111320.0
        elif p0 is not None:
            dx = (lon0 - float(p0[1])) * 111320.0 * coslat
            dy = (lat0 - float(p0[0])) * 111320.0
        else:
            dx, dy = 0.0, 1.0
        norm = math.hypot(dx, dy)
        if norm > 1e-6:
            return dx / norm, dy / norm
    return 0.0, 1.0


def _photo_legacy_convex_hull_v296(points):
    pts = sorted(set((round(float(x), 6), round(float(y), 6)) for x, y in (points or [])))
    if len(pts) <= 1:
        return pts
    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]


def _photo_legacy_station_zone_v296(name, lat, lon):
    """Compact rail-aligned capsule used only when no better persisted station zone exists."""
    ux, uy = _photo_legacy_station_axis_v296(name)
    big_stations = _photo_legacy_active_big_stations_v307()
    half_len = PHOTO_LEGACY_BIG_STATION_HALF_LENGTH_M_V296 if name in big_stations else PHOTO_LEGACY_STATION_HALF_LENGTH_M_V296
    half_w = PHOTO_LEGACY_BIG_STATION_HALF_WIDTH_M_V296 if name in big_stations else PHOTO_LEGACY_STATION_HALF_WIDTH_M_V296
    cloud = []
    for sign in (-1.0, 1.0):
        cx, cy = sign * half_len * ux, sign * half_len * uy
        for i in range(18):
            a = 2.0 * math.pi * i / 18.0
            cloud.append((cx + half_w * math.cos(a), cy + half_w * math.sin(a)))
    hull = _photo_legacy_convex_hull_v296(cloud)
    coslat = max(0.2, math.cos(math.radians(float(lat))))
    out = []
    for x, y in hull:
        p_lat = float(lat) + y / 111320.0
        p_lon = float(lon) + x / (111320.0 * coslat)
        out.append([round(p_lat, 7), round(p_lon, 7)])
    return out


def _photo_legacy_segments_v296():
    if not _photo_legacy_enabled_v296():
        return []
    stations = _photo_legacy_active_stations_v307()
    out = []
    for seq in _photo_legacy_active_sequences_v307():
        pts = []
        for name in seq:
            coord = stations.get(name)
            if coord is None:
                continue
            pts.append([round(float(coord[0]), 7), round(float(coord[1]), 7)])
        if len(pts) >= 2:
            out.append(pts)
    return out


def _photo_legacy_route_cache_path_v300():
    family = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(current_family_key() or "family").strip() or "family")
    member = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(current_member_key() or "member").strip() or "member")
    return os.path.join(APP_DIR, PHOTO_LEGACY_ROUTE_CACHE_DIR_V300, f"{family}__{member}.json")


def _photo_legacy_coerce_segment_v300(segment):
    clean = []
    prev = None
    for pair in segment or []:
        if not isinstance(pair, (list, tuple)) or len(pair) < 2:
            continue
        try:
            lat = round(float(pair[0]), 7)
            lon = round(float(pair[1]), 7)
        except Exception:
            continue
        if not (math.isfinite(lat) and math.isfinite(lon)):
            continue
        if prev is not None:
            try:
                if _nearby_haversine_m(prev[0], prev[1], lat, lon) < 0.8:
                    continue
            except Exception:
                pass
        clean.append([lat, lon])
        prev = [lat, lon]
    return clean if len(clean) >= 2 else []


def _photo_legacy_coerce_segments_v300(segments):
    out = []
    for seg in segments or []:
        clean = _photo_legacy_coerce_segment_v300(seg)
        if len(clean) >= 2:
            out.append(clean)
    return out


def _read_photo_legacy_route_cache_v300():
    if not _photo_legacy_enabled_v296():
        return []
    path = _photo_legacy_route_cache_path_v300()
    try:
        if not os.path.exists(path):
            return []
        with open(path, 'r', encoding='utf-8') as f:
            payload = json.load(f)
    except Exception:
        return []
    if not isinstance(payload, dict):
        return []
    if str(payload.get('schema') or '') != PHOTO_LEGACY_ROUTE_CACHE_SCHEMA_V300:
        return []
    return _photo_legacy_coerce_segments_v300(payload.get('segments') or [])


def _save_photo_legacy_route_cache_v300(segments):
    clean_segments = _photo_legacy_coerce_segments_v300(segments)
    if not clean_segments:
        return False
    path = _photo_legacy_route_cache_path_v300()
    tmp = f"{path}.tmp"
    payload = {
        'schema': PHOTO_LEGACY_ROUTE_CACHE_SCHEMA_V300,
        'saved_at_jst': datetime.now(ZoneInfo('Asia/Tokyo')).isoformat(),
        'family_key': str(current_family_key() or ''),
        'member_key': str(current_member_key() or ''),
        'segments': clean_segments,
    }
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(payload, f, ensure_ascii=False, separators=(',', ':'))
        os.replace(tmp, path)
        return True
    except Exception:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return False


def _photo_legacy_pair_route_v300(name_a, name_b):
    coord_a = PHOTO_LEGACY_STATIONS_V296.get(name_a)
    coord_b = PHOTO_LEGACY_STATIONS_V296.get(name_b)
    if coord_a is None or coord_b is None:
        return []
    lat0, lon0 = float(coord_a[0]), float(coord_a[1])
    lat1, lon1 = float(coord_b[0]), float(coord_b[1])
    key = f"{lat0:.6f},{lon0:.6f};{lat1:.6f},{lon1:.6f}"
    routed = _project_osrm_route_chunk_v298(key)
    if len(routed) >= 2:
        try:
            start_gap = _nearby_haversine_m(routed[0][0], routed[0][1], lat0, lon0)
            end_gap = _nearby_haversine_m(routed[-1][0], routed[-1][1], lat1, lon1)
        except Exception:
            start_gap = end_gap = 0.0
        if start_gap <= 180.0 and end_gap <= 180.0:
            return _photo_legacy_coerce_segment_v300(routed)
    return [[round(lat0, 7), round(lon0, 7)], [round(lat1, 7), round(lon1, 7)]]


def _photo_legacy_build_routes_v300():
    if not _photo_legacy_enabled_v296():
        return []
    out = []
    for seq in PHOTO_LEGACY_ROUTE_SEQUENCES_V296:
        parts = []
        names = [str(name or '') for name in seq]
        for name_a, name_b in zip(names[:-1], names[1:]):
            part = _photo_legacy_pair_route_v300(name_a, name_b)
            if len(part) >= 2:
                parts.append(part)
        joined = _project_join_paths_v298(parts)
        joined = _photo_legacy_coerce_segment_v300(joined)
        if len(joined) >= 2:
            out.append(joined)
    return out


def _photo_legacy_prepare_routes_v300():
    if not _photo_legacy_enabled_v296():
        return [], {'mode': 'disabled', 'saved': False}
    saved = _read_photo_legacy_route_cache_v300()
    if saved:
        return saved, {'mode': 'loaded', 'saved': True}
    built = _photo_legacy_build_routes_v300()
    if built:
        _save_photo_legacy_route_cache_v300(built)
        return built, {'mode': 'built', 'saved': True}
    return _photo_legacy_segments_v296(), {'mode': 'fallback', 'saved': False}

PHOTO_LEGACY_ROUTE_CACHE_SCHEMA_V301 = "photo_route_cache_v301"
PHOTO_LEGACY_ROUTE_SERVICE_URLS_V301 = (
    "https://router.project-osrm.org/route/v1/foot",
)
PHOTO_LEGACY_ROUTE_CANDIDATE_WORKERS_V301 = 6
PHOTO_LEGACY_ROUTE_ENDPOINT_OFFSET_M_V301 = 80.0
PHOTO_LEGACY_ROUTE_ENDPOINT_ANGLE_DELTAS_V301 = (0.0, 38.0, -38.0, 78.0, -78.0, 138.0, -138.0)
PHOTO_LEGACY_ROUTE_ACCEPTABLE_ENDPOINT_GAP_M_V301 = 210.0
PHOTO_LEGACY_ROUTE_ACCEPTABLE_RATIO_MIN_V301 = 0.92
PHOTO_LEGACY_ROUTE_ACCEPTABLE_RATIO_MAX_V301 = 4.8


def _photo_legacy_route_cache_path_v301():
    family = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(current_family_key() or "family").strip() or "family")
    member = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(current_member_key() or "member").strip() or "member")
    return os.path.join(APP_DIR, PHOTO_LEGACY_ROUTE_CACHE_DIR_V300, f"{family}__{member}.json")


def _read_photo_legacy_route_cache_v301():
    if not _photo_legacy_enabled_v296():
        return []
    path = _photo_legacy_route_cache_path_v301()
    try:
        if not os.path.exists(path):
            return []
        with open(path, 'r', encoding='utf-8') as f:
            payload = json.load(f)
    except Exception:
        return []
    if not isinstance(payload, dict):
        return []
    if str(payload.get('schema') or '') != PHOTO_LEGACY_ROUTE_CACHE_SCHEMA_V301:
        return []
    return _photo_legacy_coerce_segments_v300(payload.get('segments') or [])


def _save_photo_legacy_route_cache_v301(segments):
    clean_segments = _photo_legacy_coerce_segments_v300(segments)
    if not clean_segments:
        return False
    path = _photo_legacy_route_cache_path_v301()
    tmp = f"{path}.tmp"
    payload = {
        'schema': PHOTO_LEGACY_ROUTE_CACHE_SCHEMA_V301,
        'saved_at_jst': datetime.now(ZoneInfo('Asia/Tokyo')).isoformat(),
        'family_key': str(current_family_key() or ''),
        'member_key': str(current_member_key() or ''),
        'segments': clean_segments,
    }
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(payload, f, ensure_ascii=False, separators=(',', ':'))
        os.replace(tmp, path)
        return True
    except Exception:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return False


def _photo_legacy_heading_rad_v301(lat0, lon0, lat1, lon1):
    avg_lat = math.radians((float(lat0) + float(lat1)) / 2.0)
    east = math.radians(float(lon1) - float(lon0)) * math.cos(avg_lat)
    north = math.radians(float(lat1) - float(lat0))
    return math.atan2(east, north)


def _photo_legacy_offset_point_v301(lat, lon, heading_rad, distance_m):
    lat = float(lat)
    lon = float(lon)
    distance_m = float(distance_m)
    north_m = math.cos(float(heading_rad)) * distance_m
    east_m = math.sin(float(heading_rad)) * distance_m
    dlat = (north_m / 6378137.0) * (180.0 / math.pi)
    dlon = (east_m / (6378137.0 * max(0.12, math.cos(math.radians(lat))))) * (180.0 / math.pi)
    return [round(lat + dlat, 7), round(lon + dlon, 7)]


def _photo_legacy_access_candidates_v301(lat, lon, target_lat, target_lon):
    base_lat = float(lat)
    base_lon = float(lon)
    heading = _photo_legacy_heading_rad_v301(base_lat, base_lon, target_lat, target_lon)
    out = [{
        'point': [round(base_lat, 7), round(base_lon, 7)],
        'offset_m': 0.0,
        'angle_delta_deg': 0.0,
        'source': 'station_center',
    }]
    seen = {(round(base_lat, 7), round(base_lon, 7))}
    for delta in PHOTO_LEGACY_ROUTE_ENDPOINT_ANGLE_DELTAS_V301:
        pt = _photo_legacy_offset_point_v301(base_lat, base_lon, heading + math.radians(delta), PHOTO_LEGACY_ROUTE_ENDPOINT_OFFSET_M_V301)
        key = (pt[0], pt[1])
        if key in seen:
            continue
        seen.add(key)
        out.append({
            'point': pt,
            'offset_m': float(PHOTO_LEGACY_ROUTE_ENDPOINT_OFFSET_M_V301),
            'angle_delta_deg': float(delta),
            'source': 'station_exit_probe',
        })
    return out


def _photo_legacy_route_request_v301(start_point, end_point):
    if not (isinstance(start_point, (list, tuple)) and isinstance(end_point, (list, tuple)) and len(start_point) >= 2 and len(end_point) >= 2):
        return None
    try:
        s_lat = float(start_point[0]); s_lon = float(start_point[1])
        e_lat = float(end_point[0]); e_lon = float(end_point[1])
    except Exception:
        return None
    if not all(math.isfinite(v) for v in (s_lat, s_lon, e_lat, e_lon)):
        return None
    coords = f"{s_lon:.6f},{s_lat:.6f};{e_lon:.6f},{e_lat:.6f}"
    headers = {'User-Agent': 'TokyoBurariPhotoRoadSnapV301/1.0'}
    params = {
        'overview': 'full',
        'geometries': 'geojson',
        'steps': 'false',
        'alternatives': 'false',
        'continue_straight': 'true',
    }
    for base_url in PHOTO_LEGACY_ROUTE_SERVICE_URLS_V301:
        try:
            response = requests.get(f"{base_url}/{coords}", params=params, headers=headers, timeout=8.0)
            response.raise_for_status()
            payload = response.json()
        except Exception:
            continue
        routes = payload.get('routes') if isinstance(payload, dict) else None
        if not isinstance(routes, list) or not routes:
            continue
        first = routes[0] if isinstance(routes[0], dict) else {}
        geometry = first.get('geometry') if isinstance(first, dict) else None
        coords_out = geometry.get('coordinates') if isinstance(geometry, dict) else None
        snapped = []
        prev = None
        for raw in coords_out or []:
            if not isinstance(raw, (list, tuple)) or len(raw) < 2:
                continue
            try:
                lon = float(raw[0]); lat = float(raw[1])
            except Exception:
                continue
            if not (math.isfinite(lat) and math.isfinite(lon)):
                continue
            pt = [round(lat, 7), round(lon, 7)]
            if prev is not None:
                try:
                    if _nearby_haversine_m(prev[0], prev[1], pt[0], pt[1]) < 0.7:
                        continue
                except Exception:
                    pass
            snapped.append(pt)
            prev = pt
        if len(snapped) >= 2:
            return {
                'points': snapped,
                'distance_m': float(first.get('distance') or 0.0),
                'duration_s': float(first.get('duration') or 0.0),
                'provider': base_url,
            }
    return None


def _photo_legacy_station_pair_score_v301(route, station_a, station_b, cand_a, cand_b):
    if not isinstance(route, dict):
        return float('inf')
    points = _photo_legacy_coerce_segment_v300(route.get('points') or [])
    if len(points) < 2:
        return float('inf')
    a_lat, a_lon = float(station_a[0]), float(station_a[1])
    b_lat, b_lon = float(station_b[0]), float(station_b[1])
    try:
        start_gap = _nearby_haversine_m(points[0][0], points[0][1], a_lat, a_lon)
        end_gap = _nearby_haversine_m(points[-1][0], points[-1][1], b_lat, b_lon)
        straight_m = _nearby_haversine_m(a_lat, a_lon, b_lat, b_lon)
    except Exception:
        return float('inf')
    distance_m = max(0.0, float(route.get('distance_m') or 0.0))
    if straight_m < 1.0:
        straight_m = 1.0
    ratio = distance_m / straight_m if distance_m > 0 else 0.0
    if ratio < PHOTO_LEGACY_ROUTE_ACCEPTABLE_RATIO_MIN_V301 or ratio > PHOTO_LEGACY_ROUTE_ACCEPTABLE_RATIO_MAX_V301:
        return float('inf')
    if start_gap > PHOTO_LEGACY_ROUTE_ACCEPTABLE_ENDPOINT_GAP_M_V301 or end_gap > PHOTO_LEGACY_ROUTE_ACCEPTABLE_ENDPOINT_GAP_M_V301:
        return float('inf')
    access_penalty = float(cand_a.get('offset_m') or 0.0) + float(cand_b.get('offset_m') or 0.0)
    angle_penalty = (abs(float(cand_a.get('angle_delta_deg') or 0.0)) + abs(float(cand_b.get('angle_delta_deg') or 0.0))) * 0.18
    route_detail_bonus = -min(len(points), 180) * 0.06
    ratio_target = 1.18 if straight_m < 500.0 else 1.28
    ratio_penalty = abs(ratio - ratio_target) * 180.0
    return start_gap * 0.95 + end_gap * 0.95 + access_penalty * 0.72 + angle_penalty + ratio_penalty + route_detail_bonus


def _photo_legacy_pair_route_v301(name_a, name_b):
    coord_a = PHOTO_LEGACY_STATIONS_V296.get(name_a)
    coord_b = PHOTO_LEGACY_STATIONS_V296.get(name_b)
    if coord_a is None or coord_b is None:
        return []
    station_a = (float(coord_a[0]), float(coord_a[1]))
    station_b = (float(coord_b[0]), float(coord_b[1]))

    direct = _photo_legacy_route_request_v301(station_a, station_b)
    if direct is not None:
        direct_score = _photo_legacy_station_pair_score_v301(direct, station_a, station_b, {'offset_m': 0.0, 'angle_delta_deg': 0.0}, {'offset_m': 0.0, 'angle_delta_deg': 0.0})
        if math.isfinite(direct_score):
            return _photo_legacy_coerce_segment_v300(direct.get('points') or [])

    start_candidates = _photo_legacy_access_candidates_v301(station_a[0], station_a[1], station_b[0], station_b[1])
    end_candidates = _photo_legacy_access_candidates_v301(station_b[0], station_b[1], station_a[0], station_a[1])
    candidate_jobs = []
    for cand_a in start_candidates:
        for cand_b in end_candidates:
            candidate_jobs.append((cand_a, cand_b))

    best_points = []
    best_score = float('inf')

    def _job(job):
        cand_a, cand_b = job
        route = _photo_legacy_route_request_v301(cand_a.get('point'), cand_b.get('point'))
        score = _photo_legacy_station_pair_score_v301(route, station_a, station_b, cand_a, cand_b)
        return score, route

    max_workers = max(1, min(int(PHOTO_LEGACY_ROUTE_CANDIDATE_WORKERS_V301), len(candidate_jobs)))
    if max_workers <= 1:
        for job in candidate_jobs:
            try:
                score, route = _job(job)
            except Exception:
                continue
            if math.isfinite(score) and score < best_score:
                best_score = score
                best_points = _photo_legacy_coerce_segment_v300(route.get('points') or []) if isinstance(route, dict) else []
    else:
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = [executor.submit(_job, job) for job in candidate_jobs]
            for future in futures:
                try:
                    score, route = future.result()
                except Exception:
                    continue
                if math.isfinite(score) and score < best_score:
                    best_score = score
                    best_points = _photo_legacy_coerce_segment_v300(route.get('points') or []) if isinstance(route, dict) else []

    if len(best_points) >= 2:
        return best_points
    if direct is not None:
        return _photo_legacy_coerce_segment_v300(direct.get('points') or [])
    return []


def _photo_legacy_build_routes_v301():
    if not _photo_legacy_enabled_v296():
        return []
    out = []
    for seq in PHOTO_LEGACY_ROUTE_SEQUENCES_V296:
        parts = []
        names = [str(name or '') for name in seq]
        for name_a, name_b in zip(names[:-1], names[1:]):
            part = _photo_legacy_pair_route_v301(name_a, name_b)
            if len(part) >= 2:
                parts.append(part)
        joined = _project_join_paths_v298(parts)
        joined = _photo_legacy_coerce_segment_v300(joined)
        if len(joined) >= 2:
            out.append(joined)
    return out


def _photo_legacy_prepare_routes_v301():
    if not _photo_legacy_enabled_v296():
        return [], {'mode': 'disabled', 'saved': False}
    saved = _read_photo_legacy_route_cache_v301()
    if saved:
        return saved, {'mode': 'loaded', 'saved': True}
    built = _photo_legacy_build_routes_v301()
    if built:
        _save_photo_legacy_route_cache_v301(built)
        return built, {'mode': 'built', 'saved': True}
    # Accuracy-first: do not persist straight fallback segments.
    return [], {'mode': 'unresolved', 'saved': False}


PHOTO_LEGACY_ROUTE_SCHEMA_V302 = "photo_legacy_pedestrian_graph_v302"
PHOTO_LEGACY_ROUTE_STORAGE_FILE_V302 = "photo_legacy_pedestrian_routes_v302.json"
PHOTO_LEGACY_ROUTE_OSRM_FOOT_BASE_V302 = "https://routing.openstreetmap.de/routed-foot/route/v1/driving"
PHOTO_LEGACY_ROUTE_MAX_WAYPOINTS_V302 = 8
PHOTO_LEGACY_ROUTE_REQUEST_TIMEOUT_V302 = 12.0
PHOTO_LEGACY_ROUTE_RETRY_COUNT_V302 = 2


def _photo_legacy_route_storage_path_v302():
    return f"{_gps_track_prefix()}/{PHOTO_LEGACY_ROUTE_STORAGE_FILE_V302}"


def _photo_legacy_route_document_v302(segments):
    clean_segments = _photo_legacy_coerce_segments_v300(segments)
    return {
        "schema": PHOTO_LEGACY_ROUTE_SCHEMA_V302,
        "saved_at_jst": now_jst().isoformat(),
        "family_key": str(current_family_key() or ""),
        "member_key": str(current_member_key() or ""),
        "source": "osm_pedestrian_road_graph",
        "routing_endpoint": "routing.openstreetmap.de/routed-foot",
        "segments": clean_segments,
    }


@st.cache_data(ttl=3600, max_entries=24, show_spinner=False)
def _read_photo_legacy_route_cache_v302(family_key, member_key):
    path = f"{_gps_track_prefix(family_key, member_key)}/{PHOTO_LEGACY_ROUTE_STORAGE_FILE_V302}"
    try:
        raw = supabase_client().storage.from_(GPS_TRACK_BUCKET).download(path)
    except Exception:
        return []
    try:
        payload = json.loads(bytes(raw).decode("utf-8"))
    except Exception:
        return []
    if not isinstance(payload, dict) or str(payload.get("schema") or "") != PHOTO_LEGACY_ROUTE_SCHEMA_V302:
        return []
    return _photo_legacy_coerce_segments_v300(payload.get("segments") or [])


def _save_photo_legacy_route_cache_v302(segments):
    document = _photo_legacy_route_document_v302(segments)
    clean_segments = document.get("segments") or []
    if not clean_segments:
        return False
    blob = json.dumps(document, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    path = _photo_legacy_route_storage_path_v302()
    bucket = supabase_client().storage.from_(GPS_TRACK_BUCKET)
    options = {"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "3600", "upsert": "true"}
    try:
        bucket.upload(path=path, file=blob, file_options=options)
    except Exception:
        try:
            bucket.update(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "3600"})
        except Exception:
            try:
                bucket.remove([path])
            except Exception:
                pass
            try:
                bucket.upload(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "3600"})
            except Exception:
                return False
    _read_photo_legacy_route_cache_v302.clear()
    return True


def _photo_legacy_route_chunk_names_v302(sequence, max_waypoints=None):
    names = [str(name or "") for name in (sequence or []) if PHOTO_LEGACY_STATIONS_V296.get(name) is not None]
    if len(names) < 2:
        return []
    limit = max(2, int(max_waypoints or PHOTO_LEGACY_ROUTE_MAX_WAYPOINTS_V302))
    chunks = []
    start = 0
    while start < len(names) - 1:
        end = min(len(names), start + limit)
        chunk = names[start:end]
        if len(chunk) >= 2:
            chunks.append(chunk)
        if end >= len(names):
            break
        start = end - 1
    return chunks


def _photo_legacy_route_request_names_v302(names):
    coords = []
    for name in names or []:
        coord = PHOTO_LEGACY_STATIONS_V296.get(name)
        if coord is None:
            continue
        coords.append((float(coord[0]), float(coord[1])))
    if len(coords) < 2:
        return []
    coord_text = ";".join(f"{lon:.6f},{lat:.6f}" for lat, lon in coords)
    url = f"{PHOTO_LEGACY_ROUTE_OSRM_FOOT_BASE_V302}/{coord_text}"
    params = {
        "overview": "full",
        "geometries": "geojson",
        "steps": "false",
        "alternatives": "false",
        "continue_straight": "true",
    }
    headers = {"User-Agent": "TokyoBurariHistoricalPhotoRouteV302/1.0"}
    last_payload = None
    for _ in range(max(1, int(PHOTO_LEGACY_ROUTE_RETRY_COUNT_V302))):
        try:
            response = requests.get(url, params=params, headers=headers, timeout=float(PHOTO_LEGACY_ROUTE_REQUEST_TIMEOUT_V302))
            response.raise_for_status()
            payload = response.json()
            last_payload = payload
        except Exception:
            continue
        routes = payload.get("routes") if isinstance(payload, dict) else None
        if not isinstance(routes, list) or not routes:
            continue
        geometry = routes[0].get("geometry") if isinstance(routes[0], dict) else None
        raw_coords = geometry.get("coordinates") if isinstance(geometry, dict) else None
        out = []
        prev = None
        for raw in raw_coords or []:
            if not isinstance(raw, (list, tuple)) or len(raw) < 2:
                continue
            try:
                lon = float(raw[0]); lat = float(raw[1])
            except Exception:
                continue
            if not (math.isfinite(lat) and math.isfinite(lon)):
                continue
            point = [round(lat, 7), round(lon, 7)]
            if prev is not None:
                try:
                    if _nearby_haversine_m(prev[0], prev[1], point[0], point[1]) < 0.7:
                        continue
                except Exception:
                    pass
            out.append(point)
            prev = point
        if len(out) >= 2:
            return out
    return []


def _photo_legacy_build_routes_v302():
    if not _photo_legacy_enabled_v296():
        return []
    routes = []
    for sequence in PHOTO_LEGACY_ROUTE_SEQUENCES_V296:
        parts = []
        for chunk_names in _photo_legacy_route_chunk_names_v302(sequence):
            part = _photo_legacy_route_request_names_v302(chunk_names)
            if len(part) >= 2:
                parts.append(part)
        joined = _project_join_paths_v298(parts)
        joined = _photo_legacy_coerce_segment_v300(joined)
        if len(joined) >= 2:
            routes.append(joined)
    return routes


def _photo_legacy_prepare_routes_v302():
    if not _photo_legacy_enabled_v296():
        return [], {"mode": "disabled", "saved": False}
    family = str(current_family_key() or "")
    member = str(current_member_key() or "")
    saved = _read_photo_legacy_route_cache_v302(family, member)
    if saved:
        return saved, {"mode": "loaded", "saved": True}
    built = _photo_legacy_build_routes_v302()
    if built:
        saved_ok = _save_photo_legacy_route_cache_v302(built)
        return built, {"mode": "built", "saved": bool(saved_ok)}
    # Accuracy-first: never draw a station-to-station straight chord as a fallback.
    return [], {"mode": "unresolved", "saved": False}


def _photo_legacy_map_points_v296():
    if not _photo_legacy_enabled_v296():
        return []
    return [
        {"lat": round(float(lat), 7), "lon": round(float(lon), 7)}
        for lat, lon in _photo_legacy_active_stations_v307().values()
    ]


def _merge_photo_legacy_stations_v296(rows):
    """Mark the photographed historical stations reached without re-running image inference."""
    base_rows = [dict(r) for r in (rows or []) if isinstance(r, dict)]
    if not _photo_legacy_enabled_v296():
        return _merge_station_rows_v293(base_rows)
    by_name = {}
    for row in base_rows:
        by_name.setdefault(_station_name_base_v293(row.get("name")), row)
    for name, (lat, lon) in _photo_legacy_active_stations_v307().items():
        base = _station_name_base_v293(name)
        existing = by_name.get(base)
        if existing is not None:
            existing["arrived"] = True
            existing["visited"] = True
            if len(existing.get("arrival_zone") or []) < 3:
                existing["arrival_zone"] = _photo_legacy_station_zone_v296(name, lat, lon)
                existing["footprint_source"] = "historical_wall_photo_numeric_seed"
                existing["method"] = "historical_wall_photo_station_capsule_v296"
                existing["zone_cache_status"] = "static_numeric_seed"
            continue
        row = {
            "name": name,
            "lat": round(float(lat), 7),
            "lon": round(float(lon), 7),
            "visited": True,
            "arrived": True,
            "distance_m": 0.0,
            "arrival_zone": _photo_legacy_station_zone_v296(name, lat, lon),
            "physical_shapes": [],
            "footprint_source": "historical_wall_photo_numeric_seed",
            "method": "historical_wall_photo_station_capsule_v296",
            "zone_cache_status": "static_numeric_seed",
            "zone_cache_key": _station_row_key_v293(name, lat, lon),
            "debug_osaki": False,
        }
        base_rows.append(row)
        by_name[base] = row
    return _merge_station_rows_v293(base_rows)

def _project_station_preflight_v293(raw_points, map_points):
    """Resolve only new station work before Leaflet is mounted, then persist the result."""
    family = current_family_key(); member = current_member_key()
    state = _read_station_visit_state_v293(family, member) or {
        "checked_through_ts_ms": 0, "gps_point_count": 0, "scan_cells": [], "stations": []
    }
    try:
        latest_ts = max((int(p.get("ts_ms") or 0) for p in (raw_points or []) if isinstance(p, dict)), default=0)
    except Exception:
        latest_ts = 0
    checked_ts = max(0, int(state.get("checked_through_ts_ms") or 0))
    known_rows = [_coerce_station_state_row_v293(r) for r in (state.get("stations") or [])]
    known_rows = [r for r in known_rows if r]

    # Fast path: no GPS point newer than the saved state.  No Overpass, no raster tile
    # download, no station fitting.  This is the normal path when revisiting the map.
    if known_rows and latest_ts <= checked_ts:
        for row in known_rows:
            best = _station_center_best_distance_v293(row, map_points)
            if math.isfinite(best):
                row["distance_m"] = round(best, 1)
            row["zone_cache_status"] = "visit_state_loaded"
        merged_loaded = _merge_photo_legacy_stations_v296(_merge_station_rows_v293(known_rows))
        # If this is the first v296 visit, freeze the photo-derived numeric station rows into
        # the same per-user station state. Subsequent opens need no historical image work.
        if len(merged_loaded) > len(_merge_station_rows_v293(known_rows)):
            try:
                _save_station_visit_state_v293(
                    family, member, checked_ts, len(raw_points or []),
                    sorted(set(str(x) for x in (state.get("scan_cells") or []) if str(x))), merged_loaded,
                )
            except Exception:
                pass
        return merged_loaded, {
            "mode": "loaded", "new_gps": 0, "new_cells": 0, "saved": True,
        }

    walk_raw = _project_walk_raw_points_v293(raw_points)
    if checked_ts > 0:
        new_walk_raw = [p for p in walk_raw if int(p.get("ts_ms") or 0) > checked_ts]
    else:
        new_walk_raw = list(walk_raw)
    scanned = set(str(x) for x in (state.get("scan_cells") or []) if str(x))
    new_cells = []
    scan_points = []
    for p in new_walk_raw:
        cell = _station_scan_cell_v293(p.get("lat"), p.get("lon"))
        if cell and cell not in scanned:
            new_cells.append(cell); scan_points.append(p)

    rows_by_key = {}
    for row in known_rows:
        rows_by_key[_station_row_key_v293(row.get("name"), row.get("lat"), row.get("lon"))] = row

    # Cheap local re-check against already prepared numeric polygons.  This catches a new
    # arrival within an already scanned neighborhood without any network request.
    if new_walk_raw:
        new_walk_simple = [{"lat": p.get("lat"), "lon": p.get("lon")} for p in new_walk_raw]
        for row in rows_by_key.values():
            zone = row.get("arrival_zone") or []
            if len(zone) >= 3 and not bool(row.get("arrived")):
                try:
                    if _project_track_enters_station_zone_v290(new_walk_simple, zone, float(row["lat"]), float(row["lon"])):
                        row["arrived"] = True; row["visited"] = True
                except Exception:
                    pass
            best = _station_center_best_distance_v293(row, map_points)
            if math.isfinite(best):
                row["distance_m"] = round(best, 1)

    # Discover station anchors only when the walker enters a map cell never scanned before.
    # One bounding-box query covers all new cells in this run.
    if scan_points:
        candidates = _station_candidates_for_points_v293(scan_points)
        for station in candidates or []:
            try:
                name = str(station.get("name") or "駅")
                lat = float(station["lat"]); lon = float(station["lon"])
            except Exception:
                continue
            # Osaki remains a fixed diagnostic anchor until its red outline is approved.
            if _station_name_base_v293(name) == "大崎":
                continue
            best = _station_center_best_distance_v293({"lat": lat, "lon": lon}, map_points)
            if best > GPS_TRACK_STATION_NEAR_RADIUS_M:
                continue
            key = _station_row_key_v293(name, lat, lon)
            existing = rows_by_key.get(key)
            if existing is not None:
                if math.isfinite(best): existing["distance_m"] = round(best, 1)
                continue
            # Image inference is reserved for stations that the GPS actually approached.
            # Distant candidates remain lightweight markers and can be inferred later if
            # the route gets closer.
            if best <= float(STATION_PREFLIGHT_INFER_CENTER_RADIUS_M):
                fp = _project_station_image_corridor_persisted_v292(name, lat, lon)
                row = _station_row_from_footprint_v293(station, fp, map_points, debug_osaki=False)
            else:
                row = {
                    "name": name, "lat": round(lat, 7), "lon": round(lon, 7),
                    "visited": False, "arrived": False, "distance_m": round(best, 1) if math.isfinite(best) else None,
                    "arrival_zone": [], "physical_shapes": [], "footprint_source": "anchor_only",
                    "method": "anchor_only_not_inferred", "debug_osaki": False,
                    "zone_cache_status": "not_needed_yet", "zone_cache_key": key,
                }
            rows_by_key[key] = row
        scanned.update(new_cells)

    # Osaki uses the image-derived diagnostic geometry, but only when this user's route is
    # close enough to Osaki or an Osaki row already exists in saved state.
    osaki_lat = 35.61939; osaki_lon = 139.72849
    osaki_key = _station_row_key_v293("大崎駅", osaki_lat, osaki_lon)
    osaki_best = _station_center_best_distance_v293({"lat": osaki_lat, "lon": osaki_lon}, map_points)
    if osaki_key in rows_by_key or osaki_best <= GPS_TRACK_STATION_NEAR_RADIUS_M:
        osaki = _project_osaki_forced_debug_v292(map_points)
        if isinstance(osaki, dict):
            rows_by_key[osaki_key] = osaki

    rows = _merge_photo_legacy_stations_v296(_merge_station_rows_v293(list(rows_by_key.values())))
    saved = False
    try:
        _save_station_visit_state_v293(
            family, member, latest_ts, len(raw_points or []),
            sorted(scanned), rows,
        )
        saved = True
    except Exception:
        saved = False
    return rows, {
        "mode": "updated", "new_gps": len(new_walk_raw), "new_cells": len(set(new_cells)), "saved": saved,
    }


def _project_clean_segment_v298(segment):
    cleaned = []
    prev = None
    for pair in segment or []:
        if not isinstance(pair, (list, tuple)) or len(pair) < 2:
            continue
        try:
            lat = round(float(pair[0]), 7); lon = round(float(pair[1]), 7)
        except Exception:
            continue
        if not (math.isfinite(lat) and math.isfinite(lon)):
            continue
        if prev is not None:
            try:
                if _nearby_haversine_m(prev[0], prev[1], lat, lon) < 1.2:
                    continue
            except Exception:
                pass
        cleaned.append([lat, lon])
        prev = [lat, lon]
    return cleaned


def _project_segment_total_m_v298(segment):
    total = 0.0
    prev = None
    for pair in _project_clean_segment_v298(segment):
        if prev is not None:
            try:
                total += _nearby_haversine_m(prev[0], prev[1], pair[0], pair[1])
            except Exception:
                pass
        prev = pair
    return total


def _project_route_anchor_points_v298(segment):
    pts = _project_clean_segment_v298(segment)
    if len(pts) <= 2:
        return pts
    out = [pts[0]]
    last = pts[0]
    for idx, point in enumerate(pts[1:-1], start=1):
        keep = False
        try:
            if _nearby_haversine_m(last[0], last[1], point[0], point[1]) >= float(PROJECT_ROUTE_SNAP_MIN_ANCHOR_SPACING_M_V299):
                keep = True
        except Exception:
            keep = True
        if not keep and len(out) >= 1 and idx + 1 < len(pts):
            prev = out[-1]
            nxt = pts[idx + 1]
            try:
                ax = point[1] - prev[1]; ay = point[0] - prev[0]
                bx = nxt[1] - point[1]; by = nxt[0] - point[0]
                na = math.hypot(ax, ay); nb = math.hypot(bx, by)
                if na > 1e-12 and nb > 1e-12:
                    cosine = max(-1.0, min(1.0, (ax * bx + ay * by) / (na * nb)))
                    turn_deg = math.degrees(math.acos(cosine))
                    if turn_deg >= 18.0:
                        keep = True
            except Exception:
                pass
        if keep:
            out.append(point)
            last = point
    if _nearby_haversine_m(out[-1][0], out[-1][1], pts[-1][0], pts[-1][1]) >= 1.2:
        out.append(pts[-1])
    else:
        out[-1] = pts[-1]
    if len(out) <= int(PROJECT_ROUTE_SNAP_MAX_ANCHORS_V299):
        return out
    keep_indices = {0, len(out) - 1}
    step = (len(out) - 1) / float(PROJECT_ROUTE_SNAP_MAX_ANCHORS_V299 - 1)
    for i in range(1, PROJECT_ROUTE_SNAP_MAX_ANCHORS_V299 - 1):
        keep_indices.add(int(round(i * step)))
    return [out[i] for i in sorted(i for i in keep_indices if 0 <= i < len(out))]


def _project_route_chunk_key_v298(points):
    clean = _project_clean_segment_v298(points)
    return ';'.join(f"{p[0]:.6f},{p[1]:.6f}" for p in clean)


@st.cache_data(ttl=PROJECT_ROUTE_SNAP_READ_TTL_SECONDS_V299, max_entries=2048, show_spinner=False)
def _project_osrm_route_chunk_v298(chunk_key):
    if not isinstance(chunk_key, str) or ';' not in chunk_key:
        return []
    raw_points = []
    for token in chunk_key.split(';'):
        token = token.strip()
        if not token or ',' not in token:
            continue
        lat_s, lon_s = token.split(',', 1)
        try:
            lat = float(lat_s); lon = float(lon_s)
        except (TypeError, ValueError):
            continue
        if math.isfinite(lat) and math.isfinite(lon):
            raw_points.append([round(lat, 6), round(lon, 6)])
    if len(raw_points) < 2:
        return []
    coords = ';'.join(f"{lon:.6f},{lat:.6f}" for lat, lon in raw_points)
    url = f"https://router.project-osrm.org/route/v1/foot/{coords}"
    params = {
        'overview': 'full',
        'geometries': 'geojson',
        'steps': 'false',
        'continue_straight': 'true',
    }
    headers = {'User-Agent': 'TokyoBurariRoadSnapV298/1.0'}
    try:
        response = requests.get(url, params=params, headers=headers, timeout=7.0)
        response.raise_for_status()
        payload = response.json()
    except Exception:
        return []
    routes = payload.get('routes') if isinstance(payload, dict) else None
    if not isinstance(routes, list) or not routes:
        return []
    geometry = routes[0].get('geometry') if isinstance(routes[0], dict) else None
    coords_out = geometry.get('coordinates') if isinstance(geometry, dict) else None
    snapped = []
    prev = None
    for raw in coords_out or []:
        if not isinstance(raw, (list, tuple)) or len(raw) < 2:
            continue
        try:
            lon = float(raw[0]); lat = float(raw[1])
        except (TypeError, ValueError):
            continue
        if not (math.isfinite(lat) and math.isfinite(lon)):
            continue
        point = [round(lat, 7), round(lon, 7)]
        if prev is not None:
            try:
                if _nearby_haversine_m(prev[0], prev[1], point[0], point[1]) < 0.7:
                    continue
            except Exception:
                pass
        snapped.append(point)
        prev = point
    return snapped


def _project_chunk_points_v298(points, max_points=10):
    clean = _project_clean_segment_v298(points)
    if len(clean) < 2:
        return []
    limit = max(2, int(max_points or 2))
    if len(clean) <= limit:
        return [clean]
    chunks = []
    start = 0
    while start < len(clean) - 1:
        end = min(len(clean), start + limit)
        chunk = clean[start:end]
        if len(chunk) >= 2:
            chunks.append(chunk)
        if end >= len(clean):
            break
        start = end - 1
    return chunks


def _project_join_paths_v298(paths):
    joined = []
    prev = None
    for path in paths or []:
        clean = _project_clean_segment_v298(path)
        if len(clean) < 2:
            continue
        if joined and clean:
            try:
                gap = _nearby_haversine_m(joined[-1][0], joined[-1][1], clean[0][0], clean[0][1])
            except Exception:
                gap = float('inf')
            if gap <= float(PROJECT_ROUTE_SNAP_JOIN_TOLERANCE_M_V299):
                clean = clean[1:]
        for point in clean:
            if prev is not None:
                try:
                    if _nearby_haversine_m(prev[0], prev[1], point[0], point[1]) < 0.7:
                        continue
                except Exception:
                    pass
            joined.append(point)
            prev = point
    return joined


def _project_snap_segment_to_roads_v298(segment):
    clean = _project_clean_segment_v298(segment)
    if len(clean) < 2:
        return clean
    if _project_segment_total_m_v298(clean) < float(PROJECT_ROUTE_SNAP_MIN_SEGMENT_M_V299):
        return clean
    anchors = _project_route_anchor_points_v298(clean)
    if len(anchors) < 2:
        return clean
    snapped_paths = []
    success_count = 0
    for chunk in _project_chunk_points_v298(anchors, PROJECT_ROUTE_SNAP_MAX_CHUNK_POINTS_V299):
        key = _project_route_chunk_key_v298(chunk)
        snapped = _project_osrm_route_chunk_v298(key)
        if len(snapped) >= 2:
            snapped_paths.append(snapped)
            success_count += 1
        else:
            snapped_paths.append(chunk)
    joined = _project_join_paths_v298(snapped_paths)
    if len(joined) < 2:
        return clean
    try:
        start_gap = _nearby_haversine_m(joined[0][0], joined[0][1], clean[0][0], clean[0][1])
        end_gap = _nearby_haversine_m(joined[-1][0], joined[-1][1], clean[-1][0], clean[-1][1])
    except Exception:
        start_gap = end_gap = 0.0
    if success_count <= 0 or start_gap > 120.0 or end_gap > 120.0:
        return clean
    return joined


def _project_snap_display_segments_v298(segments):
    rows = [list(seg) for seg in (segments or []) if isinstance(seg, list) and len(seg) >= 2]
    if not rows:
        return []
    worker_count = max(1, min(int(PROJECT_ROUTE_SNAP_MAX_WORKERS_V299), len(rows)))
    if worker_count == 1:
        return [_project_snap_segment_to_roads_v298(seg) for seg in rows]
    indexed = list(enumerate(rows))
    out = [None] * len(indexed)
    with ThreadPoolExecutor(max_workers=worker_count) as executor:
        future_map = {executor.submit(_project_snap_segment_to_roads_v298, seg): idx for idx, seg in indexed}
        for future, idx in [(f, future_map[f]) for f in future_map]:
            try:
                out[idx] = future.result()
            except Exception:
                out[idx] = rows[idx]
    return [seg for seg in out if isinstance(seg, list) and len(seg) >= 2]



def _project_live_road_state_path_v525(family_key=None, member_key=None):
    return f"{_gps_track_prefix(family_key, member_key)}/{PROJECT_LIVE_ROAD_STORAGE_FILE_V525}"


def _project_live_road_default_state_v525(family_key=None, member_key=None):
    return {
        "schema": PROJECT_LIVE_ROAD_SCHEMA_V525,
        "family_key": str(family_key or current_family_key() or ""),
        "member_key": str(member_key or current_member_key() or ""),
        "provider": PROJECT_LIVE_ROAD_PROVIDER_V525,
        "saved_at": "",
        "chunks": {},
        "failures": {},
    }


def _project_live_road_read_state_v525(client, family_key, member_key):
    state = _project_live_road_default_state_v525(family_key, member_key)
    path = _project_live_road_state_path_v525(family_key, member_key)
    try:
        raw = _storage_bytes(client.storage.from_(GPS_TRACK_BUCKET).download(path))
        payload = json.loads(raw.decode("utf-8")) if raw else {}
    except Exception:
        return state
    if not isinstance(payload, dict) or str(payload.get("schema") or "") != PROJECT_LIVE_ROAD_SCHEMA_V525:
        return state
    chunks = payload.get("chunks") if isinstance(payload.get("chunks"), dict) else {}
    failures = payload.get("failures") if isinstance(payload.get("failures"), dict) else {}
    clean_chunks = {}
    for key, row in chunks.items():
        if not isinstance(row, dict):
            continue
        geometry = _project_clean_segment_v298(row.get("geometry") or [])
        geometries = []
        for candidate in (row.get("geometries") or []):
            cleaned = _project_clean_segment_v298(candidate)
            if len(cleaned) >= 2:
                geometries.append(cleaned)
        if len(geometry) < 2 and not geometries:
            continue
        clean = dict(row)
        if len(geometry) >= 2:
            clean["geometry"] = geometry
        else:
            clean.pop("geometry", None)
        if geometries:
            clean["geometries"] = geometries
        else:
            clean.pop("geometries", None)
        clean_chunks[str(key)[:80]] = clean
    clean_failures = {}
    for key, row in failures.items():
        if isinstance(row, dict):
            clean_failures[str(key)[:80]] = dict(row)
    state.update({
        "saved_at": str(payload.get("saved_at") or "")[:80],
        "chunks": clean_chunks,
        "failures": clean_failures,
    })
    return state


def _project_live_road_save_state_v525(client, family_key, member_key, state):
    chunks = state.get("chunks") if isinstance(state.get("chunks"), dict) else {}
    failures = state.get("failures") if isinstance(state.get("failures"), dict) else {}
    document = {
        "schema": PROJECT_LIVE_ROAD_SCHEMA_V525,
        "family_key": str(family_key or ""),
        "member_key": str(member_key or ""),
        "provider": PROJECT_LIVE_ROAD_PROVIDER_V525,
        "saved_at": now_jst().isoformat(),
        "chunks": chunks,
        "failures": failures,
    }
    blob = json.dumps(document, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    path = _project_live_road_state_path_v525(family_key, member_key)
    bucket = client.storage.from_(GPS_TRACK_BUCKET)
    options = {"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0", "upsert": "true"}
    try:
        bucket.upload(path=path, file=blob, file_options=options)
    except Exception:
        try:
            bucket.update(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0"})
        except Exception:
            try:
                bucket.remove([path])
            except Exception:
                pass
            bucket.upload(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0"})
    return True


def _project_live_road_anchor_points_v525(segment):
    pts = _project_clean_segment_v298(segment)
    if len(pts) <= 2:
        return pts
    out = [pts[0]]
    last = pts[0]
    for idx, point in enumerate(pts[1:-1], start=1):
        keep = False
        try:
            if _nearby_haversine_m(last[0], last[1], point[0], point[1]) >= float(PROJECT_LIVE_ROAD_ANCHOR_SPACING_M_V525):
                keep = True
        except Exception:
            keep = True
        if not keep:
            try:
                prev = out[-1]
                nxt = pts[idx + 1]
                ax = point[1] - prev[1]; ay = point[0] - prev[0]
                bx = nxt[1] - point[1]; by = nxt[0] - point[0]
                na = math.hypot(ax, ay); nb = math.hypot(bx, by)
                if na > 1e-12 and nb > 1e-12:
                    cosine = max(-1.0, min(1.0, (ax * bx + ay * by) / (na * nb)))
                    if math.degrees(math.acos(cosine)) >= 24.0:
                        keep = True
            except Exception:
                pass
        if keep:
            out.append(point); last = point
    if out[-1] != pts[-1]:
        out.append(pts[-1])
    return out


def _project_live_road_detail_anchor_points_v526(segment):
    """Keep substantially more walking evidence than the v525 display-only pass.

    The resulting coordinates are still never rendered directly. They only constrain
    road routing, which lets us restore genuine walked streets that v496 intentionally
    hid while retaining a road-shaped final display.
    """
    pts = _project_clean_segment_v298(segment)
    if len(pts) <= 2:
        return pts
    out = [pts[0]]
    last = pts[0]
    spacing = float(PROJECT_LIVE_ROAD_DETAIL_ANCHOR_SPACING_M_V526)
    turn_limit = float(PROJECT_LIVE_ROAD_DETAIL_TURN_DEGREES_V526)
    for idx, point in enumerate(pts[1:-1], start=1):
        keep = False
        try:
            if _nearby_haversine_m(last[0], last[1], point[0], point[1]) >= spacing:
                keep = True
        except Exception:
            keep = True
        if not keep:
            try:
                prev = pts[idx - 1]
                nxt = pts[idx + 1]
                ax = point[1] - prev[1]; ay = point[0] - prev[0]
                bx = nxt[1] - point[1]; by = nxt[0] - point[0]
                na = math.hypot(ax, ay); nb = math.hypot(bx, by)
                if na > 1e-12 and nb > 1e-12:
                    cosine = max(-1.0, min(1.0, (ax * bx + ay * by) / (na * nb)))
                    if math.degrees(math.acos(cosine)) >= turn_limit:
                        keep = True
            except Exception:
                pass
        if keep:
            out.append(point)
            last = point
    if out[-1] != pts[-1]:
        out.append(pts[-1])
    return out


def _project_live_road_group_source_v525(display_segments, display_meta):
    windows = display_meta.get("segment_windows") if isinstance(display_meta, dict) else []
    windows = windows if isinstance(windows, list) else []
    source_rows = []
    for idx, segment in enumerate(display_segments or []):
        clean = _project_clean_segment_v298(segment)
        if len(clean) < 2:
            continue
        meta = windows[idx] if idx < len(windows) and isinstance(windows[idx], dict) else {}
        source_rows.append({
            "coords": clean,
            "start_ts_ms": max(0, int(meta.get("start_ts_ms") or 0)),
            "end_ts_ms": max(0, int(meta.get("end_ts_ms") or 0)),
            "session_id": str(meta.get("session_id") or ""),
            "source": str(meta.get("source") or ""),
            "distance_m": _project_segment_total_m_v298(clean),
        })
    groups = []
    current = None
    for row in source_rows:
        if current is None:
            current = dict(row)
            continue
        try:
            time_gap = (float(row.get("start_ts_ms") or 0) - float(current.get("end_ts_ms") or 0)) / 1000.0
            end_point = current["coords"][-1]; start_point = row["coords"][0]
            endpoint_gap = _nearby_haversine_m(end_point[0], end_point[1], start_point[0], start_point[1])
        except Exception:
            time_gap = float("inf"); endpoint_gap = float("inf")
        same_session = bool(current.get("session_id")) and current.get("session_id") == row.get("session_id")
        same_source = bool(current.get("source")) and current.get("source") == row.get("source")
        combined_m = float(current.get("distance_m") or 0.0) + float(row.get("distance_m") or 0.0) + max(0.0, endpoint_gap if math.isfinite(endpoint_gap) else 0.0)
        merge_ok = (
            0 <= time_gap <= float(PROJECT_LIVE_ROAD_GROUP_MAX_TIME_GAP_SECONDS_V525)
            and endpoint_gap <= float(PROJECT_LIVE_ROAD_GROUP_MAX_ENDPOINT_GAP_M_V525)
            and combined_m <= float(PROJECT_LIVE_ROAD_GROUP_MAX_M_V525)
            and (same_session or (same_source and time_gap <= 45.0))
        )
        if merge_ok:
            coords = list(current.get("coords") or [])
            incoming = list(row.get("coords") or [])
            if coords and incoming and coords[-1] == incoming[0]:
                incoming = incoming[1:]
            coords.extend(incoming)
            current["coords"] = coords
            current["end_ts_ms"] = max(int(current.get("end_ts_ms") or 0), int(row.get("end_ts_ms") or 0))
            current["distance_m"] = combined_m
        else:
            groups.append(current)
            current = dict(row)
    if current is not None:
        groups.append(current)
    return groups


def _project_live_road_source_chunks_v525(display_segments, display_meta, fallback_segments=None, detail_segments=None):
    chunks = []
    seen_keys = set()
    group_index = 0

    def append_chunk(kind, group, part_index, part, start_ts_ms=0, end_ts_ms=0, signature_prefix=None):
        clean_part = _project_clean_segment_v298(part)
        if len(clean_part) < 2:
            return
        raw_m = _project_segment_total_m_v298(clean_part)
        min_m = float(PROJECT_LIVE_ROAD_DETAIL_MIN_CHUNK_M_V526) if kind == "detail" else (12.0 if kind == "coarse" else 7.0)
        if raw_m < min_m:
            return
        prefix = str(signature_prefix or kind)
        signature = prefix + "|" + ";".join(f"{float(p[0]):.6f},{float(p[1]):.6f}" for p in clean_part)
        key = hashlib.sha1((PROJECT_LIVE_ROAD_SCHEMA_V525 + "|" + signature).encode("utf-8")).hexdigest()[:28]
        if key in seen_keys:
            return
        seen_keys.add(key)
        chunks.append({
            "key": key, "kind": kind, "group": group, "part": part_index,
            "anchors": clean_part, "raw_m": round(raw_m, 2),
            "start_ts_ms": int(start_ts_ms or 0), "end_ts_ms": int(end_ts_ms or 0),
        })

    # v526 coverage pass FIRST. v271 walking segments are less destructive than v496,
    # but remain cleaned for accuracy/noise and walk-like continuity. Using 12m-spaced
    # anchors in short chunks makes the pedestrian router follow small side streets and
    # restores places that disappeared when v525 only used the strict display trace.
    for detail_index, segment in enumerate(detail_segments or []):
        anchors = _project_live_road_detail_anchor_points_v526(segment)
        if len(anchors) < 2:
            continue
        for part_index, part in enumerate(_project_chunk_points_v298(anchors, PROJECT_LIVE_ROAD_DETAIL_MAX_ANCHORS_V526)):
            append_chunk(
                "detail", detail_index, part_index, part,
                signature_prefix=PROJECT_LIVE_ROAD_DETAIL_ALGO_V526,
            )

    # Keep all v525 source definitions unchanged so already-persisted road inference is
    # immediately reusable while the new detail pass fills historical gaps in background.
    groups = _project_live_road_group_source_v525(display_segments, display_meta)
    for group in groups:
        anchors = _project_live_road_anchor_points_v525(group.get("coords") or [])
        if len(anchors) < 2:
            continue
        for part_index, part in enumerate(_project_chunk_points_v298(anchors, PROJECT_LIVE_ROAD_MAX_ANCHORS_V525)):
            append_chunk(
                "strict", group_index, part_index, part,
                start_ts_ms=int(group.get("start_ts_ms") or 0),
                end_ts_ms=int(group.get("end_ts_ms") or 0),
                signature_prefix="strict",
            )
        group_index += 1

    # Coarse urban fixes still contribute only after road inference succeeds.
    for fallback_index, segment in enumerate(fallback_segments or []):
        anchors = _project_live_road_anchor_points_v525(segment)
        if len(anchors) < 2:
            continue
        for part_index, part in enumerate(_project_chunk_points_v298(anchors, PROJECT_LIVE_ROAD_MAX_ANCHORS_V525)):
            append_chunk(
                "coarse", group_index + fallback_index, part_index, part,
                signature_prefix="coarse",
            )
    return chunks


def _project_live_road_point_polyline_distance_m_v525(point, geometry):
    try:
        plat = float(point[0]); plon = float(point[1])
    except Exception:
        return float("inf")
    line = _project_clean_segment_v298(geometry)
    if len(line) < 2:
        return float("inf")
    lat0 = math.radians(plat)
    sx = 111320.0 * max(0.2, math.cos(lat0)); sy = 111320.0
    px = plon * sx; py = plat * sy
    best = float("inf")
    for a, b in zip(line[:-1], line[1:]):
        ax = float(a[1]) * sx; ay = float(a[0]) * sy
        bx = float(b[1]) * sx; by = float(b[0]) * sy
        vx = bx - ax; vy = by - ay
        denom = vx * vx + vy * vy
        if denom <= 1e-9:
            dist = math.hypot(px - ax, py - ay)
        else:
            t = max(0.0, min(1.0, ((px - ax) * vx + (py - ay) * vy) / denom))
            qx = ax + t * vx; qy = ay + t * vy
            dist = math.hypot(px - qx, py - qy)
        best = min(best, dist)
    return best


def _project_live_road_reduce_geometry_v525(geometry):
    clean = _project_clean_segment_v298(geometry)
    if len(clean) <= 2:
        return clean
    out = [clean[0]]
    for idx in range(1, len(clean) - 1):
        point = clean[idx]
        try:
            dist = _nearby_haversine_m(out[-1][0], out[-1][1], point[0], point[1])
        except Exception:
            dist = 99.0
        keep = dist >= 4.0
        if not keep and idx + 1 < len(clean):
            try:
                prev = out[-1]; nxt = clean[idx + 1]
                ax = point[1] - prev[1]; ay = point[0] - prev[0]
                bx = nxt[1] - point[1]; by = nxt[0] - point[0]
                na = math.hypot(ax, ay); nb = math.hypot(bx, by)
                if na > 1e-12 and nb > 1e-12:
                    cosine = max(-1.0, min(1.0, (ax * bx + ay * by) / (na * nb)))
                    keep = math.degrees(math.acos(cosine)) >= 12.0
            except Exception:
                pass
        if keep:
            out.append(point)
    if out[-1] != clean[-1]:
        out.append(clean[-1])
    if len(out) <= 360:
        return out
    step = max(1, int(math.ceil(len(out) / 360.0)))
    sampled = out[::step]
    if sampled[-1] != out[-1]:
        sampled.append(out[-1])
    return sampled


def _project_live_road_request_geometry_v526(anchors, *, continue_straight=True):
    anchors = _project_clean_segment_v298(anchors)
    if len(anchors) < 2:
        return []
    coords = ";".join(f"{float(lon):.6f},{float(lat):.6f}" for lat, lon in anchors)
    params = urlencode({
        "overview": "full",
        "geometries": "geojson",
        "steps": "false",
        "continue_straight": "true" if continue_straight else "false",
    })
    url = f"{PROJECT_LIVE_ROAD_BASE_URL_V525}/{coords}?{params}"
    req = Request(url, headers={"User-Agent": "TokyoBurariProjectRoadMatchV526/1.0"})
    try:
        with urlopen(req, timeout=float(PROJECT_LIVE_ROAD_REQUEST_TIMEOUT_V525)) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except Exception:
        return []
    routes = payload.get("routes") if isinstance(payload, dict) else None
    if not isinstance(routes, list) or not routes or not isinstance(routes[0], dict):
        return []
    geometry_payload = routes[0].get("geometry") or {}
    raw_coords = geometry_payload.get("coordinates") if isinstance(geometry_payload, dict) else None
    geometry = []
    for value in raw_coords or []:
        if not isinstance(value, (list, tuple)) or len(value) < 2:
            continue
        try:
            lon = float(value[0]); lat = float(value[1])
        except (TypeError, ValueError):
            continue
        if math.isfinite(lat) and math.isfinite(lon):
            geometry.append([round(lat, 7), round(lon, 7)])
    return _project_live_road_reduce_geometry_v525(geometry)


def _project_live_road_validate_geometry_v526(anchors, geometry, *, kind="strict", raw_m=None):
    anchors = _project_clean_segment_v298(anchors)
    geometry = _project_clean_segment_v298(geometry)
    if len(anchors) < 2 or len(geometry) < 2:
        return None
    raw_m = max(0.1, float(raw_m or _project_segment_total_m_v298(anchors)))
    route_m = _project_segment_total_m_v298(geometry)
    ratio = route_m / raw_m
    detail = str(kind or "") == "detail"
    ratio_min = float(PROJECT_LIVE_ROAD_DETAIL_RATIO_MIN_V526 if detail else PROJECT_LIVE_ROAD_RATIO_MIN_V525)
    ratio_max = float(PROJECT_LIVE_ROAD_DETAIL_RATIO_MAX_V526 if detail else PROJECT_LIVE_ROAD_RATIO_MAX_V525)
    if ratio < ratio_min or ratio > ratio_max:
        return None
    errors = sorted(_project_live_road_point_polyline_distance_m_v525(point, geometry) for point in anchors)
    if not errors or not math.isfinite(errors[-1]):
        return None
    median_error = errors[len(errors) // 2]
    max_error = float(PROJECT_LIVE_ROAD_DETAIL_MAX_ANCHOR_ERROR_M_V526 if detail else PROJECT_LIVE_ROAD_MAX_ANCHOR_ERROR_M_V525)
    median_limit = float(PROJECT_LIVE_ROAD_DETAIL_MEDIAN_ANCHOR_ERROR_M_V526 if detail else PROJECT_LIVE_ROAD_MEDIAN_ANCHOR_ERROR_M_V525)
    if errors[-1] > max_error or median_error > median_limit:
        return None
    return {
        "raw_m": raw_m,
        "route_m": route_m,
        "ratio": ratio,
        "max_anchor_error_m": errors[-1],
        "median_anchor_error_m": median_error,
    }


def _project_live_road_route_v525(chunk):
    anchors = _project_clean_segment_v298((chunk or {}).get("anchors") or [])
    if len(anchors) < 2:
        return None
    kind = str((chunk or {}).get("kind") or "strict")
    raw_m = max(0.1, float((chunk or {}).get("raw_m") or _project_segment_total_m_v298(anchors)))

    # v526 detail chunks use many more waypoints and allow natural turns at each anchor.
    # This is deliberately slower than v525 but strongly constrains the inferred road to
    # the streets represented by the recorded walk.
    geometry = _project_live_road_request_geometry_v526(
        anchors,
        continue_straight=(kind != "detail"),
    )
    metrics = _project_live_road_validate_geometry_v526(anchors, geometry, kind=kind, raw_m=raw_m)
    if metrics:
        return {
            "geometry": geometry,
            "raw_m": round(metrics["raw_m"], 2),
            "route_m": round(metrics["route_m"], 2),
            "ratio": round(metrics["ratio"], 4),
            "max_anchor_error_m": round(metrics["max_anchor_error_m"], 2),
            "median_anchor_error_m": round(metrics["median_anchor_error_m"], 2),
            "provider": PROJECT_LIVE_ROAD_PROVIDER_V525,
            "kind": kind,
            "algorithm": PROJECT_LIVE_ROAD_DETAIL_ALGO_V526 if kind == "detail" else "v525",
            "start_ts_ms": int((chunk or {}).get("start_ts_ms") or 0),
            "end_ts_ms": int((chunk or {}).get("end_ts_ms") or 0),
            "saved_at": now_jst().isoformat(),
        }

    # If a dense detail chunk cannot be routed as one path, recover the portions that
    # can be inferred confidently. This is the main coverage repair for old walks: one
    # noisy point no longer causes an entire 100-200m walked section to disappear.
    if kind != "detail" or len(anchors) <= 2:
        return None

    fallback_parts = _project_chunk_points_v298(
        anchors,
        max(2, int(PROJECT_LIVE_ROAD_DETAIL_FALLBACK_ANCHORS_V526)),
    )
    geometries = []
    raw_total = 0.0
    route_total = 0.0
    max_errors = []
    median_errors = []
    accepted_parts = 0
    for part in fallback_parts:
        part_raw_m = max(0.1, _project_segment_total_m_v298(part))
        part_geometry = _project_live_road_request_geometry_v526(part, continue_straight=False)
        part_metrics = _project_live_road_validate_geometry_v526(
            part,
            part_geometry,
            kind="detail",
            raw_m=part_raw_m,
        )
        if not part_metrics:
            continue
        geometries.append(part_geometry)
        raw_total += float(part_metrics["raw_m"])
        route_total += float(part_metrics["route_m"])
        max_errors.append(float(part_metrics["max_anchor_error_m"]))
        median_errors.append(float(part_metrics["median_anchor_error_m"]))
        accepted_parts += 1

    if not geometries:
        return None
    ratio = route_total / max(0.1, raw_total)
    return {
        "geometries": geometries,
        "raw_m": round(raw_total, 2),
        "route_m": round(route_total, 2),
        "ratio": round(ratio, 4),
        "max_anchor_error_m": round(max(max_errors) if max_errors else 0.0, 2),
        "median_anchor_error_m": round(max(median_errors) if median_errors else 0.0, 2),
        "provider": PROJECT_LIVE_ROAD_PROVIDER_V525,
        "kind": kind,
        "algorithm": PROJECT_LIVE_ROAD_DETAIL_ALGO_V526 + "_partial",
        "partial": accepted_parts < len(fallback_parts),
        "matched_parts": accepted_parts,
        "total_parts": len(fallback_parts),
        "start_ts_ms": int((chunk or {}).get("start_ts_ms") or 0),
        "end_ts_ms": int((chunk or {}).get("end_ts_ms") or 0),
        "saved_at": now_jst().isoformat(),
    }


@st.cache_resource(show_spinner=False)
def _project_live_road_runtime_v525():
    return {"lock": threading.Lock(), "executor": ThreadPoolExecutor(max_workers=1, thread_name_prefix="burari-road-match"), "jobs": {}}


def _project_live_road_worker_v525(owner, source_chunks):
    from supabase import create_client
    client = create_client(SUPABASE_URL, SUPABASE_SECRET_KEY)
    family_key, member_key = owner
    state = _project_live_road_read_state_v525(client, family_key, member_key)
    chunks = state.setdefault("chunks", {})
    failures = state.setdefault("failures", {})
    active_keys = {str(row.get("key") or "") for row in source_chunks if isinstance(row, dict) and row.get("key")}
    now_epoch = time.time()
    attempted = 0; saved_count = 0; failed_count = 0
    kind_priority = {"detail": 0, "strict": 1, "coarse": 2}
    ordered_chunks = sorted(
        [row for row in (source_chunks or []) if isinstance(row, dict)],
        key=lambda row: (
            kind_priority.get(str(row.get("kind") or ""), 9),
            int(row.get("group") or 0),
            int(row.get("part") or 0),
        ),
    )
    for chunk in ordered_chunks:
        key = str((chunk or {}).get("key") or "")
        if not key or key in chunks:
            continue
        failure = failures.get(key) if isinstance(failures.get(key), dict) else {}
        try:
            retry_after = float(failure.get("retry_after_epoch") or 0.0)
        except Exception:
            retry_after = 0.0
        if retry_after > now_epoch:
            continue
        if attempted >= int(PROJECT_LIVE_ROAD_MAX_REQUESTS_PER_JOB_V525):
            break
        attempted += 1
        result = _project_live_road_route_v525(chunk)
        if result:
            chunks[key] = result
            failures.pop(key, None)
            saved_count += 1
        else:
            attempts = max(0, int(failure.get("attempts") or 0)) + 1
            delay = min(float(PROJECT_LIVE_ROAD_RETRY_MAX_SECONDS_V525), float(PROJECT_LIVE_ROAD_RETRY_BASE_SECONDS_V525) * (2 ** min(5, attempts - 1)))
            failures[key] = {
                "attempts": attempts,
                "last_at": now_jst().isoformat(),
                "retry_after_epoch": round(time.time() + delay, 1),
            }
            failed_count += 1
        # v526 detail inference is intentionally slower. Save every two completed chunks
        # so phone/app restarts never force already-finished street inference to repeat.
        if attempted % 2 == 0:
            state["chunks"] = chunks; state["failures"] = failures
            _project_live_road_save_state_v525(client, family_key, member_key, state)

    if len(chunks) > int(PROJECT_LIVE_ROAD_MAX_STATE_CHUNKS_V525):
        active = {key: row for key, row in chunks.items() if key in active_keys}
        if len(active) < int(PROJECT_LIVE_ROAD_MAX_STATE_CHUNKS_V525):
            extras = [(key, row) for key, row in chunks.items() if key not in active_keys]
            extras.sort(key=lambda pair: str((pair[1] or {}).get("saved_at") or ""), reverse=True)
            room = int(PROJECT_LIVE_ROAD_MAX_STATE_CHUNKS_V525) - len(active)
            active.update(extras[:max(0, room)])
        chunks = active
    failures = {key: row for key, row in failures.items() if key in active_keys or float((row or {}).get("retry_after_epoch") or 0.0) > time.time()}
    state["chunks"] = chunks; state["failures"] = failures
    state["source_chunk_count"] = len(source_chunks)
    state["last_job"] = {"attempted": attempted, "saved": saved_count, "failed": failed_count, "at": now_jst().isoformat()}
    _project_live_road_save_state_v525(client, family_key, member_key, state)
    return state["last_job"]


def _project_live_road_launch_v525(source_chunks, state):
    source_chunks = [row for row in (source_chunks or []) if isinstance(row, dict) and row.get("key")]
    if not source_chunks:
        return False
    chunks = state.get("chunks") if isinstance(state, dict) and isinstance(state.get("chunks"), dict) else {}
    failures = state.get("failures") if isinstance(state, dict) and isinstance(state.get("failures"), dict) else {}
    now_epoch = time.time()
    missing = False
    for row in source_chunks:
        key = str(row.get("key") or "")
        if key in chunks:
            continue
        failure = failures.get(key) if isinstance(failures.get(key), dict) else {}
        try:
            retry_after = float(failure.get("retry_after_epoch") or 0.0)
        except Exception:
            retry_after = 0.0
        if retry_after <= now_epoch:
            missing = True
            break
    runtime = _project_live_road_runtime_v525()
    owner = (current_family_key(), current_member_key())
    with runtime["lock"]:
        future = runtime["jobs"].get(owner)
        if future is not None:
            if not future.done():
                return True
            runtime["jobs"].pop(owner, None)
            # Give the next rerun a chance to reload the just-saved state before a new batch.
            return True
        if not missing:
            return False
        runtime["jobs"][owner] = runtime["executor"].submit(_project_live_road_worker_v525, owner, source_chunks)
        return True


def _project_live_road_segments_v525(source_chunks, state):
    chunks = state.get("chunks") if isinstance(state, dict) and isinstance(state.get("chunks"), dict) else {}
    output = []
    matched = 0
    detail_total = 0
    detail_matched = 0
    rendered_parts = 0
    for source in source_chunks or []:
        key = str((source or {}).get("key") or "")
        row = chunks.get(key) if key else None
        kind = str((source or {}).get("kind") or "")
        if kind == "detail":
            detail_total += 1
        if not isinstance(row, dict):
            continue
        geometries = []
        geometry = _project_clean_segment_v298(row.get("geometry") or [])
        if len(geometry) >= 2:
            geometries.append(geometry)
        for candidate in (row.get("geometries") or []):
            cleaned = _project_clean_segment_v298(candidate)
            if len(cleaned) >= 2:
                geometries.append(cleaned)
        if not geometries:
            continue
        matched += 1
        if kind == "detail":
            detail_matched += 1
        for geometry in geometries:
            output.append(geometry)
            rendered_parts += 1
    total = len(source_chunks or [])
    return output, {
        "matched": matched,
        "total": total,
        "pending": max(0, total - matched),
        "detail_matched": detail_matched,
        "detail_total": detail_total,
        "rendered_parts": rendered_parts,
    }


@st.cache_resource(show_spinner=False)
def _project_live_road_tick_component_v525():
    return st.components.v2.component(
        "burari_project_road_tick_v525",
        html="<span hidden></span>",
        js="""export default function(component){const {data,setTriggerValue}=component;let timer=null;if(data?.pending){timer=setTimeout(()=>setTriggerValue('tick',{t:Date.now()}),8000);}return()=>{if(timer!==null)clearTimeout(timer);};}""",
    )


def _project_live_road_tick_v525(pending):
    if not pending:
        return
    try:
        _project_live_road_tick_component_v525()(
            data={"pending": True},
            key=f"project_road_tick_v525_{current_family_key()}_{current_member_key()}",
            height=1,
            on_tick_change=lambda: None,
        )
    except Exception:
        pass



# ============================================================
# v527: full GPS -> road map matching rebuild
# ============================================================

def _project_gps_match_state_path_v527(family_key=None, member_key=None):
    return f"{_gps_track_prefix(family_key, member_key)}/{PROJECT_GPS_MATCH_STORAGE_FILE_V527}"


def _project_gps_match_default_state_v527(family_key=None, member_key=None):
    return {
        "schema": PROJECT_GPS_MATCH_SCHEMA_V527,
        "family_key": str(family_key or current_family_key() or ""),
        "member_key": str(member_key or current_member_key() or ""),
        "provider": PROJECT_GPS_MATCH_PROVIDER_V527,
        "saved_at": "",
        "chunks": {},
        "failures": {},
        "source_chunk_count": 0,
    }


def _project_gps_match_read_state_v527(client, family_key, member_key):
    state = _project_gps_match_default_state_v527(family_key, member_key)
    try:
        raw = _storage_bytes(client.storage.from_(GPS_TRACK_BUCKET).download(
            _project_gps_match_state_path_v527(family_key, member_key)
        ))
        payload = json.loads(raw.decode("utf-8")) if raw else {}
    except Exception:
        return state
    if not isinstance(payload, dict) or str(payload.get("schema") or "") != PROJECT_GPS_MATCH_SCHEMA_V527:
        return state
    chunks = payload.get("chunks") if isinstance(payload.get("chunks"), dict) else {}
    failures = payload.get("failures") if isinstance(payload.get("failures"), dict) else {}
    clean_chunks = {}
    for key, row in chunks.items():
        if not isinstance(row, dict):
            continue
        geometries = []
        for candidate in row.get("geometries") or []:
            cleaned = _project_clean_segment_v298(candidate)
            if len(cleaned) >= 2:
                geometries.append(cleaned)
        if not geometries:
            geometry = _project_clean_segment_v298(row.get("geometry") or [])
            if len(geometry) >= 2:
                geometries.append(geometry)
        terminal_no_match = str(row.get("status") or "") == "no_match"
        if not geometries and not terminal_no_match:
            continue
        clean = dict(row)
        clean.pop("diagnostics", None)
        clean.pop("diagnostic_event_count", None)
        clean["geometries"] = geometries
        clean.pop("geometry", None)
        clean_chunks[str(key)[:80]] = clean
    clean_failures = {
        str(key)[:80]: dict(row)
        for key, row in failures.items()
        if isinstance(row, dict)
    }
    state.update({
        "saved_at": str(payload.get("saved_at") or "")[:80],
        "chunks": clean_chunks,
        "failures": clean_failures,
        "source_chunk_count": max(0, int(payload.get("source_chunk_count") or 0)),
        "last_job": payload.get("last_job") if isinstance(payload.get("last_job"), dict) else {},
    })
    return state


def _project_gps_match_save_state_v527(client, family_key, member_key, state):
    document = {
        "schema": PROJECT_GPS_MATCH_SCHEMA_V527,
        "family_key": str(family_key or ""),
        "member_key": str(member_key or ""),
        "provider": PROJECT_GPS_MATCH_PROVIDER_V527,
        "saved_at": now_jst().isoformat(),
        "source_chunk_count": max(0, int((state or {}).get("source_chunk_count") or 0)),
        "active_chunk_keys": [str(x)[:96] for x in ((state or {}).get("active_chunk_keys") or []) if str(x or "").strip()],
        "chunks": (state or {}).get("chunks") if isinstance((state or {}).get("chunks"), dict) else {},
        "failures": (state or {}).get("failures") if isinstance((state or {}).get("failures"), dict) else {},
        "last_job": (state or {}).get("last_job") if isinstance((state or {}).get("last_job"), dict) else {},
    }
    blob = json.dumps(document, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    path = _project_gps_match_state_path_v527(family_key, member_key)
    bucket = client.storage.from_(GPS_TRACK_BUCKET)
    options = {"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0", "upsert": "true"}
    try:
        bucket.upload(path=path, file=blob, file_options=options)
    except Exception:
        try:
            bucket.update(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0"})
        except Exception:
            try:
                bucket.remove([path])
            except Exception:
                pass
            bucket.upload(path=path, file=blob, file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0"})
    return True


def _project_gps_walk_row_segments_v527(points):
    """Retain full GPS metadata while applying the same walk-only continuity rules as v271.

    v271 returns only coordinates, which discards timestamps and Location accuracy. v527
    keeps those fields because OSRM Match can use both to reject implausible transitions
    and choose the most plausible pedestrian road sequence.
    """
    segments = []
    current = []
    prev = None
    rows = [row for row in _project_clean_track_points_v372(points) if isinstance(row, dict)]
    rows.sort(key=lambda row: int(float(row.get("ts_ms") or 0)))
    for point in rows:
        if prev is None:
            prev = point
            continue
        try:
            dt = max(0.001, (float(point.get("ts_ms")) - float(prev.get("ts_ms"))) / 1000.0)
            dist = _nearby_haversine_m(float(prev["lat"]), float(prev["lon"]), float(point["lat"]), float(point["lon"]))
        except Exception:
            if len(current) >= 2:
                segments.append(current)
            current = []
            prev = point
            continue
        reported_speed = point.get("speed_mps")
        try:
            reported_speed = float(reported_speed) if reported_speed is not None else None
        except (TypeError, ValueError):
            reported_speed = None
        estimated_speed = dist / dt if dt > 0 else 999.0
        same_session = bool(str(point.get("session_id") or "")) and str(point.get("session_id") or "") == str(prev.get("session_id") or "")
        point_source = str(point.get("source") or "").strip().lower()
        prev_source = str(prev.get("source") or "").strip().lower()
        same_source = bool(point_source) and point_source == prev_source
        short_session_restart = (
            not same_session
            and same_source
            and dt <= 75.0
            and dist <= 90.0
            and estimated_speed <= GPS_TRACK_WALK_MAX_SPEED_MPS
        )
        implausibly_fast_report = (
            reported_speed is not None
            and reported_speed > 8.0
            and dist > 30.0
        )
        walk_like = (
            (same_session or short_session_restart)
            and dt <= GPS_TRACK_SEGMENT_MAX_GAP_SECONDS
            and dist <= GPS_TRACK_SEGMENT_MAX_JUMP_M
            and estimated_speed <= GPS_TRACK_WALK_MAX_SPEED_MPS
            and not implausibly_fast_report
        )
        if walk_like:
            if not current:
                current = [dict(prev)]
            current.append(dict(point))
        else:
            if len(current) >= 2:
                segments.append(current)
            current = []
        prev = point
    if len(current) >= 2:
        segments.append(current)
    return segments


def _project_gps_match_prepare_rows_v527(rows):
    """Make OSRM-safe ordered observations without fabricating coordinates."""
    out = []
    last_ts_sec = None
    last_coord = None
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        try:
            lat = float(row.get("lat")); lon = float(row.get("lon")); ts_ms = int(float(row.get("ts_ms") or 0))
        except (TypeError, ValueError):
            continue
        if not (math.isfinite(lat) and math.isfinite(lon)) or ts_ms <= 0:
            continue
        ts_sec = int(ts_ms // 1000)
        # OSRM requires monotonic timestamps. If two fixes fall in the same second,
        # keep the later one only when it actually moved; otherwise the extra duplicate
        # adds no map-matching evidence.
        if last_ts_sec is not None and ts_sec <= last_ts_sec:
            continue
        coord = [round(lat, 7), round(lon, 7)]
        if last_coord is not None:
            try:
                if _nearby_haversine_m(last_coord[0], last_coord[1], coord[0], coord[1]) < 0.8:
                    continue
            except Exception:
                pass
        try:
            accuracy = float(row.get("accuracy_m")) if row.get("accuracy_m") is not None else 12.0
        except (TypeError, ValueError):
            accuracy = 12.0
        if not math.isfinite(accuracy) or accuracy <= 0:
            accuracy = 12.0
        # Android horizontal accuracy is useful evidence. Keep a floor so points do not
        # become overconfident, and a ceiling so a single very poor fix does not invite
        # a completely different parallel road hundreds of metres away.
        accuracy = max(4.0, min(55.0, accuracy))
        out.append({
            "lat": coord[0], "lon": coord[1], "ts_ms": ts_ms, "ts_sec": ts_sec,
            "accuracy_m": accuracy,
            "session_id": str(row.get("session_id") or ""),
            "source": str(row.get("source") or ""),
        })
        last_ts_sec = ts_sec
        last_coord = coord
    return out


def _project_gps_match_source_chunks_v527(points):
    chunks = []
    seen = set()
    max_points = max(8, int(PROJECT_GPS_MATCH_MAX_POINTS_V527))
    overlap = max(2, min(max_points - 2, int(PROJECT_GPS_MATCH_OVERLAP_POINTS_V527)))
    stride = max(2, max_points - overlap)
    for segment_index, segment_rows in enumerate(_project_gps_walk_row_segments_v527(points)):
        prepared = _project_gps_match_prepare_rows_v527(segment_rows)
        if len(prepared) < int(PROJECT_GPS_MATCH_MIN_POINTS_V527):
            continue
        start = 0
        part_index = 0
        while start < len(prepared) - 1:
            part = prepared[start:start + max_points]
            if len(part) < 2:
                break
            raw_coords = [[row["lat"], row["lon"]] for row in part]
            raw_m = _project_segment_total_m_v298(raw_coords)
            if raw_m >= 4.0:
                signature = (
                    PROJECT_GPS_MATCH_SCHEMA_V527 + "|"
                    + str(part[0]["ts_ms"]) + "|" + str(part[-1]["ts_ms"]) + "|"
                    + ";".join(f"{row['lat']:.6f},{row['lon']:.6f},{int(row['ts_sec'])}" for row in part)
                )
                key = hashlib.sha1(signature.encode("utf-8")).hexdigest()[:32]
                if key not in seen:
                    seen.add(key)
                    chunks.append({
                        "key": key,
                        "segment": segment_index,
                        "part": part_index,
                        "rows": part,
                        "raw_m": round(raw_m, 2),
                        "start_ts_ms": int(part[0]["ts_ms"]),
                        "end_ts_ms": int(part[-1]["ts_ms"]),
                    })
            if start + max_points >= len(prepared):
                break
            start += stride
            part_index += 1
    return chunks


def _project_percentile_simple_v527(values, q):
    vals = sorted(float(v) for v in values if v is not None and math.isfinite(float(v)))
    if not vals:
        return float("inf")
    if len(vals) == 1:
        return vals[0]
    pos = max(0.0, min(1.0, float(q))) * (len(vals) - 1)
    lo = int(math.floor(pos)); hi = int(math.ceil(pos))
    if lo == hi:
        return vals[lo]
    frac = pos - lo
    return vals[lo] * (1.0 - frac) + vals[hi] * frac


def _project_gps_match_geometry_from_payload_v527(raw_geometry):
    payload = raw_geometry if isinstance(raw_geometry, dict) else {}
    coords = payload.get("coordinates") if isinstance(payload.get("coordinates"), list) else []
    out = []
    for value in coords:
        if not isinstance(value, (list, tuple)) or len(value) < 2:
            continue
        try:
            lon = float(value[0]); lat = float(value[1])
        except (TypeError, ValueError):
            continue
        if math.isfinite(lat) and math.isfinite(lon):
            point = [round(lat, 7), round(lon, 7)]
            if not out:
                out.append(point)
            else:
                try:
                    if _nearby_haversine_m(out[-1][0], out[-1][1], point[0], point[1]) >= 0.7:
                        out.append(point)
                except Exception:
                    out.append(point)
    return _project_live_road_reduce_geometry_v525(out)


def _project_gps_match_request_v527(rows, *, rate_state=None):
    rows = _project_gps_match_prepare_rows_v527(rows)
    if len(rows) < int(PROJECT_GPS_MATCH_MIN_POINTS_V527):
        return None
    if isinstance(rate_state, dict):
        # v529: enforce the same >=1.05s limit between REQUEST STARTS. The old code
        # waited after the response completed, adding network latency on top of the
        # intended interval and leaving the worker idle without improving accuracy.
        elapsed = time.monotonic() - float(rate_state.get("last_request_started_monotonic") or 0.0)
        wait = float(PROJECT_GPS_MATCH_REQUEST_INTERVAL_V527) - elapsed
        if wait > 0:
            time.sleep(wait)
        rate_state["last_request_started_monotonic"] = time.monotonic()
        rate_state["requests"] = int(rate_state.get("requests") or 0) + 1
    coords = ";".join(f"{float(row['lon']):.7f},{float(row['lat']):.7f}" for row in rows)
    timestamps = ";".join(str(int(row["ts_sec"])) for row in rows)
    radiuses = ";".join(f"{float(row['accuracy_m']):.1f}" for row in rows)
    params = urlencode({
        "overview": "full",
        "geometries": "geojson",
        "steps": "false",
        "annotations": "false",
        "tidy": "true",
        "gaps": "split",
        "timestamps": timestamps,
        "radiuses": radiuses,
    })
    url = f"{PROJECT_GPS_MATCH_BASE_URL_V527}/{coords}?{params}"
    req = Request(url, headers={"User-Agent": "TokyoBurariProjectGpsMatchV529/1.0"})
    try:
        with urlopen(req, timeout=float(PROJECT_GPS_MATCH_REQUEST_TIMEOUT_V527)) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        status = int(getattr(exc, "code", 0) or 0)
        return {
            "ok": False,
            "error": f"HTTP{status or 'error'}",
            "transient": bool(status == 429 or status >= 500),
            "rows": rows,
        }
    except (URLError, TimeoutError) as exc:
        return {"ok": False, "error": type(exc).__name__, "transient": True, "rows": rows}
    except Exception as exc:
        return {"ok": False, "error": type(exc).__name__, "transient": True, "rows": rows}
    if not isinstance(payload, dict) or str(payload.get("code") or "") != "Ok":
        return {
            "ok": False,
            "error": str((payload or {}).get("code") or "no_match")[:80],
            "transient": False,
            "rows": rows,
        }
    return {"ok": True, "payload": payload, "rows": rows}


def _project_gps_match_evaluate_v527(request_result):
    if not isinstance(request_result, dict) or not request_result.get("ok"):
        return []
    payload = request_result.get("payload") if isinstance(request_result.get("payload"), dict) else {}
    rows = request_result.get("rows") if isinstance(request_result.get("rows"), list) else []
    matchings = payload.get("matchings") if isinstance(payload.get("matchings"), list) else []
    tracepoints = payload.get("tracepoints") if isinstance(payload.get("tracepoints"), list) else []
    if not rows or not matchings:
        return []
    accepted = []
    for matching_index, matching in enumerate(matchings):
        if not isinstance(matching, dict):
            continue
        geometry = _project_gps_match_geometry_from_payload_v527(matching.get("geometry") or {})
        if len(geometry) < 2:
            continue
        try:
            confidence = float(matching.get("confidence") or 0.0)
        except (TypeError, ValueError):
            confidence = 0.0
        member_indices = []
        snap_errors = []
        normalized_errors = []
        for index, tracepoint in enumerate(tracepoints):
            if index >= len(rows) or not isinstance(tracepoint, dict):
                continue
            try:
                if int(tracepoint.get("matchings_index")) != matching_index:
                    continue
            except Exception:
                continue
            loc = tracepoint.get("location") if isinstance(tracepoint.get("location"), (list, tuple)) else None
            if not loc or len(loc) < 2:
                continue
            try:
                snapped_lon = float(loc[0]); snapped_lat = float(loc[1])
                source = rows[index]
                error_m = _nearby_haversine_m(float(source["lat"]), float(source["lon"]), snapped_lat, snapped_lon)
                accuracy = max(4.0, float(source.get("accuracy_m") or 12.0))
            except Exception:
                continue
            member_indices.append(index)
            snap_errors.append(error_m)
            normalized_errors.append(error_m / accuracy)
        if len(member_indices) < 2:
            continue
        coverage = len(member_indices) / max(1, len(rows))
        median_snap = _project_percentile_simple_v527(snap_errors, 0.50)
        p90_snap = _project_percentile_simple_v527(snap_errors, 0.90)
        median_norm = _project_percentile_simple_v527(normalized_errors, 0.50)
        p90_norm = _project_percentile_simple_v527(normalized_errors, 0.90)
        subset_coords = [[rows[i]["lat"], rows[i]["lon"]] for i in member_indices]
        raw_m = max(0.1, _project_segment_total_m_v298(subset_coords))
        route_m = _project_segment_total_m_v298(geometry)
        ratio = route_m / raw_m
        strong = confidence >= float(PROJECT_GPS_MATCH_STRONG_CONFIDENCE_V527)
        confidence_ok = confidence >= float(PROJECT_GPS_MATCH_MIN_CONFIDENCE_V527)
        # A low OSRM confidence can still be correct in a dense Tokyo grid when the GPS
        # snaps very tightly to one road sequence. Require tight normalized errors in that
        # case rather than discarding the walk solely because several parallel streets exist.
        tight_low_confidence = median_norm <= 1.05 and p90_norm <= 2.1 and median_snap <= 18.0 and p90_snap <= 42.0
        error_ok = (
            median_snap <= float(PROJECT_GPS_MATCH_MAX_MEDIAN_SNAP_M_V527)
            and p90_snap <= float(PROJECT_GPS_MATCH_MAX_P90_SNAP_M_V527)
            and median_norm <= 1.8
            and p90_norm <= 3.4
        )
        ratio_ok = float(PROJECT_GPS_MATCH_RATIO_MIN_V527) <= ratio <= float(PROJECT_GPS_MATCH_RATIO_MAX_V527)
        coverage_ok = (
            coverage >= float(PROJECT_GPS_MATCH_MIN_TRACE_COVERAGE_V527)
            or len(member_indices) >= 8
            or (len(member_indices) >= 4 and strong and p90_snap <= 35.0)
        )
        if not ratio_ok or not error_ok or not coverage_ok or not (confidence_ok or tight_low_confidence or strong):
            continue
        accepted.append({
            "geometry": geometry,
            "confidence": round(confidence, 4),
            "matched_points": len(member_indices),
            "coverage": round(coverage, 4),
            "median_snap_m": round(median_snap, 2),
            "p90_snap_m": round(p90_snap, 2),
            "median_accuracy_ratio": round(median_norm, 3),
            "p90_accuracy_ratio": round(p90_norm, 3),
            "raw_m": round(raw_m, 2),
            "route_m": round(route_m, 2),
            "route_ratio": round(ratio, 4),
        })
    return accepted


def _project_gps_match_route_chunk_v527(chunk, rate_state=None):
    rows = list((chunk or {}).get("rows") or [])
    if len(rows) < int(PROJECT_GPS_MATCH_MIN_POINTS_V527):
        return None
    if not isinstance(rate_state, dict):
        rate_state = {"last_request_started_monotonic": 0.0, "requests": 0}
    rate_state["chunk_had_transient_failure_v530"] = False
    requests_before = int(rate_state.get("requests") or 0)

    def attempt(candidate_rows, depth=0):
        result = _project_gps_match_request_v527(candidate_rows, rate_state=rate_state)
        if isinstance(result, dict) and bool(result.get("transient")):
            rate_state["chunk_had_transient_failure_v530"] = True
        accepted = _project_gps_match_evaluate_v527(result)
        if accepted:
            return accepted
        # v529: keep the same accuracy-preserving split for genuine map-matching
        # rejection/NoMatch. A timeout, 429, 5xx, or network failure contains no road
        # evidence, so recursively sending 2/4 smaller requests only burns time.
        if isinstance(result, dict) and bool(result.get("transient")):
            return []
        if depth >= int(PROJECT_GPS_MATCH_MAX_SPLIT_DEPTH_V527) or len(candidate_rows) < 12:
            return []
        midpoint = len(candidate_rows) // 2
        overlap = min(3, max(1, len(candidate_rows) // 10))
        left = candidate_rows[:min(len(candidate_rows), midpoint + overlap)]
        right = candidate_rows[max(0, midpoint - overlap):]
        output = []
        if len(left) >= int(PROJECT_GPS_MATCH_MIN_POINTS_V527):
            output.extend(attempt(left, depth + 1))
        if len(right) >= int(PROJECT_GPS_MATCH_MIN_POINTS_V527):
            output.extend(attempt(right, depth + 1))
        return output

    matches = attempt(rows, 0)
    if not matches:
        return None
    geometries = [row["geometry"] for row in matches if len(row.get("geometry") or []) >= 2]
    if not geometries:
        return None
    confidences = [float(row.get("confidence") or 0.0) for row in matches]
    medians = [float(row.get("median_snap_m") or 0.0) for row in matches]
    p90s = [float(row.get("p90_snap_m") or 0.0) for row in matches]
    return {
        "geometries": geometries,
        "provider": PROJECT_GPS_MATCH_PROVIDER_V527,
        "algorithm": PROJECT_GPS_MATCH_SCHEMA_V527,
        "request_count": max(0, int(rate_state.get("requests") or 0) - requests_before),
        "match_count": len(geometries),
        "min_confidence": round(min(confidences) if confidences else 0.0, 4),
        "median_confidence": round(_project_percentile_simple_v527(confidences, 0.5), 4) if confidences else 0.0,
        "max_median_snap_m": round(max(medians) if medians else 0.0, 2),
        "max_p90_snap_m": round(max(p90s) if p90s else 0.0, 2),
        "raw_m": round(float((chunk or {}).get("raw_m") or 0.0), 2),
        "start_ts_ms": int((chunk or {}).get("start_ts_ms") or 0),
        "end_ts_ms": int((chunk or {}).get("end_ts_ms") or 0),
        "saved_at": now_jst().isoformat(),
    }


@st.cache_resource(show_spinner=False)
def _project_gps_match_runtime_v527():
    return {"lock": threading.Lock(), "executor": ThreadPoolExecutor(max_workers=1, thread_name_prefix="burari-gps-map-match"), "jobs": {}}


def _project_gps_match_checkpoint_v528(client, family_key, member_key, state):
    """Persist progress without letting a transient Storage failure kill the long worker."""
    last_error = None
    for attempt in range(max(1, int(PROJECT_GPS_MATCH_CHECKPOINT_RETRIES_V528))):
        try:
            _project_gps_match_save_state_v527(client, family_key, member_key, state)
            return True
        except Exception as exc:
            last_error = exc
            if attempt + 1 < int(PROJECT_GPS_MATCH_CHECKPOINT_RETRIES_V528):
                time.sleep(float(PROJECT_GPS_MATCH_CHECKPOINT_RETRY_SECONDS_V528))
    # Keep processing in memory. A later chunk checkpoint will retry the full state.
    try:
        state["last_checkpoint_error"] = type(last_error).__name__ if last_error else "unknown"
    except Exception:
        pass
    return False


def _project_gps_match_worker_v527(owner, source_chunks):
    """v528: drain the entire source snapshot on the server, independent of page reruns.

    Once launched, this loop does not use the browser tick or the Burari Project page to
    advance. It processes every currently eligible chunk, checkpoints each result, and if
    only retry-delayed failures remain it sleeps server-side until the next retry window.
    The loop exits only when every chunk in this snapshot has a persisted match.
    """
    from supabase import create_client

    client = create_client(SUPABASE_URL, SUPABASE_SECRET_KEY)
    family_key, member_key = owner
    ordered = sorted(
        [dict(row) for row in (source_chunks or []) if isinstance(row, dict) and row.get("key")],
        key=lambda row: (int(row.get("start_ts_ms") or 0), int(row.get("segment") or 0), int(row.get("part") or 0)),
    )
    active_keys = {str(row.get("key") or "") for row in ordered if row.get("key")}
    if not ordered:
        return {"status": "complete", "attempted": 0, "saved": 0, "failed": 0, "requests": 0, "pending": 0}

    state = _project_gps_match_read_state_v527(client, family_key, member_key)
    chunks = state.setdefault("chunks", {})
    failures = state.setdefault("failures", {})
    rate_state = {"last_request_started_monotonic": 0.0, "requests": 0}
    attempted_total = 0
    saved_total = 0
    failed_total = 0
    request_total = 0
    dirty_attempts = 0
    last_checkpoint_monotonic = 0.0

    def checkpoint(status, *, next_retry_epoch=0.0, force=False):
        nonlocal dirty_attempts, last_checkpoint_monotonic
        processed_count = sum(1 for key in active_keys if key in chunks)
        matched_count = sum(
            1 for key in active_keys
            if key in chunks and any(len(g or []) >= 2 for g in ((chunks.get(key) or {}).get("geometries") or []))
        )
        unmatched_count = max(0, processed_count - matched_count)
        pending_count = max(0, len(active_keys) - processed_count)
        elapsed = time.monotonic() - float(last_checkpoint_monotonic or 0.0)
        if not force:
            enough_attempts = dirty_attempts >= int(PROJECT_GPS_MATCH_CHECKPOINT_EVERY_ATTEMPTS_V529)
            enough_time = elapsed >= float(PROJECT_GPS_MATCH_CHECKPOINT_MAX_SECONDS_V529)
            if dirty_attempts > 0 and not enough_attempts and not enough_time:
                return processed_count, pending_count
        state["chunks"] = chunks
        state["failures"] = failures
        state["source_chunk_count"] = len(ordered)
        state["last_job"] = {
            "status": str(status or "running"),
            "attempted": attempted_total,
            "saved": saved_total,
            "failed": failed_total,
            "requests": request_total,
            "processed": processed_count,
            "matched": matched_count,
            "unmatched": unmatched_count,
            "pending": pending_count,
            "next_retry_epoch": round(float(next_retry_epoch or 0.0), 1),
            "at": now_jst().isoformat(),
            "server_continuous": True,
            "checkpoint_batching": True,
        }
        if _project_gps_match_checkpoint_v528(client, family_key, member_key, state):
            dirty_attempts = 0
            last_checkpoint_monotonic = time.monotonic()
        return processed_count, pending_count

    checkpoint("running", force=True)

    while True:
        # Reuse every successful chunk already persisted by v527/v528. This also lets a
        # worker resume from a partially completed historical rebuild after a new launch.
        pending_rows = [row for row in ordered if str(row.get("key") or "") not in chunks]
        if not pending_rows:
            # Keep only data relevant to the active GPS snapshot before the final save.
            if len(chunks) > int(PROJECT_GPS_MATCH_MAX_STATE_CHUNKS_V527):
                chunks = {key: row for key, row in chunks.items() if key in active_keys}
            failures = {key: row for key, row in failures.items() if key in active_keys}
            checkpoint("complete", force=True)
            return dict(state.get("last_job") or {})

        now_epoch = time.time()
        ready = []
        future_retry_epochs = []
        for chunk in pending_rows:
            key = str(chunk.get("key") or "")
            failure = failures.get(key) if isinstance(failures.get(key), dict) else {}
            try:
                retry_after = float(failure.get("retry_after_epoch") or 0.0)
            except Exception:
                retry_after = 0.0
            if retry_after <= now_epoch:
                ready.append(chunk)
            else:
                future_retry_epochs.append(retry_after)

        if not ready:
            # No browser/page interaction is needed here. Stay alive on the server and
            # wake periodically until the earliest retry becomes eligible.
            next_retry = min(future_retry_epochs) if future_retry_epochs else (now_epoch + float(PROJECT_GPS_MATCH_RETRY_POLL_SECONDS_V528))
            checkpoint("waiting_retry", next_retry_epoch=next_retry, force=True)
            remaining = max(0.5, next_retry - time.time())
            time.sleep(min(float(PROJECT_GPS_MATCH_RETRY_POLL_SECONDS_V528), remaining))
            continue

        for chunk in ready:
            key = str(chunk.get("key") or "")
            if not key or key in chunks:
                continue
            failure = failures.get(key) if isinstance(failures.get(key), dict) else {}
            attempted_total += 1
            requests_before = int(rate_state.get("requests") or 0)
            result = None
            worker_error = ""
            try:
                result = _project_gps_match_route_chunk_v527(chunk, rate_state=rate_state)
            except Exception as exc:
                worker_error = type(exc).__name__
            request_total += max(0, int(rate_state.get("requests") or 0) - requests_before)

            if result:
                chunks[key] = result
                failures.pop(key, None)
                saved_total += 1
            else:
                transient_failure = bool(rate_state.get("chunk_had_transient_failure_v530")) or bool(worker_error)
                attempts = max(0, int(failure.get("attempts") or 0)) + 1
                if transient_failure:
                    delay = min(
                        float(PROJECT_GPS_MATCH_TRANSIENT_RETRY_MAX_SECONDS_V530),
                        float(PROJECT_GPS_MATCH_TRANSIENT_RETRY_BASE_SECONDS_V530) * (2 ** min(3, attempts - 1)),
                    )
                    failures[key] = {
                        "attempts": attempts,
                        "last_at": now_jst().isoformat(),
                        "retry_after_epoch": round(time.time() + delay, 1),
                        "last_error": worker_error or "transient_provider_error",
                        "transient": True,
                    }
                else:
                    # The full v527 matching + recursive split pass ran and produced no
                    # road that met the unchanged accuracy thresholds. Repeating exactly
                    # the same deterministic request after 30 minutes adds no evidence;
                    # finalize it as no-match and continue the remaining GPS chunks now.
                    chunks[key] = {
                        "geometries": [],
                        "provider": PROJECT_GPS_MATCH_PROVIDER_V527,
                        "algorithm": PROJECT_GPS_MATCH_SCHEMA_V527,
                        "status": "no_match",
                        "raw_m": round(float((chunk or {}).get("raw_m") or 0.0), 2),
                        "start_ts_ms": int((chunk or {}).get("start_ts_ms") or 0),
                        "end_ts_ms": int((chunk or {}).get("end_ts_ms") or 0),
                        "saved_at": now_jst().isoformat(),
                    }
                    failures.pop(key, None)
                failed_total += 1

            # v529: matching accuracy is unchanged. Batch only the Storage checkpoint
            # so the growing full JSON document is not rewritten after every routing
            # request. Forced saves still happen before retry sleeps and on completion.
            dirty_attempts += 1
            checkpoint("running", force=False)


def _project_gps_match_launch_v527(source_chunks, state):
    """Start one owner-scoped server job whenever any chunk is still unmatched."""
    source_chunks = [dict(row) for row in (source_chunks or []) if isinstance(row, dict) and row.get("key")]
    if not source_chunks:
        return False
    chunks = state.get("chunks") if isinstance(state, dict) and isinstance(state.get("chunks"), dict) else {}
    unfinished = any(str(row.get("key") or "") not in chunks for row in source_chunks)
    runtime = _project_gps_match_runtime_v527()
    owner = (current_family_key(), current_member_key())
    with runtime["lock"]:
        future = runtime["jobs"].get(owner)
        if future is not None:
            if not future.done():
                return True
            # A previous job ended. Remove it and immediately relaunch if anything in
            # the current GPS snapshot is still missing; do not require another page tick.
            runtime["jobs"].pop(owner, None)
        if not unfinished:
            return False
        runtime["jobs"][owner] = runtime["executor"].submit(
            _project_gps_match_worker_v527,
            owner,
            [dict(row) for row in source_chunks],
        )
        return True


def _project_gps_match_segments_v527(source_chunks, state):
    chunks = state.get("chunks") if isinstance(state, dict) and isinstance(state.get("chunks"), dict) else {}
    output = []
    processed = 0
    matched = 0
    unmatched = 0
    rendered_parts = 0
    seen_geometry = set()
    for source in source_chunks or []:
        key = str((source or {}).get("key") or "")
        row = chunks.get(key) if key else None
        if not isinstance(row, dict):
            continue
        processed += 1
        geometries = []
        for geometry in row.get("geometries") or []:
            cleaned = _project_clean_segment_v298(geometry)
            if len(cleaned) >= 2:
                geometries.append(cleaned)
        if not geometries:
            if str(row.get("status") or "") == "no_match":
                unmatched += 1
            continue
        matched += 1
        for geometry in geometries:
            # Overlapping source windows intentionally share several GPS observations.
            # Deduplicate exactly repeated matched geometries while keeping genuine
            # out-and-back walks on the same road visually identical, not doubled.
            sig = tuple((round(float(p[0]), 6), round(float(p[1]), 6)) for p in geometry)
            rev = tuple(reversed(sig))
            canonical = sig if sig <= rev else rev
            if canonical in seen_geometry:
                continue
            seen_geometry.add(canonical)
            output.append(geometry)
            rendered_parts += 1
    total = len(source_chunks or [])
    return output, {
        "processed": processed,
        "matched": matched,
        "unmatched": unmatched,
        "total": total,
        "pending": max(0, total - processed),
        "rendered_parts": rendered_parts,
    }


@st.cache_resource(show_spinner=False)
def _project_gps_match_tick_component_v527():
    return st.components.v2.component(
        "burari_project_gps_match_tick_v527",
        html="<span hidden></span>",
        js="""export default function(component){const {data,setTriggerValue}=component;let timer=null;if(data?.pending){timer=setTimeout(()=>setTriggerValue('tick',{t:Date.now()}),8000);}return()=>{if(timer!==null)clearTimeout(timer);};}""",
    )


def _project_gps_match_tick_v527(pending):
    if not pending:
        return
    try:
        _project_gps_match_tick_component_v527()(
            data={"pending": True},
            key=f"project_gps_match_tick_v527_{current_family_key()}_{current_member_key()}",
            height=1,
            on_tick_change=lambda: None,
        )
    except Exception:
        pass



