# Salt bread map: loaded only on its own page; no new database table is required.
def _salt_shop_key_v622(row):
    saved = str(row.get('shop_state_key') or '')
    if re.fullmatch(r'[0-9a-f]{64}', saved):
        return saved
    lat,lng = _salt_coordinates_v609(row['lat'], row['lng'])
    name = _salt_normal_v609(row.get('name')).casefold()
    return hashlib.sha256((name+f'|{lat:.5f}|{lng:.5f}').encode()).hexdigest()


def _salt_apply_shop_status_v622(doc, row, status):
    if status not in ('unmarked','revisit','visited'):
        raise ValueError('お店の状態を確認できません。')
    lat,lng = _salt_coordinates_v609(row['lat'], row['lng'])
    name = _salt_normal_v609(row.get('name'))[:120]
    if not name:raise ValueError('店名を確認できません。')
    key = _salt_shop_key_v622(row)
    # These are personal bookmarks, not a copy of expiring product evidence.
    doc.setdefault('shop_states', {})[key] = {'shop_state_key':key,'name':name,
        'address':str(row.get('address') or '')[:240], 'lat':lat,'lng':lng,
        'status':status,'updated_at':now_jst().isoformat()}
    for entry in doc.get('entries', {}).values():
        if _salt_shop_key_v622(entry)==key:
            entry['shop_state_key']=key
    return key


def _salt_commons_photo_ref_v632(tags):
    """Only retain explicit links to an individual Commons photograph."""
    from urllib.parse import unquote
    for raw in (tags.get('wikimedia_commons'), tags.get('image')):
        value = str(raw or '').strip()
        if not value or len(value) > 1200:
            continue
        if value.startswith('https://'):
            parsed = urlparse(value)
            if parsed.hostname == 'commons.wikimedia.org' and parsed.path.startswith('/wiki/'):
                value = unquote(parsed.path[len('/wiki/'):])
                if value.startswith('Special:FilePath/'):
                    value = 'File:'+value[len('Special:FilePath/'):]
            elif parsed.hostname == 'upload.wikimedia.org' and parsed.path.startswith('/wikipedia/commons/'):
                parts = parsed.path.split('/')
                value = 'File:'+unquote(parts[-2] if '/thumb/' in parsed.path else parts[-1])
            else:
                continue
        if (value.startswith('File:') and len(value) <= 600
                and not any(c in value for c in ('|', '\n', '\r', '\x00'))
                and re.search(r'\.(?:jpe?g|png|webp)$', value, re.I)):
            return value
    return ''


def _salt_map_cards_v622(doc, discovery, include_unknown=False):
    states=doc.get('shop_states') or {}
    recorded=_salt_cards_v609(doc)
    recorded_keys={_salt_shop_key_v622(row) for row in recorded}
    photo_refs={_salt_shop_key_v622(row):row.get('photo_ref','') for row in _salt_discovery_rows_v617(discovery) if row.get('photo_ref')}
    rows=[];seen=set()
    for row in recorded:
        key=_salt_shop_key_v622(row);mark=states.get(key)
        row.update(shop_state_key=key,shop_status=mark['status'] if mark else ('visited' if row.get('visits') else 'unmarked'))
        row['photo_ref']=photo_refs.get(key,'')
        rows.append(row);seen.add(key)
    for row in _salt_discovery_rows_v617(discovery):
        key=_salt_shop_key_v622(row)
        if key in recorded_keys or key in seen:continue
        mark=states.get(key);status=mark['status'] if mark else 'unmarked'
        rows.append({**row,'candidate':True,'src':'','shop_state_key':key,'shop_status':status})
        seen.add(key)
    for key,mark in states.items():
        if key in seen or key in recorded_keys or mark['status']=='unmarked':continue
        rows.append({**mark,'id':'saved_status_'+key,'candidate':True,'status_only':True,
            'src':'','shop_status':mark['status'],
            'searched_at':'','expires_at':'','evidence':''})
    return rows


def _salt_owner_v609():
    family, member = str(current_family_key()), str(current_member_key())
    if not family or not member:
        raise ValueError("ログインし直してください。")
    return hashlib.sha256((family + "\0" + member).encode()).hexdigest()


def _salt_prefix_v609():
    return "salt_bread_v609/" + _salt_owner_v609()


def _salt_empty_v609():
    return {"version": 1, "revision": 0, "owner": _salt_owner_v609(), "entries": {}, "order": []}


def _salt_missing_v609(exc):
    for value in [getattr(exc, "status_code", None), getattr(exc, "status", None)]:
        if str(value) == "404":
            return True
    for arg in getattr(exc, "args", ()):
        if isinstance(arg, dict) and str(arg.get("statusCode") or arg.get("status") or arg.get("code")) == "404":
            return True
    return "Object not found" in str(exc) or "NoSuchKey" in str(exc)


def _salt_load_v609(force=False):
    key = "_salt_doc_v609_" + _salt_owner_v609()
    cached = None if force else _session_cache_get(key, max_age_seconds=20)
    if cached is not None:
        return json.loads(json.dumps(cached))
    try:
        raw = supabase_client().storage.from_(GPS_TRACK_BUCKET).download(_salt_prefix_v609() + "/map.json")
    except Exception as exc:
        if not _salt_missing_v609(exc):
            raise RuntimeError("パンの記録を読み込めませんでした。再読み込みしてください。") from exc
        doc = _salt_empty_v609()
    else:
        doc = json.loads(_storage_bytes(raw).decode("utf-8"))
        if not isinstance(doc, dict) or doc.get("owner") != _salt_owner_v609() or not isinstance(doc.get("entries"), dict) or not isinstance(doc.get("order"), list):
            raise ValueError("パンの保存データを確認できません。上書きせず停止しました。")
        if set(doc["order"]) != set(doc["entries"]) or len(doc["order"]) != len(set(doc["order"])):
            raise ValueError("パンの順位データを確認できません。")
        for key, entry in doc["entries"].items():
            if not isinstance(entry, dict) or entry.get("id") != key or not re.fullmatch(r"[0-9a-f]{32}", key):
                raise ValueError("お店の記録を確認できません。")
            _salt_coordinates_v609(entry["lat"], entry["lng"])
            for visit in entry.get("visits", []):
                if any(not str(path).startswith(_salt_prefix_v609() + "/images/") for path in visit.get("photos", [])):
                    raise ValueError("写真の持ち主を確認できません。")
    states=doc.get('shop_states', {})
    if not isinstance(states,dict):raise ValueError('お店の色分けデータを確認できません。')
    for identity,mark in states.items():
        if not re.fullmatch(r'[0-9a-f]{64}',str(identity)) or not isinstance(mark,dict) or mark.get('shop_state_key')!=identity or mark.get('status') not in ('unmarked','revisit','visited'):
            raise ValueError('お店の色分けデータを確認できません。')
        _salt_coordinates_v609(mark['lat'],mark['lng'])
    _session_cache_set(key, doc)
    return json.loads(json.dumps(doc))



@st.cache_resource
def _salt_write_lock_v609():
    return threading.RLock()


def _salt_commit_v609(operation, payload, expected_revision=None):
    # Re-read immediately before a mutation so a cached page cannot erase newer visits.
    with _salt_write_lock_v609():
        doc = _salt_load_v609(force=True)
        if expected_revision is not None and int(expected_revision) != int(doc.get("revision") or 0):
            raise ValueError("別の画面で記録が更新されました。再読み込みしてから操作してください。")
        entries, order = doc["entries"], doc["order"]
        if operation == "visit":
            place = payload["place"]
            lat, lng = _salt_coordinates_v609(place["lat"], place["lng"])
            name = str(place.get("name") or "").strip()[:120]
            if not name:
                raise ValueError("店名を入力してください。")
            identity = hashlib.sha256((name + f"|{lat:.5f}|{lng:.5f}").encode()).hexdigest()
            entry_id = str(payload.get("entry_id") or "")
            if entry_id and entry_id not in entries:
                raise ValueError("登録先のお店が見つかりません。")
            if not entry_id:
                entry_id = next((k for k, v in entries.items() if v.get("place_key") == identity), "") or uuid.uuid4().hex
            entry = dict(entries.get(entry_id) or {"id": entry_id, "place_key": identity, "visits": []})
            visit = dict(payload["visit"])
            if not re.fullmatch(r"[0-9a-f]{32}", str(visit.get("id") or "")):
                raise ValueError("記録を確認できません。")
            prefix = _salt_prefix_v609() + "/images/"
            if any(not str(p).startswith(prefix) for p in visit.get("photos", [])):
                raise ValueError("写真の保存先を確認できません。")
            if not any(v.get("id") == visit["id"] for v in entry["visits"]):
                entry["visits"] = list(entry["visits"]) + [visit]
            entry.update(name=name, address=str(place.get("address") or "")[:240], lat=lat, lng=lng,
                         again=bool(payload.get("again")), updated_at=now_jst().isoformat())
            entry['shop_state_key']=_salt_shop_key_v622(entry)
            entries[entry_id] = entry
            previous_status=(doc.get('shop_states') or {}).get(entry['shop_state_key'],{}).get('status')
            _salt_apply_shop_status_v622(doc, entry, 'revisit' if previous_status=='revisit' else 'visited')
            if entry_id not in order:
                order.append(entry_id)
        elif operation == 'shop_status':
            _salt_apply_shop_status_v622(doc, payload['shop'], payload.get('status'))
        elif operation == "pin_visibility":
            entry_id = str(payload.get("entry_id") or "")
            if entry_id not in entries or not isinstance(payload.get("visible"), bool):
                raise ValueError("お店のピンを確認できません。")
            entries[entry_id]["pin_hidden"] = not payload["visible"]
            entries[entry_id]["updated_at"] = now_jst().isoformat()
        elif operation == "edit_visit":
            entry_id = str(payload.get("entry_id") or "")
            if entry_id not in entries:
                raise ValueError("お店の記録が見つかりません。")
            entry = entries[entry_id]
            visit = next((v for v in entry["visits"] if v.get("id") == payload.get("visit_id")), None)
            if visit is None:
                raise ValueError("食べた記録が見つかりません。")
            name = str(payload.get("name") or "").strip()[:120]
            if not name:
                raise ValueError("店名を入力してください。")
            paths = payload.get("photos")
            if not isinstance(paths, list) or any(not str(p).startswith(_salt_prefix_v609()+"/images/") for p in paths):
                raise ValueError("写真の保存先を確認できません。")
            date_value = datetime.fromisoformat(str(payload.get("date") or "")).date().isoformat()
            visit.update(note=str(payload.get("note") or "")[:4000], date=date_value, photos=list(dict.fromkeys(paths)))
            entry.update(name=name, address=str(payload.get("address") or "")[:240], again=bool(payload.get("again")), updated_at=now_jst().isoformat())
            entry["place_key"] = hashlib.sha256((name + f"|{entry['lat']:.5f}|{entry['lng']:.5f}").encode()).hexdigest()
        elif operation == "order":
            desired = payload.get("order")
            if not isinstance(desired, list) or len(desired) != len(order) or len(set(desired)) != len(desired) or set(desired) != set(order):
                raise ValueError("順位が変わりました。再読み込みしてから並べ替えてください。")
            doc["order"] = list(desired)
        else:
            raise ValueError("操作を確認できません。")
        doc["revision"] = int(doc.get("revision") or 0) + 1
        doc["updated_at"] = now_jst().isoformat()
        raw = json.dumps(doc, ensure_ascii=False, separators=(",", ":")).encode()
        # Reuse the app's existing metadata-bucket compatibility configuration.
        supabase_client().storage.from_(GPS_TRACK_BUCKET).upload(
            path=_salt_prefix_v609() + "/map.json", file=raw,
            file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0", "upsert": "true"},
        )
        _session_cache_set("_salt_doc_v609_" + _salt_owner_v609(), doc)
        return doc



def _salt_coordinates_v609(lat, lng):
    if isinstance(lat, bool) or isinstance(lng, bool):
        raise ValueError("場所を確認してください。")
    lat, lng = float(lat), float(lng)
    if not (math.isfinite(lat) and math.isfinite(lng) and 35.45 <= lat <= 35.95 and 139.4 <= lng <= 140.05):
        raise ValueError("東京都とその周辺の場所を選んでください。")
    return lat, lng


def _salt_normal_v609(value):
    return re.sub(r"\s+", " ", unicodedata.normalize("NFKC", str(value or ""))).strip()


def _salt_trace_v609(web, event, detail=None, level="INFO", stage=""):
    web.logs.append({"time": now_jst().isoformat(), "event": event, "level": level, "stage": stage, "detail": detail or {}})
    web.logs[:] = web.logs[-80:]


class _SaltWebV609:
    def __init__(self):
        self.logs = []
        self.deadline = time.monotonic() + 16.0


def _salt_lookup_json_v609(web, url, params, operation):
    started = time.monotonic()
    method = "POST" if operation == "bakery_search" else "GET"
    info = {"url": url, "parameters": params, "operation": operation, "method": method, "failed_stage": operation + ".request"}
    _salt_trace_v609(web, "request", dict(info))
    try:
        headers={"User-Agent":"BurariSaltBreadMap/1.0","Accept":"application/json"}
        if method == "POST":
            headers["Content-Type"]="application/x-www-form-urlencoded; charset=UTF-8"
            request=Request(url,data=urlencode(params).encode(),headers=headers,method="POST")
        else:
            request=Request(url+"?"+urlencode(params),headers=headers)
        remaining = getattr(web, "deadline", time.monotonic() + 4.0) - time.monotonic()
        if remaining < 0.25:
            raise TimeoutError("検索の通信待ち時間を超えました。")
        with urlopen(request, timeout=min(60.0 if operation == "bakery_search" else 10.0 if operation in ("bakery_photon", "bakery_details") else 4.0, remaining)) as response:
            info.update(status=response.status, content_type=response.headers.get("Content-Type", ""))
            raw = response.read(4 * 1024 * 1024 + 1)
        if len(raw) > 4 * 1024 * 1024:
            raise ValueError("検索結果が大きすぎます。検索範囲を狭めるか、店名を詳しく入力してください。")
        info["failed_stage"] = operation + ".json"
        doc = json.loads(raw.decode())
        _salt_trace_v609(web, "response", {**info, "elapsed_ms": round((time.monotonic() - started) * 1000)})
        return doc, info
    except Exception as exc:
        info.update(status=getattr(exc, "code", info.get("status")), exception_type=type(exc).__name__, error=str(exc), elapsed_ms=round((time.monotonic() - started) * 1000))
        if isinstance(exc, HTTPError):
            try:
                info["response_body"] = _safe_error_text(exc.read(2048).decode("utf-8", errors="replace"), 2048)
            except Exception:
                pass
        info.update(_salt_exception_details_v609(exc))
        exc.landmark_diagnostic = info
        _salt_trace_v609(web, "request_failed", info, "ERROR")
        raise





@st.cache_data(ttl=3600, show_spinner=False)
def _salt_search_v609(query):
    # The Photon -> exact/partial Overpass pipeline is ported from Sumai v215.
    query = _salt_normal_v609(query)
    if not 2 <= len(query) <= 180:
        raise ValueError("店名や住所を2文字以上で入力してください。")
    web = _SaltWebV609()
    web.search_policy = "overpass_photon_v633"
    compact = re.sub(r"\s+", "", query)
    pattern = ".*".join(re.sub(r"([.\[\]{}()*+?^$|\\])", r"\\\1", token) for token in query.split())
    try:
        # Sumai also uses GSI for Japanese addresses. Show all usable address
        # candidates for confirmation instead of pretending a town centroid is a shop.
        if re.search(r"東京都|[市区町村].*[0-9０-９]|丁目", query):
            addresses, info = _salt_lookup_json_v609(web, "https://msearch.gsi.go.jp/address-search/AddressSearch", {"q": query}, "address_search")
            results = []
            if not isinstance(addresses, list):
                raise ValueError("住所検索の応答を確認できませんでした。")
            for item in addresses:
                try:
                    lng, lat = item["geometry"]["coordinates"][:2]
                    lat, lng = _salt_coordinates_v609(lat, lng)
                    address = _salt_normal_v609(item.get("properties", {}).get("title"))
                    if address:
                        results.append({"name": "住所から登録", "address": address, "lat": lat, "lng": lng, "source": "国土地理院・住所検索", "address_only": True})
                except (KeyError, ValueError, TypeError, IndexError):
                    continue
            return {"candidates": results, "logs": web.logs}
        doc, info = _salt_name_document_v609(web, query, pattern)
        results, seen = [], set()
        for index, element in enumerate(doc["elements"]):
            tags = element.get("tags") or {}
            point = element.get("center") or element
            try:
                lat, lng = _salt_coordinates_v609(point["lat"], point["lon"])
            except (ValueError, KeyError, TypeError):
                continue
            name = _salt_normal_v609(tags.get("name:ja") or tags.get("name"))
            if _salt_closed_reason_v633(tags):
                _salt_trace_v609(web,"inactive_name_candidate_excluded",{"name":name,"reason":_salt_closed_reason_v633(tags)})
                continue
            if not name:
                continue
            address = _salt_normal_v609(tags.get("addr:full")) or "".join(_salt_normal_v609(tags.get(k)) for k in ("addr:province", "addr:city", "addr:suburb", "addr:quarter", "addr:neighbourhood", "addr:street", "addr:block_number", "addr:housenumber"))
            key = (name, round(lat, 5), round(lng, 5))
            if key in seen:
                continue
            seen.add(key)
            results.append({"name": name, "address": address or "住所未取得・地図の位置を確認してください", "lat": lat, "lng": lng, "source": "Google Maps" if info.get("provider") == "Google Places" else info.get("provider", "Overpass") + " / OpenStreetMap", "_rank": _salt_candidate_rank_v613(query, tags, index)})
        results.sort(key=lambda p: p["_rank"])
        for result in results:
            result.pop("_rank", None)
        return {"candidates": results, "logs": web.logs}
    except Exception as exc:
        # Preserve technical evidence without putting a saved location at a guessed point.
        info = getattr(exc, "landmark_diagnostic", {}) or {}
        status = str(info.get("status") or getattr(exc, "code", ""))
        if status == "429":
            message = "検索サービスが混雑しています。少し時間をおいて、同じ店名で再検索してください。"
        elif status in ("401", "403"):
            message = "検索サービスへのアクセスが拒否されました。店名の入力が原因ではありません。検索ログをご確認ください。"
        elif _salt_transient_v612(exc):
            message = "検索サービスに接続できませんでした。少し時間をおいて、同じ店名で再検索してください。"
        else:
            message = "検索結果を読み取れませんでした。検索ログをご確認ください。"
        error = RuntimeError(message)
        error.salt_logs = web.logs + [{"event": "search_failed", "detail": getattr(exc, "landmark_diagnostic", {}), "error": str(exc)}]
        raise error from exc


def _salt_save_visit_v609(place, files, note, date_value, again, entry_id="", visit_id=None):
    visit_id = visit_id or uuid.uuid4().hex
    paths = []
    try:
        from PIL import Image, ImageOps
        for index, file in enumerate(files or []):
            raw = file.getvalue()
            with Image.open(io.BytesIO(raw)) as image:
                image = ImageOps.exif_transpose(image).convert("RGB")
                image.thumbnail((1800, 1800))
                buffer = io.BytesIO()
                image.save(buffer, format="JPEG", quality=90)
            path = f"{_salt_prefix_v609()}/images/{visit_id}_{index}.jpg"
            supabase_client().storage.from_(PHOTO_BUCKET).upload(path=path, file=buffer.getvalue(), file_options={"content-type": "image/jpeg", "cache-control": "3600", "upsert": "true"})
            paths.append(path)
        return _salt_commit_v609("visit", {"place": place, "entry_id": entry_id, "again": again,
            "visit": {"id": visit_id, "date": str(date_value), "note": str(note or "")[:4000], "photos": paths}})
    except Exception:
        # Keep uploaded files on an ambiguous metadata write failure: a server may
        # have committed despite a lost HTTP reply. Never erase a committed photo.
        raise


def _salt_capture_v609(component_key, inbox_key):
    value = st.session_state.get(component_key)
    event = value.get("salt_action") if isinstance(value, dict) else getattr(value, "salt_action", None)
    if isinstance(event, dict) and event.get("nonce"):
        st.session_state[inbox_key] = dict(event)


def _salt_preview_v609(place):
    st.session_state["_salt_candidate_v609"] = dict(place)
    st.session_state["salt_mode_v609"] = "地図"


@st.cache_resource
def _salt_search_jobs_v609():
    return {"executor": ThreadPoolExecutor(max_workers=2, thread_name_prefix="salt-search"), "jobs": {}, "lock": threading.RLock()}


def _salt_start_search_v609(query):
    query = _salt_normal_v609(query)
    if not 2 <= len(query) <= 180:
        raise ValueError("店名や住所を2文字以上で入力してください。")
    owner = _salt_owner_v609()
    registry = _salt_search_jobs_v609()
    with registry["lock"]:
        # Keep one outstanding lookup per owner and expire abandoned completed jobs.
        for key, job in list(registry["jobs"].items()):
            if job["future"].done() and time.monotonic() - job["at"] > 3600:
                registry["jobs"].pop(key, None)
        previous = registry["jobs"].get(owner)
        if previous and not previous["future"].done():
            return
        registry["jobs"][owner] = {"future": registry["executor"].submit(_salt_search_v609, query), "at": time.monotonic()}
    st.session_state["_salt_search_wait_v609_" + owner] = True


def _salt_collect_search_v609():
    owner, registry = _salt_owner_v609(), _salt_search_jobs_v609()
    with registry["lock"]:
        job = registry["jobs"].get(owner)
        if not job:
            st.session_state.pop("_salt_search_wait_v609_" + owner, None)
            return False
        if not job["future"].done():
            st.session_state["_salt_search_wait_v609_" + owner] = True
            return False
        registry["jobs"].pop(owner, None)
    try:
        result = job["future"].result()
    except Exception as exc:
        result = {"candidates": [], "error": str(exc), "logs": getattr(exc, "salt_logs", [])}
    st.session_state["_salt_search_result_v609"] = result
    if result.get("error"):
        _app_error_record_v610("salt.place_search", result["error"], {"events": result.get("logs") or []})
    st.session_state.pop("_salt_candidate_v609", None)
    st.session_state.pop("_salt_search_wait_v609_" + owner, None)
    return True


@st.fragment(run_every=1)
def _salt_search_progress_v609():
    # Only this small status fragment polls; Back/Home can run while HTTP waits.
    if str(st.session_state.get("main_page")) != "salt_bread":
        return
    if _salt_collect_search_v609():
        st.rerun(scope="app")
    st.info("店名と住所を検索しています。戻る操作も使えます。")


def _salt_cards_v609(doc):
    entries = [doc["entries"][key] for key in doc["order"]]
    paths = []
    for entry in entries:
        photos = [p for visit in entry.get("visits", []) for p in visit.get("photos", [])]
        paths.append(photos[-1] if photos else "")
    signed = signed_photo_url_map(tuple(p for p in paths if p), expires_in=1800) if any(paths) else {}
    return [{"id": entry["id"], "name": entry["name"], "address": entry.get("address", ""), "lat": entry["lat"], "lng": entry["lng"],
             "shop_state_key": _salt_shop_key_v622(entry), "pin_hidden": bool(entry.get("pin_hidden")), "src": str(signed.get(path) or ""), "again": bool(entry.get("again")), "visits": len(entry.get("visits", [])),
             "note": str((entry.get("visits") or [{}])[-1].get("note") or "")}
            for entry, path in zip(entries, paths)]



def _app_error_clean_v610(value):
    text = str(value or "")
    for name in ("SUPABASE_SECRET_KEY", "OPENAI_API_KEY", "GOOGLE_PLACES_API_KEY"):
        secret_value = str(globals().get(name) or "")
        if len(secret_value) > 8:
            text = text.replace(secret_value, "[REDACTED]")
    text = re.sub(r"(?i)(authorization|apikey|access_token|refresh_token|native_bridge_token|signature|token)([\s\"':=]+)[^\s&\"<>]+", r"\1\2[REDACTED]", text)
    text = re.sub(r"data:image/[^,]+,[A-Za-z0-9+/=]+", "[IMAGE OMITTED]", text)
    return text[:12000]


@st.cache_resource
def _app_error_jobs_v610():
    return {"executor": ThreadPoolExecutor(max_workers=1, thread_name_prefix="burari-errors"), "pending": [], "lock": threading.RLock()}


def _app_error_store_v610(client, path, blob):
    result = client.storage.from_(GPS_TRACK_BUCKET).upload(path=path, file=blob,
        file_options={"content-type": GPS_TRACK_STORAGE_MIME, "cache-control": "0", "upsert": "true"})
    if (isinstance(result, dict) and result.get("error")) or getattr(result, "error", None):
        raise RuntimeError("エラーログの保存先からエラーが返されました。")
    return True


def _app_error_record_v610(stage, error, detail=None, event_id=None, source="server"):
    """Account-scoped bounded diagnostics; no photo bytes, keys or blocking upload."""
    try:
        owner = _salt_owner_v609()
        safe_id = re.sub(r"[^a-f0-9]", "", str(event_id or ""))[:32]
        if len(safe_id) != 32:
            safe_id = uuid.uuid4().hex
        key = "_app_errors_v610_" + owner
        rows = list(st.session_state.get(key) or [])
        if any(row.get("id") == safe_id for row in rows):
            return
        context = dict(detail or {})
        if isinstance(error, BaseException):
            import traceback
            context.setdefault("traceback", "".join(traceback.format_exception(type(error), error, error.__traceback__)))
        row = {"schema": "burari_errors_v610", "id": safe_id, "owner": owner, "build": APP_BUILD,
               "at": now_jst().isoformat(), "source": str(source), "page": str(st.session_state.get("main_page") or ""),
               "stage": str(stage)[:160], "error_type": type(error).__name__ if isinstance(error, BaseException) else "ClientError",
               "message": _app_error_clean_v610(error),
               "detail": _app_error_clean_v610(json.dumps(context, ensure_ascii=False, default=str))}
        rows.append(row)
        st.session_state[key] = rows[-200:]
        registry = _app_error_jobs_v610()
        with registry["lock"]:
            pending = [future for future in registry["pending"] if not future.done()]
            registry["pending"] = pending
            if len(pending) >= 100:
                st.session_state["_app_error_save_status_v610"] = "ログの送信待ちです。端末内のログは出力できます。"
                return
            stamp = now_jst().strftime("%Y%m%dT%H%M%S")
            path = _salt_prefix_v609() + f"/errors/{stamp}_{safe_id}.json"
            future = registry["executor"].submit(_app_error_store_v610, supabase_client(), path, json.dumps(row, ensure_ascii=False).encode())
            pending.append(future)
            st.session_state["_app_error_future_v610_" + owner] = future
    except Exception:
        # A diagnostic must never interfere with Back, or hide the original failure.
        pass


def _app_error_capture_v610(component_key, event_key, owner):
    try:
        current_owner = _salt_owner_v609()
    except Exception:
        return
    if owner != current_owner:
        return
    state = st.session_state.get(component_key)
    event = state.get(event_key) if isinstance(state, dict) else getattr(state, event_key, None)
    if not isinstance(event, dict):
        return
    rows = event.get("rows") if isinstance(event.get("rows"), list) else [event]
    for row in rows[-200:]:
        if isinstance(row, dict):
            _app_error_record_v610(row.get("stage") or "browser", row.get("message") or "ブラウザーエラー",
                                  row.get("detail") or {}, row.get("id"), source="browser")


def _app_error_history_v610():
    owner, bucket = _salt_owner_v609(), supabase_client().storage.from_(GPS_TRACK_BUCKET)
    folder = _salt_prefix_v609() + "/errors"
    listing = bucket.list(folder, {"limit": 100, "offset": 0, "sortBy": {"column": "name", "order": "desc"}})
    rows = []
    for item in _coerce_storage_list_rows(listing):
        name = str(item.get("name") or "")
        if not re.fullmatch(r"\d{8}T\d{6}_[0-9a-f]{32}\.json", name):
            continue
        blob = _storage_bytes(bucket.download(folder + "/" + name))
        if len(blob) > 60000:
            continue
        row = json.loads(blob.decode())
        if row.get("schema") == "burari_errors_v610" and row.get("owner") == owner:
            rows.append(row)
    return rows


@st.cache_resource
def _app_error_reader_v610():
    return st.components.v2.component("burari_error_reader_v610",
        html='<button id="error-read">この端末の地図・写真エラーログを取り込む</button><span id="error-read-status" role="status"></span>',
        css='\nbutton{width:100%;min-height:44px;border:1px solid #b6c2cf;background:#fff;color:#173a5e;border-radius:12px;padding:8px}span{display:block;font-size:12px;margin:5px}\n',
        js=r'''export default function(component) {
          const {parentElement,data,setTriggerValue}=component;
          parentElement.querySelector('#error-read').onclick=()=>{
            let rows=[];
            try{rows=JSON.parse(localStorage.getItem('burari_errors_v610_'+data.owner)||'[]');}catch(_){}
            parentElement.querySelector('#error-read-status').textContent=`${Array.isArray(rows)?rows.length:0}件を取り込みました`;
            setTriggerValue('client_logs',{rows:Array.isArray(rows)?rows:[],nonce:String(Date.now())});
          };
        }''')


def _app_error_settings_v610():
    with st.expander("エラーログ"):
        owner = _salt_owner_v609()
        key = "_app_errors_v610_" + owner
        component_key = "app_error_reader_v610_" + owner
        _app_error_reader_v610()(data={"owner": owner}, key=component_key,
            on_client_logs_change=lambda: _app_error_capture_v610(component_key, "client_logs", owner))
        if st.button("保存済みのエラーログも読み込む", key="error_history_v610"):
            try:
                st.session_state["_app_error_history_v610_" + owner] = _app_error_history_v610()
            except Exception as exc:
                _app_error_record_v610("diagnostics.history_read", exc)
                st.warning("保存済みログを読み込めませんでした。端末内のログは出力できます。")
        rows = list(st.session_state.get("_app_error_history_v610_" + owner) or []) + list(st.session_state.get(key) or [])
        merged = {row.get("id"): row for row in rows if isinstance(row, dict) and row.get("owner") == owner}
        rows = sorted(merged.values(), key=lambda row: str(row.get("at") or ""))
        st.caption(f"出力対象 {len(rows)}件。保存済みログは直近100件を読み込みます。")
        future = st.session_state.get("_app_error_future_v610_" + owner)
        if future and future.done() and future.exception():
            st.caption("ログの保存先への送信に失敗しました。端末内のログをダウンロードしてください。")
        payload = {"build": APP_BUILD, "exported_at": now_jst().isoformat(), "errors": rows}
        st.download_button("エラーログを出力（JSON）", json.dumps(payload, ensure_ascii=False, indent=2),
                           "burari_errors.json", "application/json", key="app_errors_json_v610")
        text = "\n\n".join(f"{row.get('at')} [{row.get('stage')}] {row.get('message')}\n{row.get('detail')}" for row in rows)
        st.download_button("エラーログを出力（TXT）", text or "記録されたエラーはありません。", "burari_errors.txt", "text/plain", key="app_errors_txt_v610")


def _salt_photo_capture_v610(component_key, scope_key):
    try:
        if not scope_key.startswith("_salt_photos_v610_" + _salt_owner_v609() + "_"):
            return
    except Exception:
        return
    state = st.session_state.get(component_key)
    event = state.get("photo_event") if isinstance(state, dict) else getattr(state, "photo_event", None)
    if not isinstance(event, dict) or not event.get("nonce"):
        return
    token_key = scope_key + "_nonce"
    if st.session_state.get(token_key) == event["nonce"]:
        return
    st.session_state[token_key] = event["nonce"]
    try:
        if event.get("action") == "clear":
            st.session_state[scope_key] = []
            st.session_state.pop(scope_key + "_error", None)
            return
        items = event.get("photos")
        if not isinstance(items, list) or len(items) > 30:
            raise ValueError("写真を30枚以内で選び直してください。")
        photos = []
        for item in items:
            data_url = str(item.get("data_url") or "")
            if not data_url.startswith("data:image/jpeg;base64,") or len(data_url) > 16 * 1024 * 1024:
                raise ValueError("選んだ写真を読み込めませんでした。")
            raw = base64.b64decode(data_url.split(",", 1)[1], validate=True)
            from PIL import Image
            with Image.open(io.BytesIO(raw)) as image:
                image.verify()
            photos.append({"raw": raw, "name": str(item.get("name") or "")[:120], "thumb": str(item.get("thumb") or "")[:150000]})
        st.session_state[scope_key] = photos
        st.session_state.pop(scope_key + "_error", None)
    except Exception as exc:
        st.session_state[scope_key + "_error"] = str(exc)
        _app_error_record_v610("salt.photo_selection", exc)


